#include <stdlib.h>
#include <pthread.h>

typedef struct DeviceStatusReport {
    time_t timestamp;
    int device_id;
    float signal_strength;
    // List of error codes
} DeviceStatusReport;

typedef struct ReportNode {
    DeviceStatusReport report;
    struct ReportNode* next;
} ReportNode;

typedef struct DeviceStatusManager {
    pthread_mutex_t lock;
    ReportNode* reports;
} DeviceStatusManager;

// Initialize the manager
void init_device_status_manager(DeviceStatusManager* manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->reports = NULL;
}

// Add or update a report
void add_or_update_report(DeviceStatusManager* manager, DeviceStatusReport report) {
    pthread_mutex_lock(&manager->lock);
    // Check if the device_id already exists and update the report
    ReportNode* current = manager->reports;
    while (current != NULL) {
        if (current->report.device_id == report.device_id) {
            current->report = report;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        current = current->next;
    }
    // If not found, add the new report
    ReportNode* new_node = (ReportNode*)malloc(sizeof(ReportNode));
    new_node->report = report;
    new_node->next = manager->reports;
    manager->reports = new_node;
    pthread_mutex_unlock(&manager->lock);
}

// Retrieve a report by device_id
DeviceStatusReport* get_report_by_device_id(DeviceStatusManager* manager, int device_id) {
    pthread_mutex_lock(&manager->lock);
    ReportNode* current = manager->reports;
    while (current != NULL) {
        if (current->report.device_id == device_id) {
            DeviceStatusReport* result = &current->report;
            pthread_mutex_unlock(&manager->lock);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

// Calculate summary statistics
void calculate_summary(DeviceStatusManager* manager, float* avg_signal_strength, int** error_codes, int* error_count) {
    pthread_mutex_lock(&manager->lock);
    float total_signal_strength = 0;
    int unique_errors[1024] = {0}; // Assuming max 1024 unique errors
    ReportNode* current = manager->reports;
    while (current != NULL) {
        total_signal_strength += current->report.signal_strength;
        for (int i = 0; i < current->report.error_codes_count; i++) {
            if (!unique_errors[current->report.error_codes[i]]) {
                unique_errors[current->report.error_codes[i]] = 1;
            }
        }
        current = current->next;
    }
    *avg_signal_strength = total_signal_strength / (current == NULL ? 1 : current);
    // Count the frequency of each error code
    int count = 0;
    for (int i = 0; i < 1024; i++) {
        if (unique_errors[i]) {
            (*error_codes)[count++] = i;
        }
    }
    *error_count = count;
    pthread_mutex_unlock(&manager->lock);
}

// External data ingestion service integration
void* external_service_thread(void* arg) {
    DeviceStatusManager* manager = (DeviceStatusManager*)arg;
    while (1) {
        // Simulate fetching new reports
        DeviceStatusReport report;
        // Fetch report from external service
        // On success:
        add_or_update_report(manager, report);
        // On failure, retry logic here
        // Sleep for a short period before next attempt
        sleep(1);
    }
    return NULL;
}

// Main function to demonstrate usage
int main() {
    DeviceStatusManager manager;
    init_device_status_manager(&manager);

    pthread_t service_thread;
    pthread_create(&service_thread, NULL, external_service_thread, &manager);

    // Example usage of the library
    // ...

    pthread_join(service_thread, NULL);
    return 0;
}
```

