#define MAX_OFFSETS 1000
#define MAX_KEYS 1000
#define MAX_RECORDS 1000
#define MIN_VALUE 1
#define MAX_VALUE 100

typedef struct {
    int value;
} record;

long offsets[MAX_OFFSETS];
int keys[MAX_KEYS];
record records[MAX_RECORDS];

sqlite3 *db;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_operation(const char *operation, int outcome) {
    time_t now = time(NULL);
    printf("[%ld] %s: %s\n", now, operation, outcome ? "Success" : "Failure");
}

int create_record(int key, int value) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < MAX_KEYS; i++) {
        if (keys[i] == -1) {
            keys[i] = key;
            records[i].value = value;

            long offset = rand() % MAX_OFFSETS;
            offsets[i] = offset;

            // Simulate database insert
            int rc = sqlite3_exec(db, "INSERT INTO records (key, value, offset) VALUES (?, ?, ?)", NULL, NULL, NULL);
            if (rc != SQLITE_OK) {
                log_operation("Database Insert", 0);
                pthread_mutex_unlock(&mutex);
                return -1;
            }

            log_operation("Create Record", 1);
            pthread_mutex_unlock(&mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&mutex);
    return -1;
}

int get_record(int key, int *value) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < MAX_KEYS; i++) {
        if (keys[i] == key) {
            *value = records[i].value;
            log_operation("Get Record", 1);
            pthread_mutex_unlock(&mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&mutex);
    return -1;
}

void *init_database(const char *db_url) {
    int rc = sqlite3_open(db_url, &db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db));
        exit(1);
    }

    const char *create_table_sql =
        "CREATE TABLE IF NOT EXISTS records ("
        "id INTEGER PRIMARY KEY AUTOINCREMENT,"
        "key INTEGER,"
        "value INTEGER,"
        "offset LONG"
        ");";

    rc = sqlite3_exec(db, create_table_sql, 0, 0, 0);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        exit(1);
    }

    return NULL;
}

int main() {
    srand(time(NULL));

    // Initialize database
    init_database("your_database_url");

    // Example usage
    int key = rand() % MAX_KEYS;
    int value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;

    if (create_record(key, value) != 0) {
        fprintf(stderr, "Failed to create record\n");
        return 1;
    }

    int retrieved_value;
    if (get_record(key, &retrieved_value) != 0) {
        fprintf(stderr, "Failed to get record\n");
        return 1;
    }

    printf("Retrieved value: %d\n", retrieved_value);

    sqlite3_close(db);
    return 0;
}
