#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_FILES 10
#define BUFFER_SIZE 4096

typedef struct {
    char *file_path;
    int file_size;
} File;

void* process_file(void* arg) {
    File* file = (File*)arg;
    FILE *fp = fopen(file->file_path, "r");
    if (!fp) {
        perror("Error opening file");
        return NULL;
    }

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, fp)) {
        // Process the data here
    }

    fclose(fp);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [options] file1.txt [file2.txt ...]\n", argv[0]);
        exit(1);
    }

    File files[MAX_FILES];
    int num_files = 0;
    for (int i = 1; i < argc && num_files < MAX_FILES; ++i) {
        files[num_files].file_path = argv[i];
        FILE *fp = fopen(files[num_files].file_path, "r");
        if (!fp) {
            fprintf(stderr, "Error opening file %s\n", argv[i]);
            continue;
        }
        fseek(fp, 0, SEEK_END);
        files[num_files].file_size = ftell(fp);
        fclose(fp);
        num_files++;
    }

    pthread_t threads[MAX_FILES];
    for (int i = 0; i < num_files; ++i) {
        if (pthread_create(&threads[i], NULL, process_file, &files[i])) {
            fprintf(stderr, "Error creating thread\n");
            exit(1);
        }
    }

    for (int i = 0; i < num_files; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
