int main(int argc, char *argv[]) {
    if(argc != 3) {
        printf("Usage: %s <latitude> <longitude>\n", argv[0]);
        return 1;
    }

    double latitude = atof(argv[1]);
    double longitude = atof(argv[2]);

    handle_requests(latitude, longitude);
    cache_and_rate_limit(latitude, longitude);

