#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define BUFFER_SIZE 1024

typedef struct {
    int* buffer;
    size_t head;
    size_t tail;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
} IntBuffer;

IntBuffer* create_buffer() {
    IntBuffer* buf = malloc(sizeof(IntBuffer));
    if (buf == NULL) return NULL;

    buf->buffer = malloc(BUFFER_SIZE * sizeof(int));
    if (buf->buffer == NULL) {
        free(buf);
        return NULL;
    }

    buf->head = 0;
    buf->tail = 0;
    buf->count = 0;

    pthread_mutex_init(&buf->mutex, NULL);
    pthread_cond_init(&buf->not_empty, NULL);
    pthread_cond_init(&buf->not_full, NULL);

    return buf;
}

void destroy_buffer(IntBuffer* buf) {
    free(buf->buffer);
    pthread_mutex_destroy(&buf->mutex);
    pthread_cond_destroy(&buf->not_empty);
    pthread_cond_destroy(&buf->not_full);
    free(buf);
}

void enqueue(IntBuffer* buf, int value) {
    pthread_mutex_lock(&buf->mutex);

    while (buf->count == BUFFER_SIZE)
        pthread_cond_wait(&buf->not_full, &buf->mutex);

    buf->buffer[buf->tail] = value;
    buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    buf->count++;

    pthread_cond_signal(&buf->not_empty);
    pthread_mutex_unlock(&buf->mutex);
}

int dequeue(IntBuffer* buf) {
    int value;

    pthread_mutex_lock(&buf->mutex);

    while (buf->count == 0)
        pthread_cond_wait(&buf->not_empty, &buf->mutex);

    value = buf->buffer[buf->head];
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    buf->count--;

    pthread_cond_signal(&buf->not_full);
    pthread_mutex_unlock(&buf->mutex);

    return value;
}

int find_largest_in_window(IntBuffer* buf, time_t window_start, time_t window_end) {
    int max_value = INT_MIN;

    pthread_mutex_lock(&buf->mutex);

    for (size_t i = 0; i < buf->count; i++) {
        if (buf->buffer[(buf->head + i) % BUFFER_SIZE] > max_value)
            max_value = buf->buffer[(buf->head + i) % BUFFER_SIZE];
    }

    pthread_mutex_unlock(&buf->mutex);

    return max_value;
}

void* consumer(void* arg) {
    IntBuffer* buf = (IntBuffer*)arg;
    int value;

    while (1) {
        value = dequeue(buf);
        // Process the value
        printf("Consumed: %d\n", value);
    }

    return NULL;
}

int main() {
    IntBuffer* buffer = create_buffer();

    pthread_t consumer_thread;
    pthread_create(&consumer_thread, NULL, consumer, buffer);

    // Simulate producer inserting values into buffer
    for (int i = 0; i < 10; i++) {
        enqueue(buffer, i);
    }

    pthread_join(consumer_thread, NULL);

    destroy_buffer(buffer);

    return 0;
}
