package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net/http"
	"sync"
	"time"

	"go.uber.org/zap"
)

type ErrorLog struct {
	Timestamp   time.Time `json:"timestamp"`
	Severity    string    `json:"severity"`
	Code        int       `json:"code"`
	Message     string    `json:"message"`
	Metadata    map[string]interface{} `json:"metadata"`
}

type Logger struct {
	client         *http.Client
	queue          chan ErrorLog
	wg             sync.WaitGroup
	logBatchSize   int
	batchTimeout   time.Duration
	retryAttempts  int
	exponentialBackoff time.Duration
	closeChan      chan struct{}
	stopChan       chan struct{}
	logger         *zap.Logger
}

func NewLogger(serviceURL string, logBatchSize int, batchTimeout, exponentialBackoff time.Duration, retryAttempts int) (*Logger, error) {
	client := &http.Client{
		Timeout: 5 * time.Second,
	}
	queue := make(chan ErrorLog)
	closeChan := make(chan struct{})
	stopChan := make(chan struct{})

	logger, err := zap.NewProduction()
	if err != nil {
		return nil, err
	}

	l := &Logger{
		client:        client,
		queue:         queue,
		wg:            sync.WaitGroup{},
		logBatchSize:  logBatchSize,
		batchTimeout:  batchTimeout,
		retryAttempts: retryAttempts,
		exponentialBackoff: exponentialBackoff,
		closeChan:     closeChan,
		stopChan:      stopChan,
		logger:        logger,
	}

	l.wg.Add(1)
	go l.processQueue()

	return l, nil
}

func (l *Logger) Log(errorLog ErrorLog) {
	select {
	case <-l.closeChan:
	case l.queue <- errorLog:
	}
}

func (l *Logger) processQueue() {
	defer l.wg.Done()
	ticker := time.NewTicker(l.batchTimeout)
	batch := []ErrorLog{}
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			if len(batch) > 0 {
				l.sendBatch(batch)
				batch = []ErrorLog{}
			}
		case errorLog := <-l.queue:
			batch = append(batch, errorLog)
			if len(batch) >= l.logBatchSize {
				l.sendBatch(batch)
				batch = []ErrorLog{}
			}
		case <-l.stopChan:
			if len(batch) > 0 {
				l.sendBatch(batch)
			}
			return
		}
	}
}

func (l *Logger) sendBatch(batch []ErrorLog) {
	payload, err := json.Marshal(batch)
	if err != nil {
		l.logger.Error("Failed to marshal log batch", zap.Error(err))
		return
	}

	req, _ := http.NewRequest("POST", "https://error-log-service.com/log", bytes.NewBuffer(payload))
	req.Header.Set("Content-Type", "application/json")

	var resp *http.Response
	var errRetry error
	for attempt := 0; attempt <= l.retryAttempts; attempt++ {
		resp, errRetry = l.client.Do(req)
		if errRetry == nil && resp.StatusCode == http.StatusOK {
			return
		}
		if errRetry != nil {
			l.logger.Error("Failed to send log batch", zap.Error(errRetry))
		} else if resp.StatusCode != http.StatusOK {
			l.logger.Warn("Non-OK status code when sending log batch", zap.Int("status_code", resp.StatusCode))
		}
		time.Sleep(l.exponentialBackoff * time.Duration(1<<attempt))
	}

	l.logger.Error("Failed to send log batch after retries")
}

func (l *Logger) Close() {
	close(l.closeChan)
	l.wg.Wait()
	close(l.stopChan)
}

func main() {
	logger, err := NewLogger("https://error-log-service.com/log", 100, time.Second, time.Second, 5)
	if err != nil {
		fmt.Println("Failed to create logger:", err)
		return
	}
	defer logger.Close()

	go func() {
		for {
			select {
			case <-time.After(time.Millisecond * 10):
				logger.Log(ErrorLog{
					Timestamp:   time.Now(),
					Severity:    "ERROR",
					Code:        500,
					Message:     "An error occurred",
					Metadata:    map[string]interface{}{"service": "example-service"},
				})
			case <-logger.closeChan:
				return
			}
		}
	}()

	// Simulate service mesh operations
	time.Sleep(time.Minute)
	logger.Close()
}
