    unsigned char iv[16];  // Adjust size based on cipher type
} CryptoContext;

// Function to initialize cryptographic context
CryptoContext* init_crypto_context(CipherType cipher_type, CipherMode mode) {
    CryptoContext *ctx = (CryptoContext*)malloc(sizeof(CryptoContext));
    ctx->cipher_type = cipher_type;
    ctx->mode = mode;
    EVP_CIPHER_CTX_init(ctx->ctx);
    // Initialize key and IV based on cipher type and mode
