}

// Function to clean up cryptographic context
void cleanup_crypto_context(CryptoContext *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
    }
}

// Function to encrypt data
int encrypt_data(CryptoContext *ctx, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    return EVP_EncryptUpdate(ctx->ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
}

// Function to decrypt data
