// Example usage of the cryptographic library
void perform_cryptography(void) {
    CryptoAlgorithm* algorithm = load_crypto_library("openssl");

    if (algorithm == NULL) {
        fprintf(stderr, "Failed to load cryptographic library.\n");
        return;
    }

    // Initialize the cryptographic context
    algorithm->init(algorithm->handle);

    // Perform cryptographic operations
    unsigned char data[] = "Hello, World!";
    size_t length = strlen((char*)data);
    algorithm->update(algorithm->handle, data, length);
    unsigned char result[128];
    memset(result, 0, sizeof(result));
