#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pem.h>
#include <openssl/sha.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_KEY_SIZE 256

typedef struct {
    EVP_CIPHER_CTX *ctx;
    pthread_mutex_t lock;
} CryptoCtx;

int init_crypto_ctx(CryptoCtx *ctx, const EVP_CIPHER *cipher) {
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) return -1;
    if (pthread_mutex_init(&ctx->lock, NULL) != 0) return -1;
    return 0;
}

void free_crypto_ctx(CryptoCtx *ctx) {
    if (ctx->ctx) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        pthread_mutex_destroy(&ctx->lock);
    }
}

int encrypt_file(const char *input_path, const char *output_path, CryptoCtx *ctx, const unsigned char *key, const unsigned char *iv) {
    FILE *in = fopen(input_path, "rb");
    if (!in) return -1;
    FILE *out = fopen(output_path, "wb");
    if (!out) {
        fclose(in);
        return -1;
    }

    pthread_mutex_lock(&ctx->lock);
    EVP_EncryptInit_ex(ctx->ctx, cipher, NULL, key, iv);
    while (!feof(in)) {
        unsigned char in_buf[4096], out_buf[4096];
        int in_len = fread(in_buf, 1, sizeof(in_buf), in);
        if (in_len <= 0) break;
        int out_len;
        EVP_EncryptUpdate(ctx->ctx, out_buf, &out_len, in_buf, in_len);
        fwrite(out_buf, 1, out_len, out);
    }
    int final_out_len;
    EVP_EncryptFinal_ex(ctx->ctx, out_buf, &final_out_len);
    fwrite(out_buf, 1, final_out_len, out);
    pthread_mutex_unlock(&ctx->lock);

    fclose(in);
    fclose(out);
    return 0;
}

// Similar functions for decryption, signing, and verification would be implemented here
