#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define MAX_SEMAPHORES 100
#define MAX_CLIENTS 50

typedef struct {
    sem_t *semaphores[MAX_SEMAPHORES];
    int semaphore_count;
} SemaphorePool;

SemaphorePool pool;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void* client_thread(void* arg) {
    int client_id = *(int*)arg;
    free(arg);

    while (1) {
        pthread_mutex_lock(&pool_lock);
        if (pool.semaphore_count > 0) {
            sem_t *sem = pool.semaphores[--pool.semaphore_count];
            pthread_mutex_unlock(&pool_lock);

            // Simulate semaphore usage
            sem_wait(sem);
            printf("Client %d using semaphore\n", client_id);
            sleep(1);
            sem_post(sem);

            pthread_mutex_lock(&pool_lock);
            pool.semaphores[pool.semaphore_count++] = sem;
            pthread_mutex_unlock(&pool_lock);
        } else {
            pthread_mutex_unlock(&pool_lock);
            usleep(500 * 1000); // Sleep for 500ms if no semaphores are available
        }
    }

    return NULL;
}

void create_semaphore(int initial_value) {
    sem_t *sem = malloc(sizeof(sem_t));
    sem_init(sem, 0, initial_value);

    pthread_mutex_lock(&pool_lock);
    pool.semaphores[pool.semaphore_count++] = sem;
    pthread_mutex_unlock(&pool_lock);
}

void delete_semaphore(int index) {
    pthread_mutex_lock(&pool_lock);
    if (index >= 0 && index < pool.semaphore_count) {
        sem_t *sem = pool.semaphores[index];
        sem_destroy(sem);
        free(sem);

        for (int i = index; i < pool.semaphore_count - 1; ++i) {
            pool.semaphores[i] = pool.semaphores[i + 1];
        }
        --pool.semaphore_count;
    }
    pthread_mutex_unlock(&pool_lock);
}

void* monitoring_thread(void* arg) {
    while (1) {
        printf("Semaphore Pool Status:\n");
        for (int i = 0; i < pool.semaphore_count; ++i) {
            sem_t *sem = pool.semaphores[i];
            int value;
            sem_getvalue(sem, &value);
            printf("Semaphore %d: Value = %d\n", i, value);
        }
        sleep(10); // Update every 10 seconds
    }

    return NULL;
}

int main() {
    pthread_t monitoring;
    pthread_create(&monitoring, NULL, monitoring_thread, NULL);

    for (int i = 0; i < MAX_SEMAPHORES / 2; ++i) {
        create_semaphore(rand() % 10);
    }

    int client_ids[MAX_CLIENTS];
    pthread_t clients[MAX_CLIENTS];

    for (int i = 0; i < MAX_CLIENTS; ++i) {
        client_ids[i] = i;
        pthread_create(&clients[i], NULL, client_thread, &client_ids[i]);
    }

    // Simulate server operations
    sleep(60);

    for (int i = 0; i < MAX_SEMAPHORES / 2; ++i) {
        delete_semaphore(rand() % pool.semaphore_count);
    }

    for (int i = 0; i < MAX_CLIENTS; ++i) {
        pthread_join(clients[i], NULL);
    }

    pthread_join(monitoring, NULL);

    return 0;
}
