use std::collections::{HashMap, HashSet};
use std::sync::{Arc, Mutex};
use tokio::net::TcpStream;
use futures::future::join_all;
use rustc_llvm as llvm;

struct Grammar {
    rules: HashMap<String, Vec<String>>,
}

impl Grammar {
    fn new() -> Self {
        Grammar { rules: HashMap::new() }
    }

    fn load(&mut self, config_service_url: &str) {
        let mut stream = TcpStream::connect(config_service_url).unwrap();
        // Fetch grammar from external service
        let grammar_str = fetch_grammar_from_service(&mut stream);
        parse_grammar_into_rules(&grammar_str, &mut self.rules);
    }

    fn apply_to(&self, input: &str) -> String {
        let mut result = String::new();
        for line in input.lines() {
            if let Some(rule) = self.rules.get(line.trim()) {
                result.push_str(&rule.join(" "));
            }
        }
        result
    }
}

fn fetch_grammar_from_service(stream: &mut TcpStream) -> String {
    // Simulate fetching grammar from external service
    "example -> hello world".to_string()
}

fn parse_grammar_into_rules(grammar_str: &str, rules_map: &mut HashMap<String, Vec<String>>) {
    for rule in grammar_str.split_whitespace() {
        if let Some((key, value)) = rule.split_once("->") {
            rules_map.entry(key.trim().to_string()).or_insert_with(Vec::new).push(value.trim().to_string());
        }
    }
}

struct CachingParser {
    cache: Arc<Mutex<HashMap<String, String>>>,
    grammar: Grammar,
}

impl CachingParser {
    fn new() -> Self {
        CachingParser { cache: Arc::new(Mutex::new(HashMap::new())), grammar: Grammar::new() }
    }

    fn load_grammar(&mut self, config_service_url: &str) {
        self.grammar.load(config_service_url);
    }

    fn parse_and_cache(&self, input: &str) -> String {
        if let Some(result) = self.cache.lock().unwrap().get(input) {
            result.clone()
        } else {
            let result = self.grammar.apply_to(input);
            self.cache.lock().unwrap().insert(input.to_string(), result.clone());
            result
        }
    }
}

struct ParsingEngine {
    parser: CachingParser,
}

impl ParsingEngine {
    fn new() -> Self {
        ParsingEngine { parser: CachingParser::new() }
    }

    fn load_grammar(&mut self, config_service_url: &str) {
        self.parser.load_grammar(config_service_url);
    }

    async fn parse_files(&self, file_paths: &[&str]) -> Vec<String> {
        let futures = file_paths.iter().map(|&file_path| {
            tokio::spawn(async move {
                match std::fs::read_to_string(file_path) {
                    Ok(content) => self.parser.parse_and_cache(&content),
                    Err(_) => "Error reading file".to_string(),
                }
            })
        });
        join_all(futures).await
    }

    fn generate_llvm_ir(&self, parsed_content: &str) -> String {
        let llvm_context = llvm::Context::create();
        let module = llvm::Module::new("ir_module", &llvm_context);
        // Simulate LLVM IR generation
        format!("Generated LLVM IR for: {}", parsed_content)
    }
}

#[tokio::main]
async fn main() {
    let mut engine = ParsingEngine::new();
    engine.load_grammar("config_service_url");
    let file_paths = vec!["input1.txt", "input2.txt"];
    let results = engine.parse_files(&file_paths).await;
    for result in results {
        println!("{}", engine.generate_llvm_ir(&result));
    }
}
