        }
    }
};

class RequestHandler {
public:
    RequestHandler(MockInterfaceTable& table, boost::asio::io_context& ioc)
        : table_(table), ioc_(ioc) {}

    void start(const std::string& url) {
        auto work = boost::make_shared<boost::asio::executor_work_guard<boost::asio::io_context::executor_type>>(ioc_.get_executor());
        std::thread([this, work]() mutable { ioc_.run(); }).detach();
        do_request(url);
    }

private:
    void do_request(const std::string& url) {
        tcp::resolver resolver(ioc_);
        http::request<http::string_body> req{http::verb::get, url, 11};
        req.set(http::field::host, "example.com");
        req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);

        resolver.async_resolve("example.com", "http", [this, &req](boost::system::error_code ec, tcp::resolver::results_type results) {
            if (ec) {
                std::cerr << "Resolver error: " << ec.message() << std::endl;
                return;
            }
            async_connect(results.begin(), results.end(), req, [this](const boost::system::error_code& err, tcp::endpoint, http::request<http::string_body>&& req) {
                if (err) {
                    std::cerr << "Connect error: " << err.message() << std::endl;
                    return;
                }
                async_send(req, [this](const boost::system::error_code& err, std::size_t bytes_transferred) {
                    if (err) {
                        std::cerr << "Send error: " << err.message() << std::endl;
                        return;
                    }
                    async_read_until(this->stream_, this->buf_, "\r\n", [this](const boost::system::error_code& err, std::size_t bytes_transferred) {
                        if (err) {
                            std::cerr << "Read error: " << err.message() << std::endl;
                            return;
                        }
                        // Process response
                        async_request(next_url());
                    });
                });
            });
        });
    }

    void async_request(const std::string& url) {
        if (!url.empty()) {
            do_request(url);
        } else {
            ioc_.stop();
        }
    }

private:
    MockInterfaceTable& table_;
    boost::asio::io_context& ioc_;
    tcp::resolver resolver;
    http::request<http::string_body> req;
    http::response<http::dynamic_body> res;
    tcp::socket socket{ioc_};
    boost::beast::flat_buffer buf_;
};

