using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Threading;
using System.Threading.Tasks;

public class QueryExecutor
{
    private readonly Dictionary<string, Task<IDataReader>> _cache = new Dictionary<string, Task<IDataReader>>();
    private readonly ILogger _logger;
    private readonly RetryStrategy _retryStrategy;

    public QueryExecutor(ILogger logger, RetryStrategy retryStrategy)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _retryStrategy = retryStrategy ?? throw new ArgumentNullException(nameof(retryStrategy));
    }

    public async Task<IDataReader> ExecuteComplexQueryAsync(
        List<object> values,
        SqlConnection connection,
        SqlCommand command,
        Func<SqlDataReader, Task> resultProcessor)
    {
        if (values == null || values.Count == 0)
            throw new ArgumentException("Values cannot be null or empty", nameof(values));
        if (connection == null) 
            throw new ArgumentNullException(nameof(connection));
        if (command == null) 
            throw new ArgumentNullException(nameof(command));
        if (resultProcessor == null) 
            throw new ArgumentNullException(nameof(resultProcessor));

        string cacheKey = GetCacheKey(values, command);

        if (_cache.ContainsKey(cacheKey))
            return await _cache[cacheKey];

        Task<IDataReader> resultTask;

        lock (_cache)
        {
            if (_cache.TryGetValue(cacheKey, out var existingTask))
                return await existingTask;
            else
                _cache[cacheKey] = resultTask = ExecuteQueryAsync(values, connection, command, resultProcessor);
        }

        return await resultTask;
    }

    private async Task<IDataReader> ExecuteQueryAsync(
        List<object> values,
        SqlConnection connection,
        SqlCommand command,
        Func<SqlDataReader, Task> resultProcessor)
    {
        using (var transaction = connection.BeginTransaction())
        {
            try
            {
                command.Connection = connection;
                command.Transaction = transaction;

                foreach (var value in values)
                    command.Parameters.AddWithValue("@", value);

                var resultTask = _retryStrategy.ExecuteAsync(async () =>
                {
                    await connection.OpenAsync();
                    using (var reader = await command.ExecuteReaderAsync())
                        return await reader.ReadAllAsync();
                });

                _logger.Log("Query executed successfully with parameters: " + string.Join(", ", values));
                return await resultTask;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to execute query with parameters: " + string.Join(", ", values));
                throw;
            }
        }
    }

    private string GetCacheKey(List<object> values, SqlCommand command)
    {
        return $"{command.CommandText}+{string.Join(",", values)}";
    }
}

public interface ILogger
{
    void Log(string message);
    void LogError(Exception ex, string message);
}

public class RetryStrategy
{
    public async Task<T> ExecuteAsync<T>(Func<Task<T>> action)
    {
        int retries = 3;
        TimeSpan delay = TimeSpan.FromSeconds(1);

        for (int i = 0; i < retries; i++)
        {
            try
            {
                return await action();
            }
            catch when (i < retries - 1)
            {
                _logger.Log($"Retry {i + 1} failed. Retrying in {delay.TotalSeconds}s...");
                await Task.Delay(delay);
            }
        }

        throw new Exception("Operation timed out after multiple retries.");
    }
}

public static class SqlExtensions
{
    public static async Task<DataTable> ReadAllAsync(this SqlDataReader reader)
    {
        var table = new DataTable();

        if (await reader.GetSchemaTableAsync() == null)
            return table;

        foreach (DataRow row in await reader.GetSchemaTableAsync().AsTask())
        {
            table.Columns.Add(row["ColumnName"].ToString(), Type.GetType(row["DataTypeName"].ToString()));
        }

        while (await reader.ReadAsync())
        {
            var DataRow = table.NewRow();

            for (int i = 0; i < reader.FieldCount; i++)
            {
                DataRow[i] = reader.GetValue(i);
            }

            table.Rows.Add(DataRow);
        }

        return table;
    }
}
