using System.Threading.Tasks;
using Consul;

public class GameServerManager
{
    private readonly IConsulClient _consulClient;
    private readonly List<GameServer> _servers;

    public GameServerManager()
    {
        _consulClient = new ConsulClient(c => c.Address = new Uri("http://localhost:8500"));
        _servers = new List<GameServer>();
    }

    public async Task InitializeServersAsync()
    {
        var catalogServiceResponse = await _consulClient.Catalog.ServiceList("game-server").ConfigureAwait(false);
        foreach (var serviceEntry in catalogServiceResponse.Response)
        {
            var server = new GameServer(serviceEntry.ServiceID, serviceEntry.ServiceAddress, serviceEntry.ServicePort);
            await server.LoadConfigurationAsync(_consulClient).ConfigureAwait(false);
            _servers.Add(server);
        }
    }

