using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml.XPath;

public class OrderService
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, ProductDetails> _cache;
    private readonly string _apiEndpoint;
    private readonly int _maxRequestsPerMinute;
    private DateTime _lastRequestTime = DateTime.MinValue;
    private int _requestCountThisMinute = 0;

    public OrderService(HttpClient httpClient, string apiEndpoint, int maxRequestsPerMinute)
    {
        _httpClient = httpClient;
        _cache = new ConcurrentDictionary<string, ProductDetails>();
        _apiEndpoint = apiEndpoint;
        _maxRequestsPerMinute = maxRequestsPerMinute;
    }

    public async Task<XElement> GetOrderAsync(Stream xmlStream)
    {
        var xpathResult = new XPathDocument(xmlStream).CreateNavigator().SelectSingleNode("//Order");
        if (xpathResult == null) throw new InvalidOperationException("No 'Order' element found in the XML document.");

        var orderId = xpathResult.GetAttribute("Id", "");
        if (string.IsNullOrEmpty(orderId)) throw new InvalidOperationException("'Order' element must have an 'Id' attribute.");

        ProductDetails productDetails;
        if (!_cache.TryGetValue(orderId, out productDetails))
        {
            await EnsureRequestQuotaAsync();
            productDetails = await FetchProductDetailsAsync(orderId);
            _cache.TryAdd(orderId, productDetails);
        }

        return new XElement(xpathResult.OuterXml)
        {
            { "ProductName", productDetails.Name },
            { "Price", productDetails.Price.ToString() }
        };
    }

    private async Task EnsureRequestQuotaAsync()
    {
        if (_requestCountThisMinute >= _maxRequestsPerMinute)
        {
            var timeSinceLastRequest = DateTime.Now - _lastRequestTime;
            if (timeSinceLastRequest.TotalSeconds < 60)
                await Task.Delay(60000 - (int)timeSinceLastRequest.TotalMilliseconds);
            _requestCountThisMinute = 0;
            _lastRequestTime = DateTime.Now;
        }
    }

    private async Task<ProductDetails> FetchProductDetailsAsync(string orderId)
    {
        var response = await _httpClient.GetAsync($"{_apiEndpoint}/{orderId}");
        if (!response.IsSuccessStatusCode) throw new InvalidOperationException("Failed to fetch product details from the API.");

        var content = await response.Content.ReadAsStringAsync();
        return JsonConvert.DeserializeObject<ProductDetails>(content);
    }
}

public class ProductDetails
{
    public string Name { get; set; }
    public decimal Price { get; set; }
}
