// Function to handle HTTP POST requests
void handlePOSTRequest(const std::string& sectionID, const std::string& elementID, const std::string& htmlContent) {
    // Lock for thread safety during update
    static std::mutex mutex;

    // Mutex lock guard
    std::lock_guard<std::mutex> lock(mutex);

    try {
        // Update external service API
        if (!updateExternalService(sectionID, elementID, htmlContent)) {
            throw std::runtime_error("Failed to update external service");
        }

        // Dynamically allocate memory for octree node
        std::unique_ptr<OctreeNode> newNode(new OctTreeNode(htmlContent));

        // Insert new or update existing node in octree
        if (!octree.insert(sectionID, elementID, std::move(newNode))) {
            throw std::runtime_error("Failed to insert/update node in octree");
        }

        // Cache the updated section for faster access
        cacheSection(sectionID, htmlContent);

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
}

// Asynchronous update function to handle high-concurrency
void asyncUpdate(const std::string& sectionID, const std::string& elementID, const std::string& htmlContent) {
    // Use a queue to enqueue updates
    static std::queue<std::tuple<std::string, std::string, std::string>> updateQueue;
    updateQueue.push(std::make_tuple(sectionID, elementID, htmlContent));

    // Process updates asynchronously
    std::thread([=]() {
        while (!updateQueue.empty()) {
            auto [sectionID, elementID, htmlContent] = updateQueue.front();
            updateQueue.pop();

            try {
                handlePOSTRequest(sectionID, elementID, htmlContent);
            } catch (const std::exception& e) {
                std::cerr << "Async error: " << e.what() << std::endl;
            }
        }
    }).detach();
}

