public class MoSTStateService {

    private static final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private static MoSTState cachedState = null;
    private static long lastRefreshTime = 0;
    private static final long REFRESH_INTERVAL = TimeUnit.MINUTES.toMillis(5); // Refresh every 5 minutes
    private static final long FRESHNESS_THRESHOLD = TimeUnit.HOURS.toMillis(1); // Cache is considered fresh for 1 hour

    public MoSTStateService() {
        scheduler.scheduleAtFixedRate(this::refreshState, REFRESH_INTERVAL, REFRESH_INTERVAL, TimeUnit.MILLISECONDS);
    }

    public synchronized MoSTState getState() throws IOException {
        long currentTime = System.currentTimeMillis();
        if (cachedState == null || currentTime - lastRefreshTime > FRESHNESS_THRESHOLD) {
            cachedState = loadFromStorageOrAPI();
            lastRefreshTime = currentTime;
        }
        return cachedState;
    }

    private synchronized void refreshState() {
        try {
            MoSTState newState = loadFromStorageOrAPI();
            if (newState != null && !newState.getClass().equals(cachedState.getClass())) {
                throw new IOException("Incorrect state class loaded from storage or API");
            }
            cachedState = newState;
            lastRefreshTime = System.currentTimeMillis();
        } catch (IOException e) {
            // Log error and handle exception gracefully
        }
    }

    private MoSTState loadFromStorageOrAPI() throws IOException {
        File file = new File("path/to/state/file");
        if (file.exists()) {
            try {
                return readStateFromFile(file);
            } catch (Exception e) {
                // Handle exception, possibly delete the file or log error
            }
        }

        // Fallback to API call
        return fetchStateFromAPI();
    }

