const fs = require('fs').promises;
const path = require('path');
const axios = require('axios');
const LRU = require('lru-cache');

// Configuration
const MAX_CONCURRENCY = 10;
const API_URL = 'https://api.example.com/validate';
const CACHE_MAX_SIZE = 500; // Cache for 500 unique file hashes
const RATE_LIMIT_MS = 100;

// Caching setup
const cache = new LRU({ max: CACHE_MAX_SIZE });

async function getMetadata(filePath) {
    const stats = await fs.stat(filePath);
    return {
        creationDate: stats.birthtime,
        lastModifiedDate: stats.mtime,
        size: stats.size,
        contentType: path.extname(filePath).toLowerCase()
    };
}

async function validateFileHash(fileHash) {
    if (cache.has(fileHash)) {
        return cache.get(fileHash);
    }

    const response = await axios.post(API_URL, { fileHash }, {
        headers: {
            'Content-Type': 'application/json'
        },
        timeout: RATE_LIMIT_MS
    });

    cache.set(fileHash, response.data.valid);

    return response.data.valid;
}

async function processFile(filePath) {
    try {
        const metadata = await getMetadata(filePath);
        const fileHash = // Function to extract hash from filePath
        const isValid = await validateFileHash(fileHash);

        if (!isValid) {
            console.warn(`Alert: Invalid file hash for ${filePath}`);
        }

        return { ...metadata, isValid };
    } catch (error) {
        console.error(`Error processing file ${filePath}:`, error);
        throw error;
    }
}

async function processDirectory(directoryPath) {
    try {
        const files = await fs.readdir(directoryPath);
        const promises = files.map(async (file) => {
            const filePath = path.join(directoryPath, file);
            return fs.stat(filePath).then(stat => {
                if (stat.isDirectory()) {
                    return processDirectory(filePath);
                } else {
                    return processFile(filePath);
                }
            });
        });

        return Promise.all(promises);
    } catch (error) {
        console.error(`Error processing directory ${directoryPath}:`, error);
        throw error;
    }
}

async function main() {
    const rootDirectory = 'path/to/your/directory';
    try {
        await processDirectory(rootDirectory);
        console.log('File processing complete');
    } catch (error) {
        console.error('Application failed:', error);
    }
}

main();
```

This code provides a basic structure for the asynchronous Node.js application described. It uses `fs.promises` for file operations, `axios` for API requests, and `lru-cache` for caching. The `processFile` function handles metadata extraction and hash validation, while `processDirectory` recursively processes all files and subdirectories within a given directory. Error handling and logging are implemented to ensure the application's robustness and performance monitoring.

To fully implement this solution, you would need to fill in the details of how to extract file hashes from file paths and define unit tests for individual components. Additionally, integration tests should be created to validate the end-to-end functionality of the application."]

