def analyze_sentiment(review, api_key):
    headers = {'Authorization': f'Bearer {api_key}'}
    response = requests.post(SENTIMENT_API_URL, json={'review': review}, headers=headers)
    if response.status_code != 200:
        logging.error(f"API request failed with status code: {response.status_code}")
        return None
    return response.json()

# Issue Categorization function
def categorize_issue(review):
    for category, patterns in BUG_PATTERNS.items():
        for pattern in patterns:
            if pattern in review.lower():
                return category
    return "unknown"

# Route to process reviews
