        issue_category = categorize_issue(review)
        logging.info(f"Review categorized as {issue_category} with sentiment: {sentiment_result}")
        return jsonify({'category': issue_category, 'sentiment': sentiment_result})
    else:
        return jsonify({'error': 'Failed to analyze review'}), 500

