class ScriptManager {
  constructor() {
    this.scripts = {};
    this.loadedScripts = new Set();
    this.scriptQueue = [];
    this.maxConcurrentLoads = 3;
    this.concurrentLoads = 0;
  }

  async fetchScriptMetadata(scriptKey) {
    try {
      const response = await fetch(`/api/scripts/${scriptKey}`);
      if (!response.ok) throw new Error('Network response was not ok');
      return response.json();
    } catch (error) {
      console.error(`Failed to fetch metadata for script ${scriptKey}:`, error);
      return { code: '' };
    }
  }

  async loadScript(scriptKey) {
    if (this.loadedScripts.has(scriptKey)) return;

    const scriptMetadata = await this.fetchScriptMetadata(scriptKey);

    this.scriptQueue.push(scriptKey);

    while (this.concurrentLoads < this.maxConcurrentLoads && this.scriptQueue.length > 0) {
      const currentScriptKey = this.scriptQueue.shift();
      this.executeScript(currentScriptKey, scriptMetadata);
    }
  }

  executeScript(scriptKey, scriptMetadata) {
    try {
      const scriptElement = document.createElement('script');
      scriptElement.type = 'text/javascript';
      scriptElement.innerHTML = scriptMetadata.code;
      document.body.appendChild(scriptElement);

      this.loadedScripts.add(scriptKey);
      this.concurrentLoads++;

      scriptElement.onload = () => {
        this.concurrentLoads--;
        if (this.scriptQueue.length > 0) {
          this.executeScript(this.scriptQueue.shift(), scriptMetadata);
        }
      };
    } catch (error) {
      console.error(`Failed to load script ${scriptKey}:`, error);
    }
  }

  async renderFooterScripts(scriptsConfig) {
    for (const script of scriptsConfig) {
      this.scripts[script.key] = script;
    }

    const allDependencies = new Set();
    Object.values(this.scripts).forEach(script => {
      if (script.dependencies) {
        script.dependencies.forEach(dep => allDependencies.add(dep));
      }
    });

    // Ensure dependencies are loaded before the scripts that depend on them
    for (const dep of Array.from(allDependencies)) {
      await this.loadScript(dep);
    }

    // Load and execute all scripts without dependencies
    const noDepScripts = Object.keys(this.scripts).filter(key => !this.scripts[key].dependencies);
    for (const scriptKey of noDepScripts) {
      await this.loadScript(scriptKey);
    }

    return '';
  }
}

// Usage example:
const scriptManager = new ScriptManager();
scriptManager.renderFooterScripts([
  { key: 'dep1', code: 'console.log("Dependency 1");' },
  { key: 'mainScript', code: 'console.log("Main script running.");', dependencies: ['dep1'] }
]).then(html => {
  document.body.innerHTML += html;
});
```']

