// resourceBundleLoader.js

const axios = require('axios');
const LRU = require('lru-cache');

const cache = new LRU({
  max: 500,
  ttl: 60 * 1000, // Cache for 1 minute
});

const fetchResourceBundle = async (url) => {
  try {
    const response = await axios.get(url);
    if (response.status !== 200) {
      throw new Error(`Server-side error: ${response.statusText}`);
    }
    return response.data;
  } catch (error) {
    console.error('Network error or server-side failure:', error);
    throw error;
  }
};

const validateResourceBundle = (resourceBundle) => {
  if (!Array.isArray(resourceBundle)) {
    throw new Error('Invalid resource bundle structure');
  }
  return resourceBundle.length;
};

const getResourceBundleCount = async (url, fallbackUrl) => {
  try {
    let resourceBundle = cache.get(url);
    if (!resourceBundle) {
      resourceBundle = await fetchResourceBundle(url);
      cache.set(url, resourceBundle);
    }
    return validateResourceBundle(resourceBundle);
  } catch (error) {
    console.error('Failed to load primary bundle, falling back:', error);
    try {
      const fallbackResourceBundle = await fetchResourceBundle(fallbackUrl);
      return validateResourceBundle(fallbackResourceBundle);
    } catch (fallbackError) {
      console.error('Failed to load fallback bundle:', fallbackError);
      throw error;
    }
  }
};

module.exports = {
  getResourceBundleCount,
};
