import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;

public class EventProcessor {
    private static final int MAX_RETRIES = 5;
    private static final long INITIAL_BACKOFF = 1000; // milliseconds
    private static final double BACKOFF_MULTIPLIER = 2.0;

    private final ExternalApi externalApi;
    private final ExecutorService executorService;
    private final BlockingQueue<Event> eventQueue;
    private final Map<Integer, Event> eventsMap;

    public EventProcessor(ExternalApi externalApi) {
        this.externalApi = externalApi;
        this.executorService = Executors.newCachedThreadPool();
        this.eventQueue = new LinkedBlockingQueue<>();
        this.eventsMap = Collections.synchronizedMap(new HashMap<>());
    }

    public void processEvents(List<Long> timestamps) {
        List<Event> events = timestamps.stream()
                .map(timestamp -> new Event(timestamp))
                .collect(Collectors.toList());

        for (Event event : events) {
            try {
                validateEvent(event);
                eventQueue.put(event);
            } catch (Exception e) {
                logError(e, event);
            }
        }

        executorService.execute(() -> processEventsInQueue());
    }

    private void validateEvent(Event event) throws Exception {
        int retryCount = 0;
        while (retryCount < MAX_RETRIES) {
            try {
                if (externalApi.validateTimestamp(event.getTimestamp())) {
                    return;
                }
            } catch (Exception e) {
                logError(e, event);
                retryCount++;
                long backoffTime = INITIAL_BACKOFF * Math.pow(BACKOFF_MULTIPLIER, retryCount);
                Thread.sleep(backoffTime);
            }
        }
        throw new Exception("Validation failed after " + MAX_RETRIES + " retries");
    }

    private void processEventsInQueue() {
        while (true) {
            Event event;
            try {
                event = eventQueue.take();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return;
            }

            if (!eventsMap.containsKey(event.getId())) {
                eventsMap.put(event.getId(), event);
                // Implement disjointness check and pair formation logic here
                System.out.println("Processing event: " + event);
            }
        }
    }

    private void logError(Exception e, Event event) {
        System.err.println("Error processing event " + event.getId() + ": " + e.getMessage());
        // Log error details with timestamp and stack trace
    }

    public static class Event {
        private final int id;
        private final long timestamp;

        public Event(long timestamp) {
            this.id = generateId();
            this.timestamp = timestamp;
        }

        public int getId() {
            return id;
        }

        public long getTimestamp() {
            return timestamp;
        }

        private static int generateId() {
            // Generate a unique ID for each event
            return new Random().nextInt(100000);
        }
    }

    public interface ExternalApi {
        boolean validateTimestamp(long timestamp) throws Exception;
    }
}
