use reqwest::{
    Client,
    header::{HeaderMap, HeaderName,HeaderValue},
    Error,
};
use tokio::time::{Duration, Instant};

pub struct HttpClient {
    client: Client,
    timeout: Duration,
    retry_policy: RetryPolicy,
}

impl HttpClient {
    pub fn new(timeout: Duration, retry_policy: RetryPolicy) -> Self {
        HttpClient {
            client: Client::new(),
            timeout,
            retry_policy,
        }
    }

    pub async fn get<T>(&self, url: &str, token: Option<&str>) -> Result<T, Error>
    where
        for<'de> T: serde::Deserialize<'de>,
    {
        let mut headers = HeaderMap::new();
        if let Some(token) = token {
            headers.insert(
                HeaderName::from_static("Authorization"),
                HeaderValue::from(format!("Bearer {}", token)),
            );
        }

        self.send_request(url, "GET", None, Some(headers), None).await
    }

    pub async fn post<T>(&self, url: &str, body: serde_json::Value, token: Option<&str>) -> Result<T, Error>
    where
        for<'de> T: serde::Deserialize<'de>,
    {
        let mut headers = HeaderMap::new();
        if let Some(token) = token {
            headers.insert(
                HeaderName::from_static("Authorization"),
                HeaderValue::from(format!("Bearer {}", token)),
            );
        }
        headers.insert(
            HeaderName::from_static("Content-Type"),
            HeaderValue::from("application/json"),
        );

        self.send_request(url, "POST", Some(&body), Some(headers), None).await
    }

    async fn send_request<T>(
        &self,
        url: &str,
        method: &str,
        body: Option<&serde_json::Value>,
        headers: Option<HeaderMap>,
        disable_ssl_verification: Option<bool>,
    ) -> Result<T, Error>
    where
        for<'de> T: serde::Deserialize<'de>,
    {
        let mut request = self.client.request(reqwest::Method::from(method), url);
        if let Some(headers) = headers {
            request = request.headers(headers);
        }
        if let Some(body) = body {
            request = request.json(body);
        }
        if let Some(disable_ssl_verification) = disable_ssl_verification {
            request = request.tls握手设置自定义TLS握手代码();
        }

        let start_time = Instant::now();
        while let Err(e) = self.retry_policy.apply(request.send().await, &self.timeout, start_time) {
            if e.is_request_error() || e.is_timeout() {
                return Err(e);
            }
            tokio::time::sleep(self.retry_policy.backoff()).await;
        }

        Ok(response.json().await?)
    }
}

pub struct RetryPolicy {
    max_retries: usize,
    initial_backoff: Duration,
    max_backoff: Duration,
}

impl RetryPolicy {
    pub fn new(max_retries: usize, initial_backoff: Duration, max_backoff: Duration) -> Self {
        RetryPolicy {
            max_retries,
            initial_backoff,
            max_backoff,
        }
    }

    async fn apply<F>(&self, f: F, timeout: &Duration, start_time: Instant) -> Result<reqwest::Response, Error>
    where
        F: FnOnce() -> reqwest::Result<reqwest::Response>,
    {
        let mut retries = 0;
        while retries < self.max_retries {
            match f().await {
                Ok(response) => {
                    if response.status().is_success() {
                        return Ok(response);
                    }
                }
                Err(e) if e.is_request_error() || e.is_timeout() => return Err(e),
                Err(_) => {}
            }

            retries += 1;
            let backoff = self.initial_backoff.mul_f32(2.0f32.powi(retries as i32 - 1))
                .clamp(self.initial_backoff, self.max_backoff);
            tokio::time::sleep(backoff).await;
        }

        Err(Error::new(reqwest::StatusCode::INTERNAL_SERVER_ERROR, "Max retries exceeded"))
    }
}

fn main() {
    let http_client = HttpClient::new(Duration::from_secs(10), RetryPolicy::new(3, Duration::from_secs(1), Duration::from_secs(5)));

    tokio::runtime::Runtime::new().unwrap().block_on(async move {
        match http_client.get::<serde_json::Value>("https://api.example.com/data", Some("your_token")).await {
            Ok(response) => println!("Response: {:?}", response),
            Err(e) => eprintln!("Error: {}", e),
        }
    });
}
```

