<?php

use GuzzleHttp\Client;
use Illuminate\Database\Capsule\Manager as Capsule;

class ClinicUpdateAPI {
    private $capsule;
    private $loggerClient;

    public function __construct(Capsule $capsule, Client $loggerClient) {
        $this->capsule = $capsule;
        $this->loggerClient = $loggerClient;
    }

    public function updateClinic($clinicId, $newStatus, $lastModifiedIp) {
        try {
            // Begin transaction
            $this->capsule->transaction(function () use ($clinicId, $newStatus, $lastModifiedIp) {
                $clinic = Clinic::findOrNew($clinicId);
                $clinic->status = $newStatus;
                $clinic->last_modified_ip = $lastModifiedIp;
                $clinic->updated_at = now();
                $clinic->save();

                // Log the update action
                $this->logUpdateAction($clinicId, $newStatus, $lastModifiedIp);
            });

            return [
                'status' => 'success',
                'message' => 'Clinic record updated successfully'
            ];
        } catch (\Exception $e) {
            return [
                'status' => 'error',
                'message' => 'Failed to update clinic record: ' . $e->getMessage()
            ];
        }
    }

    private function logUpdateAction($clinicId, $newStatus, $lastModifiedIp) {
        $this->loggerClient->post('/log', [
            'json' => [
                'action' => 'update',
                'data' => [
                    'clinic_id' => $clinicId,
                    'new_status' => $newStatus,
                    'last_modified_ip' => $lastModifiedIp
                ]
            ],
            'http_errors' => false // Prevent Guzzle from throwing exceptions on non-200 responses
        ]);
    }
}

// Usage example:
$capsule = new Capsule;
$capsule->addConnection([
    'driver' => 'mysql',
    'host' => env('DB_HOST', '127.0.0.1'),
    'database' => env('DB_DATABASE', 'forge'),
    'username' => env('DB_USERNAME', 'forge'),
    'password' => env('DB_PASSWORD', ''),
    'charset' => 'utf8mb4',
    'collation' => 'utf8mb4_unicode_ci',
    'prefix' => '',
]);
$capsule->setAsGlobal();
$capsule->bootEloquent();

$loggerClient = new Client(['base_uri' => 'https://logging-service.com/api/v1/']);

$api = new ClinicUpdateAPI($capsule, $loggerClient);
$result = $api->updateClinic(123, 'open', $_SERVER['REMOTE_ADDR']);
echo json_encode($result);
