["```php
<?php

namespace TokenLibrary;

use GuzzleHttp\Client;
use GuzzleHttp\Exception\RequestException;
use GuzzleHttp\Promise;
use Monolog\Logger;
use Monolog\Handler\StreamHandler;

class SecureTokenGenerator
{
    private $client;
    private $logger;
    private $idpUrl;
    private $retryLimit = 3;
    private $timeout = 5.0;
    private $circuitBreaker = false;

    public function __construct($idpUrl, $logPath)
    {
        $this->client = new Client([
            'base_uri' => $idpUrl,
            'timeout'  => $this->timeout,
        ]);

        $this->logger = new Logger('token_library');
        $this->logger->pushHandler(new StreamHandler($logPath, Logger::WARNING));
    }

    public function generateToken($length = 32, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789')
    {
        if ($this->circuitBreaker) {
            throw new \RuntimeException('Circuit breaker is open');
        }

        try {
            return Promise\settle($this->client->requestAsync('POST', '/generate-token', [
                'json' => ['length' => $length, 'charset' => $charset],
            ]))->wait(true)->getValueNow()->getBody()->getContents();
        } catch (RequestException $e) {
            if ($this->retryLimit > 0) {
                $this->retryLimit--;
                return $this->generateToken($length, $charset);
            }

            $this->circuitBreaker = true;
            throw new \RuntimeException('Failed to generate token', 0, $e);
        }
    }

    public function validateToken($token)
    {
        try {
            $response = $this->client->request('POST', '/validate-token', [
                'json' => ['token' => $token],
            ]);

            return (int)$response->getBody();
        } catch (RequestException $e) {
            $this->logger->error('Token validation failed: ' . $e->getMessage());
            return false;
        }
    }

    public function revokeToken($token)
    {
        try {
            $this->client->request('POST', '/revoke-token', [
                'json' => ['token' => $token],
            ]);

            return true;
        } catch (RequestException $e) {
            $this->logger->error('Token revocation failed: ' . $e->getMessage());
            return false;
        }
    }
}
```

This code snippet defines a `SecureTokenGenerator` class that encapsulates the functionality for generating, validating, and revoking secure tokens. It uses the Guzzle HTTP client to communicate with an external identity provider (IdP) for token operations. The class includes error handling, retry mechanisms, and circuit breaker patterns to manage transient errors gracefully. Additionally, it logs critical events for audit trails."]

