<?php

// Define custom exceptions
class PasswordValidationException extends Exception {}
class DatabaseConnectionException extends Exception {}
class InvalidUserIdException extends Exception {}

// DAO for database operations
class UserDAO {
    private $db;

    public function __construct($host, $dbname, $username, $password) {
        try {
            $this->db = new PDO("mysql:host=$host;dbname=$dbname", $username, $password);
            $this->db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        } catch (PDOException $e) {
            throw new DatabaseConnectionException($e->getMessage());
        }
    }

    public function updatePassword($userId, $newHashedPassword) {
        $stmt = $this->db->prepare("UPDATE users SET password = :password WHERE id = :id");
        return $stmt->execute(['password' => $newHashedPassword, 'id' => $userId]);
    }
}

// Main authentication service
class AuthService {
    private $userDAO;

    public function __construct($host, $dbname, $username, $password) {
        $this->userDAO = new UserDAO($host, $dbname, $username, $password);
    }

    public function updatePassword($userId, $newPassword) {
        if (!preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,20}$/', $newPassword)) {
            throw new PasswordValidationException("Password must be between 8-20 characters and include at least one uppercase letter, one lowercase letter, one digit, and one special character.");
        }

        if (password_verify($newPassword, $this->userDAO->getUserHashedPassword($userId))) {
            throw new InvalidUserIdException("New password cannot be the same as the current password.");
        }

        $newHashedPassword = password_hash($newPassword, PASSWORD_BCRYPT);
        return $this->userDAO->updatePassword($userId, $newHashedPassword);
    }
}

// Example usage
try {
    $authService = new AuthService('localhost', 'mydatabase', 'username', 'password');
    if ($authService->updatePassword(123, 'NewP@ssw0rd')) {
        echo "Password updated successfully.";
    } else {
        echo "Failed to update password.";
    }
} catch (Exception $e) {
    error_log(json_encode([
        'message' => $e->getMessage(),
        'code' => $e->getCode(),
        'file' => $e->getFile(),
        'line' => $e->getLine()
    ]));
    echo "An error occurred: " . $e->getMessage();
}
?>
