    virtual void applySpecialEffect(int id, int targetId) const = 0;
};

class Combatant {
public:
    Combatant(AttackDatabase& db, int id);
    ~Combatant();

    std::string selectAttack() const;

private:
    AttackDatabase& db_;
    int id_;
    int cooldown_{9};
    bool active_{true};
    mutable std::mutex mutex_;
    std::condition_variable cv_;
};

class CombatSystem {
public:
    explicit CombatSystem(AttackDatabase& db, size_t numCombatants);
    ~CombatSystem();

    void startCombat();
    void stopCombat();
    void resetCooldown(int combatantId);

private:
    AttackDatabase& db_;
    size_t numCombatants_;
    std::vector<std::unique_ptr<Combatant>> combatants_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;
    std::atomic<bool> running_{false};
};

// CombatSystem.cpp
#include "CombatSystem.hpp"

Combatant::Combatant(AttackDatabase& db, int id)
    : db_(db), id_(id) {}

Combatant::~Combatant() {
    // Cleanup resources if necessary
}

std::string Combatant::selectAttack() const {
    std::unique_lock<std::mutex> lock(mutex_);
    cv_.wait(lock, [this] { return active_ && cooldown_ == 0; });
    cooldown_ = 9;
    int attackId = db_.getAttackName(1); // Placeholder for random selection
    return db_.getAttackName(attackId);
}

CombatSystem::CombatSystem(AttackDatabase& db, size_t numCombatants)
    : db_(db), numCombatants_(numCombatants) {
    combatants_.resize(numCombatants_);
    for (size_t i = 0; i < numCombatants_; ++i) {
        combatants_[i] = std::make_unique<Combatant>(db, static_cast<int>(i));
    }
}

CombatSystem::~CombatSystem() {
    stopCombat();
}

void CombatSystem::startCombat() {
    running_ = true;
    for (auto& combatant : combatants_) {
        std::thread(&Combatant::selectAttack, combatant.get()).detach();
    }
}

void CombatSystem::stopCombat() {
    running_ = false;
    cv_.notify_all();
}

void CombatSystem::resetCooldown(int combatantId) {
    if (combatantId >= 0 && combatantId < numCombatants_) {
        std::lock_guard<std::mutex> lock(combatants_[combatantId]->mutex_);
        combatants_[combatantId]->cooldown_ = 9;
        combatants_[combatantId]->active_ = true;
    }
}

// Example usage
