using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading.Tasks;
using Serilog;

public class DynamicValueGenerator
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, (int Min, int Max)> _rangeCache;
    private readonly Timer _updateTimer;
    private readonly object _lock = new object();
    private Random _random;

    public DynamicValueGenerator(string apiEndpoint, int updateIntervalSeconds)
    {
        _httpClient = new HttpClient { BaseAddress = new Uri(apiEndpoint) };
        _rangeCache = new ConcurrentDictionary<string, (int Min, int Max)>();
        _updateTimer = new Timer(UpdateRangesAsync, null, TimeSpan.Zero, TimeSpan.FromSeconds(updateIntervalSeconds));
        _random = new Random();
    }

    public void SetSeed(int seed)
    {
        lock (_lock)
        {
            _random = new Random(seed);
        }
    }

    public int GenerateRandomInt(string rangeKey)
    {
        lock (_lock)
        {
            if (!_rangeCache.TryGetValue(rangeKey, out var range))
            {
                return 0; // Fallback to default range or handle error
            }
            return _random.Next(range.Min, range.Max);
        }
    }

    public float GenerateRandomFloat(string rangeKey)
    {
        lock (_lock)
        {
            if (!_rangeCache.TryGetValue(rangeKey, out var range))
            {
                return 0; // Fallback to default range or handle error
            }
            double diff = range.Max - range.Min;
            double scale = _random.NextDouble();
            return (float)(range.Min + (scale * diff));
        }
    }

    private async Task UpdateRangesAsync(object state)
    {
        try
        {
            var response = await _httpClient.GetAsync("api/ranges");
            if (response.IsSuccessStatusCode)
            {
                var ranges = await response.Content.ReadAsAsync<Dictionary<string, (int Min, int Max)>>();
                foreach (var range in ranges)
                {
                    _rangeCache[range.Key] = range.Value;
                }
            }
            else
            {
                Log.Error("Failed to fetch ranges from external service.");
            }
        }
        catch (Exception ex)
        {
            Log.Error(ex, "An error occurred while updating ranges.");
        }
    }

    public void ResetGenerator()
    {
        lock (_lock)
        {
            _random = new Random();
        }
    }

    ~DynamicValueGenerator()
    {
        _updateTimer.Dispose();
        _httpClient.Dispose();
    }
}
