    uint8_t* data;
    size_t size;
};

struct ResourceBundle {
    pthread_mutex_t lock;
    struct Resource** resources;
    size_t count;
    size_t capacity;
};

ResourceBundle* rb_load(const char* filename) {
    // Implement file loading and parsing logic
}

void rb_free(ResourceBundle* bundle) {
    pthread_mutex_lock(&bundle->lock);
    for (size_t i = 0; i < bundle->count; ++i) {
        free(bundle->resources[i]->key);
        free(bundle->resources[i]->data);
        free(bundle->resources[i]);
    }
    free(bundle->resources);
    pthread_mutex_unlock(&bundle->lock);
    pthread_mutex_destroy(&bundle->lock);
    free(bundle);
}

const Resource* rb_get(ResourceBundle* bundle, const char* key) {
    pthread_mutex_lock(&bundle->lock);
    for (size_t i = 0; i < bundle->count; ++i) {
        if (strcmp(bundle->resources[i]->key, key) == 0) {
            pthread_mutex_unlock(&bundle->lock);
            return bundle->resources[i];
        }
    }
    pthread_mutex_unlock(&bundle->lock);
    return NULL;
}

void rb_set(ResourceBundle* bundle, const char* key, const void* data, size_t size) {
    pthread_mutex_lock(&bundle->lock);
    for (size_t i = 0; i < bundle->count; ++i) {
        if (strcmp(bundle->resources[i]->key, key) == 0) {
            free(bundle->resources[i]->data);
            memcpy(bundle->resources[i]->data, data, size);
            bundle->resources[i]->size = size;
            pthread_mutex_unlock(&bundle->lock);
            return;
        }
    }
    // Implement logic to add new resource
    pthread_mutex_unlock(&bundle->lock);
}
