}

void logger_log(Logger *logger, const char *message) {
    pthread_mutex_lock(&logger->lock);
    // Simulate logging operation
    printf("Log: %s\n", message);
    pthread_mutex_unlock(&logger->lock);
}

char* processString(const char* input, size_t sizeLimit, bool padFlag, Logger *logger) {
    if (input == NULL || logger == NULL) {
        logger_log(logger, "Invalid input or logger object");
        return NULL;
    }

    size_t inputLen = strlen(input);

    if (inputLen <= sizeLimit) {
        if (!padFlag) {
            char *newString = malloc(inputLen + 2);
            if (newString == NULL) {
                logger_log(logger, "Memory allocation failed");
                return NULL;
            }
            strcpy(newString, input);
            newString[inputLen] = '\n';
            newString[inputLen + 1] = '\0';
            logger_log(logger, newString);
            return newString;
        } else {
            char *newString = malloc(sizeLimit + 2);
            if (newString == NULL) {
                logger_log(logger, "Memory allocation failed");
                return NULL;
            }
            strncpy(newString, input, sizeLimit);
            newString[sizeLimit] = ' ';
            newString[sizeLimit + 1] = '\0';
            logger_log(logger, newString);
            return newString;
        }
    } else {
        if (!padFlag) {
            char *newString = malloc(sizeLimit + 2);
            if (newString == NULL) {
                logger_log(logger, "Memory allocation failed");
                return NULL;
            }
            strncpy(newString, input, sizeLimit - 1);
            newString[sizeLimit - 1] = '\n';
            newString[sizeLimit] = '\0';
            logger_log(logger, newString);
            return newString;
        } else {
            char *newString = malloc(sizeLimit + 2);
            if (newString == NULL) {
                logger_log(logger, "Memory allocation failed");
                return NULL;
            }
            strncpy(newString, input, sizeLimit - 1);
            newString[sizeLimit - 1] = '\n';
            newString[sizeLimit] = ' ';
            newString[sizeLimit + 1] = '\0';
            logger_log(logger, newString);
            return newString;
        }
    }

    // Handle any other edge cases here
    logger_log(logger, "Unhandled case in processString");
    return NULL;
}
