#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Function prototypes
double calculate_moving_average(double values[], int count);
int parse_line(const char *line, double **values, int *count);
void append_average_to_line(char **line, double average);
void free_memory(char *line, double *values);

int main(int argc, char *argv[]) {
    // Check for arguments
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <log_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        double *values = NULL;
        int count = 0;

        if (parse_line(line, &values, &count) == 0) {
            // Calculate moving average
            double average = calculate_moving_average(values, count);

            // Append average to line
            append_average_to_line(&line, average);
        }

        // Free dynamically allocated memory
        free_memory(line, values);
    }

    if (ferror(file)) {
        perror("Error reading file");
    }
    fclose(file);
    free(line);

    return EXIT_SUCCESS;
}

double calculate_moving_average(double values[], int count) {
    if (count < 3) {
        return -1; // Not enough data
    }

    double sum = values[count - 1] + values[count - 2] + values[count - 3];
    return sum / 3;
}

int parse_line(const char *line, double **values, int *count) {
    // Assuming comma-separated format
    const char delimiters[] = ",";
    char *token = strtok(line, delimiters);
    *count = 0;

    while (token != NULL) {
        if (sscanf(token, "%lf", &(*values)[*count]) != 1) {
            fprintf(stderr, "Invalid data type or missing value\n");
            free(*values);
            *values = NULL;
            return -1;
        }
        (*count)++;
        token = strtok(NULL, delimiters);
    }

    // Dynamically allocate memory for values
    *values = realloc(*values, *count * sizeof(double));
    if (!*values) {
        perror("Failed to reallocate memory");
        return -1;
    }

    return 0;
}

void append_average_to_line(char **line, double average) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), ",%.2f", average);

    *line = realloc(*line, strlen(*line) + strlen(buffer) + 1);
    if (*line) {
        strcat(*line, buffer);
    }
}

void free_memory(char *line, double *values) {
    free(values);
    free(line);
}
