typedef struct {
    char filename[MAX_FILENAME_LENGTH];
    char new_filename[MAX_FILENAME_LENGTH];
    int valid_version;
} FileData;

sem_t semaphore;

void* process_file(void* arg) {
    FileData* file_data = (FileData*)arg;

    // Simulate metadata validation
    if (validate_version(file_data->filename, &file_data->valid_version)) {
        if (!file_data->valid_version) {
            increment_version(file_data);
        }
        rename_file(file_data);
        log_operation(file_data);
    } else {
        handle_error("Metadata service error", file_data->filename);
    }

    sem_post(&semaphore);
    pthread_exit(NULL);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        return EXIT_FAILURE;
    }

    DIR* dir = opendir(argv[1]);
    if (!dir) {
        perror("opendir");
        return EXIT_FAILURE;
    }

    FileData files[MAX_THREAD_COUNT];
    pthread_t threads[MAX_THREAD_COUNT];
    int file_count = 0;

    sem_init(&semaphore, 0, MAX_THREAD_COUNT);

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) {
            snprintf(files[file_count].filename, sizeof(files[file_count].filename), "%s/%s", argv[1], entry->d_name);
            files[file_count].new_filename[0] = '\0';
            files[file_count].valid_version = -1;

            if (pthread_create(&threads[file_count], NULL, process_file, &files[file_count])) {
                perror("pthread_create");
                return EXIT_FAILURE;
            }

            file_count++;
        }
    }

    closedir(dir);

    for (int i = 0; i < file_count; i++) {
        sem_wait(&semaphore);
    }

    for (int i = 0; i < file_count; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&semaphore);

    return EXIT_SUCCESS;
}

