        for (String filePath : filePaths) {
            executorService.submit(() -> executeOperation(filePath, operationType));
        }
        executorService.shutdown();
    }

    private void executeOperation(String filePath, OperationType operationType) {
        try {
            long startTime = System.currentTimeMillis();
            switch (operationType) {
                case COPY:
                    client.copyFile(filePath);
                    break;
                case MOVE:
                    client.moveFile(filePath);
                    break;
                case DELETE:
                    client.deleteFile(filePath);
                    break;
            }
            logDatabase.logSuccess(filePath, operationType, System.currentTimeMillis() - startTime);
        } catch (Exception e) {
            logDatabase.logFailure(filePath, operationType, e.getMessage());
            retryOperation(filePath, operationType, e);
        }
    }

