public class SecurityUtils
{
    public static int[] FindLargestInDecryptedMessage(string base64EncodedMessage, byte[] key, byte[] iv)
    {
        try
        {
            var decryptedBytes = DecryptBase64String(base64EncodedMessage, key, iv);
            if (decryptedBytes == null || decryptedBytes.Length == 0)
                return new int[0];

            string decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);
            var numbers = decryptedMessage.Split(new[] { ' ', ',', '.', '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries)
                                        .Select(int.Parse).ToArray();

            if (numbers.Length == 0)
                return new int[0];

            Array.Sort(numbers);
            Array.Reverse(numbers);

            return new[] { numbers[0] };
        }
        catch
        {
            return null;
        }
    }

    private static byte[] DecryptBase64String(string base64EncodedMessage, byte[] key, byte[] iv)
    {
        try
        {
            using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
            {
                tdes.Key = key;
                tdes.IV = iv;

                ICryptoTransform decryptor = tdes.CreateDecryptor(tdes.Key, tdes.IV);

                byte[] decryptedBytes = Convert.FromBase64String(base64EncodedMessage);
                using (MemoryStream msDecrypt = new MemoryStream(decryptedBytes))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                        {
                            return Encoding.UTF8.GetBytes(srDecrypt.ReadToEnd());
                        }
                    }
                }
            }
        }
        catch
        {
            return null;
        }
    }

