            foreach (var token in input.Split(new[] { ' ', ',', '.', '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries))
            {
                if (int.TryParse(token, out int number))
                    numbers.Add(number);
            }
        }

        var base64EncodedMessage = Convert.ToBase64String(Encoding.UTF8.GetBytes(string.Join(",", numbers)));
        var key = new byte[] { /* Triple DES key */ };
        var iv = new byte[] { /* IV */ };

