using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.Logging;

public class PasswordHasher
{
    private readonly IDistributedCache _cache;
    private readonly ILogger<PasswordHasher> _logger;

    public PasswordHasher(IDistributedCache cache, ILogger<PasswordHasher> logger)
    {
        _cache = cache;
        _logger = logger;
    }

    public async Task<string> HashPasswordAsync(string password, string username)
    {
        // Validate input
        if (string.IsNullOrEmpty(password) || string.IsNullOrEmpty(username))
        {
            throw new ArgumentException("Username and password cannot be null or empty.");
        }

        // Generate salt
        var salt = GenerateSalt();

        // Hash password with salt
        var hash = await HashPasswordWithSaltAsync(password, salt);

        // Store hash and username in cache
        await _cache.SetStringAsync($"{username}:hash", hash);
        await _cache.SetStringAsync($"{username}:salt", Convert.ToBase64String(salt));

        // Log audit event
        _logger.LogInformation("User {Username} password hashed successfully.", username);

        return hash;
    }

    private byte[] GenerateSalt()
    {
        var salt = new byte[16];
        using (var rng = RandomNumberGenerator.Create())
        {
            rng.GetBytes(salt);
        }
        return salt;
    }

    private async Task<string> HashPasswordWithSaltAsync(string password, byte[] salt)
    {
        using (var pbkdf2 = new Rfc2898DeriveBytes(password, salt, Convert.ToInt32(Environment.GetEnvironmentVariable("PBKDF2_ITERATIONS"))))
        {
            return BitConverter.ToString(pbkdf2.GetBytes(Convert.ToInt32(Environment.GetEnvironmentVariable("HASH_BYTE_SIZE")))).Replace("-", "");
        }
    }

    public async Task<bool> VerifyPasswordAsync(string password, string username)
    {
        // Retrieve hash and salt from cache
        var cachedHash = await _cache.GetStringAsync($"{username}:hash");
        var cachedSalt = Convert.FromBase64String(await _cache.GetStringAsync($"{username}:salt"));

        if (string.IsNullOrEmpty(cachedHash) || cachedSalt == null)
        {
            throw new InvalidOperationException("No password hash found for the given username.");
        }

        // Hash input password with retrieved salt
        var providedHash = await HashPasswordWithSaltAsync(password, cachedSalt);

        return cachedHash.Equals(providedHash, StringComparison.OrdinalIgnoreCase);
    }
}
