const express = require('express');
const crypto = require('crypto');
const aws4 = require('aws4');
const Queue = require('p-queue');

const app = express();
app.use(express.json());
const queue = new Queue({ concurrency: 5 });

const kmsCredentials = {
  accessKeyId: process.env.KMS_ACCESS_KEY_ID,
  secretAccessKey: process.env.KMS_SECRET_ACCESS_KEY,
};

async function encryptPassword(password) {
  const params = {
    KeyId: 'alias/your-kms-key-alias',
    Plaintext: password,
  };

  try {
    const response = await new Promise((resolve, reject) => {
      aws4.request('kms', params, kmsCredentials, (err, data) => {
        if (err) reject(err);
        else resolve(data.CiphertextBlob);
      });
    });

    return Buffer.from(response).toString('base64');
  } catch (error) {
    throw new Error(`Failed to encrypt password: ${error.message}`);
  }
}

async function modifyKickstartFile(configData, userInputs) {
  let modifiedConfig = configData;

  for (const [key, value] of Object.entries(userInputs)) {
    const regex = new RegExp(`\\${key}`, 'g');
    modifiedConfig = modifiedConfig.replace(regex, value);
  }

  try {
    const encryptedPassword = await encryptPassword(modifiedConfig.password);
    modifiedConfig.password = encryptedPassword;
    return modifiedConfig;
  } catch (error) {
    throw new Error(`Failed to modify Kickstart file: ${error.message}`);
  }
}

app.post('/modify-kickstart', async (req, res) => {
  const { configData, userInputs } = req.body;

  try {
    const result = await queue.add(() => modifyKickstartFile(configData, userInputs));
    res.status(200).json(result);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

module.exports = app;
