import abc
import json
import asyncio
import logging
from functools import lru_cache

# Setup basic configuration for logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class JSONModel(abc.ABC):
    @abc.abstractmethod
    def parse_json(self, data: dict) -> None:
        pass

    @abc.abstractmethod
    def to_json(self) -> str:
        pass

class Registry:
    _registry = {}
    _lock = asyncio.Lock()

    @staticmethod
    async def register(api_id: str, factory_func):
        async with Registry._lock:
            if api_id in Registry._registry:
                logger.warning(f"Factory for API ID {api_id} already registered.")
                return False
            Registry._registry[api_id] = factory_func
            return True

    @staticmethod
    async def get_json_model(api_id: str) -> JSONModel:
        if api_id not in Registry._registry:
            raise ValueError(f"No factory registered for API ID {api_id}")

        factory_func = Registry._registry[api_id]
        return await factory_func()

async def fetch_json_with_api_endpoint_id(api_endpoint_id, json_string):
    try:
        model_class = await Registry.get_json_model(api_endpoint_id)
        data = json.loads(json_string)
        model_instance = model_class()
        model_instance.parse_json(data)
        return model_instance.to_json()
    except ValueError as e:
        logger.error(f"Invalid API endpoint ID: {e}")
    except json.JSONDecodeError:
        logger.error("Malformed JSON")
    except Exception as e:
        logger.exception("An error occurred while fetching JSON")

@lru_cache(maxsize=128)
def slow_api_response():
    # Simulate a slow API response
    asyncio.sleep(5)
    return {"key": "value"}

class SlowAPIModel(JSONModel):
    def parse_json(self, data: dict) -> None:
        self.data = data

    def to_json(self) -> str:
        return json.dumps(self.data)

# Example usage
async def main():
    api_id = "slow_api"
    # Register factory function for the API ID
    await Registry.register(api_id, SlowAPIModel)

    # Fetch JSON model asynchronously
    result = await fetch_json_with_api_endpoint_id(api_id, json.dumps(slow_api_response()))
    print(result)

asyncio.run(main())
