using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;

public class OAuthTokenValidator : IDisposable
{
    private readonly HttpClient _httpClient;
    private JObject _validationRules;
    private DateTime _lastUpdate = DateTime.MinValue;
    private readonly object _lock = new object();

    public OAuthTokenValidator(string apiEndpoint)
    {
        _httpClient = new HttpClient();
        LoadValidationRules(apiEndpoint);
    }

    public async Task<bool> IsTokenValid(string jsonString)
    {
        JObject tokenData = JObject.Parse(jsonString);

        if (DateTime.Now - _lastUpdate > TimeSpan.FromMinutes(1))
        {
            lock (_lock)
            {
                if (DateTime.Now - _lastUpdate > TimeSpan.FromMinutes(1))
                {
                    await LoadValidationRules();
                }
            }
        }

        // Perform token validation using the current rules
        return ValidateToken(tokenData, _validationRules);
    }

    private async Task LoadValidationRules(string apiEndpoint = null)
    {
        try
        {
            string endpoint = apiEndpoint ?? "https://api.example.com/validate";
            HttpResponseMessage response = await _httpClient.GetAsync(endpoint);
            if (response.IsSuccessStatusCode)
            {
                string jsonContent = await response.Content.ReadAsStringAsync();
                JObject newRules = JObject.Parse(jsonContent);

                lock (_lock)
                {
                    _validationRules = newRules;
                    _lastUpdate = DateTime.Now;
                }
            }
        }
        catch
        {
            // Fallback to default rules or existing rules on error
        }
    }

    private bool ValidateToken(JObject tokenData, JObject rules)
    {
        foreach (JProperty rule in rules.Properties())
        {
            string tokenValue = tokenData[rule.Name]?.ToString();
            if (!string.IsNullOrEmpty(tokenValue) && !tokenValue.Equals(rule.Value.ToString()))
            {
                return false;
            }
        }

        return true;
    }

    public void Dispose()
    {
        _httpClient.Dispose();
    }
}
