#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <string.h>

// Define semaphore pool structure
typedef struct {
    sem_t *semaphores;
    int count;
} SemaphorePool;

// Initialize semaphore pool
SemaphorePool* init_semaphore_pool(int num_semaphores) {
    SemaphorePool *pool = (SemaphorePool*)malloc(sizeof(SemaphorePool));
    if (pool == NULL) {
        perror("Failed to allocate memory for semaphore pool");
        return NULL;
    }
    pool->count = num_semaphores;
    pool->semaphores = (sem_t*)calloc(num_semaphores, sizeof(sem_t));
    if (pool->semaphores == NULL) {
        perror("Failed to allocate memory for semaphores");
        free(pool);
        return NULL;
    }
    for (int i = 0; i < num_semaphores; i++) {
        if (sem_init(&pool->semaphores[i], 0, 1) != 0) {
            perror("Failed to initialize semaphore");
            for (int j = 0; j < i; j++) {
                sem_destroy(&pool->semaphores[j]);
            }
            free(pool->semaphores);
            free(pool);
            return NULL;
        }
    }
    return pool;
}

// Destroy semaphore pool
void destroy_semaphore_pool(SemaphorePool *pool) {
    if (pool != NULL) {
        for (int i = 0; i < pool->count; i++) {
            sem_destroy(&pool->semaphores[i]);
        }
        free(pool->semaphores);
        free(pool);
    }
}

// Acquire semaphore
void acquire_semaphore(SemaphorePool *pool, int index) {
    if (index >= 0 && index < pool->count) {
        sem_wait(&pool->semaphores[index]);
    } else {
        fprintf(stderr, "Invalid semaphore index\n");
    }
}

// Release semaphore
void release_semaphore(SemaphorePool *pool, int index) {
    if (index >= 0 && index < pool->count) {
        sem_post(&pool->semaphores[index]);
    } else {
        fprintf(stderr, "Invalid semaphore index\n");
    }
}
