#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <errno.h>
#include <pthread.h>

typedef struct {
    char *buffer;
    size_t capacity;
    size_t length;
} StringPool;

StringPool stringPool = {NULL, 0, 0};

void initStringPool(size_t initialCapacity) {
    stringPool.capacity = initialCapacity;
    stringPool.length = 0;
    stringPool.buffer = (char *)malloc(initialCapacity);
    if (!stringPool.buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void destroyStringPool() {
    free(stringPool.buffer);
    stringPool.capacity = 0;
    stringPool.length = 0;
    stringPool.buffer = NULL;
}

char *allocateString(size_t size) {
    if (stringPool.length + size > stringPool.capacity) {
        size_t newCapacity = stringPool.capacity == 0 ? 128 : stringPool.capacity * 2;
        while (newCapacity < stringPool.length + size) {
            newCapacity *= 2;
        }
        char *newBuffer = (char *)realloc(stringPool.buffer, newCapacity);
        if (!newBuffer) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        stringPool.capacity = newCapacity;
    }
    char *result = stringPool.buffer + stringPool.length;
    stringPool.length += size;
    return result;
}

void logString(const char *input, bool padFlag) {
    printf("Logging: %s\n", input);
}

char* processString(const char* input, size_t sizeLimit, bool padFlag) {
    if (input == NULL) {
        fprintf(stderr, "Input string is null\n");
        return NULL;
    }

    size_t length = strlen(input);

    if (!padFlag && length <= sizeLimit) {
        char *result = allocateString(length + 1);
        strcpy(result, input);
        result[length] = '\n';
        logString(result, false);
        return result;
    } else if (length > sizeLimit && padFlag) {
        char *result = allocateString(sizeLimit + 1);
        strncpy(result, input, sizeLimit);
        for (size_t i = length; i < sizeLimit; ++i) {
            result[i] = ' ';
        }
        result[sizeLimit] = '\n';
        logString(result, true);
        return result;
    } else if (length > sizeLimit && !padFlag) {
        char *result = allocateString(sizeLimit + 2);
        strncpy(result, input, sizeLimit);
        result[sizeLimit] = '\n';
        result[sizeLimit + 1] = '\0';
        logString("ERROR: Truncated string logged\n", false);
        return result;
    } else {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }
}

int main() {
    initStringPool(1024 * 1024); // Initialize memory pool for 1 MB

    char* result = processString("Hello, World!", 13, true);
    if (result != NULL) {
        free(result); // Free allocated string
    }

    destroyStringPool(); // Clean up memory pool
    return 0;
}
```

