public class CloudStorageGateway {
    private Map<String, CloudStorageProvider> providers;

    public CloudStorageGateway() {
        this.providers = new HashMap<>();
    }

    // Method to add a cloud storage provider dynamically
    public void addProvider(CloudStorageProvider provider) {
        providers.put(provider.getName(), provider);
    }

    // Method to remove a cloud storage provider dynamically
    public void removeProvider(String providerName) {
        providers.remove(providerName);
    }

    // Method to upload a file to the appropriate provider based on file type and configuration
    public boolean uploadFile(String providerName, String filePath) {
        CloudStorageProvider provider = providers.get(providerName);
        if (provider != null && provider.supportsFileType(filePath)) {
            return provider.uploadFile(filePath);
        }
        return false;
    }

    // Method to download a file from the appropriate provider
    public boolean downloadFile(String providerName, String filePath) {
        CloudStorageProvider provider = providers.get(providerName);
        if (provider != null) {
            return provider.downloadFile(filePath);
        }
        return false;
    }

    // Method to synchronize files across multiple providers
    public void syncFiles() {
        for (CloudStorageProvider provider : providers.values()) {
            provider.sync();
        }
    }
}

