#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int device_id;
    float signal_strength;
    int *error_codes;
    int error_count;
} DeviceStatusReport;

typedef struct {
    DeviceStatusReport **reports;
    int count;
    pthread_mutex_t mutex;
} DeviceManager;

DeviceManager* create_device_manager() {
    DeviceManager* manager = (DeviceManager*)malloc(sizeof(DeviceManager));
    manager->reports = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroy_device_manager(DeviceManager* manager) {
    for (int i = 0; i < manager->count; i++) {
        free(manager->reports[i]->error_codes);
        free(manager->reports[i]);
    }
    free(manager->reports);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void add_device_report(DeviceManager* manager, DeviceStatusReport* report) {
    pthread_mutex_lock(&manager->mutex);
    manager->reports = realloc(manager->reports, (manager->count + 1) * sizeof(DeviceStatusReport*));
    manager->reports[manager->count] = report;
    manager->count++;
    pthread_mutex_unlock(&manager->mutex);
}

void remove_device_report(DeviceManager* manager, int device_id) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->count; i++) {
        if (manager->reports[i]->device_id == device_id) {
            free(manager->reports[i]->error_codes);
            free(manager->reports[i]);
            for (; i < manager->count - 1; i++) {
                manager->reports[i] = manager->reports[i + 1];
            }
            manager->reports = realloc(manager->reports, manager->count * sizeof(DeviceStatusReport*));
            manager->count--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

// Add more functions as needed for other operations
