int main(int argc, char* argv[]) {
    if (argc < 7) {
        printf("Usage: %s <log_file1> <output_report1> <metric_id1> <threshold_value1> ... <log_fileN> <output_reportN> <metric_idN> <threshold_valueN>\n", argv[0]);
        return 1;
    }

    LogConfig config[MAX_LOG_FILES];
    int num_logs = (argc - 1) / 4;

    for (int i = 0; i < num_logs; i++) {
        config[i].log_file = argv[(i * 4) + 1];
        config[i].output_report = argv[(i * 4) + 2];
        config[i].metric_id = atoi(argv[(i * 4) + 3]);
        config[i].threshold_value = atof(argv[(i * 4) + 4]);
    }

    pthread_t threads[MAX_THREADS];
    int thread_index = 0;

    for (int i = 0; i < num_logs; i++) {
        if (thread_index >= MAX_THREADS) {
            printf("Exceeded maximum number of concurrent threads\n");
            break;
        }
        pthread_create(&threads[thread_index], NULL, process_log, &config[i]);
        thread_index++;
    }

    for (int i = 0; i < thread_index; i++) {
        pthread_join(threads[i], NULL);
    }

