import java.io.IOException;
import java.net.URI;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class FaultTolerantLoggingSystem {

    private static final int MAX_LOGS_PER_MINUTE = 100_000;
    private static final int RETRY_LIMIT = 5;
    private static final long INITIAL_RETRY_DELAY = 100; // milliseconds
    private static final double BACKOFF_FACTOR = 2.0;

    private final ConcurrentLinkedQueue<ErrorLogEntry> logQueue = new ConcurrentLinkedQueue<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private boolean isCircuitOpen = false;
    private long lastRetryAttemptTime = System.currentTimeMillis();
    private int retryCount = 0;

    public FaultTolerantLoggingSystem() {
        scheduler.scheduleAtFixedRate(this::processLogs, 0, 5, TimeUnit.SECONDS); // Process logs every 5 seconds
    }

    public void logError(ErrorLogEntry errorLog) {
        if (!isCircuitOpen && !logQueue.offer(errorLog)) {
            System.err.println("Log queue is full. Error details discarded.");
        }
    }

    private void processLogs() {
        while (shouldProcess()) {
            ErrorLogEntry log = logQueue.poll();
            if (log != null) {
                try {
                    sendToExternalService(log);
                    retryCount = 0;
                } catch (IOException e) {
                    handleRetry(e, System.currentTimeMillis());
                }
            }
        }
    }

    private boolean shouldProcess() {
        return !isCircuitOpen && logQueue.size() > 0;
    }

    private void sendToExternalService(ErrorLogEntry log) throws IOException {
        // Simulate sending log to external service
        URI uri = URI.create("https://example.com/error-log");
        // Use HTTP client library to send POST request with JSON payload
        // Example: HttpClient.newHttpClient().send(HttpRequest.newBuilder().uri(uri).POST(HttpRequest.BodyPublishers.ofString(log.toJson())).build(), HttpResponse.BodyHandlers.ofString());
    }

    private void handleRetry(IOException e, long currentTime) {
        if (retryCount < RETRY_LIMIT && System.currentTimeMillis() - lastRetryAttemptTime > calculateNextRetryDelay()) {
            retryCount++;
            lastRetryAttemptTime = currentTime;
            // Retry sending the log
        } else {
            openCircuit();
            reportError(e);
        }
    }

    private long calculateNextRetryDelay() {
        return (long) (INITIAL_RETRY_DELAY * Math.pow(BACKOFF_FACTOR, retryCount));
    }

    private void openCircuit() {
        isCircuitOpen = true;
        scheduler.schedule(this::closeCircuit, 30, TimeUnit.SECONDS); // Close circuit after 30 seconds
    }

    private void closeCircuit() {
        isCircuitOpen = false;
    }

    private void reportError(IOException e) {
        // Log the error or send an alert
        System.err.println("Failed to log error: " + e.getMessage());
    }
}

class ErrorLogEntry {
    private long timestamp;
    private String severityLevel;
    private int errorCode;
    private String errorMessage;
    private String metadata;

    public ErrorLogEntry(long timestamp, String severityLevel, int errorCode, String errorMessage, String metadata) {
        this.timestamp = timestamp;
        this.severityLevel = severityLevel;
        this.errorCode = errorCode;
        this.errorMessage = errorMessage;
        this.metadata = metadata;
    }

    public String toJson() {
        // Convert log entry to JSON string
        return "{\"timestamp\": \"" + timestamp + "\", \"severityLevel\": \"" + severityLevel + "\", \"errorCode\": " + errorCode + ", \"errorMessage\": \"" + errorMessage + "\", \"metadata\": \"" + metadata + "\"}";
    }
}
