import os
from kubernetes import client, config
from ruamel.yaml import YAML

class KubernetesManifestProcessor:
    def __init__(self, kube_config_path):
        self.kube_config_path = kube_config_path
        self.yaml = YAML()

    def load_kube_config(self):
        config.load_kube_config(config_file=self.kube_config_path)

    def load_manifests(self, directory):
        manifests = []
        for root, _, files in os.walk(directory):
            for file in files:
                if file.endswith('.yaml') or file.endswith('.yml'):
                    with open(os.path.join(root, file), 'r') as f:
                        manifest = self.yaml.load(f)
                        manifests.append(manifest)
        return manifests

    def inject_environment_values(self, manifests, environment_values):
        for manifest in manifests:
            for key, value in environment_values.items():
                if isinstance(manifest, dict) and key in manifest:
                    manifest[key] = value
                elif isinstance(manifest, list):
                    for item in manifest:
                        if isinstance(item, dict) and key in item:
                            item[key] = value
        return manifests

    def apply_manifests(self, manifests):
        api_instance = client.CoreV1Api()
        for manifest in manifests:
            try:
                resp = api_instance.create_namespaced_pod(
                    body=manifest,
                    namespace='default'
                )
                print("Pod created. status='%s'" % str(resp.status))
            except client.rest.ApiException as e:
                print("Exception when calling CoreV1Api->create_namespaced_pod: %s\n" % e)

    def process_manifests(self, directory, environment_values):
        self.load_kube_config()
        manifests = self.load_manifests(directory)
        updated_manifests = self.inject_environment_values(manifests, environment_values)
        self.apply_manifests(updated_manifests)

if __name__ == "__main__":
    processor = KubernetesManifestProcessor(kube_config_path='~/.kube/config')
    processor.process_manifests('manifests', {'env': 'production', 'region': 'us-east-1'})
```

