import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class PokemonReportService {
    private ExecutorService executorService = Executors.newFixedThreadPool(10);
    private RedisCache cache = new RedisCache();
    private ThirdPartyApi thirdPartyApi = new ThirdPartyApi();

    public Future<PokemonReport> getPokemonReport(String pokemonId) {
        return executorService.submit(() -> {
            if (cache.contains(pokemonId)) {
                return cache.get(pokemonId);
            } else {
                PokemonReport report = fetchFromThirdParty(pokemonId);
                cache.put(pokemonId, report);
                return report;
            }
        });
    }

    private PokemonReport fetchFromThirdParty(String pokemonId) {
        try {
            return thirdPartyApi.fetchData(pokemonId);
        } catch (Exception e) {
            throw new RuntimeException("Failed to fetch data from external API", e);
        }
    }
}
