#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>

// Function to encrypt data
int encrypt_data(const unsigned char *plaintext, int plaintext_len,
                 const unsigned char *key, const unsigned char *iv,
                 unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    // Create and initialize the context
    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        return -1;

    // Provide the message to be encrypted, and obtain the encrypted output.
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        return -1;
    ciphertext_len = len;

    // Finalize the encryption
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        return -1;
    ciphertext_len += len;

    // Clean up
    EVP_CIPHER_CTX_free(ctx);

    return ciphertext_len;
}

// Function to decrypt data
int decrypt_data(const unsigned char *ciphertext, int ciphertext_len,
                 const unsigned char *key, const unsigned char *iv,
                 unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int plaintext_len;

    // Create and initialize the context
    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        return -1;

    // Provide the message to be decrypted, and obtain the plaintext output.
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len))
        return -1;
    plaintext_len = len;

    // Finalize the decryption
    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len))
        return -1;
    plaintext_len += len;

    // Clean up
    EVP_CIPHER_CTX_free(ctx);

    return plaintext_len;
}

// Function to sign data
int sign_data(const unsigned char *data, int datalen,
              const unsigned char *key, unsigned char *signature) {
    EVP_PKEY *pkey = NULL;
    int siglen;

    // Load the private key
    if (!(pkey = PEM_read_PrivateKey(NULL, NULL, NULL, (void *)key)))
        return -1;

    // Sign the data
    if (!EVP_SignInit_ex(NULL, EVP_sha256(), NULL))
        return -1;
    if (!EVP_SignUpdate(NULL, data, datalen))
        return -1;
    if (!EVP_SignFinal(NULL, signature, &siglen, pkey))
        return -1;

    // Clean up
    EVP_PKEY_free(pkey);

    return siglen;
}

// Function to verify signature
int verify_signature(const unsigned char *data, int datalen,
                     const unsigned char *signature, int siglen,
                     const unsigned char *pubkey) {
    EVP_PKEY *pkey = NULL;

    // Load the public key
    if (!(pkey = PEM_read_PUBKEY(NULL, NULL, NULL, (void *)pubkey)))
        return -1;

    // Verify the signature
    if (!EVP_VerifyInit_ex(NULL, EVP_sha256(), NULL))
        return -1;
    if (!EVP_VerifyUpdate(NULL, data, datalen))
        return -1;
    int result = EVP_VerifyFinal(NULL, signature, siglen, pkey);

    // Clean up
    EVP_PKEY_free(pkey);

    return result == 1 ? 0 : -1; // Return 0 for success, -1 for failure
}
