// main.rs

use std::error::Error;
use std::sync::{Arc, Mutex};
use tokio::task;

mod grammar_loader;
mod parser;
mod llvm_ir_generator;
mod error_handler;
mod resource_manager;
mod concurrency_manager;
mod user_interface;
mod testing;

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    let grammar_service_url = "http://example.com/grammar";
    let config_pool_size = 10;
    let max_thread_count = 8;

    // Initialize components
    let grammar_loader = Arc::new(Mutex::new(grammar_loader::GrammarLoader::new(grammar_service_url)));
    let parser = Arc::new(parser::Parser::new());
    let llvm_ir_generator = Arc::new(llvm_ir_generator::LLVMIRGenerator::new());
    let error_handler = Arc::new(error_handler::ErrorHandler::new());
    let resource_manager = Arc::new(resource_manager::ResourceManager::new(max_thread_count));
    let concurrency_manager = Arc::new(concurrency_manager::ConcurrencyManager::new(config_pool_size, max_thread_count));

    // Load initial grammars
    grammar_loader.lock().unwrap().load_grammars().await?;

    // Start processing files concurrently
    let input_files = vec!["file1.txt", "file2.txt"];
    for file in input_files {
        let grammar_loader_clone = grammar_loader.clone();
        let parser_clone = parser.clone();
        let llvm_ir_generator_clone = llvm_ir_generator.clone();
        let error_handler_clone = error_handler.clone();
        let resource_manager_clone = resource_manager.clone();
        let concurrency_manager_clone = concurrency_manager.clone();

        task::spawn(async move {
            if let Err(e) = process_file(
                grammar_loader_clone,
                parser_clone,
                llvm_ir_generator_clone,
                error_handler_clone,
                resource_manager_clone,
                concurrency_manager_clone,
                file
            ).await {
                eprintln!("Error processing file {}: {}", file, e);
            }
        });
    }

    // Wait for all tasks to complete
    task::block_on(async move {
        while let Some(_) = task::yield_now().await {}
    });

    Ok(())
}

async fn process_file(
    grammar_loader: Arc<Mutex<grammar_loader::GrammarLoader>>,
    parser: Arc<parser::Parser>,
    llvm_ir_generator: Arc<llvm_ir_generator::LLVMIRGenerator>,
    error_handler: Arc<error_handler::ErrorHandler>,
    resource_manager: Arc<resource_manager::ResourceManager>,
    concurrency_manager: Arc<concurrency_manager::ConcurrencyManager>,
    file_path: &str
) -> Result<(), Box<dyn Error>> {
    let grammar = grammar_loader.lock().unwrap().get_grammar(file_path)?;
    let input_data = parser.parse_file(file_path)?;
    let llvm_ir_code = llvm_ir_generator.generate_llvm_ir(input_data, &grammar)?;

    // Simulate generating and saving LLVM IR code
    resource_manager.save_llvm_ir(llvm_ir_code, file_path)?;
    concurrency_manager.notify_completion();

    Ok(())
}
