// Define the Node structure
struct Node {
    int id;
    int value;
    Node* next;
    Node* prev;

    Node(int id, int value) : id(id), value(value), next(nullptr), prev(nullptr) {}
};

class DoublyLinkedList {
private:
    std::mutex listMutex;
    Node* head;
    Node* tail;
    std::unordered_map<int, Node*> nodeMap;
    size_t maxSize;
    std::queue<std::string> logQueue;
    std::mutex logMutex;
    std::atomic<bool> running;

public:
    DoublyLinkedList(size_t maxSize) : head(nullptr), tail(nullptr), maxSize(maxSize), running(true) {}

    ~DoublyLinkedList() {
        clearList();
    }

    void insertOrUpdateNode(int id, int value) {
        std::lock_guard<std::mutex> lock(listMutex);
        if (nodeMap.find(id) != nodeMap.end()) {
            // Node already exists, update the value
            Node* node = nodeMap[id];
            node->value = value;
        } else {
            // Node does not exist, create a new one
            Node* newNode = new Node(id, value);
            if (head == nullptr) {
                head = tail = newNode;
            } else {
                tail->next = newNode;
                newNode->prev = tail;
                tail = newNode;
            }
            nodeMap[id] = newNode;
        }
    }

    void logOperation(const std::string& message) {
        std::lock_guard<std::mutex> lock(logMutex);
        logQueue.push(message);
    }

    // Other methods for list operations like deleteNode, traverseList, etc.
};

// Example usage
int main() {
    DoublyLinkedList list(100);
    list.insertOrUpdateNode(1, 10);
    list.logOperation("Insert or update node with id 1 and value 10");

    return 0;
}
