import random
from concurrent.futures import ThreadPoolExecutor
import time
import threading
import json
import gzip
import os

class MersenneTwisterRNG:
    def __init__(self):
        self.mt = [0] * 624
        self.index = 625

    def seed(self, seed=None):
        if seed is None:
            seed = int(time.time())
        self.mt[0] = seed
        for i in range(1, 624):
            self.mt[i] = (1812739487 * (self.mt[i - 1] ^ (self.mt[i - 1] >> 30)) + i) & 0xFFFFFFFF

    def next_uint(self):
        if self.index == 625:
            self.twist()
        y = self.mt[self.index]
        y ^= (y >> 11)
        y ^= ((y << 7) & 0x9D2C5680)
        y ^= ((y << 15) & 0xEFC60000)
        y ^= (y >> 18)
        self.index += 1
        return y

    def next_float(self):
        return self.next_uint() / 4294967296.0

    def twist(self):
        for i in range(624):
            y = (self.mt[i] & 0x80000000) + (self.mt[(i + 1) % 624] & 0x7FFFFFFF)
            self.mt[i] = self.mt[(i + 397) % 624] ^ (y >> 1)
            if y % 2 != 0:
                self.mt[i] ^= 0x9908B0DF
        self.index = 0

