class Client:
    def __init__(self, client_id, rng, log_file_path, max_log_entries=50000):
        self.client_id = client_id
        self.rng = rng
        self.log_file_path = log_file_path
        self.max_log_entries = max_log_entries
        self.logs = []

    def request_random_numbers(self, count):
        numbers = [self.rng.next_float() for _ in range(count)]
        self.log_requests(numbers)
        return numbers

    def log_requests(self, numbers):
        current_time = time.time()
        logs = [(current_time, number, self.client_id) for number in numbers]
        self.logs.extend(logs)
        if len(self.logs) > self.max_log_entries:
            self.logs = self.logs[-self.max_log_entries:]
        self.save_logs()

    def save_logs(self):
        with gzip.open(self.log_file_path, 'at') as f:
            for log in self.logs:
                f.write(json.dumps(log) + '\n')

