using System;
using System.Collections.Concurrent;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public interface IQueryExecutionService
{
    Task<IDataReader> ExecuteQueryAsync(string connectionString, string sqlCommand, IEnumerable<object> parameters, Func<IDataReader, Task> resultProcessor);
}

public class QueryExecutionService : IQueryExecutionService
{
    private readonly ConcurrentDictionary<string, Func<SqlCommand, Task>> _cache = new();
    private readonly int _maxCacheSize;
    private readonly TimeSpan _evictionInterval;

    public QueryExecutionService(int maxCacheSize, TimeSpan evictionInterval)
    {
        _maxCacheSize = maxCacheSize;
        _evictionInterval = evictionInterval;
        StartEvictionTask();
    }

    private void StartEvictionTask()
    {
        _ = Task.Run(async () =>
        {
            while (true)
            {
                await Task.Delay(_evictionInterval);
                var keysToRemove = _cache.Keys.Where(key => DateTime.Now - _cache[key]!.Target.GetCreationTime() > _evictionInterval).ToList();
                foreach (var key in keysToRemove)
                {
                    _cache.TryRemove(key, out _);
                }
            }
        });
    }

    public async Task<IDataReader> ExecuteQueryAsync(string connectionString, string sqlCommand, IEnumerable<object> parameters, Func<IDataReader, Task> resultProcessor)
    {
        var cacheKey = $"{connectionString}|{sqlCommand}";
        if (_cache.TryGetValue(cacheKey, out var cachedFunction))
        {
            return await cachedFunction.Invoke(new SqlCommand(sqlCommand, new SqlConnection(connectionString)));
        }

        using (var connection = new SqlConnection(connectionString))
        {
            using (var command = new SqlCommand(sqlCommand, connection))
            {
                parameters.ForEach(param => command.Parameters.AddWithValue(param));

                try
                {
                    await connection.OpenAsync();
                    var reader = await command.ExecuteReaderAsync(CommandBehavior.CloseConnection);
                    await resultProcessor(reader);
                    return reader;
                }
                catch (Exception ex)
                {
                    throw new InvalidOperationException("Query execution failed.", ex);
                }
            }
        }
    }

    public void ClearCache()
    {
        _cache.Clear();
    }
}
