# Define JSON schema for resource validation
RESOURCE_SCHEMA = {
    "type": "object",
    "properties": {
        "id": {"type": "string"},
        "data": {"type": "object"}
    },
    "required": ["id", "data"],
    "additionalProperties": True
}

# Simulated database and user authentication service
database = {}
user_service = {}

def validate_request_body(body):
    try:
        validate(instance=body, schema=RESOURCE_SCHEMA)
    except ValidationError as e:
        return jsonify({"error": str(e)}), 400

@app.route('/resource/<string:resource_id>', methods=['PUT'])
def update_resource(resource_id):
    user_id = request.headers.get('User-Id')
    if not user_id:
        return jsonify({"error": "User ID is required"}), 401

    body = request.json
    result = validate_request_body(body)
    if result:
        return result

    resource_version = database.get(resource_id, {}).get('version', 0) + 1
    new_resource = {
        "id": resource_id,
        "data": body['data'],
        "user_id": user_id,
        "timestamp": logger.time(),
        "version": resource_version
    }

    # Log update operation
    logger.info(f"Update operation: {new_resource}")

    database[resource_id] = new_resource
    return jsonify(new_resource), 200

@app.route('/resource/<string:resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    user_id = request.headers.get('User-Id')
    if not user_id:
        return jsonify({"error": "User ID is required"}), 401

    resource = database.get(resource_id)
    if not resource:
        return jsonify({"error": "Resource not found"}), 404

    # Log delete operation
    logger.info(f"Delete operation: {resource}")

    del database[resource_id]
    return jsonify({"message": "Resource deleted successfully"}), 200

@app.route('/revert', methods=['POST'])
def revert_last_update():
    user_id = request.headers.get('User-Id')
    if not user_id:
        return jsonify({"error": "User ID is required"}), 401

    # Implement logic to revert the last successful update
    # This might involve maintaining a history of updates and applying them in reverse order
    return jsonify({"message": "Last update reverted successfully"}), 200

if __name__ == '__main__':
    app.run(debug=True)
