    }

    protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
    {
        request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", _apiToken);
        return base.SendAsync(request, cancellationToken);
    }
}

public class HttpMessageHandlerAggregate : DelegatingHandler
{
    private readonly List<DelegatingHandler> _handlers;

    public HttpMessageHandlerAggregate(IEnumerable<DelegatingHandler> handlers)
    {
        _handlers = new List<DelegatingHandler>(handlers);
    }

    protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
    {
        DelegatingHandler currentHandler = this;
        foreach (var handler in _handlers)
        {
            var nextHandler = currentHandler.InnerHandler ?? new HttpClientHandler();
            currentHandler.InnerHandler = handler;
            currentHandler = nextHandler;
        }

        return currentHandler.SendAsync(request, cancellationToken);
    }
}
