// DynamicScriptLoader.js

class DynamicScriptLoader {
  constructor(config) {
    this.config = config;
    this.scriptQueue = [];
    this.loadingScripts = new Set();
    this.metadataCache = {};
    this.maxConcurrentLoads = 5; // Adjust based on system metrics
  }

  async loadScript(scriptId) {
    if (this.loadingScripts.size >= this.maxConcurrentLoads) {
      await this.waitForLoad();
    }
    const script = this.config.scripts.find(s => s.id === scriptId);
    if (!script) return;

    try {
      let metadata = this.metadataCache[scriptId];
      if (!metadata) {
        metadata = await this.fetchMetadata(script.metadataUrl);
        this.metadataCache[scriptId] = metadata;
      }

      for (const dependency of script.dependencies) {
        if (!this.metadataCache[dependency]) {
          await this.loadScript(dependency);
        }
      }

      const dynamicScript = document.createElement('script');
      dynamicScript.id = scriptId;
      dynamicScript.innerHTML = metadata.code;
      dynamicScript.async = true;
      document.body.appendChild(dynamicScript);

      this.loadingScripts.add(scriptId);
      await new Promise(resolve => {
        dynamicScript.onload = () => resolve();
        dynamicScript.onerror = () => resolve();
      });
    } catch (error) {
      console.error(`Failed to load script ${scriptId}:`, error);
    } finally {
      this.loadingScripts.delete(scriptId);
    }
  }

  async fetchMetadata(url) {
    const retries = 3;
    for (let attempt = 0; attempt < retries; attempt++) {
      try {
        const response = await fetch(url, { cache: 'no-cache' });
        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
        return await response.json();
      } catch (error) {
        console.warn(`Failed to fetch metadata from ${url}, retrying...`, error);
        await new Promise(resolve => setTimeout(resolve, 1000 * attempt));
      }
    }
    throw new Error('Max retries reached for metadata fetch');
  }

  async waitForLoad() {
    return new Promise(resolve => {
      const interval = setInterval(() => {
        if (this.loadingScripts.size < this.maxConcurrentLoads) {
          clearInterval(interval);
          resolve();
        }
      }, 100);
    });
  }

  // Additional methods for configuration management, logging, and monitoring can be added here
}

// Usage example:
const config = {
  scripts: [
    { id: 'scriptA', code: 'console.log("Script A");', dependencies: [], priority: 1, metadataUrl: '/api/metadataA' },
    // Add more script objects as needed
  ]
};

const loader = new DynamicScriptLoader(config);
loader.loadScript('scriptA');
```']

