// AngularJS Directive for Form Field Refresh
angular.module('formRefreshModule', [])
.directive('dynamicFormFields', function($http, $timeout, config) {
  return {
    restrict: 'A',
    link: function(scope, element, attrs) {
      var resourceId = attrs.resourceId;
      var apiUrl = attrs.apiUrl;

      function refreshField() {
        $http.get(apiUrl + '/' + resourceId)
          .then(function(response) {
            // Handle successful response
            updateFormField(response.data);
          }, function(error) {
            // Handle error with retry mechanism
            if (error.status === 429) { // Too Many Requests
              $timeout(refreshField, config.retryDelay);
            } else {
              // Retry with exponential backoff
              var delay = Math.min(config.maxRetryDelay, config.retryBackoff * config.retryCount);
              $timeout(refreshField, delay);
              config.retryCount++;
            }
          });
      }

      function updateFormField(data) {
        // Update form fields based on data received from API
        element.val(data.value);
        scope.$apply();
      }

      // Initialize field refresh
      refreshField();
    }
  };
});

// Configuration Service for Directive
angular.module('formRefreshModule').factory('config', function() {
  return {
    retryDelay: 1000,
    maxRetryDelay: 60000,
    retryBackoff: 2,
    retryCount: 0
  };
});
