public class EmployeeFetcher {

    private String dbUrl;
    private String username;
    private String password;

    public EmployeeFetcher(String dbUrl, String username, String password) {
        this.dbUrl = dbUrl;
        this.username = username;
        this.password = password;
    }

    public void fetchEmployeeDetails(int supervisorId) {
        try (Connection connection = DriverManager.getConnection(dbUrl, username, password);
             PreparedStatement preparedStatement = connection.prepareStatement("SELECT name, city, address FROM Employees WHERE supervisor_id = ?")) {

            preparedStatement.setInt(1, supervisorId);
            ResultSet resultSet = preparedStatement.executeQuery();

            while (resultSet.next()) {
                String name = resultSet.getString("name");
                String city = resultSet.getString("city");
                String address = resultSet.getString("address");

                System.out.println("Name: " + name + ", City: " + city + ", Address: " + address);
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        // Example usage
        EmployeeFetcher fetcher = new EmployeeFetcher(
                System.getenv("DB_URL"),
                System.getenv("DB_USERNAME"),
                System.getenv("DB_PASSWORD")
        );

        int supervisorId = 123; // Replace with actual supervisor ID
        fetcher.fetchEmployeeDetails(supervisorId);
    }
}
