<?php

use Dotenv\Dotenv;
use Symfony\Component\Cache\Adapter\FilesystemAdapter;
use Doctrine\DBAL\Driver\PDOConnection;
use Monolog\Logger;
use Monolog\Handler\StreamHandler;

// Load environment variables
$dotenv = Dotenv::createImmutable(__DIR__);
$dotenv->load();

// Configure caching
$cache = new FilesystemAdapter('settings_cache', 0, __DIR__ . '/cache');

// Database connection
$dbConfig = [
    'url' => $_ENV['DATABASE_URL'],
];
try {
    $connection = DriverManager::getConnection($dbConfig);
} catch (\Exception $e) {
    // Handle database connection error
}

// Error handling and logging
$logger = new Logger('app');
$logger->pushHandler(new StreamHandler(__DIR__ . '/logs/app.log', Logger::DEBUG));

// API endpoint setup
$app = new Silex\Application();

$app->get('/settings/{key}', function ($key) use ($cache, $connection, $logger) {
    // Fetch setting from cache or database
    if (!$value = $cache->getItem($key)) {
        $stmt = $connection->query("SELECT value FROM settings WHERE key = ?", [$key]);
        $result = $stmt->fetch(PDO::FETCH_ASSOC);
        if ($result) {
            $value = $result['value'];
            $cache->set($key, $value);
        }
    }

    // Log access to setting
    $logger->info('Accessed setting: ' . $key);

    return new JsonResponse(['key' => $key, 'value' => $value]);
});

$app->post('/settings/{key}', function (Request $request, $key) use ($cache, $connection, $logger) {
    // Validate input
    $newValue = $request->get('value');
    if (!$newValue) {
        return new JsonResponse(['error' => 'Invalid value'], 400);
    }

    // Update setting in database and cache
    $stmt = $connection->prepare("UPDATE settings SET value = ? WHERE key = ?");
    $stmt->execute([$newValue, $key]);
    $cache->set($key, $newValue);

    // Log update to setting
    $logger->info('Updated setting: ' . $key . ' to value: ' . $newValue);

    return new JsonResponse(['key' => $key, 'value' => $newValue]);
});

$app->run();
```

