['```rust
use reqwest::{Client, RequestBuilder, Response};
use tokio::sync::Mutex;
use std::sync::Arc;
use chrono::Utc;

pub struct HttpClient {
    client: Client,
    base_url: String,
    token: Option<String>,
}

impl HttpClient {
    pub fn new(base_url: &str) -> Self {
        HttpClient {
            client: Client::new(),
            base_url: base_url.to_string(),
            token: None,
        }
    }

    pub fn set_auth_token(&mut self, token: String) {
        self.token = Some(token);
    }

    async fn build_request<B>(&self, method: reqwest::Method, path: &str, body: Option<B>) -> RequestBuilder
    where
        B: Into<reqwest::Body> + Send,
    {
        let mut builder = self.client.request(method, format!("{}/{}", self.base_url, path));
        if let Some(token) = &self.token {
            builder = builder.header("Authorization", format!("Bearer {}", token));
        }
        body.map(|b| builder.body(b)).unwrap_or(builder)
    }

    async fn make_request<B>(&self, method: reqwest::Method, path: &str, body: Option<B>) -> Result<Response, reqwest::Error>
    where
        B: Into<reqwest::Body> + Send,
    {
        let request = self.build_request(method, path, body).await;
        request.send().await
    }

    pub async fn get(&self, path: &str) -> Result<Response, reqwest::Error> {
        self.make_request(reqwest::Method::GET, path, None).await
    }

    pub async fn post<B>(&self, path: &str, body: B) -> Result<Response, reqwest::Error>
    where
        B: Into<reqwest::Body> + Send,
    {
        self.make_request(reqwest::Method::POST, path, Some(body)).await
    }

    pub async fn put<B>(&self, path: &str, body: B) -> Result<Response, reqwest::Error>
    where
        B: Into<reqwest::Body> + Send,
    {
        self.make_request(reqwest::Method::PUT, path, Some(body)).await
    }

    pub async fn delete(&self, path: &str) -> Result<Response, reqwest::Error> {
        self.make_request(reqwest::Method::DELETE, path, None).await
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_get_request() {
        let client = HttpClient::new("https://api.example.com");
        let response = client.get("/data").await.unwrap();
        assert_eq!(response.status(), 200);
    }

    #[tokio::test]
    async fn test_post_request() {
        let client = HttpClient::new("https://api.example.com");
        let body = r#"{"key":"value"}"#;
        let response = client.post("/data", body).await.unwrap();
        assert_eq!(response.status(), 201);
    }
}
