<?php
header('Content-Type: application/json');

function updateClinicStatus($clinicId, $newStatus, $lastModifiedIp, $lastModifiedDate) {
    $sem = sem_get(1000, 1); // Initialize semaphore with key 1000 and initial value 1

    if ($sem === false) {
        return json_encode(['success' => false, 'error' => 'Failed to initialize semaphore']);
    }

    if (!sem_acquire($sem)) {
        return json_encode(['success' => false, 'error' => 'Failed to acquire semaphore']);
    }

    try {
        $db = new PDO('mysql:host=localhost;dbname=your_database', 'username', 'password');
        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        $query = "START TRANSACTION";
        $stmt = $db->prepare($query);
        $stmt->execute();

        $updateQuery = "UPDATE clinics SET status = :newStatus, last_modified_ip = :lastModifiedIp, last_modified_date = :lastModifiedDate WHERE id = :clinicId";
        $updateStmt = $db->prepare($updateQuery);
        $updateStmt->bindParam(':newStatus', $newStatus);
        $updateStmt->bindParam(':lastModifiedIp', $lastModifiedIp);
        $updateStmt->bindParam(':lastModifiedDate', $lastModifiedDate);
        $updateStmt->bindParam(':clinicId', $clinicId);

        if ($updateStmt->execute()) {
            $query = "COMMIT";
            $stmt = $db->prepare($query);
            $stmt->execute();

            sem_release($sem);
            sem_remove($sem);
            return json_encode(['success' => true, 'message' => 'Clinic status updated successfully']);
        } else {
            throw new Exception('Failed to update clinic status');
        }
    } catch (PDOException $e) {
        if ($db->inTransaction()) {
            $query = "ROLLBACK";
            $stmt = $db->prepare($query);
            $stmt->execute();
        }

        sem_release($sem);
        sem_remove($sem);
        return json_encode(['success' => false, 'error' => 'Database error: ' . $e->getMessage()]);
    } catch (Exception $e) {
        sem_release($sem);
        sem_remove($sem);
        return json_encode(['success' => false, 'error' => 'Error: ' . $e->getMessage()]);
    }
}

// Example usage:
// echo updateClinicStatus(1, 'Open', '192.168.1.1', date('Y-m-d H:i:s'));
?>
