<?php

namespace SecurityTokenLibrary;

use GuzzleHttp\Client;
use GuzzleHttp\Exception\RequestException;
use GuzzleHttp\HandlerStack;
use GuzzleHttp\Middleware;
use React\Cache\FilesystemCache;
use React\EventLoop\Factory as LoopFactory;
use React\HttpClient\Client as HttpClient;
use React\HttpClient\Request;

class SecureTokenManager
{
    private $httpClient;
    private $cache;
    private $loop;

    public function __construct($idpUrl, $cachePath)
    {
        $this->loop = LoopFactory::create();
        $handlerStack = HandlerStack::create();

        // Add middleware for retry logic
        $handlerStack->push(Middleware::retry(3, function ($retries, RequestException $exception) {
            return $exception instanceof RequestException && $exception->hasResponse() && 500 <= $exception->getResponse()->getStatusCode();
        }));

        // Add middleware for exponential backoff
        $handlerStack->push(Middleware::delay($this->exponentialBackoff()));

        // Add middleware for rate limiting
        $handlerStack->push(Middleware::limitRate(10, 1));

        $client = new Client(['base_uri' => $idpUrl, 'handler' => $handlerStack]);
        $this->httpClient = HttpClient::create($client, $this->loop);

        $this->cache = new FilesystemCache($cachePath);
    }

    private function exponentialBackoff()
    {
        return function ($retries) {
            return 2 ** $retries;
        };
    }

    public function generateToken($userId, $tokenLength = 32)
    {
        // Generate a secure token
        return bin2hex(random_bytes($tokenLength));
    }

    public function validateToken($userId, $token)
    {
        // Cache token validation results to reduce latency
        if ($this->cache->get("validation:{$userId}:{$token}")) {
            return true;
        }

        try {
            $request = Request::create('GET', '/validate-token');
            $response = $this->httpClient->request($request, ['json' => [
                'user_id' => $userId,
                'token' => $token
            ]]);
            if ($response->getStatusCode() == 200) {
                $this->cache->set("validation:{$userId}:{$token}", true, 3600);
                return true;
            }
        } catch (RequestException $e) {
            // Log the error and handle it appropriately
            error_log($e->getMessage());
        }

        return false;
    }

    public function revokeToken($userId, $token)
    {
        try {
            $request = Request::create('POST', '/revoke-token');
            $response = $this->httpClient->request($request, ['json' => [
                'user_id' => $userId,
                'token' => $token
            ]]);
            return $response->getStatusCode() == 204;
        } catch (RequestException $e) {
            // Log the error and handle it appropriately
            error_log($e->getMessage());
            return false;
        }
    }

    public function close()
    {
        $this->loop->stop();
    }
}
