<?php

use Psr\Container\ContainerInterface;
use League\OAuth2\Server\AuthorizationServer;
use League\OAuth2\Server\CryptKey\CryptKeyChain;
use League\OAuth2\Server\Client\ClientRepository;
use League\OAuth2\Server\Grant\AuthCodeGrant;
use League\OAuth2\Server\Grant\ClientCredentialsGrant;
use League\OAuth2\Server\Grant\PasswordGrant;
use League\OAuth2\Server\Grant\RefreshTokenGrant;
use League\OAuth2\Server\Response\OAuth2Response;
use League\OAuth2\Server\Storage\ClientStorageInterface;
use League\OAuth2\Server\Storage\Database\ClientStorage;
use League\OAuth2\Server\Storage\Database\AccessTokenStorage;
use League\OAuth2\Server\Storage\Database\AuthCodeStorage;
use League\OAuth2\Server\Storage\Database\SessionStorage;
use League\OAuth2\Server\Storage\Database\RefreshTokenStorage;
use Monolog\Logger;
use Monolog\Handler\StreamHandler;
use Symfony\Component\Cache\Adapter\FilesystemAdapter;

class OAuthService
{
    private $container;

    public function __construct(ContainerInterface $container)
    {
        $this->container = $container;
    }

    public function setupAuthorizationServer(): AuthorizationServer
    {
        $clientStorage = new ClientStorage($this->container->get('database'));
        $accessTokenStorage = new AccessTokenStorage($this->container->get('database'));
        $authCodeStorage = new AuthCodeStorage($this->container->get('database'));
        $sessionStorage = new SessionStorage($this->container->get('database'));
        $refreshTokenStorage = new RefreshTokenStorage($this->container->get('database'));

        $server = new AuthorizationServer(
            $clientStorage,
            $accessTokenStorage,
            $authCodeStorage,
            $refreshTokenStorage,
            $this->container->get('crypt_key_chain')
        );

        $server->enableGrantType(new AuthCodeGrant($this->container->get('auth_code_repository')));
        $server->enableGrantType(new ClientCredentialsGrant());
        $server->enableGrantType(new PasswordGrant($this->container->get('user_repository'), $this->container->get('client_credentials_repository')));
        $server->enableGrantType(new RefreshTokenGrant());

        return $server;
    }

    public function setupRequestResponse()
    {
        return new OAuth2Response();
    }

    public function setupLogger(): Logger
    {
        $logger = new Logger('oauth_service');
        $logger->pushHandler(new StreamHandler(__DIR__ . '/../../var/log/oauth.log', Logger::DEBUG));

        return $logger;
    }

    public function setupCaching()
    {
        return new FilesystemAdapter();
    }
}

class Container implements ContainerInterface
{
    private $services = [];

    public function set($id, $service)
    {
        $this->services[$id] = $service;
    }

    public function get($id)
    {
        if (!isset($this->services[$id])) {
            throw new \InvalidArgumentException("Service not found: $id");
        }

        return $this->services[$id];
    }
}

// Usage example
$container = new Container();
$container->set('database', /* Database connection instance */);
$container->set('crypt_key_chain', new CryptKeyChain([
    'publicKey' => file_get_contents(__DIR__ . '/../../config/oauth/public.pem'),
    'privateKey' => file_get_contents(__DIR__ . '/../../config/oauth/private.pem'),
    'passphrase' => ''
]));
$container->set('auth_code_repository', /* AuthCodeRepository instance */);
$container->set('user_repository', /* UserRepository instance */);
$container->set('client_credentials_repository', /* ClientCredentialsRepository instance */);

$oauthService = new OAuthService($container);
$authorizationServer = $oauthService->setupAuthorizationServer();
$requestResponse = $oauthService->setupRequestResponse();
$logger = $oauthService->setupLogger();
$caching = $oauthService->setupCaching();

// Further setup and usage of the authorization server
