<?php

// PasswordValidationException class definition
class PasswordValidationException extends Exception {}

// DAO pattern implementation for user authentication
class UserDAO {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function updateUserPassword($userId, $newPassword) {
        // Validate password using regex or custom validation logic
        if (!preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,20}$/', $newPassword)) {
            throw new PasswordValidationException("Invalid password. It must be between 8 and 20 characters long, contain at least one uppercase letter, one lowercase letter, one digit, and one special character.");
        }

        // SQL query to update user password
        $stmt = $this->db->prepare("UPDATE users SET password = :password WHERE id = :id");
        $stmt->bindParam(':password', $newPassword);
        $stmt->bindParam(':id', $userId);

        if ($stmt->execute()) {
            return true;
        } else {
            throw new Exception("Database error: " . implode(", ", $stmt->errorInfo()));
        }
    }
}

// Authentication service implementation
class AuthenticationService {
    private $userDAO;

    public function __construct($db) {
        $this->userDAO = new UserDAO($db);
    }

    public function updatePassword($userId, $newPassword) {
        try {
            return $this->userDAO->updateUserPassword($userId, $newPassword);
        } catch (Exception $e) {
            // Log error using centralized logging system
            logError(json_encode([
                'message' => $e->getMessage(),
                'file' => __FILE__,
                'line' => __LINE__,
                'trace' => $e->getTraceAsString()
            ]));
            throw new Exception("Failed to update password for user ID: " . $userId);
        }
    }
}

// Function to log messages to an error log
function logError($message) {
    $logFile = '/var/log/error.log';
    $fp = fopen($logFile, 'a');
    if ($fp !== false) {
        $time = date('Y-m-d H:i:s');
        $formattedMessage = "[$time] Error: $message\n";
        fwrite($fp, $formattedMessage);
        fclose($fp);
    } else {
        // Handle failed logging attempt
        echo "Failed to log error.";
    }
}

// Example usage of AuthenticationService
$db = new PDO('mysql:host=localhost;dbname=auth_service', 'username', 'password');
$authenticationService = new AuthenticationService($db);
try {
    $result = $authenticationService->updatePassword(1, 'NewP@ssw0rd!');
    echo "Password updated successfully.";
} catch (Exception $e) {
    echo $e->getMessage();
}
