// ConcurrencyManager class to manage concurrency and load balancing
class ConcurrencyManager {
public:
    void addServiceInstance(const std::string& serviceName) {
        std::lock_guard<std::mutex> lock(mutex_);
        serviceInstances_[serviceName]++;
    }

    void removeServiceInstance(const std::string& serviceName) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (serviceInstances_.count(serviceName) > 0) {
            serviceInstances_[serviceName]--;
        }
    }

    void distributeTraffic(const std::string& serviceName, const std::function<void()>& task) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (int i = 0; i < serviceInstances_[serviceName]; ++i) {
            threads_.emplace_back([task]() { task(); });
        }
        for (auto& thread : threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

private:
    std::unordered_map<std::string, int> serviceInstances_;
    std::vector<std::thread> threads_;
    std::mutex mutex_;
};

