#include <pthread.h>
#include <semaphore.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <dirent.h>

#define MAX_THREADS 100
#define RETRY_LIMIT 5

typedef struct {
    char *file_path;
    sem_t *sync_sem;
} FileTask;

void* process_file(void* arg) {
    FileTask *task = (FileTask *)arg;
    // Extract version, validate against metadata service
    // Increment and rename if necessary
    // Update file metadata
    sem_post(task->sync_sem);
    return NULL;
}

int main(int argc, char *argv[]) {
    DIR *dir;
    struct dirent *ent;
    pthread_t threads[MAX_THREADS];
    sem_t sync_sem;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    if ((dir = opendir(argv[1])) == NULL) {
        perror("opendir");
        return EXIT_FAILURE;
    }

    sem_init(&sync_sem, 0, MAX_THREADS);

    while ((ent = readdir(dir)) != NULL) {
        char *file_path = malloc(strlen(argv[1]) + strlen(ent->d_name) + 2);
        if (file_path == NULL) {
            perror("malloc");
            closedir(dir);
            return EXIT_FAILURE;
        }
        snprintf(file_path, strlen(argv[1]) + strlen(ent->d_name) + 2, "%s/%s", argv[1], ent->d_name);

        FileTask *task = malloc(sizeof(FileTask));
        if (task == NULL) {
            perror("malloc");
            free(file_path);
            closedir(dir);
            return EXIT_FAILURE;
        }
        task->file_path = file_path;
        task->sync_sem = &sync_sem;

        sem_wait(&sync_sem);
        pthread_create(&threads[(int)((long)sem_getvalue(&sync_sem, NULL))], NULL, process_file, (void *)task);

        if ((int)((long)sem_getvalue(&sync_sem, NULL)) >= MAX_THREADS - 1) {
            for (int i = 0; i < MAX_THREADS; ++i) {
                pthread_join(threads[i], NULL);
                sem_wait(&sync_sem);
            }
        }
    }

    closedir(dir);

    while ((int)((long)sem_getvalue(&sync_sem, NULL)) > 0) {
        pthread_join(threads[(int)((long)sem_getvalue(&sync_sem, NULL)) - 1], NULL);
        sem_wait(&sync_sem);
    }

    sem_destroy(&sync_sem);

    return EXIT_SUCCESS;
}
```

