#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define KEY_SIZE 32
#define IV_SIZE 16
#define PBKDF2_ITERATIONS 100000

typedef struct {
    unsigned char key[KEY_SIZE];
    unsigned char iv[IV_SIZE];
} EncryptionContext;

EncryptionContext* derive_key(const char* password, size_t iteration_count) {
    EncryptionContext* context = (EncryptionContext*)malloc(sizeof(EncryptionContext));
    if (!context) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    if (!PBKDF2_HMAC_SHA256(password, strlen(password), NULL, 0, context->key, KEY_SIZE, iteration_count)) {
        free(context);
        fprintf(stderr, "Key derivation failed\n");
        return NULL;
    }

    // Generate IV
    if (RAND_bytes(context->iv, IV_SIZE) != 1) {
        free(context);
        fprintf(stderr, "IV generation failed\n");
        return NULL;
    }

    return context;
}

int encrypt(const unsigned char* plaintext, size_t plaintext_len, EncryptionContext* context, unsigned char* ciphertext) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return -1;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, context->key, context->iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Encryption initialization failed\n");
        return -1;
    }

    int len;
    if (EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Encryption update failed\n");
        return -1;
    }

    int ciphertext_len = len;

    if (EVP_EncryptFinal_ex(ctx, ciphertext + len, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Encryption finalization failed\n");
        return -1;
    }

    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return ciphertext_len;
}

int decrypt(const unsigned char* ciphertext, size_t ciphertext_len, EncryptionContext* context, unsigned char* plaintext) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return -1;
    }

    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, context->key, context->iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Decryption initialization failed\n");
        return -1;
    }

    int len;
    if (EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Decryption update failed\n");
        return -1;
    }

    int plaintext_len = len;

    if (EVP_DecryptFinal_ex(ctx, plaintext + len, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Decryption finalization failed\n");
        return -1;
    }

    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return plaintext_len;
}

void cleanup(EncryptionContext* context) {
    if (context) {
        free(context);
    }
}
