import java.util.concurrent.CompletableFuture;
import java.util.stream.Stream;

public class FileManagementService {
    private final ExternalApiService externalApiService;
    private final TokenManager tokenManager;
    private final ErrorHandlingStrategy errorHandler;
    private final LoggingSystem loggingSystem;
    private final ResourceAllocator resourceAllocator;

    public FileManagementService(ExternalApiService externalApiService, TokenManager tokenManager, 
                                 ErrorHandlingStrategy errorHandler, LoggingSystem loggingSystem,
                                 ResourceAllocator resourceAllocator) {
        this.externalApiService = externalApiService;
        this.tokenManager = tokenManager;
        this.errorHandler = errorHandler;
        this.loggingSystem = loggingSystem;
        this.resourceAllocator = resourceAllocator;
    }

    public CompletableFuture<Void> processFiles(Stream<String> filePaths) {
        return filePaths.map(this::processFile)
                        .reduce(CompletableFuture.completedFuture(null), 
                                (f1, f2) -> f1.thenComposeAsync(v -> f2), 
                                (v1, v2) -> v1);
    }

    private CompletableFuture<Void> processFile(String filePath) {
        return tokenManager.authenticate()
                .thenApply(token -> externalApiService.uploadFile(filePath, token))
                .handle((result, ex) -> {
                    if (ex != null) {
