    int error_count;
} DeviceStatusReport;

typedef struct DeviceStatusManager {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    DeviceStatusReport **reports;
    int report_count;
    int capacity;
    int max_error_count;
    // Add more fields as needed
} DeviceStatusManager;

void ds_manager_init(DeviceStatusManager *manager, int initial_capacity, int max_error_count) {
    manager->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    manager->cond = (pthread_cond_t)PTHREAD_COND_INITIALIZER;
    manager->reports = NULL;
    manager->report_count = 0;
    manager->capacity = initial_capacity;
    manager->max_error_count = max_error_count;
    // Initialize other fields as needed
}

void ds_manager_add_report(DeviceStatusManager *manager, DeviceStatusReport *report) {
    pthread_mutex_lock(&manager->lock);
    if (manager->report_count >= manager->capacity) {
        // Resize the reports array
        manager->reports = realloc(manager->reports, manager->capacity * 2 * sizeof(DeviceStatusReport *));
        manager->capacity *= 2;
    }
    manager->reports[manager->report_count] = report;
    manager->report_count++;
    pthread_cond_signal(&manager->cond);
    pthread_mutex_unlock(&manager->lock);
}

