class SensorDataProcessorService : IHostedService
{
    private readonly ILogger<SensorDataProcessorService> _logger;
    private readonly IDistributedCache _cache;
    private readonly ConnectionMultiplexer _redis;
    private readonly ProducerBuilder<Null, string> _producerBuilder;
    private IProducer<Null, string> _producer;

    public SensorDataProcessorService(ILogger<SensorDataProcessorService> logger, IDistributedCache cache, ConnectionMultiplexer redis)
    {
        _logger = logger;
        _cache = cache;
        _redis = redis;
        _producerBuilder = new ProducerBuilder<Null, string>(new ProducerConfig
        {
            BootstrapServers = "your_kafka_broker"
        });
        _producer = _producerBuilder.Build();
    }

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        var consumerConfig = new ConsumerConfig
        {
            GroupId = "sensor_data_group",
            BootstrapServers = "your_kafka_broker",
            AutoOffsetReset = AutoOffsetReset.Earliest
        };

        using (var consumer = new ConsumerBuilder<Null, string>(consumerConfig).Build())
        {
            await consumer.SubscribeAsync("sensor_data_topic");

            while (!cancellationToken.IsCancellationRequested)
            {
                try
                {
                    var consumeResult = await consumer.ConsumeAsync(cancellationToken);
                    if (consumeResult is not null)
                    {
                        ProcessData(consumeResult.Message.Value);
                    }
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing message");
                }
            }
        }
    }

    public async Task StopAsync(CancellationToken cancellationToken)
    {
        await _producer.FlushAsync();
        _producer.Dispose();
    }

    private void ProcessData(string data)
    {
        // Validate and route data to appropriate processors
        var routingKey = GetRoutingKey(data);

        // Process data asynchronously
        Task.Run(async () =>
        {
            try
            {
                await ProcessAsync(data, routingKey);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing data");
            }
        });
    }

    private string GetRoutingKey(string data)
    {
        // Implement logic to determine the appropriate processor based on metadata
        return "processor_key";
    }

    private async Task ProcessAsync(string data, string routingKey)
    {
        // Process data (e.g., store in database, perform analysis)
        await StoreDataInDatabase(data, routingKey);
    }

    private async Task StoreDataInDatabase(string data, string routingKey)
    {
        // Connect to time-series database and store data
        using var connection = _redis.GetConnectionMultiplexer();
        var db = connection.GetDatabase();

        // Implement partitioning and indexing strategies for optimal performance
        await db.StringSetAsync($"sensor_data:{routingKey}", data);
    }
}
