import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.stream.annotation.EnableBinding;
import org.springframework.cloud.stream.messaging.Sink;

@SpringBootApplication
@EnableBinding(Sink.class)
public class TextProcessingServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(TextProcessingServiceApplication.class, args);
    }
}

@StreamListener(Sink.INPUT)
public class TextProcessor {

    @Autowired
    private ElasticsearchOperations elasticsearchTemplate;

    @Autowired
    private MongoTemplate mongoTemplate;

    public void processText(String text) {
        // Transform and filter the text data
        String transformedText = transformAndFilter(text);

        // Store processed results in MongoDB
        storeInMongo(transformedText);

        // Index data in Elasticsearch for efficient querying
        indexDataInElasticsearch(transformedText);
    }

    private String transformAndFilter(String text) {
        // Implementation of transformation and filtering logic
        return text.replaceAll("[^a-zA-Z0-9]", " ").toLowerCase();
    }

    private void storeInMongo(String transformedText) {
        // Store the transformed text in MongoDB
        mongoTemplate.save(new TextDocument(transformedText));
    }

    private void indexDataInElasticsearch(String transformedText) {
        // Index the transformed text in Elasticsearch
        elasticsearchTemplate.index(new IndexQueryBuilder()
                .withId(UUID.randomUUID().toString())
                .withObject(new TextDocument(transformedText))
                .build());
    }
}

class TextDocument {
    private String content;

    public TextDocument(String content) {
        this.content = content;
    }

    // Getters and setters
}
```

