const axios = require('axios');
const crypto = require('crypto');

async function handleFileUpload(url, method, service, credentials) {
  // Validate URL
  if (!url.startsWith('https')) throw new Error('URL must use HTTPS protocol');
  const response = await axios.head(url);
  if (response.status !== 200) throw new Error('File not found at the specified URL');

  // Determine upload method
  let selectedMethod = method;
  if (method === 'auto') {
    const fileSize = response.headers['content-length'];
    if (fileSize > 10 * 1024 * 1024) selectedMethod = 'multipart';
  }

  // Upload logic based on selected method
  if (selectedMethod === 'direct') {
    await directUpload(url, service, credentials);
  } else if (selectedMethod === 'multipart') {
    await multipartUpload(url, service, credentials);
  } else if (selectedMethod === 'chunked') {
    await chunkedUpload(url, service, credentials);
  }

  // Post-upload operations
  const fileHash = crypto.createHash('sha256').update(response.data).digest('hex');
  cacheFileMetadata(fileHash, response.headers);
}

