using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading.Tasks;

public interface IMessageQueue
{
    void Publish(string message);
    Task<string> Consume();
}

public class MessageQueue : IMessageQueue
{
    private readonly BlockingCollection<string> _queue = new();

    public void Publish(string message)
    {
        _queue.Add(message);
    }

    public async Task<string> Consume()
    {
        return await Task.Run(() => _queue.Take());
    }
}

public interface IMessageBroker
{
    void RegisterServiceQueue(string serviceId, IMessageQueue queue);
    void PublishMessage(string serviceId, string message);
    Task<string> ConsumeMessage(string serviceId);
}

public class MessageBroker : IMessageBroker
{
    private readonly ConcurrentDictionary<string, IMessageQueue> _serviceQueues = new();

    public void RegisterServiceQueue(string serviceId, IMessageQueue queue)
    {
        _serviceQueues.TryAdd(serviceId, queue);
    }

    public void PublishMessage(string serviceId, string message)
    {
        if (_serviceQueues.TryGetValue(serviceId, out var queue))
        {
            queue.Publish(message);
        }
    }

    public async Task<string> ConsumeMessage(string serviceId)
    {
        if (_serviceQueues.TryGetValue(serviceId, out var queue))
        {
            return await queue.Consume();
        }
        throw new InvalidOperationException("Service queue not found");
    }
}

public class MessageBrokerFactory
{
    public static IMessageBroker CreateMessageBroker()
    {
        var messageBroker = new MessageBroker();

        // Register service queues using dependency injection
        // Example: messageBroker.RegisterServiceQueue("service1", new MessageQueue());
        // messageBroker.RegisterServiceQueue("service2", new MessageQueue());

        return messageBroker;
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        var messageBroker = MessageBrokerFactory.CreateMessageBroker();

        // Example usage
        messageBroker.PublishMessage("service1", "Hello, service1!");
        var message = await messageBroker.ConsumeMessage("service1");
        Console.WriteLine(message);
    }
}
