#define MAX_SESSIONS 10000
#define THEME_CACHE_DIR "/path/to/theme/cache"

typedef struct {
    pthread_mutex_t mutex;
    EVP_CIPHER_CTX *ctx[MAX_SESSIONS];
} CipherContextManager;

CipherContextManager cipher_manager;

void init_cipher_context_manager() {
    pthread_mutex_init(&cipher_manager.mutex, NULL);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        cipher_manager.ctx[i] = NULL;
    }
}

EVP_CIPHER_CTX* get_cipher_context(int user_id) {
    pthread_mutex_lock(&cipher_manager.mutex);
    if (cipher_manager.ctx[user_id] == NULL) {
        cipher_manager.ctx[user_id] = EVP_CIPHER_CTX_new();
    }
    pthread_mutex_unlock(&cipher_manager.mutex);
    return cipher_manager.ctx[user_id];
}

void release_cipher_context(int user_id) {
    pthread_mutex_lock(&cipher_manager.mutex);
    if (cipher_manager.ctx[user_id] != NULL) {
        EVP_CIPHER_CTX_free(cipher_manager.ctx[user_id]);
        cipher_manager.ctx[user_id] = NULL;
    }
    pthread_mutex_unlock(&cipher_manager.mutex);
