    if (ctx == NULL) {
        return -1;
    }

    int result = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);
    if (!result) {
        release_cipher_context(user_id);
        return -1;
    }

    result = EVP_EncryptUpdate(ctx, encrypted_data, (int *)encrypted_len, data, data_len);
    if (!result) {
        release_cipher_context(user_id);
        return -1;
    }

    int final_len = 0;
    result = EVP_EncryptFinal_ex(ctx, encrypted_data + *encrypted_len, &final_len);
    if (!result) {
        release_cipher_context(user_id);
        return -1;
    }

    *encrypted_len += final_len;
    release_cipher_context(user_id);
    return 0;
