class DataStore {
private:
    std::vector<SensorData> storage;
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<bool> stop{false};

public:
    void store(const SensorData& data) {
        std::lock_guard<std::mutex> lock(mtx);
        storage.push_back(data);
        cv.notify_one();
    }

    void start() {
        std::thread([this]() {
            while (!stop.load()) {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [this] { return !storage.empty(); });
                SensorData data = storage.front();
                storage.erase(storage.begin());
                lock.unlock();
                // Forward to analytics service
            }
        }).detach();
    }

    void stopProcessing() {
        stop.store(true);
        cv.notify_one();
    }
};

