# Import necessary libraries
from flask import Flask, request, jsonify, session
from oauthlib.oauth2 import BackendApplicationClient
from requests_oauthlib import OAuth2Session
import redis
import os
import logging

app = Flask(__name__)
app.config['SECRET_KEY'] = os.getenv('SECRET_KEY', 'default_secret_key')

# Redis setup for session management
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)

# OAuth2 client configuration
oauth_client_id = os.getenv('OAUTH_CLIENT_ID')
oauth_client_secret = os.getenv('OAUTH_CLIENT_SECRET')
provider_url = 'https://example.com/oauth/authorize'

@app.route('/login', methods=['GET'])
def login():
    redirect_uri = request.base_url + 'callback'
    oauth = OAuth2Session(oauth_client_id, redirect_uri=redirect_uri)
    authorization_url, state = oauth.authorization_url(provider_url)
    session['oauth_state'] = state
    return jsonify({'authorization_url': authorization_url})

@app.route('/login/callback', methods=['GET'])
def callback():
    oauth = OAuth2Session(oauth_client_id, state=session['oauth_state'])
    token = oauth.fetch_token('https://example.com/oauth/token',
                             client_secret=oauth_client_secret,
                             authorization_response=request.url)
    session['access_token'] = token['access_token']
    return jsonify({'message': 'Login successful'})

@app.route('/userinfo', methods=['GET'])
def userinfo():
    if 'access_token' not in session:
        return jsonify({'error': 'Not logged in'}), 401
    oauth = OAuth2Session(oauth_client_id, token=session['access_token'])
    response = oauth.get('https://example.com/userinfo')
    return jsonify(response.json())

@app.route('/logout', methods=['GET'])
def logout():
    session.pop('access_token', None)
    return jsonify({'message': 'Logged out'})

if __name__ == '__main__':
