#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define NUM_SEMAPHORES 5

sem_t semaphores[NUM_SEMAPHORES];
int semaphore_counts[NUM_SEMAPHORES];

void* thread_function(void* arg) {
    int id = *(int*)arg;

    for (int i = 0; i < 10; i++) {
        sem_wait(&semaphores[id]);
        printf("Thread %d acquired semaphore %d\n", id, id);

        // Simulate some work
        sleep(1);

        sem_post(&semaphores[id]);
        printf("Thread %d released semaphore %d\n", id, id);
    }

    return NULL;
}

int main() {
    pthread_t threads[NUM_SEMAPHORES];
    int thread_ids[NUM_SEMAPHORES];

    for (int i = 0; i < NUM_SEMAPHORES; i++) {
        sem_init(&semaphores[i], 0, 1);
        semaphore_counts[i] = 1;

        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, thread_function, &thread_ids[i]);
    }

    for (int i = 0; i < NUM_SEMAPHORES; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < NUM_SEMAPHORES; i++) {
        sem_destroy(&semaphores[i]);
    }

    return 0;
}
