public class TransactionAggregationService {

    private final PaymentGateway paymentGateway;
    private final TransactionRepository transactionRepository;
    private final Cache<String, User> userCache;
    private final ExecutorService executorService;

    public TransactionAggregationService(PaymentGateway paymentGateway,
                                       TransactionRepository transactionRepository,
                                       Cache<String, User> userCache) {
        this.paymentGateway = paymentGateway;
        this.transactionRepository = transactionRepository;
        this.userCache = userCache;
        this.executorService = Executors.newCachedThreadPool();
    }

    public void processTransactions(List<Transaction> transactions) {
        Map<User, List<Transaction>> userTransactions = transactions.stream()
                .collect(Collectors.groupingBy(transaction -> getUserFromCache(transaction.getUserId())));

        userTransactions.forEach((user, transactionsList) -> executorService.submit(() ->
                aggregateTransactionsForUser(user, transactionsList)));
    }

    private User getUserFromCache(String userId) {
        return userCache.getIfPresent(userId);
    }

    private void aggregateTransactionsForUser(User user, List<Transaction> transactions) {
        try {
            LocalDateTime now = LocalDateTime.now(ZoneId.systemDefault());
            String timeWindow = getTimeWindow(now);

            double totalAmount = transactions.stream()
                    .mapToDouble(Transaction::getAmount)
                    .sum();
            int count = transactions.size();
            double averageValue = totalAmount / count;

            AggregationResult aggregationResult = new AggregationResult(timeWindow, user.getId(), count, totalAmount, averageValue);
            transactionRepository.save(aggregationResult);

        } catch (Exception e) {
            handleAggregationError(user, transactions, e);
        }
    }

