#include <iostream>
#include <fstream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <json/json.h>
#include "log_processor.hpp"
#include "real_time_validator.hpp"
#include "cache_manager.hpp"
#include "priority_queue.hpp"
#include "buffer_manager.hpp"
#include "logging_manager.hpp"
#include "file_reader.hpp"
#include "network_stream.hpp"
#include "api_client.hpp"
#include "autoloader.hpp"
#include "schema_updater.hpp"
#include "version_control.hpp"
#include "machine_learning_analyzer.hpp"

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <config_file>" << std::endl;
        return 1;
    }

    Json::Value config = Json::parse(std::ifstream(argv[1]).rdbuf());

    LogProcessor log_processor(config);
    RealTimeValidator validator(config, &log_processor);
    CacheManager cache_manager(&validator);
    PriorityQueue priority_queue(&cache_manager);
    BufferManager buffer_manager(&priority_queue, config);
    LoggingManager logging_manager(config);

    FileReader file_reader;
    NetworkStream network_stream;
    APIConnection api_connection;

    autoloader::load_runtime_params(config, &log_processor, &validator, &cache_manager, &priority_queue, &buffer_manager, &logging_manager);

    std::thread file_thread([&file_reader, &buffer_manager]() {
        while (true) {
            auto data = file_reader.read();
            buffer_manager.push(data);
        }
    });

    std::thread network_thread([&network_stream, &buffer_manager]() {
        while (true) {
            auto data = network_stream.read();
            buffer_manager.push(data);
        }
    });

    std::vector<std::thread> validator_threads;
    for (size_t i = 0; i < config["validation_concurrency"].asUInt(); ++i) {
        validator_threads.emplace_back([&validator, &buffer_manager]() {
            while (true) {
                auto data = buffer_manager.pop();
                if (!data) break;
                validator.validate(data);
            }
        });
    }

    std::vector<std::thread> logging_threads;
    for (size_t i = 0; i < config["logging_concurrency"].asUInt(); ++i) {
        logging_threads.emplace_back([&logging_manager, &validator]() {
            while (true) {
                auto data = validator.pop();
                if (!data) break;
                logging_manager.log(data);
            }
        });
    }

    file_thread.join();
    network_thread.join();
    for (auto& thread : validator_threads) thread.join();
    for (auto& thread : logging_threads) thread.join();

    return 0;
}
