        stop();
        for (auto& thread : worker_threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void process_data(const std::vector<char>& data) {
        std::unique_lock<std::mutex> lock(buffer_mutex_);
        buffer_.insert(buffer_.end(), data.begin(), data.end());
        if (buffer_.size() >= config_.batch_size) {
            process_batch();
        }
    }

private:
