typedef struct {
    StringMetadata metadata;
    // Add other necessary fields for batch processing
} BatchItem;

BatchItem batch[MAX_STRINGS];
int itemCount = 0;
pthread_mutex_t batchLock;
sem_t availableSlots;

void* processBatch(void* arg) {
    while (1) {
        sem_wait(&availableSlots);
        pthread_mutex_lock(&batchLock);

        if (itemCount > 0) {
            BatchItem item = batch[itemCount - 1];
            itemCount--;

            // Process the item here
            printf("Processing: %s\n", item.metadata.string);
            // Simulate processing time
            sleep(1);

            pthread_mutex_unlock(&batchLock);
        } else {
            pthread_mutex_unlock(&batchLock);
            sem_post(&availableSlots);
            break;
        }
    }

    return NULL;
}

void batchProcessStrings(StringMetadata* metadata, int count) {
    if (count > MAX_STRINGS) {
        fprintf(stderr, "Error: Exceeds maximum number of strings.\n");
        return;
    }

    pthread_t threads[10];
    sem_init(&availableSlots, 0, 10);

    for (int i = 0; i < count; i++) {
        batch[i] = (BatchItem) {metadata[i], /* Add other necessary fields */};
    }
    itemCount = count;

    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, processBatch, NULL);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&availableSlots);
}

int main() {
    StringMetadata metadata[MAX_STRINGS];
    // Populate metadata array with actual data

