    static {
        // Initialize with some default providers
        providerMap.put("AWS", new AWSStorageProvider());
        providerMap.put("GoogleCloud", new GoogleCloudProvider());
    }

    public static void registerProvider(String providerName, CloudStorageProvider provider) {
