// Main class for the CloudStorageGateway service
public class CloudStorageGateway {
    private Map<String, CloudStorageProvider> providers;

    public CloudStorageGateway() {
        providers = new HashMap<>();
        initializeProviders();
    }

    private void initializeProviders() {
        // Initialize with default providers
        providers.put("AWS", ProviderFactory.getProvider("AWS"));
        providers.put("GoogleCloud", ProviderFactory.getProvider("GoogleCloud"));
    }

    public void addProvider(String providerName, CloudStorageProvider provider) {
        providers.put(providerName, provider);
    }

    public void uploadFile(String providerName, String filePath, byte[] data) {
        CloudStorageProvider provider = providers.get(providerName);
        if (provider != null) {
            provider.upload(filePath, data);
        } else {
            throw new IllegalArgumentException("Provider not found: " + providerName);
        }
    }

    public byte[] downloadFile(String providerName, String filePath) {
        CloudStorageProvider provider = providers.get(providerName);
        if (provider != null) {
            return provider.download(filePath);
        } else {
            throw new IllegalArgumentException("Provider not found: " + providerName);
        }
    }

    public void synchronizeFiles(String providerName) {
        CloudStorageProvider provider = providers.get(providerName);
        if (provider != null) {
            provider.synchronize();
        } else {
            throw new IllegalArgumentException("Provider not found: " + providerName);
        }
    }
}
