        dataProcessingThreads[i] = std::thread([&devices, &processor, &dbClient, &analyticsClient](int index) {
            while (true) {
                SensorPacket packet;
                devices[index].sendData(packet);
                processor.processPacket(packet);
                dbClient.storeData(packet);
                analyticsClient.sendDataForAnalysis(packet);
            }
        }, i);
    }

    // Start monitoring and logging
    std::thread monitoringThread([&eventHandler]() {
        while (true) {
            eventHandler.handleEvent("Monitor");
            std::this_thread::sleep_for(std::chrono::seconds(60));
        }
    });

    // Wait for all threads to finish
    for (auto& thread : dataProcessingThreads) {
        thread.join();
    }

    monitoringThread.join();

    return 0;
}
```

