typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[AES_BLOCK_SIZE];
} CipherContext;

CipherContext cipher_context[MAX_SESSIONS];

void initialize_cipher_context(int session_id) {
    if (session_id >= MAX_SESSIONS || session_id < 0) return;
    cipher_context[session_id].ctx = EVP_CIPHER_CTX_new();
    RAND_bytes(cipher_context[session_id].iv, AES_BLOCK_SIZE);
}

void encrypt_data(int session_id, unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    if (session_id >= MAX_SESSIONS || session_id < 0) return;
    EVP_EncryptInit_ex(cipher_context[session_id].ctx, EVP_aes_256_cbc(), NULL, (unsigned char *)"YourSecretKey", cipher_context[session_id].iv);
    EVP_EncryptUpdate(cipher_context[session_id].ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(cipher_context[session_id].ctx, ciphertext + ciphertext_len, &ciphertext_len);
}

void decrypt_data(int session_id, unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    if (session_id >= MAX_SESSIONS || session_id < 0) return;
    EVP_DecryptInit_ex(cipher_context[session_id].ctx, EVP_aes_256_cbc(), NULL, (unsigned char *)"YourSecretKey", cipher_context[session_id].iv);
    EVP_DecryptUpdate(cipher_context[session_id].ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len);
    EVP_DecryptFinal_ex(cipher_context[session_id].ctx, plaintext + plaintext_len, &plaintext_len);
}

void recycle_cipher_context(int session_id) {
    if (session_id >= MAX_SESSIONS || session_id < 0) return;
    if (cipher_context[session_id].ctx != NULL) {
        EVP_CIPHER_CTX_free(cipher_context[session_id].ctx);
        cipher_context[session_id].ctx = NULL;
    }
}

