// device_status_manager.h
#ifndef DEVICE_STATUS_MANAGER_H
#define DEVICE_STATUS_MANAGER_H

#include <pthread.h>
#include "device_status_report.h"

typedef struct DeviceStatusManager {
    pthread_mutex_t mutex;
    DeviceStatusReport** reports;
    int reportCount;
    int capacity;
} DeviceStatusManager;

void initDeviceStatusManager(DeviceStatusManager* manager);
void destroyDeviceStatusManager(DeviceStatusManager* manager);
int addDeviceStatusReport(DeviceStatusManager* manager, const DeviceStatusReport* report);
int updateDeviceStatusReport(DeviceStatusManager* manager, const DeviceStatusReport* report);
int retrieveDeviceStatusReport(DeviceStatusManager* manager, int deviceId, DeviceStatusReport** report);
int deleteDeviceStatusReport(DeviceStatusManager* manager, int deviceId);

#endif // DEVICE_STATUS_MANAGER_H

// device_status_manager.c
#include <stdlib.h>
#include <string.h>
#include "device_status_manager.h"

void initDeviceStatusManager(DeviceStatusManager* manager) {
    pthread_mutex_init(&manager->mutex, NULL);
    manager->reports = (DeviceStatusReport**)malloc(10 * sizeof(DeviceStatusReport*));
    manager->reportCount = 0;
    manager->capacity = 10;
}

void destroyDeviceStatusManager(DeviceStatusManager* manager) {
    pthread_mutex_destroy(&manager->mutex);
    for (int i = 0; i < manager->reportCount; i++) {
        free(manager->reports[i]->timestamp);
        free(manager->reports[i]->errorCodes);
        free(manager->reports[i]);
    }
    free(manager->reports);
}

int addDeviceStatusReport(DeviceStatusManager* manager, const DeviceStatusReport* report) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->reportCount == manager->capacity) {
        manager->capacity *= 2;
        manager->reports = (DeviceStatusReport**)realloc(manager->reports, manager->capacity * sizeof(DeviceStatusReport*));
    }
    DeviceStatusReport* newReport = (DeviceStatusReport*)malloc(sizeof(DeviceStatusReport));
    newReport->timestamp = strdup(report->timestamp);
    newReport->deviceId = report->deviceId;
    newReport->signalStrength = report->signalStrength;
    newReport->errorCodes = (int*)malloc(report->errorCodeCount * sizeof(int));
    memcpy(newReport->errorCodes, report->errorCodes, report->errorCodeCount * sizeof(int));
    newReport->errorCodeCount = report->errorCodeCount;
    manager->reports[manager->reportCount++] = newReport;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int updateDeviceStatusReport(DeviceStatusManager* manager, const DeviceStatusReport* report) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->reportCount; i++) {
        if (manager->reports[i]->deviceId == report->deviceId) {
            free(manager->reports[i]->timestamp);
            free(manager->reports[i]->errorCodes);
            manager->reports[i]->timestamp = strdup(report->timestamp);
            manager->reports[i]->signalStrength = report->signalStrength;
            manager->reports[i]->errorCodes = (int*)realloc(manager->reports[i]->errorCodes, report->errorCodeCount * sizeof(int));
            memcpy(manager->reports[i]->errorCodes, report->errorCodes, report->errorCodeCount * sizeof(int));
            manager->reports[i]->errorCodeCount = report->errorCodeCount;
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return -1;
}

int retrieveDeviceStatusReport(DeviceStatusManager* manager, int deviceId, DeviceStatusReport** report) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->reportCount; i++) {
        if (manager->reports[i]->deviceId == deviceId) {
            *report = manager->reports[i];
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return -1;
}

int deleteDeviceStatusReport(DeviceStatusManager* manager, int deviceId) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->reportCount; i++) {
        if (manager->reports[i]->deviceId == deviceId) {
            free(manager->reports[i]->timestamp);
            free(manager->reports[i]->errorCodes);
            free(manager->reports[i]);
            for (int j = i; j < manager->reportCount - 1; j++) {
                manager->reports[j] = manager->reports[j + 1];
            }
            manager->reportCount--;
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return -1;
}
