// Define the structure for the dynamic collection
typedef struct {
    DeviceStatusReport *reports;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} DeviceReportCollection;

// Function to initialize the device report collection
void init_device_report_collection(DeviceReportCollection *collection) {
    collection->capacity = 10;
    collection->count = 0;
    collection->reports = (DeviceStatusReport *)malloc(collection->capacity * sizeof(DeviceStatusReport));
    pthread_mutex_init(&collection->lock, NULL);
}

// Function to add a new device status report
void add_device_status_report(DeviceReportCollection *collection, DeviceStatusReport report) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count == collection->capacity) {
        // Double the capacity and reallocate memory
        collection->capacity *= 2;
        collection->reports = (DeviceStatusReport *)realloc(collection->reports, collection->capacity * sizeof(DeviceStatusReport));
    }
    collection->reports[collection->count++] = report;
    pthread_mutex_unlock(&collection->lock);
}

// Function to update an existing device status report
void update_device_status_report(DeviceReportCollection *collection, int index, DeviceStatusReport new_report) {
    pthread_mutex_lock(&collection->lock);
    if (index >= 0 && index < collection->count) {
        collection->reports[index] = new_report;
    }
    pthread_mutex_unlock(&collection->lock);
}

// Function to retrieve a device status report by index
DeviceStatusReport get_device_status_report(DeviceReportCollection *collection, int index) {
    DeviceStatusReport report = {0};
    pthread_mutex_lock(&collection->lock);
    if (index >= 0 && index < collection->count) {
        report = collection->reports[index];
    }
    pthread_mutex_unlock(&collection->lock);
    return report;
}

// Function to delete a device status report by index
void delete_device_status_report(DeviceReportCollection *collection, int index) {
    pthread_mutex_lock(&collection->lock);
    if (index >= 0 && index < collection->count) {
        // Shift elements to fill the gap
        for (int i = index; i < collection->count - 1; i++) {
            collection->reports[i] = collection->reports[i + 1];
        }
        collection->count--;
    }
    pthread_mutex_unlock(&collection->lock);
}

// Function to clean up and free resources
void cleanup_device_report_collection(DeviceReportCollection *collection) {
    pthread_mutex_destroy(&collection->lock);
    free(collection->reports);
}
