class SensorData {
public:
    int sensorID;
    double reading;
    std::string metadata;
    std::time_t timestamp;

    SensorData(int id, double data, const std::string& meta, std::time_t time)
        : sensorID(id), reading(data), metadata(meta), timestamp(time) {}
};

class SensorRegistry {
private:
    std::unordered_map<int, SensorData> registry;
    std::mutex mutex;
    std::condition_variable cv;

public:
    void insert(int id, double data, const std::string& meta, std::time_t time) {
        std::lock_guard<std::mutex> lock(mutex);
        if (registry.find(id) == registry.end()) {
            registry[id] = SensorData(id, data, meta, time);
            cv.notify_one();
        }
    }

    bool remove(int id) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = registry.find(id);
        if (it != registry.end()) {
            registry.erase(it);
            return true;
        }
        return false;
    }

    SensorData* get(int id) {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this, id] { return registry.find(id) != registry.end(); });
        auto it = registry.find(id);
        if (it != registry.end()) {
            return &it->second;
        }
        return nullptr;
    }

    void cacheData(int id, double data, const std::string& meta, std::time_t time) {
        // Implement caching logic here
    }
};

