public:
    bool authenticate() {
        if (isAuthenticating) return false;
        isAuthenticating = true;
        // Perform authentication logic here
        isAuthenticating = false;
        return true;
    }

    void sendData(int id, double data, const std::string& meta, std::time_t time) {
        if (rateLimitCount >= MAX_RATE_LIMIT) {
            // Handle rate limiting logic here
            return;
        }
        // Send data to API
        rateLimitCount++;
    }
};

class BackgroundWorker {
private:
    SensorRegistry& registry;
    SensorNetworkAPI& api;
    std::thread workerThread;
    std::atomic<bool> running{true};
    std::queue<std::function<void()>> taskQueue;

public:
    BackgroundWorker(SensorRegistry& reg, SensorNetworkAPI& netApi)
        : registry(reg), api(netApi) {
        workerThread = std::thread(&BackgroundWorker::run, this);
    }

    ~BackgroundWorker() {
        running.store(false);
        workerThread.join();
    }

    void enqueueTask(const std::function<void()>& task) {
        std::lock_guard<std::mutex> lock(mutex);
        taskQueue.push(task);
    }

private:
    void run() {
        while (running.load()) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return !taskQueue.empty(); });
            auto task = taskQueue.front();
            taskQueue.pop();
            lock.unlock();

            try {
