#include <iostream>
#include <string>

void modifyFilename(const std::string& originalFilename, char* newFilename, int bufferSize) {
    // Assuming the file type is after the last dot and before any digits
    size_t lastDot = originalFilename.find_last_of('.');
    if (lastDot == std::string::npos) {
        return; // No extension found
    }

    std::string baseName = originalFilename.substr(0, lastDot);
    std::string fileType = originalFilename.substr(lastDot + 1);

    // Count digits in the base name
    int digitCount = 0;
    for (char c : baseName) {
        if (isdigit(c)) {
            digitCount++;
        }
    }

    // Construct new filename
    sprintf(newFilename, "%s%0*d.%s", baseName.c_str(), digitCount + 3, digitCount, fileType.c_str());
}

int main() {
    char newFilename[256];
    modifyFilename("sensor_data_123.txt", newFilename, sizeof(newFilename));
    std::cout << "New Filename: " << newFilename << std::endl;
    return 0;
}
