        std::lock_guard<std::mutex> lock(mapMutex);
        sensorMap[id] = data;
        cv.notify_one();
    }

    bool deleteSensor(const std::string& id) {
        std::lock_guard<std::mutex> lock(mapMutex);
        auto it = sensorMap.find(id);
        if (it != sensorMap.end()) {
            sensorMap.erase(it);
            return true;
        }
        return false;
    }

    SensorData getSensor(const std::string& id) {
        std::unique_lock<std::mutex> lock(mapMutex);
        cv.wait(lock, [this, &id]{ return !sensorMap.empty() || running == false; });
        auto it = sensorMap.find(id);
        if (it != sensorMap.end()) {
            return it->second;
        }
        // Handle error or throw exception
