#include <stdlib.h>
#include <pthread.h>
#include <sqlite3.h>

// Define configuration parameters
#define MAX_OFFSETS 1000
#define MAX_KEYS 1000
#define MAX_RECORDS 1000
#define MIN_VALUE 0
#define MAX_VALUE 1000

// Define record structure
typedef struct {
    int value;
} record;

// Define global data structures and mutexes
long offsets[MAX_OFFSETS];
int keys[MAX_KEYS];
record records[MAX_RECORDS];
pthread_mutex_t offset_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t key_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the distributed collection
int init_distributed_collection() {
    // Allocate memory for data structures
    if (posix_memalign((void**)&offsets, 64, MAX_OFFSETS * sizeof(long)) != 0) {
        return -1;
    }
    if (posix_memalign((void**)&keys, 64, MAX_KEYS * sizeof(int)) != 0) {
        free(offsets);
        return -2;
    }
    if (posix_memalign((void**)&records, 64, MAX_RECORDS * sizeof(record)) != 0) {
        free(keys);
        free(offsets);
        return -3;
    }

    // Initialize mutexes
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&offset_lock, &attr);
    pthread_mutex_init(&key_lock, &attr);
    pthread_mutex_init(&record_lock, &attr);

    return 0;
}

// Function to store a record in the distributed collection
int store_record(int key, int value) {
    // Locks for thread safety
    pthread_mutex_lock(&key_lock);
    pthread_mutex_lock(&record_lock);

    // Find an available slot
    int record_index = -1;
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].value == 0) {
            record_index = i;
            break;
        }
    }

    if (record_index == -1) {
        // No available slot
        pthread_mutex_unlock(&key_lock);
        pthread_mutex_unlock(&record_lock);
        return -4;
    }

    // Store the record
    records[record_index].value = value;

    // Find an available offset
    int offset_index = -1;
    for (int i = 0; i < MAX_OFFSETS; i++) {
        if (offsets[i] == 0) {
            offset_index = i;
            break;
        }
    }

    if (offset_index == -1) {
        // No available slot
        pthread_mutex_unlock(&key_lock);
        pthread_mutex_unlock(&record_lock);
        return -5;
    }

    // Store the offset
    offsets[offset_index] = key;

    // Unlock mutexes
    pthread_mutex_unlock(&key_lock);
    pthread_mutex_unlock(&record_lock);

    // Persist to external database
    sqlite3 *db;
    sqlite3_stmt *stmt;
    int rc = sqlite3_open("my_database.db", &db);
    if (rc != SQLITE_OK) {
        return -6;
    }

    char sql[256];
    snprintf(sql, sizeof(sql), "INSERT INTO records (key, value) VALUES (%d, %d)", key, value);
    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, 0);
    if (rc != SQLITE_OK) {
        sqlite3_close(db);
        return -7;
    }

    rc = sqlite3_step(stmt);
    if (rc != SQLITE_DONE) {
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return -8;
    }

    sqlite3_finalize(stmt);
    sqlite3_close(db);

    return 0;
}

// Function to retrieve a record from the distributed collection
int retrieve_record(int key, int *value) {
    // Locks for thread safety
    pthread_mutex_lock(&key_lock);
    pthread_mutex_lock(&record_lock);

    // Find the offset
    int offset_index = -1;
    for (int i = 0; i < MAX_OFFSETS; i++) {
        if (offsets[i] == key) {
            offset_index = i;
            break;
        }
    }

    if (offset_index == -1) {
        // Key not found
        pthread_mutex_unlock(&key_lock);
        pthread_mutex_unlock(&record_lock);
        return -9;
    }

    // Retrieve the record value
    *value = records[offset_index].value;

    // Unlock mutexes
    pthread_mutex_unlock(&key_lock);
    pthread_mutex_unlock(&record_lock);

    return 0;
}

// Function to clean up resources
void cleanup_distributed_collection() {
    // Free memory
    free(offsets);
    free(keys);
    free(records);

    // Destroy mutexes
    pthread_mutex_destroy(&offset_lock);
    pthread_mutex_destroy(&key_lock);
    pthread_mutex_destroy(&record_lock);
}
