typedef struct {
    time_t timestamp;
    int device_id;
    int signal_strength;
    // Other fields...
} DeviceStatusReport;

typedef struct {
    DeviceStatusReport *reports;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} ReportManager;

ReportManager* report_manager_create() {
    ReportManager *manager = malloc(sizeof(ReportManager));
    manager->reports = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void report_manager_add(ReportManager *manager, DeviceStatusReport report) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        // Resize array
        manager->capacity *= 2;
        manager->reports = realloc(manager->reports, manager->capacity * sizeof(DeviceStatusReport));
    }
    manager->reports[manager->count++] = report;
    pthread_mutex_unlock(&manager->lock);
}

DeviceStatusReport* report_manager_get_by_device_id(ReportManager *manager, int device_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->reports[i].device_id == device_id) {
            pthread_mutex_unlock(&manager->lock);
            return &manager->reports[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void report_manager_update(ReportManager *manager, int device_id, DeviceStatusReport new_report) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->reports[i].device_id == device_id) {
            manager->reports[i] = new_report;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void report_manager_destroy(ReportManager *manager) {
    free(manager->reports);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
