    void stop() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            is_active = false;
        }
        condition_.notify_all();
        if (worker_thread_.joinable()) {
            worker_thread_.join();
        }
    }

    template <typename T>
    void ingestData(const std::string& key, const T& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        data_queue_.push({key, std::any_cast<T>(data)});
        condition_.notify_one();
    }

private:
    void processData() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return !is_active || !data_queue_.empty(); });
            if (!is_active && data_queue_.empty()) {
                break;
            }
            auto item = data_queue_.front();
            data_queue_.pop();
            lock.unlock();

            // Process the data
            processDataItem(item);
        }
    }

    void processDataItem(const std::pair<std::string, std::any>& item) {
        const auto& [key, data] = item;
        if (schema.find(key) != schema.end()) {
            // Perform data transformation and aggregation here
        } else {
            // Handle unknown schema
        }
    }

    Schema schema;
    std::thread worker_thread_;
    std::mutex mutex_;
    std::condition_variable condition_;
    std::queue<std::pair<std::string, std::any>> data_queue_;
    bool is_active;
};

}  // namespace DataStreamProcessor
```

This code snippet provides a basic structure for a modular C++ library that processes heterogeneous data streams in real-time. It includes the necessary components for dependency management, concurrency and scalability, performance optimization, resource management, error handling, data schema flexibility, aggregation and transformation, testing, usability, and configuration. The actual implementation of data processing logic is left to be developed based on specific requirements and use cases.']

