#include <atomic>

class ImageDatasetManager {
public:
    void uploadImage(const std::string& imagePath) {
        // Compress and format conversion logic here
        std::cout << "Uploading image: " << imagePath << std::endl;
    }

    void downloadImage(const std::string& cloudPath, const std::string& localPath) {
        // Download and decompression logic here
        std::cout << "Downloading image from: " << cloudPath << " to " << localPath << std::endl;
    }

private:
    std::queue<std::string> uploadQueue;
    std::queue<std::pair<std::string, std::string>> downloadQueue;

    std::thread uploadThread;
    std::thread downloadThread;

    std::mutex queueMutex;
    std::condition_variable cv;

    void uploadWorker() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait(lock, [this] { return !uploadQueue.empty(); });
            std::string imagePath = uploadQueue.front();
            uploadQueue.pop();
            lock.unlock();

            uploadImage(imagePath);

            // Adjust upload rate based on network conditions and API limits
        }
    }

    void downloadWorker() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait(lock, [this] { return !downloadQueue.empty(); });
            auto [cloudPath, localPath] = downloadQueue.front();
            downloadQueue.pop();
            lock.unlock();

            downloadImage(cloudPath, localPath);

            // Adjust download rate based on network conditions and API limits
        }
    }

public:
    ImageDatasetManager() {
        uploadThread = std::thread(&ImageDatasetManager::uploadWorker, this);
        downloadThread = std::thread(&ImageDatasetManager::downloadWorker, this);
    }

    ~ImageDatasetManager() {
        // Stop worker threads gracefully
        uploadQueue.push("STOP");
        downloadQueue.push({"STOP", ""});
        uploadThread.join();
        downloadThread.join();
    }
};

int main() {
    ImageDatasetManager manager;
    manager.uploadImage("path/to/local/image.jpg");
    manager.downloadImage("cloud/path/to/image.jpg", "path/to/local/downloaded_image.jpg");

    return 0;
}
```

