typedef struct {
    double metrics[NUM_METRICS];
    pthread_mutex_t lock;
} RecordData;

RecordData records[MAX_RECORDS] = {{.lock = PTHREAD_MUTEX_INITIALIZER}};
double moving_average[NUM_METRICS] = {0};
int current_index = 0, record_count = 0;

void update_record(const char *line) {
    // Parse the line and store the metrics in the buffer
    // This is a placeholder for actual parsing logic
}

void compute_moving_average() {
    pthread_mutex_lock(&records[current_index].lock);
    for (int i = 0; i < NUM_METRICS; i++) {
        moving_average[i] += records[(current_index + i) % MAX_RECORDS].metrics[i];
    }
    for (int i = 0; i < NUM_METRICS; i++) {
        moving_average[i] /= record_count;
    }
    pthread_mutex_unlock(&records[current_index].lock);
}

void* process_log_file(void *arg) {
    FILE *file = fopen("log.txt", "r");
    if (!file) {
        perror("Failed to open log file");
        return NULL;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        update_record(line);
        compute_moving_average();
        current_index = (current_index + 1) % MAX_RECORDS;
        record_count++;
    }

    fclose(file);
    return NULL;
}

void send_to_server() {
