    ErrorCode** error_codes;
    int error_count;
} DeviceStatusReport;

typedef struct DeviceStatusReportList {
    DeviceStatusReport** reports;
    int count;
    pthread_mutex_t lock;
} DeviceStatusReportList;

void initDeviceStatusReportList(DeviceStatusReportList* list) {
    list->reports = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void addDeviceStatusReport(DeviceStatusReportList* list, DeviceStatusReport report) {
    pthread_mutex_lock(&list->lock);
    DeviceStatusReport** new_reports = realloc(list->reports, (list->count + 1) * sizeof(DeviceStatusReport*));
    if (new_reports == NULL) {
        // Handle memory allocation failure
        return;
    }
    list->reports = new_reports;
    list->reports[list->count] = &report;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

