#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the DeviceStatusReport structure
typedef struct {
    time_t timestamp;
    int deviceId;
    float signalStrength;
    int *errorCodes;
    int errorCodeCount;
} DeviceStatusReport;

// Define the DeviceStatusManager structure
typedef struct {
    DeviceStatusReport **reports;
    size_t count;
    pthread_mutex_t mutex;
} DeviceStatusManager;

// Initialize the DeviceStatusManager
void initDeviceStatusManager(DeviceStatusManager *manager) {
    manager->reports = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
}

// Add a report to the DeviceStatusManager
void addReport(DeviceStatusManager *manager, DeviceStatusReport *report) {
    pthread_mutex_lock(&manager->mutex);
    manager->reports = realloc(manager->reports, (manager->count + 1) * sizeof(DeviceStatusReport *));
    manager->reports[manager->count] = report;
    manager->count++;
    pthread_mutex_unlock(&manager->mutex);
}

// Retrieve a report from the DeviceStatusManager
DeviceStatusReport* getReport(DeviceStatusManager *manager, int deviceId) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->reports[i]->deviceId == deviceId) {
            pthread_mutex_unlock(&manager->mutex);
            return manager->reports[i];
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}

// Update a report in the DeviceStatusManager
void updateReport(DeviceStatusManager *manager, DeviceStatusReport *newReport) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->reports[i]->deviceId == newReport->deviceId) {
            // Free old error codes
            free(manager->reports[i]->errorCodes);
            manager->reports[i] = newReport;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

// Delete a report from the DeviceStatusManager
void deleteReport(DeviceStatusManager *manager, int deviceId) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->reports[i]->deviceId == deviceId) {
            // Free old error codes
            free(manager->reports[i]->errorCodes);
            // Shift remaining reports
            for (size_t j = i + 1; j < manager->count; j++) {
                manager->reports[j - 1] = manager->reports[j];
            }
            manager->count--;
            // Resize array if necessary
            if ((manager->count > 0) && (manager->count * 4 <= manager->count)) {
                manager->reports = realloc(manager->reports, manager->count * sizeof(DeviceStatusReport *));
            }
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

// Process a resource bundle
void processResourceBundle(DeviceStatusManager *manager, DeviceStatusReport *report) {
    addReport(manager, report);
}
