import io.github.resilience4j.circuitbreaker.CircuitBreaker;
import io.github.resilience4j.circuitbreaker.CircuitBreakerConfig;
import io.github.resilience4j.retry.Retry;
import io.github.resilience4j.retry.RetryConfig;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;

public class ErrorLoggingService {
    private final CircuitBreaker circuitBreaker;
    private final Retry retry;
    private final ObjectMapper objectMapper = new ObjectMapper();
    private final int batchSize = 100;
    private final long batchInterval = 500L; // milliseconds
    private final String logServiceUrl = "https://external-error-log-service.com/log";
    private ErrorLogBatch currentBatch;

    public ErrorLoggingService() {
        CircuitBreakerConfig circuitBreakerConfig = CircuitBreakerConfig.custom()
                .failureRateThreshold(50)
                .waitDurationInOpenState(Duration.ofMillis(1000))
                .build();
        RetryConfig retryConfig = RetryConfig.custom()
                .maxAttempts(5)
                .waitDuration(Duration.ofMillis(200))
                .retryOnResult(this::isTransientError)
                .build();

        this.circuitBreaker = CircuitBreaker.of("errorLogCircuitBreaker", circuitBreakerConfig);
        this.retry = Retry.of("errorLogRetry", retryConfig);

        currentBatch = new ErrorLogBatch(batchSize, batchInterval);
    }

    public void logError(byte[] errorData) {
        try {
            ErrorLogEntry errorLog = deserialize(errorData);
            CompletableFuture.runAsync(() -> circuitBreaker.executeRunnable(this::logBatch), CompletableFuture::runAsync)
                    .exceptionally(ex -> {
                        handleLoggingFailure(ex);
                        return null;
                    });
        } catch (IOException e) {
            throw new RuntimeException("Failed to deserialize error data", e);
        }
    }

    private ErrorLogEntry deserialize(byte[] errorData) throws IOException {
        try {
            return objectMapper.readValue(errorData, ErrorLogEntry.class);
        } catch (IOException e) {
            throw new RuntimeException("Error deserializing error log entry", e);
        }
    }

    private void logBatch() {
        while (!currentBatch.isEmpty()) {
            Retry retry = Retry.decorateRunnable(this.retry, () -> sendLogs(currentBatch.get()));
            circuitBreaker.executeRunnable(retry);
        }
    }

    private boolean isTransientError(Throwable result) {
        return result instanceof IOException || result instanceof RuntimeException;
    }

    private void sendLogs(List<ErrorLogEntry> logs) throws IOException {
        String json = objectMapper.writeValueAsString(logs);
        // Code to send JSON payload to the external log service
    }

    private void handleLoggingFailure(Throwable ex) {
        if (ex instanceof CircuitBreakerOpenException) {
            // Handle circuit breaker open state
        } else if (ex instanceof RetryExhaustedException) {
            // Handle retry exhaustion
        }
    }

    static class ErrorLogBatch {
        private final List<ErrorLogEntry> logs;
        private final long interval;

        public ErrorLogBatch(int size, long interval) {
            this.logs = new ArrayList<>(size);
            this.interval = interval;
        }

        public void add(ErrorLogEntry logEntry) {
            logs.add(logEntry);
        }

        public boolean isEmpty() {
            return logs.isEmpty();
        }

        public List<ErrorLogEntry> get() {
            return logs;
        }
    }
