#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <openssl/evp.h>

class CryptoLibrary {
public:
    enum class Algorithm { DES, AES, RSA, NULL_ENCRYPTION };
    enum class Mode { ECB, CBC, CTR, GCM };

    CryptoLibrary(Algorithm algorithm = Algorithm::NULL_ENCRYPTION, Mode mode = Mode::ECB) 
        : algorithm_(algorithm), mode_(mode) {}

    void setParameters(Algorithm algorithm, Mode mode) {
        algorithm_ = algorithm;
        mode_ = mode;
    }

    std::vector<unsigned char> encrypt(const std::vector<unsigned char>& data, const std::vector<unsigned char>& key, const std::vector<unsigned char>& iv) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) throw std::runtime_error("Failed to create cipher context");

        if (EVP_EncryptInit_ex(ctx, getOpenSSLAlgorithm(), nullptr, key.data(), iv.data()) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Failed to initialize encryption");
        }

        std::vector<unsigned char> output(data.size() + EVP_CIPHER_block_size(getOpenSSLAlgorithm()));
        int len;
        if (EVP_EncryptUpdate(ctx, output.data(), &len, data.data(), data.size()) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Failed to encrypt data");
        }
        int final_len;
        if (EVP_EncryptFinal_ex(ctx, output.data() + len, &final_len) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Failed to finalize encryption");
        }

        output.resize(len + final_len);
        EVP_CIPHER_CTX_free(ctx);

        return output;
    }

    std::vector<unsigned char> decrypt(const std::vector<unsigned char>& encrypted_data, const std::vector<unsigned char>& key, const std::vector<unsigned char>& iv) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) throw std::runtime_error("Failed to create cipher context");

        if (EVP_DecryptInit_ex(ctx, getOpenSSLAlgorithm(), nullptr, key.data(), iv.data()) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Failed to initialize decryption");
        }

        std::vector<unsigned char> output(encrypted_data.size());
        int len;
        if (EVP_DecryptUpdate(ctx, output.data(), &len, encrypted_data.data(), encrypted_data.size()) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Failed to decrypt data");
        }
        int final_len;
        if (EVP_DecryptFinal_ex(ctx, output.data() + len, &final_len) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Failed to finalize decryption");
        }

        output.resize(len + final_len);
        EVP_CIPHER_CTX_free(ctx);

        return output;
    }

private:
    Algorithm algorithm_;
    Mode mode_;

    EVP_CIPHER* getOpenSSLAlgorithm() const {
        switch (algorithm_) {
            case Algorithm::DES: return EVP_des_ecb();
            case Algorithm::AES: return EVP_aes_256_cbc();
            case Algorithm::RSA: throw std::runtime_error("RSA not supported in this version");
            case Algorithm::NULL_ENCRYPTION: return nullptr;
        }
        throw std::runtime_error("Unknown algorithm");
    }

    static std::mutex encryptionMutex_;
};

std::mutex CryptoLibrary::encryptionMutex_;

int main() {
    // Example usage
    try {
        CryptoLibrary crypto(CryptoLibrary::Algorithm::AES, CryptoLibrary::Mode::CBC);
        std::vector<unsigned char> key(32); // AES-256 key size
        std::vector<unsigned char> iv(16);  // AES block size

        std::vector<unsigned char> plainText = { 'H', 'e', 'l', 'l', 'o', ',', ' ', 'W', 'o', 'r', 'l', 'd', '!' };
        std::vector<unsigned char> encryptedData = crypto.encrypt(plainText, key, iv);
        std::vector<unsigned char> decryptedData = crypto.decrypt(encryptedData, key, iv);

        for (auto& byte : decryptedData) {
            std::cout << byte;
        }
        std::cout << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
