// Main Application Class
@SpringBootApplication
public class PokemonReportServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(PokemonReportServiceApplication.class, args);
    }
}

// Service Layer Interface
public interface PokemonService {
    CompletableFuture<Pokemon> getPokemonDetails(String name);
}

// Service Layer Implementation
@Service
public class PokemonServiceImpl implements PokemonService {

    @Autowired
    private ExternalApiClient externalApiClient;

    @Autowired
    private CacheManager cacheManager;

    @Override
    public CompletableFuture<Pokemon> getPokemonDetails(String name) {
        // Check cache for existing data
        return cacheManager.getAsync("pokemon:" + name, () -> fetchPokemonFromExternalApi(name));
    }

    private Pokemon fetchPokemonFromExternalApi(String name) {
        // Fetch data from external API
        return externalApiClient.fetchPokemon(name);
    }
}

// External API Client
@RestController
public class ExternalApiController {

    @Autowired
    private RestTemplate restTemplate;

    public Pokemon fetchPokemon(String name) {
        // Call to external API and return result
        return restTemplate.getForObject("https://api.pokemontcg.io/v2/cards?name=" + name, Pokemon.class);
    }
}

// Cache Manager Configuration
@Configuration
public class CacheConfig {

    @Bean
    public CacheManager cacheManager() {
        CaffeineCacheManager caffeineCacheManager = new CaffeineCacheManager("pokemon");
        caffeineCacheManager.setCaffeine(caffeineBuilder());
        return caffeineCacheManager;
    }

    private Caffeine<Object, Object> caffeineBuilder() {
        return Caffeine.newBuilder()
                .expireAfterWrite(10, TimeUnit.MINUTES)
                .maximumSize(100);
    }
}

// Health Check and Circuit Breaker
@RestController
public class HealthCheckController {

    @Autowired
    private CircuitBreakerRegistry circuitBreakerRegistry;

    @GetMapping("/health")
    public String checkHealth() {
        CircuitBreaker circuitBreaker = circuitBreakerRegistry.circuitBreaker("externalApi");
        if (circuitBreaker.isOpen()) {
            return "Service is currently unavailable";
        }
        return "Service is healthy";
    }
}

// Tracing and Logging
@SpringBootApplication
public class PokemonReportServiceApplication {

    @Bean
    public Tracer tracer() {
        return GlobalTracer.get();
    }

    public static void main(String[] args) {
        SpringApplication.run(PokemonReportServiceApplication.class, args);
    }
}
