from cryptography.hazmat.primitives import serialization, hashes
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.asymmetric import padding
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC

class RNG:
    def __init__(self, seed):
        self.mt = random.Random(seed)

    def generate_int(self):
        return self.mt.randint(0, 2**31 - 1)

    def generate_float(self):
        return self.mt.random()

class RNGManager:
    def __init__(self, initial_seed, data_source_url):
        self.rng = RNG(initial_seed)
        self.data_source_url = data_source_url
        self.lock = threading.Lock()
        self.update_lock = threading.Lock()
        self.queue = queue.Queue()
        self.threads = []

    def run(self):
        for _ in range(10):  # Adjust number of threads based on load
            thread = threading.Thread(target=self.worker)
            thread.start()
            self.threads.append(thread)

        while True:
            time.sleep(1)
            with self.update_lock:
                if not self.queue.empty():
                    new_seed = self.fetch_new_seed_from_data_source()
                    if new_seed is not None:
                        with self.lock:
                            self.rng = RNG(new_seed)

    def worker(self):
        while True:
            request = self.queue.get()
            if request is None:
                break
            response = []
            for _ in range(request['count']):
                if request['type'] == 'int':
                    response.append(self.rng.generate_int())
                elif request['type'] == 'float':
                    response.append(self.rng.generate_float())
            self.queue.task_done()
            request['callback'](response)

    def fetch_new_seed_from_data_source(self):
        try:
            response = requests.get(self.data_source_url)
            if response.status_code == 200:
                return int(response.text)
            else:
                logging.error(f"Failed to fetch new seed: {response.status_code}")
        except requests.exceptions.RequestException as e:
            logging.error(f"Request failed: {e}")
        return None

    def generate_numbers(self, count, number_type):
        response = []
        def callback(result):
            nonlocal response
            response.extend(result)

        self.queue.put({'count': count, 'type': number_type, 'callback': callback})
        self.queue.join()
        return response

class ConfigManager:
