    {
        // Simulate adding an edge to the graph database
        await Task.Delay(100);
    }

    public async Task<IDataReader> ExecuteQuery(string query, int? limit = null, int? offset = null)
    {
        if (_cache.TryGetValue(query, out var cachedResult))
        {
            return (IDataReader)cachedResult;
        }

        var result = await FetchDataFromDatabase(query, limit, offset);
        _cache.TryAdd(query, result);

        return result;
    }

    private async Task<IDataReader> FetchDataFromDatabase(string query, int? limit, int? offset)
