        # Implementation to send push notification
        pass

class MessageRouter:
    def __init__(self, external_service):
        self.external_service = external_service
        self.email_queue = MessageQueue()
        self.sms_queue = MessageQueue()
        self.push_notification_queue = MessageQueue()

    def route_message(self, message):
        if message.priority == 'high':
            self.email_queue.enqueue(message)
            self.sms_queue.enqueue(message)
            self.push_notification_queue.enqueue(message)
        elif message.priority == 'medium':
            self.email_queue.enqueue(message)
            self.sms_queue.enqueue(message)
        else:
            self.email_queue.enqueue(message)

class MessageDeliveryService:
    def __init__(self, external_service):
        self.external_service = external_service

    def deliver_messages(self):
        while True:
            email_message = message_router.email_queue.dequeue()
            if email_message:
                external_service.send_email(user_email, email_message.content)

            sms_message = message_router.sms_queue.dequeue()
            if sms_message:
                external_service.send_sms(user_phone, sms_message.content)

            push_notification_message = message_router.push_notification_queue.dequeue()
            if push_notification_message:
                external_service.send_push_notification(user_device_id, push_notification_message.content)

# Usage
