using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml.XPath;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class XmlParser
{
    private readonly ILogger<XmlParser> _logger;
    private readonly XPathNavigator _navigator;

    public XmlParser(XPathDocument document, ILogger<XmlParser> logger)
    {
        _navigator = document.CreateNavigator();
        _logger = logger;
    }

    public XPathNavigator GetSingleElement(string name, string namespaceUri = null)
    {
        var node = _navigator.SelectSingleNode($"//${namespaceUri}{name}", new XmlNamespaceManager(_navigator.NameTable));
        if (node == null) throw new InvalidOperationException("No matching element found.");
        if (_navigator.SelectNodes($"//${namespaceUri}{name}", new XmlNamespaceManager(_navigator.NameTable)).Count > 1)
            _logger.LogWarning("Multiple matches found for single query. Proceeding with first match.");
        return node;
    }

    public IEnumerable<XPathNavigator> GetMultipleElements(string name, string namespaceUri = null)
    {
        var nodes = _navigator.Select($"//${namespaceUri}{name}", new XmlNamespaceManager(_navigator.NameTable));
        if (nodes.Count() == 0) throw new InvalidOperationException("No matching elements found.");
        return nodes.Cast<XPathNavigator>();
    }

    public static async Task<XmlParser> FromUrlAsync(string url, ILogger<XmlParser> logger)
    {
        using var client = new System.Net.Http.HttpClient();
        try
        {
            var response = await client.GetAsync(url);
            response.EnsureSuccessStatusCode();
            var xmlContent = await response.Content.ReadAsStringAsync();
            return new XmlParser(new XPathDocument(new System.IO.StringReader(xmlContent)), logger);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to download XML from URL.");
            throw;
        }
    }

    // Additional methods for error handling, logging, performance optimization, etc.
}
