# Import necessary libraries
from flask import Flask, request, jsonify
from sqlalchemy import create_engine
import redis
import requests

app = Flask(__name__)

# Database connections
sql_db = create_engine('sqlite:///products.db')
no_sql_db = redis.StrictRedis(host='localhost', port=6379, db=0)

# External API client
third_party_api = 'https://api.example.com/products'

# Middleware for handling external service failures
def handle_failure(func):
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            print(f"Failed to call {func.__name__}: {e}")
            # Fallback logic here
            return jsonify({"error": "Service unavailable"}), 503
    return wrapper

# CRUD operations
@app.route('/products', methods=['POST'])
@handle_failure
def create_product():
    data = request.get_json()
    # SQL and NoSQL integration logic here
    sql_db.execute("INSERT INTO products (name, metadata) VALUES (?, ?)", (data['name'], data['metadata']))
    no_sql_db.set(data['id'], data)
    return jsonify({"message": "Product created successfully"}), 201

@app.route('/products/<product_id>', methods=['GET'])
@handle_failure
def get_product(product_id):
    # Cache lookup first
    product = no_sql_db.get(product_id)
    if not product:
        # Fetch from SQL and update cache
        result = sql_db.execute("SELECT * FROM products WHERE id = ?", (product_id,))
        product = result.fetchone()
        no_sql_db.set(product_id, product)
    return jsonify(product), 200

@app.route('/products/<product_id>', methods=['PUT'])
@handle_failure
def update_product(product_id):
    data = request.get_json()
    # Update SQL and NoSQL databases
    sql_db.execute("UPDATE products SET name = ?, metadata = ? WHERE id = ?", (data['name'], data['metadata'], product_id))
    no_sql_db.set(product_id, data)
    return jsonify({"message": "Product updated successfully"}), 200

@app.route('/products/<product_id>', methods=['DELETE'])
@handle_failure
def delete_product(product_id):
    # Delete from SQL and NoSQL databases
    sql_db.execute("DELETE FROM products WHERE id = ?", (product_id,))
    no_sql_db.delete(product_id)
    return jsonify({"message": "Product deleted successfully"}), 204

# Run the Flask application
if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

