class UserAccount {
    // Database connection properties
    private $host = 'localhost';
    private $username = 'your_username';
    private $password = 'your_password';
    private $dbname = 'your_database';

    public function __construct() {
        $this->conn = new mysqli($this->host, $this->username, $this->password, $this->dbname);
        if ($this->conn->connect_error) {
            die("Connection failed: " . $this->conn->connect_error);
        }
    }

    // CRUD methods
    public function create($data) {
        $stmt = $this->conn->prepare("INSERT INTO users (name, email) VALUES (?, ?)");
        $stmt->bind_param("ss", $data['name'], $data['email']);
        return $stmt->execute();
    }

    public function read($id) {
        $stmt = $this->conn->prepare("SELECT * FROM users WHERE id = ?");
        $stmt->bind_param("i", $id);
        $stmt->execute();
        return $stmt->get_result()->fetch_assoc();
    }

    public function update($id, $data) {
        $stmt = $this->conn->prepare("UPDATE users SET name = ?, email = ? WHERE id = ?");
        $stmt->bind_param("ssi", $data['name'], $data['email'], $id);
        return $stmt->execute();
    }

    public function delete($id) {
        $stmt = $this->conn->prepare("DELETE FROM users WHERE id = ?");
        $stmt->bind_param("i", $id);
        return $stmt->execute();
    }
}

// Implement a Circuit Breaker pattern for resilient messaging
class CircuitBreaker {
    private $open = false;
    private $timeout = 10;

    public function call($callable, $params) {
        if ($this->open) {
            throw new Exception("Circuit breaker is open");
        }

        try {
            return call_user_func_array($callable, $params);
        } catch (Exception $e) {
            $this->open = true;
            sleep($this->timeout);
            return $this->call($callable, $params); // Retry
        }
    }
}

// Example usage of UserAccount and CircuitBreaker
$userAccount = new UserAccount();
$circuitBreaker = new CircuitBreaker();

$data = ['name' => 'John Doe', 'email' => 'john@example.com'];
try {
    $circuitBreaker->call([$userAccount, 'create'], [$data]);
} catch (Exception $e) {
    echo "Error: " . $e->getMessage();
}
?>
