// JavaScript function to refresh dialog fields in an Angular application
function refreshDialogFields(resourceId, url) {
    const targetFieldNames = ['email', 'phone'];
    const fields = document.querySelectorAll('.dialog-field');

    fields.forEach(field => {
        if (targetFieldNames.includes(field.name)) {
            fetch(url + '?resourceId=' + resourceId)
                .then(response => response.json())
                .then(result => {
                    field.value = result[field.name];
                    window.parent.postMessage({ fieldName: field.name, value: result[field.name] }, '*');
                })
                .catch(error => console.error('Error:', error));
        }
    });
}
