use std::time::{Instant};
use rustc_driver::{self, catches_signals};
use std::process;
use get_resident_set_size::get_resident_set_size;

fn main() {
    let start = Instant::now();

    let mut args: Vec<String> = std::env::args().collect();

    // Remove the first argument which is the path to the rustc binary
    args.remove(0);

    let compiler_args = args.clone();

    let result = catches_signals(|| {
        rustc_driver::catch_with_exit_code(
            &compiler_args,
            None,
            Some(&rustc_session::early_error)
        )
    });

    let duration = start.elapsed();
    println!("Compilation took: {:?}", duration);

    match result {
        Ok(exit_code) => process::exit(exit_code),
        Err(e) => early_error(None, &format!("{}", e)),
    }

    let mem_usage_before = get_resident_set_size().unwrap_or(0);
    rustc_driver::run_compiler(&compiler_args, |compiler| {
        // Compilation logic here
        Ok(())
    }).unwrap();

    let mem_usage_after = get_resident_set_size().unwrap_or(0);
    println!("Memory usage before compilation: {} bytes", mem_usage_before);
    println!("Memory usage after compilation: {} bytes", mem_usage_after);
}
