    private readonly HttpClient _httpClient;

    public DynamicDataAggregator()
    {
        _dataSources = new Dictionary<string, DataSource>();
        _httpClient = new HttpClient();
    }

    public void AddDataSource(string url, string format, Dictionary<string, object> transformationRules)
    {
        if (!_dataSources.ContainsKey(url))
        {
            var dataSource = new DataSource(url, format, transformationRules);
            _dataSources[url] = dataSource;
        }
    }

    public async Task<List<object>> AggregateDataAsync()
    {
        List<object> aggregatedData = new List<object>();

        foreach (var dataSource in _dataSources)
        {
            try
            {
                var data = await FetchAndTransformDataAsync(dataSource.Value);
                if (data != null)
                {
                    aggregatedData.AddRange(data);
                }
            }
            catch (Exception ex)
            {
                // Handle exceptions and fallbacks here
                Console.WriteLine($"Error fetching or transforming data from {dataSource.Key}: {ex.Message}");
            }
        }

        return aggregatedData;
    }

    private async Task<List<object>> FetchAndTransformDataAsync(DataSource dataSource)
    {
        var response = await _httpClient.GetAsync(dataSource.Url);
        if (response.IsSuccessStatusCode)
        {
            string content = await response.Content.ReadAsStringAsync();
            return TransformData(content, dataSource.Format, dataSource.TransformationRules);
        }
        else
