// DynamicFormUpdater directive
angular.module('DynamicFormModule')
  .directive('dynamicFormUpdater', ['$http', '$timeout', function($http, $timeout) {
    return {
      restrict: 'A',
      scope: {
        resourceId: '@',
        apiUrl: '@'
      },
      link: function(scope, element, attrs) {
        var cache = {};
        var retryAttempts = 0;
        const MAX_RETRIES = 5;
        const RETRY_INTERVAL = 2000;

        function fetchAndUpdateForm() {
          if (cache[scope.resourceId]) {
            updateForm(cache[scope.resourceId]);
          } else {
            fetchDataFromAPI();
          }
        }

        function fetchDataFromAPI() {
          $http.get(scope.apiUrl + scope.resourceId)
            .then(function(response) {
              cache[scope.resourceId] = response.data;
              updateForm(response.data);
            })
            .catch(function(error) {
              handleApiError(error);
            });
        }

        function handleApiError(error) {
          if (retryAttempts < MAX_RETRIES) {
            retryAttempts++;
            $timeout(fetchDataFromAPI, RETRY_INTERVAL);
          } else {
            console.error('Max retries reached for resource ID:', scope.resourceId);
          }
        }

        function updateForm(data) {
          // Update form fields based on data
          element.find('input').each(function() {
            var field = $(this).attr('name');
            if (data[field]) {
              $(this).val(data[field]);
            }
          });
        }

        fetchAndUpdateForm();
      }
    };
  }]);

