// module-loader.ts

export class ModuleLoader {
  private cache: { [key: string]: any } = {};
  private errorLog: string[] = [];
  private loadingPromises: { [key: string]: Promise<any> } = {};

  async loadModule(moduleUrl: string): Promise<any> {
    if (this.cache[moduleUrl]) {
      return this.cache[moduleUrl];
    }

    if (this.loadingPromises[moduleUrl]) {
      return await this.loadingPromises[moduleUrl];
    }

    try {
      const loadingPromise = fetch(moduleUrl)
        .then(response => response.text())
        .then(text => eval(text))
        .catch(error => {
          this.logError(`Failed to load module ${moduleUrl}: ${error}`);
          throw error;
        });

      this.loadingPromises[moduleUrl] = loadingPromise;

      const module = await loadingPromise;
      this.cache[moduleUrl] = module;
      return module;
    } catch (error) {
      this.logError(`Module loading failed for ${moduleUrl}: ${error}`);
      throw error;
    }
  }

  logError(message: string): void {
    this.errorLog.push(message);
    console.error(message); // Log to the console or integrate with a logging service
  }

  getErrorLog(): string[] {
    return this.errorLog;
  }
}
```

