// auth_service.rs
use tokio::sync::mpsc;
use std::collections::HashMap;

pub struct AuthService {
    idp_client: IdPClient,
    token_cache: HashMap<String, String>,
}

impl AuthService {
    pub fn new(idp_url: &str) -> Self {
        let idp_client = IdPClient::new(idp_url);
        AuthService {
            idp_client,
            token_cache: HashMap::new(),
        }
    }

    pub async fn authenticate(&mut self, username: &str, password: &str) -> Result<String, String> {
        if let Some(token) = self.token_cache.get(username) {
            return Ok(token.clone());
        }
        match self.idp_client.authenticate(username, password).await {
            Ok(new_token) => {
                self.token_cache.insert(username.to_string(), new_token.clone());
                Ok(new_token)
            }
            Err(e) => Err(e),
        }
    }

    pub async fn refresh_token(&mut self, username: &str) -> Result<String, String> {
        if let Some(token) = self.token_cache.get(username) {
            match self.idp_client.refresh_token(token).await {
                Ok(new_token) => {
                    self.token_cache.insert(username.to_string(), new_token.clone());
                    Ok(new_token)
                }
                Err(e) => Err(e),
            }
        } else {
            Err("Token not found for user".to_string())
        }
    }
}

// idp_client.rs
use reqwest::Client;
use std::collections::HashMap;

pub struct IdPClient {
    client: Client,
    url: String,
}

impl IdPClient {
    pub fn new(url: &str) -> Self {
        IdPClient {
            client: Client::new(),
            url: url.to_string(),
        }
    }

    async fn authenticate(&self, username: &str, password: &str) -> Result<String, String> {
        let response = self.client.post(format!("{}/authenticate", self.url))
            .form(&[("username", username), ("password", password)])
            .send()
            .await?;
        match response.status() {
            reqwest::StatusCode::OK => {
                let data: HashMap<String, String> = response.json().await?;
                Ok(data["token"].clone())
            }
            _ => Err("Authentication failed".to_string()),
        }
    }

    async fn refresh_token(&self, token: &str) -> Result<String, String> {
        let response = self.client.post(format!("{}/refresh", self.url))
            .form(&[("token", token)])
            .send()
            .await?;
        match response.status() {
            reqwest::StatusCode::OK => {
                let data: HashMap<String, String> = response.json().await?;
                Ok(data["new_token"].clone())
            }
            _ => Err("Token refresh failed".to_string()),
        }
    }
}

