use std::collections::HashMap;

pub struct Metrics {
    data: Mutex<HashMap<String, u64>>,
}

impl Metrics {
    pub fn new() -> Self {
        Metrics {
            data: Mutex::new(HashMap::new()),
        }
    }

    pub async fn update(&self, key: &str, value: u64) {
        let mut data = self.data.lock().await;
        *data.entry(key.to_string()).or_insert(0) += value;
    }

    pub async fn get(&self, key: &str) -> Option<u64> {
        let data = self.data.lock().await;
        data.get(key).cloned()
    }
}

