const express = require('express');
const axios = require('axios');
const { createClient } = require('redis');
const retry = require('async-retry');

const app = express();
app.use(express.json());

// Redis client setup for data storage
const redisClient = createClient();

// Third-party service URLs and configurations
const exchangeAPIs = [
  'https://api.exchange1.com/data',
  'https://api.exchange2.com/data'
];

const cloudStorageURL = 'https://storage.googleapis.com/my-bucket';
const analyticsPlatformURL = 'https://analytics.api.com/ingest';

// Circuit breaker state
let isCircuitOpen = false;
let circuitBreakerCount = 0;

// Anomaly detection thresholds and configurations
const anomalyThresholds = {
  low: 10,
  high: 20,
  timeOfDayAdjustment: {
    morning: { low: 5, high: 15 },
    afternoon: { low: 7, high: 18 }
  }
};

// Middleware to handle circuit breaker logic
app.use(async (req, res, next) => {
  if (isCircuitOpen) {
    return res.status(503).send('Service is currently unavailable');
  }

  try {
    await retry(() => axios.get(req.url), { retries: 3 });
    next();
  } catch (error) {
    circuitBreakerCount++;
    if (circuitBreakerCount >= 10) {
      isCircuitOpen = true;
      setInterval(() => {
        circuitBreakerCount = 0;
        isCircuitOpen = false;
      }, 60000); // Reset after 1 minute
    }
    next(error);
  }
});

// Route to process financial market data from exchanges
app.post('/data', async (req, res) => {
  const { data } = req.body;

  try {
    // Store data in Redis for real-time processing
    await redisClient.set('marketData', JSON.stringify(data));

    // Send data to third-party services
    await Promise.all([
      axios.post(cloudStorageURL, data),
      axios.post(analyticsPlatformURL, data)
    ]);

    res.status(201).send('Data processed successfully');
  } catch (error) {
    console.error('Error processing data:', error);
    res.status(500).send('Internal Server Error');
  }
});

// Route to detect anomalies in market data
app.get('/anomalies', async (req, res) => {
  try {
    const data = JSON.parse(await redisClient.get('marketData'));

    // Anomaly detection logic
    const isAnomaly = checkForAnomaly(data);

    if (isAnomaly) {
      console.log('Anomaly detected:', data);
      await axios.post('https://alerts.api.com/trigger', { data, severity: 'high' });
    }

    res.status(200).send({ anomalyDetected: isAnomaly });
  } catch (error) {
    console.error('Error detecting anomalies:', error);
    res.status(500).send('Internal Server Error');
  }
});

// Function to check for anomalies in data
function checkForAnomaly(data) {
  const currentTime = new Date();
  const timeOfDay = currentTime.getHours();

  let thresholdLow, thresholdHigh;
  if (timeOfDay >= 9 && timeOfDay <= 12) {
    thresholdLow = anomalyThresholds.timeOfDayAdjustment.morning.low;
    thresholdHigh = anomalyThresholds.timeOfDayAdjustment.morning.high;
  } else if (timeOfDay >= 13 && timeOfDay <= 17) {
    thresholdLow = anomalyThresholds.timeOfDayAdjustment.afternoon.low;
    thresholdHigh = anomalyThresholds.timeOfDayAdjustment.afternoon.high;
  } else {
    thresholdLow = anomalyThresholds.low;
    thresholdHigh = anomalyThresholds.high;
  }

  return data < thresholdLow || data > thresholdHigh;
}

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
