use hyper::{Body, Request, Response, Server};
use hyper::service::{make_service_fn, service_fn};
use std::convert::Infallible;
use std::net::SocketAddr;
use tower_http::auth::{RequireAuthorizationLayer, Authorization, BasicCredentials};
use tower_http::limit::ConcurrencyLimitLayer;
use tower_http::trace::TraceLayer;
use tokio_tower::fallback::FallbackService;

async fn handle_request(_req: Request<Body>) -> Result<Response<Body>, Infallible> {
    Ok(Response::new(Body::from("Hello, world!")))
}

#[tokio::main]
async fn main() {
    let addr = SocketAddr::from(([127, 0, 0, 1], 3000));

    let make_svc = make_service_fn(|_conn| async {
        Ok::<_, Infallible>(service_fn(handle_request))
    });

    let limit_layer = ConcurrencyLimitLayer::new(100);
    let trace_layer = TraceLayer::new_for_http();
    let require_auth = RequireAuthorizationLayer::basic("realm", |auth: Authorization<BasicCredentials>| {
        auth.credentials.username == "admin" && auth.credentials.password == "password"
    });

    let service = make_svc
        .layer(limit_layer)
        .layer(trace_layer)
        .layer(require_auth);

    let server = Server::bind(&addr).serve(service.into_make_service());

    if let Err(e) = server.await {
        eprintln!("Server error: {}", e);
    }
}
