public class LoadBalancer {
    private List<PaymentGateway> gateways;
    private int currentIndex;

    public LoadBalancer(List<PaymentGateway> gateways) {
        this.gateways = gateways;
        this.currentIndex = 0;
    }

    public PaymentGateway selectGateway() {
        PaymentGateway gateway = gateways.get(currentIndex);
        currentIndex = (currentIndex + 1) % gateways.size();
        return gateway;
    }
}

