class UserDAO {
    private $connection;

    public function __construct($dbHost, $dbName, $dbUser, $dbPass) {
        try {
            $this->connection = new PDO("mysql:host=$dbHost;dbname=$dbName", $dbUser, $dbPass);
            $this->connection->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        } catch (PDOException $e) {
            // Log error to centralized system
            file_put_contents('error_log.json', json_encode(['timestamp' => date('c'), 'message' => $e->getMessage()]), FILE_APPEND);
            throw $e;
        }
    }

    public function updateUserPassword($userId, $newPassword) {
        $sql = "UPDATE users SET password = :password WHERE id = :id";
        $stmt = $this->connection->prepare($sql);
        $stmt->bindParam(':password', $newPassword);
        $stmt->bindParam(':id', $userId);

        if (!$stmt->execute()) {
            // Log error to centralized system
            file_put_contents('error_log.json', json_encode(['timestamp' => date('c'), 'message' => 'Failed to update user password']), FILE_APPEND);
            throw new Exception("Failed to update user password");
        }
    }

