    private $dao;

    public function __construct(UserDAO $dao) {
        $this->dao = $dao;
    }

    public function updatePassword($userId, $newPassword) {
        try {
            $this->validateUserId($userId);
            $this->validatePassword($newPassword);
            $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT);
            $this->dao->updateUserPassword($userId, $hashedPassword);
        } catch (Exception $e) {
            // Log error to centralized system
            file_put_contents('error_log.json', json_encode(['timestamp' => date('c'), 'message' => $e->getMessage()]), FILE_APPEND);
            throw $e;
        }
    }

    private function validatePassword($password) {
        if (strlen($password) < 8 || strlen($password) > 20) {
            throw new Exception("Password must be between 8 and 20 characters");
        }
        if (!preg_match('/[A-Z]/', $password)) {
            throw new Exception("Password must contain at least one uppercase letter");
        }
        if (!preg_match('/[a-z]/', $password)) {
            throw new Exception("Password must contain at least one lowercase letter");
        }
        if (!preg_match('/\d/', $password)) {
            throw new Exception("Password must contain at least one digit");
        }
        if (!preg_match('/[^A-Za-z0-9]/', $password)) {
            throw new Exception("Password must contain at least one special character");
        }
    }
}

