#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STATES 1000
#define MAX_TRANSITIONS 500

typedef enum {
    STATE_RUNNING,
    STATE_PAUSED,
    STATE_STOPPED
} State;

typedef struct {
    State currentState;
    int transitions[MAX_TRANSITIONS];
} FSA;

FSA fsa;

pthread_mutex_t mutex;
sem_t sem;

void initializeFSA() {
    pthread_mutex_init(&mutex, NULL);
    sem_init(&sem, 0, MAX_STATES);
    memset(fsa.transitions, -1, sizeof(int) * MAX_TRANSITIONS);
    fsa.currentState = STATE_STOPPED;
}

void lockFSA() {
    sem_wait(&sem);
    pthread_mutex_lock(&mutex);
}

void unlockFSA() {
    pthread_mutex_unlock(&mutex);
    sem_post(&sem);
}

int transitionState(State newState) {
    lockFSA();
    if (fsa.transitions[newState] == -1) {
        printf("Invalid state transition from %d to %d\n", fsa.currentState, newState);
        unlockFSA();
        return -1;
    }
    fsa.currentState = newState;
    unlockFSA();
    return 0;
}

