// CombatSystem.hpp
#pragma once

#include <vector>
#include <thread>
#include <atomic>
#include <chrono>
#include <mutex>
#include <condition_variable>
#include <memory>

class Combatant;
class AttackDatabase;

class CombatSystem {
public:
    CombatSystem(size_t maxCombatants, std::shared_ptr<AttackDatabase> db);
    ~CombatSystem();

    void start();
    void stop();
    void addCombatant(std::shared_ptr<Combatant> combatant);

private:
    void attackProcessorLoop();
    void fetchAttackDetails(const Combatant& combatant);

    size_t maxCombatants_;
    std::vector<std::shared_ptr<Combatant>> combatants_;
    std::atomic<bool> running_{false};
    std::thread processorThread_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;
};

// CombatSystem.cpp
#include "CombatSystem.hpp"

CombatSystem::CombatSystem(size_t maxCombatants, std::shared_ptr<AttackDatabase> db)
    : maxCombatants_(maxCombatants), combatants_(), running_(false) {
    // Initialize the attack database connection
}

CombatSystem::~CombatSystem() {
    stop();
}

void CombatSystem::start() {
    if (running_.exchange(true)) return;
    processorThread_ = std::thread(&CombatSystem::attackProcessorLoop, this);
}

void CombatSystem::stop() {
    if (!running_) return;
    running_.store(false);
    cv_.notify_all();
    processorThread_.join();
}

void CombatSystem::addCombatant(std::shared_ptr<Combatant> combatant) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (combatants_.size() < maxCombatants_) {
        combatants_.push_back(combatant);
    }
}

void CombatSystem::attackProcessorLoop() {
    while (running_) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait_for(lock, std::chrono::seconds(1), [this] { return !combatants_.empty(); });

        if (!running_) break;

        auto combatant = combatants_.back();
        combatants_.pop_back();
        lock.unlock();

        fetchAttackDetails(*combatant);
    }
}

