#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_FILES 1000000
#define MAX_THREADS 100

typedef struct {
    char *path;
    int version;
} FileData;

typedef struct {
    pthread_mutex_t lock;
    int thread_count;
} ThreadManager;

void* process_file(void* arg) {
    FileData *file = (FileData*)arg;
    // Simulate file processing
    sleep(1);
    printf("Processed file: %s, Version: %d\n", file->path, file->version);
    return NULL;
}

int main() {
    FileData files[MAX_FILES];
    ThreadManager thread_manager;

    pthread_mutex_init(&thread_manager.lock, NULL);
    thread_manager.thread_count = 0;

    // Populate files array with example data
    for (int i = 0; i < MAX_FILES; i++) {
        sprintf(files[i].path, "file%d.txt", i);
        files[i].version = rand() % 100;
    }

    pthread_t threads[MAX_THREADS];

    // Process files in parallel
    for (int i = 0; i < MAX_FILES; i++) {
        pthread_mutex_lock(&thread_manager.lock);
        if (thread_manager.thread_count >= MAX_THREADS) {
            pthread_cond_wait(&thread_manager.condition, &thread_manager.lock);
        }
        thread_manager.thread_count++;
        pthread_mutex_unlock(&thread_manager.lock);

        pthread_create(&threads[i], NULL, process_file, &files[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < MAX_FILES; i++) {
        pthread_join(threads[i], NULL);
        pthread_mutex_lock(&thread_manager.lock);
        thread_manager.thread_count--;
        pthread_cond_signal(&thread_manager.condition);
        pthread_mutex_unlock(&thread_manager.lock);
    }

    pthread_mutex_destroy(&thread_manager.lock);

    return 0;
}
```

