```c
// device_status_manager.c

#include "device_status_manager.h"
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    DeviceStatusReport* reports;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DeviceStatusManager;

static DeviceStatusManager manager = {0};

Status ds_manager_init() {
    // Initialize the manager
    manager.capacity = 128;
    manager.count = 0;
    manager.reports = (DeviceStatusReport*)malloc(manager.capacity * sizeof(DeviceStatusReport));
    if (!manager.reports) return STATUS_ERROR;

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&manager.mutex, &attr);
    pthread_mutexattr_destroy(&attr);

    return STATUS_SUCCESS;
}

Status ds_manager_update_report(DeviceStatusReport* report) {
    pthread_mutex_lock(&manager.mutex);
    if (manager.count >= manager.capacity) {
        DeviceStatusReport* new_reports = realloc(manager.reports, manager.capacity * 2 * sizeof(DeviceStatusReport));
        if (!new_reports) {
            pthread_mutex_unlock(&manager.mutex);
            return STATUS_ERROR;
        }
        manager.reports = new_reports;
        manager.capacity *= 2;
    }

    for (size_t i = 0; i < manager.count; ++i) {
        if (manager.reports[i].device_id == report->device_id) {
            memcpy(&manager.reports[i], report, sizeof(DeviceStatusReport));
            pthread_mutex_unlock(&manager.mutex);
            return STATUS_SUCCESS;
        }
    }

    manager.reports[manager.count++] = *report;
    pthread_mutex_unlock(&manager.mutex);
    return STATUS_SUCCESS;
}

Status ds_manager_get_report(uint64_t device_id, DeviceStatusReport* out_report) {
    pthread_mutex_lock(&manager.mutex);
    for (size_t i = 0; i < manager.count; ++i) {
        if (manager.reports[i].device_id == device_id) {
            memcpy(out_report, &manager.reports[i], sizeof(DeviceStatusReport));
            pthread_mutex_unlock(&manager.mutex);
            return STATUS_SUCCESS;
        }
    }
    pthread_mutex_unlock(&manager.mutex);
    return STATUS_DEVICE_NOT_FOUND;
}

void ds_manager_calculate_summary(float* avg_signal_strength, int* error_code_frequency, float* env_stats[2]) {
    // Calculate summary statistics
    *avg_signal_strength = 0.0f;
    memset(error_code_frequency, 0, sizeof(int) * 65536);
    env_stats[0] = (float*)calloc(2, sizeof(float)); // Temperature and Humidity
    env_stats[1] = (float*)calloc(2, sizeof(float));

    pthread_mutex_lock(&manager.mutex);
    for (size_t i = 0; i < manager.count; ++i) {
        *avg_signal_strength += manager.reports[i].signal_strength;
        error_code_frequency[manager.reports[i].error_code]++;
        env_stats[0][0] += manager.reports[i].temperature;
        env_stats[0][1] += manager.reports[i].humidity;
    }
    pthread_mutex_unlock(&manager.mutex);

    *avg_signal_strength /= manager.count;
    env_stats[0][0] /= manager.count;
    env_stats[0][1] /= manager.count;
}

void ds_manager_shutdown() {
    // Shutdown the manager
    free(manager.reports);
    pthread_mutex_destroy(&manager.mutex);
}
