// This is a high-level design sketch for a C library to manage device status reports.
// The actual implementation would require a detailed breakdown of each component.

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    char* device_id;
    int signal_strength;
    int error_code;
    void* environmental_metadata; // Pointer to variable length metadata
} DeviceStatusReport;

typedef struct {
    DeviceStatusReport** reports;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DeviceStatusManager;

// Initialize the manager with a given initial capacity
void init_manager(DeviceStatusManager* manager, size_t initial_capacity) {
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->reports = (DeviceStatusReport**)malloc(initial_capacity * sizeof(DeviceStatusReport*));
    pthread_mutex_init(&manager->lock, NULL);
}

// Function to add or update a report
void add_or_update_report(DeviceStatusManager* manager, DeviceStatusReport* report) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; i++) {
        if (strcmp(manager->reports[i]->device_id, report->device_id) == 0) {
            // Update existing report
            free(manager->reports[i]);
            manager->reports[i] = report;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }
    // Add new report
    if (manager->count >= manager->capacity) {
        manager->capacity *= 2;
        manager->reports = (DeviceStatusReport**)realloc(manager->reports, manager->capacity * sizeof(DeviceStatusReport*));
    }
    manager->reports[manager->count++] = report;
    pthread_mutex_unlock(&manager->lock);
}

// Function to retrieve a report by device ID
DeviceStatusReport* get_report_by_device_id(DeviceStatusManager* manager, const char* device_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; i++) {
        if (strcmp(manager->reports[i]->device_id, device_id) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return manager->reports[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Function to clean up the manager
void cleanup_manager(DeviceStatusManager* manager) {
    for (size_t i = 0; i < manager->count; i++) {
        free(manager->reports[i]);
    }
    free(manager->reports);
    pthread_mutex_destroy(&manager->lock);
}

// Example usage:
int main() {
    DeviceStatusManager manager;
    init_manager(&manager, 10);

    // Create a new report
    DeviceStatusReport* report = (DeviceStatusReport*)malloc(sizeof(DeviceStatusReport));
    report->timestamp = time(NULL);
    report->device_id = "device123";
    report->signal_strength = -75;
    report->error_code = 0;
    report->environmental_metadata = NULL; // Null for simplicity

    // Add or update the report
    add_or_update_report(&manager, report);

    // Retrieve the report
    DeviceStatusReport* retrieved_report = get_report_by_device_id(&manager, "device123");
    if (retrieved_report != NULL) {
        printf("Retrieved signal strength: %d\n", retrieved_report->signal_strength);
    }

    cleanup_manager(&manager);

    return 0;
}
```

