    int deviceId;
    double signalStrength;
    std::vector<int> errorCodes;
};

class DeviceStatusManager {
public:
    void addDevice(const DeviceStatusReport& report) {
        std::lock_guard<std::mutex> lock(mutex_);
        reports_.push_back(report);
        cv_.notify_all();
    }

    DeviceStatusReport getReport(int deviceId) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (true) {
            if (!reports_.empty()) {
                for (auto it = reports_.begin(); it != reports_.end(); ++it) {
                    if (it->deviceId == deviceId) {
                        DeviceStatusReport report = *it;
                        reports_.erase(it);
                        return report;
                    }
                }
            }
            cv_.wait(lock, [this] { return !reports_.empty(); });
        }
    }

private:
    std::vector<DeviceStatusReport> reports_;
    std::mutex mutex_;
