typedef struct Logger {
    void (*log)(const char *message);
} Logger;

void defaultLogger(const char *message) {
    printf("%s\n", message);
}

Logger createLogger(void (*logFunc)(const char *)) {
    Logger logger;
    logger.log = logFunc ? logFunc : defaultLogger;
    return logger;
}

char* processString(const char *input, size_t sizeLimit, int padFlag, Logger *logger) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    pthread_mutex_lock(&lock);

    if (strlen(input) <= sizeLimit && !padFlag) {
        char *result = strdup(input);
        if (result != NULL) {
            result[strlen(result)] = '\n';
            logger->log(result);
        }
        pthread_mutex_unlock(&lock);
        return result;
    } else if (strlen(input) > sizeLimit && padFlag) {
        char *result = malloc(sizeLimit + 1);
        if (result != NULL) {
            strncpy(result, input, sizeLimit);
            for (size_t i = strlen(result); i < sizeLimit; i++) {
                result[i] = ' ';
            }
            result[sizeLimit] = '\0';
            logger->log(result);
            free(input);
        } else {
            logger->log("Memory allocation failed");
        }
        pthread_mutex_unlock(&lock);
        return result;
    } else if (strlen(input) > sizeLimit && !padFlag) {
        logger->log("Input exceeds size limit and pad flag is false");
        pthread_mutex_unlock(&lock);
        return NULL;
    } else {
        pthread_mutex_unlock(&lock);
        return NULL;
    }
}

int main() {
    Logger logger = createLogger(defaultLogger);
    const char *input1 = "Hello, World!";
    size_t sizeLimit1 = 12;
    int padFlag1 = 0;

    char *result1 = processString(input1, sizeLimit1, padFlag1, &logger);
    if (result1 != NULL) {
        free(result1);
    }

    const char *input2 = "Hello, World!";
    size_t sizeLimit2 = 13;
    int padFlag2 = 1;

    char *result2 = processString(input2, sizeLimit2, padFlag2, &logger);
    if (result2 != NULL) {
        free(result2);
    }

    const char *input3 = "Hello, World!";
    size_t sizeLimit3 = 5;
    int padFlag3 = 0;

    char *result3 = processString(input3, sizeLimit3, padFlag3, &logger);
    if (result3 != NULL) {
        free(result3);
    }

    return 0;
}
