const express = require('express');
const axios = require('axios');
const kafka = require('kafka-node');
const { RateLimiter } = require('limiter');
const redis = require('redis');
const crypto = require('crypto');

const app = express();
const port = 3000;

// Initialize rate limiter
const rateLimiter = new RateLimiter({
  interval: '1 minute',
  maxRequests: 500,
});

// Initialize Kafka producer and consumer
const client = new kafka.KafkaClient({ kafkaHost: 'localhost:9092' });
const producer = new kafka.Producer(client);
const consumer = new kafka.Consumer(client, [
  { topic: 'financial-data', partition: 0 },
], {
  autoCommit: false,
});

// Initialize Redis cache
const redisClient = redis.createClient();

app.use(express.json());

app.post('/process-data', async (req, res) => {
  const data = req.body;

  try {
    await rateLimiter.removeTokens(1);
    const response = await axios.post('https://api.example.com/process', data);
    producer.send([{ topic: 'processed-data', messages: JSON.stringify(response.data) }]);
    res.status(200).json({ message: 'Data processed successfully' });
  } catch (error) {
    if (error.response && error.response.status === 429) {
      return res.status(429).json({ message: 'Too many requests, please try again later' });
    }
    return res.status(500).json({ message: 'Failed to process data' });
  }
});

consumer.on('message', async (message) => {
  const data = JSON.parse(message.value);
  // Process and validate data
  // Call trading platforms or payment gateways
  // Update compliance tools
});

consumer.on('error', (err) => {
  console.error(err);
});

app.listen(port, () => {
  console.log(`Service listening at http://localhost:${port}`);
});
