// main.rs

use std::env;
use std::fs::File;
use std::io::{self, Read};
use std::net::SocketAddr;
use std::sync::Arc;
use std::time::Duration;
use tokio::signal;
use tokio::task;
use tokio::time::{interval, Instant};

mod func_config;
mod server_config;
mod performance_monitor;
mod auth_service;

#[tokio::main]
async fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <function_name>", args[0]);
        return Ok(());
    }

    let function_name = &args[1];
    let config_path = "func_config.toml";

    // Load and parse the configuration file
    let mut config_file = File::open(config_path)?;
    let mut config_content = String::new();
    config_file.read_to_string(&mut config_content)?;

    // Parse the function configuration
    let func_config: func_config::FunctionConfig = toml::from_str(&config_content)
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;

    if !func_config.functions.contains_key(function_name) {
        eprintln!("Function {} not found in config", function_name);
        return Ok(());
    }

    // Load server configuration
    let server_config = server_config::load_server_config("server_config")?;
    let addr = SocketAddr::from(([127, 0, 0, 1], server_config.port));

    // Initialize the HTTP server
    let server_task = task::spawn(async move {
        let app = func_config.functions.get(function_name).unwrap().app.clone();
        axum::Server::bind(&addr)
            .serve(app.into_make_service())
            .await
            .map_err(|e| io::Error::new(io::ErrorKind::Other, e))
    });

    // Start performance monitoring
    let monitor_task = task::spawn(async move {
        performance_monitor::start_monitor(server_config.clone()).await;
    });

    // Handle graceful shutdown on SIGTERM
    let term_signal = signal::unix::signal(signal::unix::SignalKind::terminate())
        .expect("Failed to install termination signal handler");
    tokio::select! {
        _ = server_task => println!("Server exited unexpectedly"),
        _ = monitor_task => println!("Performance monitoring task exited unexpectedly"),
        _ = term_signal.recv() => {
            println!("Received SIGTERM, shutting down gracefully");
            // Perform graceful shutdown here
        }
    }

    Ok(())
}
```

