import abc
from typing import Dict, Any, Callable

class MessageQueue(abc.ABC):
    @abc.abstractmethod
    def publish(self, message: str) -> None:
        pass

    @abc.abstractmethod
    def consume(self, callback: Callable[[str], None]) -> None:
        pass

class MessageBroker:
    def __init__(self, queues: Dict[str, MessageQueue]):
        self.queues = queues

    def get_queue(self, service_id: str) -> MessageQueue:
        return self.queues.get(service_id, None)

class DefaultMessageQueue(MessageQueue):
    def publish(self, message: str) -> None:
        print(f"Publishing message: {message}")

    def consume(self, callback: Callable[[str], None]) -> None:
        print("Consuming messages...")
        # Simulate consuming messages
        for i in range(5):
            callback(f"Message-{i}")

class DependencyInjectionContainer:
    def __init__(self):
        self.queues = {}

    def register_queue(self, service_id: str, queue: MessageQueue) -> None:
        self.queues[service_id] = queue

    def resolve_queue(self, service_id: str) -> MessageQueue:
        return self.queues.get(service_id, None)

# Usage
container = DependencyInjectionContainer()
queue1 = DefaultMessageQueue()
container.register_queue("service1", queue1)
broker = MessageBroker(container.resolve_all_queues())

service1_queue = broker.get_queue("service1")
if service1_queue:
    service1_queue.publish("Hello, Service 1!")
    def callback(message: str) -> None:
        print(f"Received message: {message}")
    service1_queue.consume(callback)
```

This code provides a basic structure for a `MessageBroker` class that integrates with multiple message queues using dependency injection. It includes a default message queue implementation and a dependency injection container to manage the registration and resolution of message queues based on service identifiers. This setup allows for flexible queue configuration and easy adaptation to changes in service interfaces.']

