#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char timestamp[20];
    int device_id;
    float signal_strength;
    int error_codes[];
} DeviceStatusReport;

typedef struct {
    DeviceStatusReport** reports;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DeviceManager;

DeviceManager* create_device_manager() {
    DeviceManager* manager = (DeviceManager*)malloc(sizeof(DeviceManager));
    manager->reports = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_device_manager(DeviceManager* manager) {
    for (size_t i = 0; i < manager->count; i++) {
        free(manager->reports[i]);
    }
    free(manager->reports);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_or_update_report(DeviceManager* manager, DeviceStatusReport* report) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->reports[i]->device_id == report->device_id) {
            free(manager->reports[i]);
            manager->reports[i] = report;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 16;
        manager->reports = realloc(manager->reports, new_capacity * sizeof(DeviceStatusReport*));
        manager->capacity = new_capacity;
    }
    manager->reports[manager->count++] = report;
    pthread_mutex_unlock(&manager->lock);
}

DeviceStatusReport* get_report_by_device_id(DeviceManager* manager, int device_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->reports[i]->device_id == device_id) {
            DeviceStatusReport* report = manager->reports[i];
            pthread_mutex_unlock(&manager->lock);
            return report;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void summarize_reports(DeviceManager* manager) {
    pthread_mutex_lock(&manager->lock);
    float total_signal_strength = 0.0f;
    int error_count[256] = {0};
    for (size_t i = 0; i < manager->count; i++) {
        total_signal_strength += manager->reports[i]->signal_strength;
        for (int j = 0; manager->reports[i]->error_codes[j] != -1; j++) {
            error_count[manager->reports[i]->error_codes[j]]++;
        }
    }
    float average_signal_strength = total_signal_strength / manager->count;
    printf("Average Signal Strength: %.2f\n", average_signal_strength);
    for (int i = 0; i < 256; i++) {
        if (error_count[i] > 0) {
            printf("Error Code %d Frequency: %d\n", i, error_count[i]);
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Further implementation details would include the integration with external data ingestion service,
// resource monitoring system, compression algorithms, real-time alerting system, and analytics platform
