void populate_crc_indication(int num_ues, NFAPI_CRC_INDICATION_PDU_T **crc_indication) {
    if (num_ues <= 0) {
        fprintf(stderr, "Invalid number of UEs\n");
        return;
    }

    *crc_indication = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*crc_indication == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    srand(time(NULL));

    for (int i = 0; i < num_ues; i++) {
        (*crc_indication)[i].RX_UE_INFORMATION_TAG = i + 1;
        (*crc_indication)[i].RNTI = rand() % 256;
        (*crc_indication)[i].CRC_INDICATION_REL8_TAG = rand() % 3;
    }
}

void free_crc_indication(NFAPI_CRC_INDICATION_PDU_T *crc_indication, int num_ues) {
    if (crc_indication != NULL) {
        free(crc_indication);
    }
}

