    manager->capacity = 10;
    manager->database_url = strdup(database_url);
}

// Function to add DeviceStatusReport
void add_device_report(DeviceManager* manager, const DeviceStatusReport* report) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count == manager->capacity) {
        manager->capacity *= 2;
        manager->reports = realloc(manager->reports, sizeof(DeviceStatusReport) * manager->capacity);
    }
    memcpy(&manager->reports[manager->count], report, sizeof(DeviceStatusReport));
    manager->count++;
    pthread_mutex_unlock(&manager->mutex);
}

