class DeviceStatusManager {
public:
    DeviceStatusManager() : stop_(false) {}

    void start() {
        for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
            workers_.emplace_back(&DeviceStatusManager::worker, this);
        }
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop_ = true;
        }
        cv_.notify_all();
        for (auto& worker : workers_) {
            if (worker.joinable()) {
                worker.join();
            }
        }
    }

    void addReport(DeviceStatusReport report) {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            reports_.push_back(report);
        }
        cv_.notify_one();
    }

private:
    void worker() {
        while (true) {
            DeviceStatusReport report;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                cv_.wait(lock, [this] { return !reports_.empty() || stop_; });
                if (stop_ && reports_.empty()) {
                    break;
                }
                report = reports_.back();
                reports_.pop_back();
            }
            processReport(report);
        }
    }

    void processReport(DeviceStatusReport report) {
        // Implement the logic to process each report here
    }

    std::vector<std::thread> workers_;
    std::queue<DeviceStatusReport> reports_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::atomic<bool> stop_;
};

