#include <string.h>

char* appendSlashIfWithinLimit(const char* input, size_t maxLen) {
    if (input == NULL || maxLen <= 0) {
        return NULL;
    }

    size_t len = strlen(input);
    if (len >= maxLen) {
        return NULL;
    }

    char* result = (char*)malloc((len + 2) * sizeof(char));
    if (result == NULL) {
        return NULL;
    }

    strcpy(result, input);
    if (input[len - 1] != '/') {
        result[len++] = '/';
    }
    result[len] = '\0';

    return result;
}
