#define BUFFER_SIZE 1024*1024 // 1MB buffer
#define WINDOW_SIZE 60 // 1 minute window

typedef struct {
    int value;
    time_t timestamp;
} Event;

Event buffer[BUFFER_SIZE];
sem_t empty, full;
pthread_mutex_t lock;
int head = 0, tail = 0;

void* producer(void* arg) {
    while (1) {
        Event event;
        // Simulate data ingestion
        event.value = rand() % 1000000;
        event.timestamp = time(NULL);

        sem_wait(&empty);
        pthread_mutex_lock(&lock);
        buffer[tail] = event;
        tail = (tail + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&lock);
        sem_post(&full);
    }
}

void* consumer(void* arg) {
    Event window[WINDOW_SIZE];
    int count = 0;

    while (1) {
        sem_wait(&full);
        pthread_mutex_lock(&lock);
        buffer[head].timestamp -= WINDOW_SIZE * 60; // Adjust timestamp for sliding window
        if (buffer[head].timestamp < time(NULL)) {
            head = (head + 1) % BUFFER_SIZE;
            continue;
        }
        memcpy(window, &buffer[head], sizeof(Event));
        count++;
        head = (head + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&lock);
        sem_post(&empty);

        // Process the window
        int max_value = INT_MIN;
        for (int i = 0; i < count; i++) {
            if (window[i].value > max_value) {
                max_value = window[i].value;
            }
        }
        printf("Max value in last minute: %d\n", max_value);
    }
}

