#include <iostream>
#include <forward_list>
#include <string>

void insertAfterFirstOccurrence(std::forward_list<std::string>& lst, const std::string& target, const std::string& insert) {
    auto it = lst.begin();
    while (it != lst.end()) {
        if (*it == target) {
            ++it;
            lst.insert(it, insert);
            return;
        }
        ++it;
    }
}

int main() {
    std::forward_list<std::string> lst = {"apple", "banana", "cherry"};
    insertAfterFirstOccurrence(lst, "banana", "grape");
    for (const auto& str : lst) {
        std::cout << str << " ";
    }
    return 0;
}
