#include <memory>
#include <atomic>

class UserSession {
public:
    std::string credentials;
    time_t lastLogin;
    time_t expirationTime;
    bool active;
    std::vector<std::string> resources;

    UserSession(const std::string& creds, time_t exp)
        : credentials(creds), expirationTime(exp), active(true) {}
};

class SessionManager {
private:
    std::unordered_map<std::string, std::shared_ptr<UserSession>> sessions;
    mutable std::mutex sessionMutex;
    std::condition_variable cv;
    bool running;

public:
    SessionManager() : running(false) {}

    void start() {
        running = true;
        std::thread([this]() {
            while (running) {
                time_t now = time(nullptr);
                std::unique_lock<std::mutex> lock(sessionMutex);
                for (auto it = sessions.begin(); it != sessions.end();) {
                    if (it->second->expirationTime <= now || !it->second->active) {
                        it = sessions.erase(it);
                    } else {
                        ++it;
                    }
                }
                cv.notify_all();
                lock.unlock();
                std::this_thread::sleep_for(std::chrono::seconds(60));
            }
        }).detach();
    }

    void stop() {
        running = false;
        cv.notify_all();
    }

    bool addUserSession(const std::string& userId, const UserSession& session) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        sessions[userId] = std::make_shared<UserSession>(session);
        return true;
    }

    void removeUserSession(const std::string& userId) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        sessions.erase(userId);
    }

    bool updateUserSession(const std::string& userId, const UserSession& session) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        if (sessions.find(userId) != sessions.end()) {
            sessions[userId] = std::make_shared<UserSession>(session);
            return true;
        }
        return false;
    }

    bool getUserSession(const std::string& userId, UserSession& session) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        auto it = sessions.find(userId);
        if (it != sessions.end()) {
            session = *it->second;
            return true;
        }
        return false;
    }

    size_t getUserSessionCount() const {
        std::lock_guard<std::mutex> lock(sessionMutex);
        return sessions.size();
    }
};

int main() {
    SessionManager manager;
    manager.start();

    UserSession session1("user123", time(nullptr) + 3600);
    manager.addUserSession("user123", session1);

    UserSession session2("user456", time(nullptr) + 7200);
    manager.addUserSession("user456", session2);

    std::this_thread::sleep_for(std::chrono::seconds(180));

    if (manager.getUserSessionCount() > 0) {
        std::cout << "Sessions still active:" << manager.getUserSessionCount() << std::endl;
    } else {
        std::cout << "All sessions expired or removed." << std::endl;
    }

    manager.stop();
    return 0;
}
