// Define UserSessionData structure
struct UserSessionData {
    std::string sessionId;
    int userId;
    std::string ipAddress;
    std::time_t lastActiveTimestamp;
    std::vector<std::string> activities;
};

class SessionManager {
private:
    std::mutex mtx;
    std::unordered_map<std::string, UserSessionData> sessions;
    std::condition_variable cv;
    std::atomic<bool> running{true};

public:
    void addSession(const UserSessionData& session) {
        std::lock_guard<std::mutex> lock(mtx);
        sessions[session.sessionId] = session;
        cv.notify_one();
    }

    bool getSession(std::string sessionId, UserSessionData& session) {
        std::unique_lock<std::mutex> lock(mtx);
        if (cv.wait_for(lock, std::chrono::seconds(1), [this, &sessionId]() { return sessions.count(sessionId); })) {
            session = sessions[sessionId];
            return true;
        }
        return false;
    }

    void stop() {
        running.store(false);
    }
};

int main() {
    SessionManager manager;

    std::thread writer([&manager]() {
        UserSessionData session = {"session1", 1, "192.168.1.1", time(nullptr), {"login", "logout"}};
        manager.addSession(session);
    });

    std::thread reader([&manager]() {
        UserSessionData session;
        if (manager.getSession("session1", session)) {
            std::cout << "Session found: " << session.sessionId << std::endl;
        } else {
            std::cout << "Session not found" << std::endl;
        }
    });

    writer.join();
    reader.join();

    manager.stop();

    return 0;
}
