#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Error {
    int code;
    char description[256];
} Error;

typedef struct DeviceStatusReport {
    time_t timestamp;
    int device_id;
    float signal_strength;
    Error* errors;
    int error_count;
} DeviceStatusReport;

typedef struct ReportList {
    DeviceStatusReport** reports;
    int count;
    pthread_mutex_t lock;
} ReportList;

void report_list_init(ReportList* list) {
    list->reports = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void report_list_add(ReportList* list, DeviceStatusReport* report) {
    pthread_mutex_lock(&list->lock);
    list->reports = realloc(list->reports, (list->count + 1) * sizeof(DeviceStatusReport*));
    list->reports[list->count] = report;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void report_list_remove(ReportList* list, int device_id) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->reports[i]->device_id == device_id) {
            free(list->reports[i]->errors);
            free(list->reports[i]);
            memmove(&list->reports[i], &list->reports[i + 1], (list->count - i - 1) * sizeof(DeviceStatusReport*));
            list->count--;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

DeviceStatusReport* report_list_get(ReportList* list, int device_id) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->reports[i]->device_id == device_id) {
            DeviceStatusReport* copy = malloc(sizeof(DeviceStatusReport));
            memcpy(copy, list->reports[i], sizeof(DeviceStatusReport));
            pthread_mutex_unlock(&list->lock);
            return copy;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void report_list_cleanup(ReportList* list) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        free(list->reports[i]->errors);
        free(list->reports[i]);
    }
    free(list->reports);
    list->reports = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
