} crc_monitor_t;

crc_monitor_t* crc_monitor_init(size_t num_ues) {
    if (num_ues == 0) {
        return NULL; // Handle invalid input
    }

    crc_monitor_t *monitor = malloc(sizeof(crc_monitor_t));
    if (!monitor) {
        return NULL; // Handle memory allocation failure
    }

    monitor->crc_values = calloc(num_ues, sizeof(uint32_t));
    if (!monitor->crc_values) {
        free(monitor);
        return NULL; // Handle memory allocation failure
    }

    monitor->num_ues = num_ues;
    return monitor;
}

void crc_monitor_update(crc_monitor_t *monitor, size_t ue_index, uint32_t new_crc) {
    if (ue_index >= monitor->num_ues) {
        return; // Handle invalid index
    }

    monitor->crc_values[ue_index] = new_crc;
}

void crc_monitor_free(crc_monitor_t *monitor) {
    free(monitor->crc_values);
    free(monitor);
}
