#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sqlite3.h>

#define DB_NAME "data.db"
#define TABLE_NAME "dataset"

// Function prototypes
int fetch_data(int **data, int *size);
void log_error(const char *message);

int main() {
    int *data = NULL;
    int size = 0;

    // Fetch data from the external source
    if (fetch_data(&data, &size) != SQLITE_OK) {
        log_error("Failed to fetch data.");
        return EXIT_FAILURE;
    }

    // Identify the largest integer in the dataset
    int max_value = INT_MIN;
    for (int i = 0; i < size; i++) {
        if (data[i] > max_value) {
            max_value = data[i];
        }
    }

    printf("Largest value: %d\n", max_value);

    // Free dynamically allocated memory
    free(data);

    return EXIT_SUCCESS;
}

int fetch_data(int **data, int *size) {
    sqlite3 *db;
    sqlite3_stmt *stmt;
    char *zErrMsg = 0;

    // Open database connection
    if (sqlite3_open(DB_NAME, &db) != SQLITE_OK) {
        log_error("Cannot open database: ");
        return db->errcode;
    }

    // Prepare SQL statement to fetch data from the database
    const char *sql = "SELECT value FROM " TABLE_NAME;
    if (sqlite3_prepare_v2(db, sql, -1, &stmt, 0) != SQLITE_OK) {
        log_error("SQL error: ");
        sqlite3_close(db);
        return db->errcode;
    }

    // Dynamically allocate memory for the dataset
    *size = 0;
    while ((sqlite3_step(stmt)) == SQLITE_ROW) {
        (*size)++;
        int new_size = (*size) * sizeof(int);
        int *new_data = realloc(*data, new_size);
        if (new_data == NULL) {
            log_error("Memory allocation failed.");
            sqlite3_finalize(stmt);
            sqlite3_close(db);
            return SQLITE_ERROR;
        }
        *data = new_data;
        (*data)[*size - 1] = sqlite3_column_int(stmt, 0);
    }

    // Finalize SQL statement and close database connection
    sqlite3_finalize(stmt);
    sqlite3_close(db);

    return SQLITE_OK;
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}
