package com.microservice.logging;

import java.io.IOException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import org.json.JSONObject;

public class MicroserviceLogger {
    private static final ExecutorService executor = Executors.newFixedThreadPool(10);
    private LogBackend backend;
    private LogLevel level;

    public MicroserviceLogger(LogBackend backend, LogLevel level) {
        this.backend = backend;
        this.level = level;
    }

    public void log(LogLevel logLevel, String message) {
        if (logLevel.ordinal() >= level.ordinal()) {
            JSONObject logEntry = new JSONObject();
            logEntry.put("level", logLevel.name());
            logEntry.put("message", message);
            logEntry.put("timestamp", System.currentTimeMillis());

            executor.submit(() -> writeLog(logEntry));
        }
    }

    private void writeLog(JSONObject logEntry) {
        try {
            backend.log(logEntry.toString());
        } catch (IOException e) {
            handleRetryOrFallback(e, logEntry);
        }
    }

    private void handleRetryOrFallback(Exception e, JSONObject logEntry) {
        // Implement retry logic with exponential backoff
        for (int attempt = 0; attempt < 3; attempt++) {
            try {
                backend.log(logEntry.toString());
                return;
            } catch (IOException ex) {
                if (attempt == 2) throw new RuntimeException("Failed to log after retries", ex);
                try {
                    TimeUnit.SECONDS.sleep((long) Math.pow(2, attempt));
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                    throw new RuntimeException("Interrupted while retrying log", e);
                }
            }
        }
    }

    public void setBackend(LogBackend backend) {
        this.backend = backend;
    }

    public void setLevel(LogLevel level) {
        this.level = level;
    }

    // Define LogBackend interface and implementations
    public interface LogBackend {
        void log(String logEntry) throws IOException;
    }

    public enum LogLevel {
        DEBUG, INFO, WARN, ERROR
    }
}
```

