#include <pthread.h>

#define CONFIGURE_PARAMS

typedef struct {
    int value;
} record;

long* offsets = NULL;
int* keys = NULL;
record* records = NULL;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int allocate_memory(long max_offsets, int max_keys, int max_records) {
    offsets = (long*)malloc(max_offsets * sizeof(long));
    if (!offsets) return -1;

    keys = (int*)malloc(max_keys * sizeof(int));
    if (!keys) {
        free(offsets);
        return -1;
    }

    records = (record*)malloc(max_records * sizeof(record));
    if (!records) {
        free(keys);
        free(offsets);
        return -1;
    }

    return 0;
}

void free_memory() {
    free(offsets);
    offsets = NULL;
    free(keys);
    keys = NULL;
    free(records);
    records = NULL;
}

int insert_record(int key, int value) {
    pthread_mutex_lock(&mutex);

    // Find the next available slot for a new record
    long offset = 0; // Assuming a simple sequential allocation for demonstration

    if (offset < max_offsets && keys[offset] == 0) {
        keys[offset] = key;
        records[offset].value = value;

        pthread_mutex_unlock(&mutex);
        return 0;
    }

    pthread_mutex_unlock(&mutex);
    return -1; // No available slot
}

int retrieve_record(int key, int* value) {
    pthread_mutex_lock(&mutex);

    for (long offset = 0; offset < max_offsets; ++offset) {
        if (keys[offset] == key) {
            *value = records[offset].value;

            pthread_mutex_unlock(&mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&mutex);
    return -1; // Record not found
}

int main() {
    long max_offsets = 1000;
    int max_keys = 2000;
    int max_records = 3000;

    if (allocate_memory(max_offsets, max_keys, max_records) != 0) {
        fprintf(stderr, "Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    // Example usage
    if (insert_record(123, 456) == 0) {
        printf("Record inserted successfully.\n");
    } else {
        printf("Failed to insert record.\n");
    }

    int retrieved_value;
    if (retrieve_record(123, &retrieved_value) == 0) {
        printf("Retrieved value: %d\n", retrieved_value);
    } else {
        printf("Record not found.\n");
    }

    free_memory();
    return EXIT_SUCCESS;
}
