use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use reqwest;
use serde_json;

#[derive(Debug)]
struct Record {
    value: i32,
}

struct App {
    offsets: Arc<Mutex<Vec<i64>>>,
    keys: Arc<Mutex<Vec<i32>>>,
    records: HashMap<String, Vec<Record>>,
    max_offsets: usize,
    max_keys: usize,
    max_records: usize,
    min_value: i32,
    max_value: i32,
    db_urls: Vec<String>,
}

impl App {
    fn new(config: &Config) -> Result<Self, String> {
        let offsets = Arc::new(Mutex::new(vec![0; config.max_offsets]));
        let keys = Arc::new(Mutex::new(vec![0; config.max_keys]));

        let records: HashMap<String, Vec<Record>> = config.db_urls.iter()
            .map(|url| (url.clone(), vec![]))
            .collect();

        Ok(App {
            offsets,
            keys,
            records,
            max_offsets: config.max_offsets,
            max_keys: config.max_keys,
            max_records: config.max_records,
            min_value: config.min_value,
            max_value: config.max_value,
            db_urls: config.db_urls.clone(),
        })
    }

    fn create_record(&self, key: i32, value: i32) -> Result<(), String> {
        let mut offsets = self.offsets.lock().map_err(|_| "Failed to lock offsets")?;
        let mut keys = self.keys.lock().map_err(|_| "Failed to lock keys")?;

        if offsets.len() == 0 || keys.len() == 0 {
            return Err("Offsets or keys are empty".to_string());
        }

        let offset = *offsets.last().unwrap();
        offsets.push(offset + 1);
        keys.push(key);

        for url in &self.db_urls {
            let record = Record { value };
            self.records.get_mut(url).unwrap().push(record);

            // Simulate database write operation
            if !self.write_to_db(url, offset, key, value) {
                return Err(format!("Failed to write to database: {}", url));
            }
        }

        Ok(())
    }

    fn write_to_db(&self, url: &str, offset: i64, key: i32, value: i32) -> bool {
        // Simulate network request
        let client = reqwest::Client::new();
        let data = json!({
            "offset": offset,
            "key": key,
            "value": value,
        });

        match client.post(url).json(&data).send() {
            Ok(_) => true,
            Err(_) => false,
        }
    }

    fn retrieve_record(&self, url: &str, offset: i64) -> Option<Record> {
        self.records.get(url).and_then(|records| records.iter().find(|record| record.value == offset as i32))
            .cloned()
    }
}

struct Config {
    max_offsets: usize,
    max_keys: usize,
    max_records: usize,
    min_value: i32,
    max_value: i32,
    db_urls: Vec<String>,
}

fn main() -> Result<(), String> {
    let config = Config {
        max_offsets: 1000,
        max_keys: 500,
        max_records: 2000,
        min_value: 0,
        max_value: 100,
        db_urls: vec![
            "http://db1.example.com".to_string(),
            "http://db2.example.com".to_string(),
        ],
    };

    let app = App::new(&config)?;

    // Simulate creating records
    for _ in 0..10 {
        app.create_record(rand::random::<i32>(), rand::random::<i32>())?;
    }

    // Retrieve and print a record
    if let Some(record) = app.retrieve_record("http://db1.example.com", 5) {
        println!("Retrieved record: {:?}", record);
    } else {
        println!("Record not found");
    }

    Ok(())
}
