// Define a job queue class
class JobQueue {
public:
    void enqueueTask(std::function<void()> task) {
        std::unique_lock<std::mutex> lock(mutex_);
        tasks_.push(task);
        cv_.notify_one();
    }

    bool dequeueTask(std::function<void()>& task) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (tasks_.empty()) return false;
        task = std::move(tasks_.front());
        tasks_.pop();
        return true;
    }

private:
    std::queue<std::function<void()>> tasks_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

// Define a background worker thread
class BackgroundWorker {
public:
    BackgroundWorker(JobQueue& jobQueue) : jobQueue_(jobQueue), stop_(false) {
        thread_ = std::thread(&BackgroundWorker::run, this);
    }

    ~BackgroundWorker() {
        {
            std::unique_lock<std::mutex> lock(stopMutex_);
            stop_ = true;
        }
        cv_.notify_all();
        if (thread_.joinable()) thread_.join();
    }

private:
    void run() {
        while (true) {
            std::function<void()> task;
            if (!jobQueue_.dequeueTask(task)) continue;

            try {
                task();
            } catch (...) {
                // Handle exceptions
            }
        }
    }

    JobQueue& jobQueue_;
    std::thread thread_;
    bool stop_;
    std::mutex stopMutex_;
    std::condition_variable cv_;
};

// Define a function to execute system-level commands using fork and wait
int executeSystemCommand(const std::string& command) {
    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execlp(command.c_str(), command.c_str(), nullptr);
        _exit(1); // If execlp fails, exit with an error code
    } else if (pid > 0) {
        // Parent process
        int status;
        wait(&status);
        return WEXITSTATUS(status);
    } else {
        // Fork failed
        return -1;
    }
}

int main() {
    JobQueue jobQueue;
    BackgroundWorker worker(jobQueue);

    // Example usage of the background worker and custom function
    worker.enqueueTask([&jobQueue]() {
        auto localBackend = std::make_unique<LocalStorageBackend>();
        localBackend->uploadFile("local.txt", "remote.txt");
        jobQueue.enqueueTask([=]() {
            executeSystemCommand("sync");
        });
    });

    return 0;
}
