import logging
from abc import ABC, abstractmethod
from typing import List, Optional

class LogEntry:
    def __init__(self, message: str, level: int):
        self.message = message
        self.level = level

class ExternalLoggingService(ABC):
    @abstractmethod
    def log(self, entry: LogEntry) -> None:
        pass

class ConsoleLoggingService(ExternalLoggingService):
    def log(self, entry: LogEntry) -> None:
        print(f"{entry.level}: {entry.message}")

class FileLoggingService(ExternalLoggingService):
    def __init__(self, filename: str):
        self.filename = filename

    def log(self, entry: LogEntry) -> None:
        with open(self.filename, 'a') as file:
            file.write(f"{entry.level}: {entry.message}\n")

class ExternalServiceWrapper(ExternalLoggingService):
    def __init__(self, service: ExternalLoggingService):
        self.service = service

    def log(self, entry: LogEntry) -> None:
        try:
            self.service.log(entry)
        except Exception as e:
            logging.error(f"Failed to log to external service: {e}")

class LoggingFramework:
    def __init__(self, services: List[ExternalLoggingService]):
        self.services = services

    def add_service(self, service: ExternalLoggingService) -> None:
        self.services.append(service)

    def remove_service(self, service: ExternalLoggingService) -> None:
        self.services.remove(service)

    def log(self, entry: LogEntry) -> None:
        for service in self.services:
            service.log(entry)

# Usage
console_service = ConsoleLoggingService()
file_service = FileLoggingService("logs.txt")
external_service = ExternalServiceWrapper(ConsoleLoggingService())

logging_framework = LoggingFramework([console_service, file_service, external_service])
logging_framework.log(LogEntry("This is a test log message", logging.INFO))
