int connect_to_db(DbConfig *db_config);
void cleanup(ApiConfig api_config, DbConfig db_config);

// Main program
int main() {
    Config config = {60, 2, 1}; // Example configuration
    ApiConfig api_config;
    DbConfig db_config;

    init_api(&api_config);
    connect_to_db(&db_config);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, fetch_data, &api_config) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Periodically check and log status or perform other tasks
        sleep(config.frequency);
    }

    pthread_join(thread_id, NULL);
    cleanup(api_config, db_config);

    return EXIT_SUCCESS;
}

// Worker thread function to fetch data from API and store it in the database
void* fetch_data(void* api_config) {
    ApiConfig *config = (ApiConfig*)api_config;
    CURLcode res;

    while (1) {
        // Fetch data using libcurl or other HTTP library
        if ((res = curl_easy_perform(config->handle)) != CURLE_OK) {
            fprintf(stderr, "Curl error: %s\n", curl_easy_strerror(res));
            // Implement exponential backoff and retry logic
        } else {
            // Parse the received data and store it in a Data structure
            Data data;
            // Assume parse_data is a function that fills 'data' with parsed values
            if (parse_data(/* ... */) != 0) {
                fprintf(stderr, "Failed to parse data\n");
                continue;
            }

            // Store data in the database
            store_data(data, db_config);
        }

        // Sleep for the configured frequency or until interrupted
        sleep(config->frequency);
    }

    return NULL;
}

// Function to store data into the database
int store_data(Data data, DbConfig db_config) {
    pthread_mutex_lock(&db_config.lock);
    sqlite3_stmt *stmt;

    // Prepare and execute the SQL statement to insert the data
    if (sqlite3_prepare_v2(db_config.db, "INSERT INTO data_table VALUES (?, ?)", -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare SQLite statement: %s\n", sqlite3_errmsg(db_config.db));
        pthread_mutex_unlock(&db_config.lock);
        return 1;
    }

    sqlite3_bind_int(stmt, 1, data.id);
    sqlite3_bind_text(stmt, 2, data.timestamp, strlen(data.timestamp), SQLITE_STATIC);

    if (sqlite3_step(stmt) != SQLITE_DONE) {
        fprintf(stderr, "Failed to insert data into SQLite database: %s\n", sqlite3_errmsg(db_config.db));
        sqlite3_finalize(stmt);
        pthread_mutex_unlock(&db_config.lock);
        return 1;
    }

    sqlite3_finalize(stmt);
    pthread_mutex_unlock(&db_config.lock);

    return 0;
}

// Initialize API configuration
int init_api(ApiConfig *api_config) {
    api_config->handle = curl_easy_init();
    if (!api_config->handle) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return 1;
    }

    // Set up additional API-specific configurations
    // For example: curl_easy_setopt(api_config->handle, CURLOPT_URL, "https://api.example.com/data");

    return 0;
}

// Connect to the database
int connect_to_db(DbConfig *db_config) {
    if (sqlite3_open("data.db", &db_config->db) != SQLITE_OK) {
        fprintf(stderr, "Failed to open SQLite database: %s\n", sqlite3_errmsg(db_config->db));
        return 1;
    }

    // Initialize mutex for concurrent access
    if (pthread_mutex_init(&db_config->lock, NULL) != 0) {
        fprintf(stderr, "Failed to initialize mutex\n");
        sqlite3_close(db_config->db);
        return 1;
    }

    // Create tables if they don't exist
    const char *create_table_sql = "CREATE TABLE IF NOT EXISTS data_table (id INTEGER PRIMARY KEY, timestamp TEXT)";
    if (sqlite3_exec(db_config->db, create_table_sql, NULL, NULL, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to create table in SQLite database: %s\n", sqlite3_errmsg(db_config->db));
        pthread_mutex_destroy(&db_config->lock);
        sqlite3_close(db_config->db);
        return 1;
    }

    return 0;
}

// Cleanup function to release resources
void cleanup(ApiConfig api_config, DbConfig db_config) {
    curl_easy_cleanup(api_config.handle);
    pthread_mutex_destroy(&db_config.lock);
    sqlite3_close(db_config.db);
}
