        for (CloudStorageProvider provider : providers) {
            if (provider.getClass().getSimpleName().equals(providerId)) {
                provider.downloadFile(providerId, remotePath, localPath);
                break;
            }
        }
    }

    public void synchronizeFiles(String providerId, String localPath) {
        for (CloudStorageProvider provider : providers) {
            if (provider.getClass().getSimpleName().equals(providerId)) {
                provider.synchronizeFiles(providerId, localPath);
                break;
