class SemaphorePool {
public:
    SemaphorePool(size_t size) : semaphores_(size), mutex_() {
        for (auto& sem : semaphores_) {
            sem_init(&sem, 0, 1); // Initialize each semaphore to 1
        }
    }

    ~SemaphorePool() {
        for (auto& sem : semaphores_) {
            sem_destroy(&sem);
        }
    }

    void acquire(size_t index) {
        std::lock_guard<std::mutex> lock(mutex_);
        sem_wait(&semaphores_[index]);
    }

    void release(size_t index) {
        std::lock_guard<std::mutex> lock(mutex_);
        sem_post(&semaphores_[index]);
    }

private:
    std::vector<sem_t> semaphores_;
    std::mutex mutex_;
};

