using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Polly;
using Serilog;

public class UIComponentController : ControllerBase
{
    private readonly HttpClient _httpClient;
    private readonly Policy _retryPolicy;
    private readonly IAsyncCircuitBreaker _circuitBreaker;
    private readonly BinaryFormatter _binaryFormatter;

    public UIComponentController(HttpClient httpClient, AsyncCircuitBreaker circuitBreaker)
    {
        _httpClient = httpClient;
        _circuitBreaker = circuitBreaker;
        _retryPolicy = Policy
            .Handle<HttpRequestException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));
        _binaryFormatter = new BinaryFormatter();
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateUIComponents([FromBody] List<UIComponent> components)
    {
        try
        {
            var configurations = await _retryPolicy.ExecuteAsync(() => FetchConfigurations());
            var updatedComponents = await ProcessComponents(components, configurations);
            return Ok(updatedComponents);
        }
        catch (Exception ex)
        {
            Log.Error(ex, "Error updating UI components");
            return StatusCode(500, "Internal Server Error");
        }
    }

    private async Task<List<Configuration>> FetchConfigurations()
    {
        using var response = await _httpClient.GetAsync("https://api.external.com/configs", HttpCompletionOption.ResponseHeadersRead);
        if (!response.IsSuccessStatusCode)
            throw new HttpRequestException("Failed to fetch configurations");

        return await response.Content.ReadAsAsync<List<Configuration>>();
    }

    private async Task<List<UIComponent>> ProcessComponents(List<UIComponent> components, List<Configuration> configurations)
    {
        var updatedComponents = new List<UIComponent>();

        foreach (var component in components)
        {
            if (_circuitBreaker.IsOpen) throw new Exception("Circuit breaker is open");

            var configuration = configurations.Find(c => c.Id == component.Id);
            if (configuration == null) continue;

            _binaryFormatter.Serialize(component, configuration.BinaryData);
            updatedComponents.Add(component);

            await Task.Delay(10); // Simulate processing time
        }

        return updatedComponents;
    }
}

public class UIComponent
{
    public int Id { get; set; }
    public string Content { get; set; }
    public byte[] BinaryData { get; set; }
}

public class Configuration
{
    public int Id { get; set; }
    public byte[] BinaryData { get; set; }
}
