// Class to process images
class ImageProcessor {
private:
    std::mutex queueMutex;
    std::condition_variable cv;
    std::queue<std::shared_ptr<unsigned char>> imageQueue;
    bool running;
    MachineLearningModel* mlModel;
    TelemetryLogger* logger;

public:
    ImageProcessor(MachineLearningModel* model, TelemetryLogger* log) : running(false), mlModel(model), logger(log) {}

    void startProcessing() {
        running = true;
        std::thread processingThread(&ImageProcessor::processImages, this);
        processingThread.detach();
    }

    void stopProcessing() {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            running = false;
        }
        cv.notify_all();
    }

    void submitImage(const std::shared_ptr<unsigned char>& image) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            imageQueue.push(image);
        }
        cv.notify_one();
    }

private:
    void processImages() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait(lock, [this] { return !imageQueue.empty() || !running; });
            if (!running && imageQueue.empty()) break;

            auto image = imageQueue.front();
            imageQueue.pop();
            lock.unlock();

            // Process the image
            std::vector<std::string> results = mlModel->detectObjects(image);
            logger->logImageProcessingStats(results.size());
        }
    }
};

