    virtual ~DataIngestionService() = default;
    virtual void start() = 0;
    virtual void stop() = 0;
    virtual bool isConnected() const = 0;
    virtual void ingestData(const std::vector<MarketData>& data) = 0;
};

// Define a concrete implementation of DataIngestionService
class ExternalDataFeed : public DataIngestionService {
public:
    ExternalDataFeed(std::string endpoint, std::string authKey)
        : endpoint_(endpoint), authKey_(authKey), connected_(false) {}

    void start() override {
        // Simulate starting the service
        connected_ = true;
        std::cout << "ExternalDataFeed started." << std::endl;
    }

    void stop() override {
        // Simulate stopping the service
        connected_ = false;
        std::cout << "ExternalDataFeed stopped." << std::endl;
    }

    bool isConnected() const override {
        return connected_;
    }

    void ingestData(const std::vector<MarketData>& data) override {
        if (connected_) {
            // Simulate data ingestion
            for (const auto& md : data) {
                std::cout << "Ingesting data: " << md.symbol << " " << md.price << std::endl;
            }
        } else {
            std::cerr << "Error: Data ingestion service not connected." << std::endl;
        }
    }

private:
    std::string endpoint_;
    std::string authKey_;
    bool connected_;
};

// Define a thread-safe data queue for market data
class MarketDataQueue {
public:
    void push(const MarketData& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        dataQueue_.push(data);
        cv_.notify_one();
    }

    bool pop(MarketData& data, std::chrono::milliseconds timeout = std::chrono::milliseconds(100)) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (cv_.wait_for(lock, timeout, [this] { return !dataQueue_.empty(); })) {
            data = dataQueue_.front();
            dataQueue_.pop();
            return true;
        }
        return false;
    }

private:
    std::queue<MarketData> dataQueue_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;
};

// Define a worker thread for processing market data
class DataProcessor {
public:
    DataProcessor(std::shared_ptr<MarketDataQueue> queue, std::vector<std::unique_ptr<DataIngestionService>> services)
        : queue_(queue), services_(services), running_(true) {}

    void start() {
        std::thread([this] { this->run(); }).detach();
    }

    void stop() {
        running_ = false;
        cv_.notify_all();
    }

private:
    void run() {
        while (running_) {
            MarketData data;
            if (queue_->pop(data)) {
                for (auto& service : services_) {
                    if (service->isConnected()) {
                        service->ingestData({data});
                    }
                }
            } else {
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        }
    }

    std::shared_ptr<MarketDataQueue> queue_;
    std::vector<std::unique_ptr<DataIngestionService>> services_;
    std::atomic<bool> running_;
    std::condition_variable cv_;
};

// Define a class for managing the library
class FinancialMarketDataLibrary {
public:
    void addService(std::unique_ptr<DataIngestionService> service) {
        services_.push_back(std::move(service));
    }

    void start() {
        for (auto& service : services_) {
            service->start();
        }
        processor_.reset(new DataProcessor(queue_, services_));
        processor_->start();
    }

    void stop() {
        if (processor_) {
            processor_->stop();
        }
        for (auto& service : services_) {
            service->stop();
        }
    }

private:
    std::shared_ptr<MarketDataQueue> queue_ = std::make_shared<MarketDataQueue>();
    std::vector<std::unique_ptr<DataIngestionService>> services_;
    std::unique_ptr<DataProcessor> processor_;
};

int main() {
    FinancialMarketDataLibrary library;

    // Add data ingestion services
    library.addService(std::make_unique<ExternalDataFeed>("endpoint1", "authKey1"));
    library.addService(std::make_unique<ExternalDataFeed>("endpoint2", "authKey2"));

