#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct ErrorCode {
    int code;
    int frequency;
} ErrorCode;

typedef struct DeviceStatusReport {
    time_t timestamp;
    char deviceID[20];
    float signalStrength;
    struct ErrorCode* errors;
    int errorCount;
} DeviceStatusReport;

typedef struct ReportCollection {
    DeviceStatusReport** reports;
    int count;
    pthread_mutex_t lock;
} ReportCollection;

void addReport(ReportCollection* collection, DeviceStatusReport* report) {
    pthread_mutex_lock(&collection->lock);
    collection->reports = realloc(collection->reports, (collection->count + 1) * sizeof(DeviceStatusReport*));
    collection->reports[collection->count++] = report;
    pthread_mutex_unlock(&collection->lock);
}

void updateReport(ReportCollection* collection, char* deviceID, DeviceStatusReport* newReport) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->count; i++) {
        if (strcmp(collection->reports[i]->deviceID, deviceID) == 0) {
            free(collection->reports[i]);
            collection->reports[i] = newReport;
            break;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

DeviceStatusReport* getReport(ReportCollection* collection, char* deviceID) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->count; i++) {
        if (strcmp(collection->reports[i]->deviceID, deviceID) == 0) {
            DeviceStatusReport* report = collection->reports[i];
            pthread_mutex_unlock(&collection->lock);
            return report;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

void calculateSummary(ReportCollection* collection, float* averageSignalStrength, ErrorCode** errorCodes, int* errorCount) {
    *averageSignalStrength = 0.0;
    *errorCount = 0;

    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->count; i++) {
        *averageSignalStrength += collection->reports[i]->signalStrength;
    }
    *averageSignalStrength /= collection->count;

    int errorMap[100] = {0}; // Assuming max 100 unique error codes
    for (int i = 0; i < collection->count; i++) {
        for (int j = 0; j < collection->reports[i]->errorCount; j++) {
            errorMap[collection->reports[i]->errors[j].code]++;
        }
    }

    *errorCodes = malloc(collection->count * sizeof(ErrorCode));
    int index = 0;
    for (int i = 0; i < 100; i++) {
        if (errorMap[i] > 0) {
            (*errorCodes)[index].code = i;
            (*errorCodes)[index].frequency = errorMap[i];
            index++;
        }
    }
    *errorCount = index;
    pthread_mutex_unlock(&collection->lock);
}

