// crc_monitor.c

#include "crc_monitor.h"
#include <stdlib.h>
#include <string.h>

typedef struct crc_monitor_instance {
    uint32_t num_ues;
    bool *ue_registered;
} crc_monitor_instance;

crc_monitor_handle crc_monitor_init(uint32_t num_ues) {
    if (num_ues == 0) return NULL;

    crc_monitor_instance *instance = malloc(sizeof(crc_monitor_instance));
    if (!instance) return NULL;

    instance->num_ues = num_ues;
    instance->ue_registered = calloc(num_ues, sizeof(bool));
    if (!instance->ue_registered) {
        free(instance);
        return NULL;
    }

    return (crc_monitor_handle)instance;
}

void crc_monitor_release(crc_monitor_handle handle) {
    if (!handle) return;

    crc_monitor_instance *instance = (crc_monitor_instance *)handle;
    free(instance->ue_registered);
    free(instance);
}

bool crc_monitor_add_ue(crc_monitor_handle handle, uint64_t ue_id) {
    if (!handle || ue_id >= ((crc_monitor_instance *)handle)->num_ues) return false;

    crc_monitor_instance *instance = (crc_monitor_instance *)handle;
    if (instance->ue_registered[ue_id]) return false;

    instance->ue_registered[ue_id] = true;
    return true;
}

bool crc_monitor_remove_ue(crc_monitor_handle handle, uint64_t ue_id) {
    if (!handle || ue_id >= ((crc_monitor_instance *)handle)->num_ues) return false;

    crc_monitor_instance *instance = (crc_monitor_instance *)handle;
    if (!instance->ue_registered[ue_id]) return false;

    instance->ue_registered[ue_id] = false;
    return true;
}

bool crc_monitor_report_crc(crc_monitor_handle handle, uint64_t ue_id, bool is_error) {
