import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class ErrorLogFramework {
    private static final int BATCH_SIZE = 100;
    private static final int RETRY_LIMIT = 5;
    private final BlockingQueue<ErrorLogEntry> logQueue = new LinkedBlockingQueue<>();

    public void logError(ErrorLogEntry error) {
        try {
            logQueue.put(error);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException("Interrupted while logging error", e);
        }
    }

    public void startLogging() {
        Thread consumerThread = new Thread(() -> {
            while (!Thread.currentThread().isInterrupted()) {
                try {
                    ErrorLogEntry[] batch = logQueue.take(BATCH_SIZE);
                    sendBatchToExternalService(batch);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });
        consumerThread.start();
    }

    private void sendBatchToExternalService(ErrorLogEntry[] batch) {
        int retries = 0;
        while (retries < RETRY_LIMIT) {
            try {
                // Simulate HTTP request to external service
                ExternalService.log(batch);
                return;
            } catch (Exception e) {
                retries++;
                if (retries >= RETRY_LIMIT) {
                    handlePermanentFailure(e);
                }
                // Exponential backoff
                try {
                    Thread.sleep(100 * (1 << retries));
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }

    private void handlePermanentFailure(Exception e) {
        // Log the failure and take appropriate action, such as notifying an administrator
        System.err.println("Permanent failure in error logging: " + e.getMessage());
    }

    public static class ErrorLogEntry {
        private String timestamp;
        private String severityLevel;
        private String errorCode;
        private String errorMessage;
        private Object metadata;

        // Getters and setters
    }

    public static class ExternalService {
        public static void log(ErrorLogEntry[] batch) throws Exception {
            // Simulate external service logging
            System.out.println("Logging " + batch.length + " errors to external service");
        }
    }
}
