// Implement a basic logger using SLF4J
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class Slf4jLogger implements Logger {
    private final org.slf4j.Logger slf4jLogger;

    public Slf4jLogger(Class<?> clazz) {
        this.slf4jLogger = LoggerFactory.getLogger(clazz);
    }

    @Override
    public void debug(String message) {
        slf4jLogger.debug(message);
    }

    @Override
    public void info(String message) {
        slf4jLogger.info(message);
    }

    @Override
    public void warn(String message) {
        slf4jLogger.warn(message);
    }

    @Override
    public void error(String message) {
        slf4jLogger.error(message);
    }
}

// Implement a factory to create logger instances based on environment and configuration
import java.util.Properties;

public class LoggerFactory {
    public static Logger getLogger(Class<?> clazz, Properties config) {
        String environment = (String) config.get("environment");
        if ("production".equalsIgnoreCase(environment)) {
            return new Slf4jLogger(clazz);
        } else {
            // Add more environments and loggers as needed
            return new Slf4jLogger(clazz);
        }
    }
}

// Usage example
public class Application {
    public static void main(String[] args) {
        Properties config = new Properties();
        config.setProperty("environment", "production");
        Logger logger = LoggerFactory.getLogger(Application.class, config);

        logger.debug("This is a debug message.");
        logger.info("This is an info message.");
        logger.warn("This is a warning message.");
        logger.error("This is an error message.");
    }
}
