mod grammar_service {
    use std::sync::{Arc, Mutex};
    use tokio::sync::Semaphore;

    pub struct GrammarService {
        client: reqwest::Client,
        semaphore: Arc<Semaphore>,
    }

    impl GrammarService {
        pub fn new(max_connections: usize) -> Self {
            GrammarService {
                client: reqwest::Client::new(),
                semaphore: Arc::new(Semaphore::new(max_connections)),
            }
        }

        pub async fn fetch_grammar(&self, url: &str) -> Result<String, reqwest::Error> {
            let permit = self.semaphore.acquire().await?;
            let response = self.client.get(url).send().await?;
            if response.status().is_success() {
                response.text().await
            } else {
                Err(reqwest::Error::from(response))
            }
        }

        pub async fn update_grammar(&self, url: &str, grammar: &str) -> Result<(), reqwest::Error> {
            let permit = self.semaphore.acquire().await?;
            self.client.post(url).body(grammar).send().await?
                .error_for_status()?;
            Ok(())
        }
    }
}

