struct Node {
    std::string id;
    std::string value;
};

class DoublyLinkedList {
public:
    void insert(const Node& node) {
        list.push_front(node);
    }

    bool update(const std::string& id, const std::string& newValue) {
        for (auto& node : list) {
            if (node.id == id) {
                node.value = newValue;
                return true;
            }
        }
        return false;
    }

private:
    std::list<Node> list;
};

void insertOrUpdateNode(DoublyLinkedList& list, const std::string& id, const std::string& newValue, 
                       std::vector<std::function<void(const std::string&)>>& apiCallbacks, 
                       std::chrono::seconds initialBackoff, std::chrono::seconds maxBackoff, 
                       int maxRetries, std::chrono::seconds rollingWindow) {
    std::mutex mutex;
    std::atomic<int> operationCount(0);
    std::queue<std::string> logQueue;

    auto retryFunction = [&](const std::function<bool()>& task, const std::string& action, 
                             std::chrono::seconds backoff, int retries) -> bool {
        for (int i = 0; i <= retries; ++i) {
            if (task()) {
                apiCallbacks[0](action + " succeeded");
                return true;
            }
            if (i < retries) {
                std::this_thread::sleep_for(backoff);
                backoff += backoff;
                if (backoff > maxBackoff) {
                    backoff = maxBackoff;
                }
            } else {
                apiCallbacks[1](action + " failed after " + std::to_string(retries) + " retries");
            }
        }
        return false;
    };

    auto insertOrUpdateTask = [&list, &id, &newValue]() -> bool {
        std::lock_guard<std::mutex> lock(mutex);
        if (list.update(id, newValue)) {
            return true;
        } else {
            list.insert({id, newValue});
            return true;
        }
    };

    retryFunction(insertOrUpdateTask, "Insert or update", initialBackoff, maxRetries);

    operationCount++;
}

int main() {
    DoublyLinkedList list;
    std::vector<std::function<void(const std::string&)>> apiCallbacks = {[](const std::string& message) {
        std::cout << message << std::endl;
    }, [](const std::string& message) {
        std::cerr << message << std::endl;
    }};

    insertOrUpdateNode(list, "1", "Value1", apiCallbacks, std::chrono::seconds(1), std::chrono::seconds(30), 5, std::chrono::hours(1));

    return 0;
}
