namespace DirectoryUtil {
    class RandomGenerator {
    private:
        static std::mt19937_64 rng;

    public:
        static uint64_t generateSecureSeed() {
            auto seed = std::chrono::system_clock::now().time_since_epoch().count();
            seed ^= std::hash<std::thread::id>{}(std::this_thread::get_id());
            return seed;
        }

        static void initialize() {
            rng.seed(generateSecureSeed());
        }

        static uint64_t generateRandomNumber() {
            return rng();
        }
    };

    std::mt19937_64 RandomGenerator::rng;

    bool atomic_compare_and_exchange(std::atomic<std::string>& var, const std::string& old_val, const std::string& new_val) {
        return var.compare_exchange_strong(old_val, new_val);
    }

    void createSecureDirectory(const std::string& dirName, const std::string& envVarName) {
        if (!std::getenv(envVarName.c_str())) {
            RandomGenerator::initialize();
            uint64_t randomNumber = RandomGenerator::generateRandomNumber();
            std::string newDirPath = std::filesystem::temp_directory_path() / (dirName + "_" + std::to_string(randomNumber));
            try {
                if (std::filesystem::create_directory(newDirPath)) {
                    std::atomic<std::string> envVar(envVarName);
                    std::string oldValue = "";
                    while (!atomic_compare_and_exchange(envVar, oldValue, newDirPath)) {
                        // Retry in case of a race condition
                    }
                    std::cout << "Directory created: " << newDirPath << " and stored in environment variable: " << envVarName << std::endl;
                } else {
                    throw std::runtime_error("Failed to create directory");
                }
            } catch (const std::exception& e) {
                std::cerr << "Error creating directory or updating environment variable: " << e.what() << std::endl;
            }
        } else {
            std::cout << "Environment variable " << envVarName << " already exists with value: " << std::getenv(envVarName.c_str()) << std::endl;
        }
    }

} // namespace DirectoryUtil
