    public class StreamingDataProcessor
    {
        private readonly ConcurrentQueue<string> _dataQueue = new ConcurrentQueue<string>();
        private readonly HttpClient _httpClient;
        private readonly ILogger _logger;
        private readonly IDataTransformer _dataTransformer;
        private readonly IErrorHandlingStrategy _errorHandlingStrategy;

        public StreamingDataProcessor(HttpClient httpClient, ILogger logger, IDataTransformer dataTransformer, IErrorHandlingStrategy errorHandlingStrategy)
        {
            _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
            _dataTransformer = dataTransformer ?? throw new ArgumentNullException(nameof(dataTransformer));
            _errorHandlingStrategy = errorHandlingStrategy ?? throw new ArgumentNullException(nameof(errorHandlingStrategy));
        }

        public void StartProcessing()
        {
            Task.Run(ProcessDataAsync);
        }

        private async Task ProcessDataAsync()
        {
            while (true)
            {
                if (_dataQueue.TryDequeue(out var data))
                {
                    try
                    {
                        await _dataTransformer.TransformAndValidate(data);
                        // Process the transformed data
                        _logger.LogInfo($"Processed data: {data}");
                    }
                    catch (Exception ex)
                    {
                        _errorHandlingStrategy.HandleError(ex, data);
                    }
                }
                else
                {
                    await Task.Delay(10); // Wait for new data
                }
            }
        }

