    public OrderProcessingService(ILogger<OrderProcessingService> logger, IConfiguration configuration, HttpClient httpClient)
    {
        _logger = logger;
        _configuration = configuration;
        _httpClient = httpClient;
        _rateLimits = new ConcurrentDictionary<string, DateTime>();
        _databaseConnection = new SqlConnection(_configuration.GetConnectionString("OrderDB"));
