    private Polly.RetryPolicy CreateRateLimitPolicy(string apiEndpoint)
    {
        var retryCount = _configuration.GetValue<int>("RetryCount");
        var retryInterval = TimeSpan.FromSeconds(_configuration.GetValue<int>("RetryInterval"));

        return Policy
            .Handle<HttpRequestException>()
            .WaitAndRetryAsync(retryCount, retryAttempt => retryInterval);
    }

    private async Task ProcessOrder(string orderId)
    {
        // Retrieve order details from XML
        var xmlData = await FetchXmlData(orderId);

        if (xmlData == null)
