from flask import Flask, request, jsonify
import psycopg2
import pymongo
import requests
from functools import wraps

app = Flask(__name__)

# Database connections
sql_conn = psycopg2.connect(database="your_db", user='user', password='password', host='127.0.0.1', port= '5432')
no_sql_conn = pymongo.MongoClient("mongodb://localhost:27017/")

# Rate limiting decorator
def rate_limit(max_calls, period):
    def decorator(f):
        from time import time
        cache = {}

        @wraps(f)
        def wrapped(*args, **kwargs):
            key = request.remote_addr + request.endpoint
            if key not in cache:
                cache[key] = []
            else:
                now = int(time())
                timestamps = [t for t in cache[key] if now - t < period]
                if len(timestamps) >= max_calls:
                    return jsonify({"error": "Rate limit exceeded"}), 429
                else:
                    timestamps.append(now)
                    cache[key] = timestamps
            return f(*args, **kwargs)
        return wrapped
    return decorator

# Circuit breaker pattern
class CircuitBreaker:
    def __init__(self, max_failures=3, reset_timeout=5):
        self.max_failures = max_failures
        self.reset_timeout = reset_timeout
        self.failures = 0
        self.last_failure_time = None

    def __call__(self, func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if self.failures >= self.max_failures and (time.time() - self.last_failure_time) < self.reset_timeout:
                return "Service unavailable", 503
            try:
                result = func(*args, **kwargs)
                self.failures = 0
                return result
            except Exception as e:
                self.failures += 1
                self.last_failure_time = time.time()
                raise e
        return wrapper

# Fallback mechanism
def fallback(func):
    @wraps(func)
    def wrapped(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            # Implement degraded functionality here
            return "Fallback response", 503
    return wrapped

@app.route('/products', methods=['GET'])
@rate_limit(max_calls=100, period=60)
@circuit_breaker()
def get_products():
    try:
        products = []
        cursor = sql_conn.cursor()
        cursor.execute("SELECT * FROM products")
        rows = cursor.fetchall()
        for row in rows:
            product = {
                "id": row[0],
                "name": row[1],
                "description": row[2]
            }
            products.append(product)
        return jsonify(products), 200
    except Exception as e:
        return str(e), 500

@app.route('/products', methods=['POST'])
@rate_limit(max_calls=10, period=60)
@circuit_breaker()
def create_product():
    data = request.get_json()
    try:
        cursor = sql_conn.cursor()
        cursor.execute("INSERT INTO products (name, description) VALUES (%s, %s)", (data['name'], data['description']))
        sql_conn.commit()
        return jsonify({"message": "Product created successfully"}), 201
    except Exception as e:
        return str(e), 500

@app.route('/products/<int:id>', methods=['PUT'])
@rate_limit(max_calls=10, period=60)
@circuit_breaker()
def update_product(id):
    data = request.get_json()
    try:
        cursor = sql_conn.cursor()
        cursor.execute("UPDATE products SET name=%s, description=%s WHERE id=%s", (data['name'], data['description'], id))
        sql_conn.commit()
        return jsonify({"message": "Product updated successfully"}), 200
    except Exception as e:
        return str(e), 500

@app.route('/products/<int:id>', methods=['DELETE'])
@rate_limit(max_calls=10, period=60)
@circuit_breaker()
def delete_product(id):
    try:
        cursor = sql_conn.cursor()
        cursor.execute("DELETE FROM products WHERE id=%s", (id,))
        sql_conn.commit()
        return jsonify({"message": "Product deleted successfully"}), 200
    except Exception as e:
        return str(e), 500

if __name__ == '__main__':
    app.run(debug=True)
