import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.client.circuitbreaker.EnableCircuitBreaker;
import org.springframework.context.annotation.Bean;
import io.github.resilience4j.retry.Retry;
import io.github.resilience4j.retry.RetryConfig;
import org.springframework.cache.CacheManager;
import org.springframework.cache.concurrent.ConcurrentMapCacheManager;
import org.springframework.scheduling.annotation.EnableAsync;

@SpringBootApplication
@EnableCircuitBreaker
@EnableAsync
public class DynamicConfigServiceApplication {

    public static void main(String[] args) {
        SpringApplication.run(DynamicConfigServiceApplication.class, args);
    }

    @Bean
    public Retry dynamicConfigRetry() {
        return Retry.of("dynamicConfigRetry", RetryConfig.custom()
                .maxAttempts(5)
                .waitDuration(Duration.ofMillis(100))
                .build());
    }

    @Bean
    public CacheManager cacheManager() {
        return new ConcurrentMapCacheManager("configCache");
    }
}
