    FILE* error_log = fopen("error.log", "a");
    if (error_log != NULL) {
        time_t now = time(NULL);
        fprintf(error_log, "[%s] ERROR: %s\n", ctime(&now), message);
        fclose(error_log);
    } else {
        printf("Failed to open error log file.\n");
    }
}

// Example usage of the log_error function
int main() {
    const char* failure_message = "Authentication failed due to incorrect password.";
    log_error(failure_message);
    return 0;
}
