// DynamicScriptLoader.js

class DynamicScriptLoader {
  constructor(options = {}) {
    this.options = options;
    this.scripts = [];
    this.cache = new Map();
    this.locks = {};
    this.queue = [];
    this.isProcessingQueue = false;
  }

  addScript(script) {
    this.scripts.push(script);
  }

  async loadScripts() {
    if (this.isProcessingQueue) return;
    this.isProcessingQueue = true;

    while (this.queue.length > 0) {
      const scriptId = this.queue.shift();
      await this.loadScript(scriptId);
    }

    this.isProcessingQueue = false;
  }

  async loadScript(scriptId) {
    if (this.locks[scriptId]) return;
    this.locks[scriptId] = true;

    try {
      const script = this.scripts.find(s => s.id === scriptId);

      if (!script) throw new Error(`Script with id ${scriptId} not found`);

      if (script.dependencies.length > 0) {
        await Promise.all(script.dependencies.map(depId => this.loadScript(depId)));
      }

      if (this.cache.has(script.metadataUrl)) {
        await this.executeScript(script, this.cache.get(script.metadataUrl));
      } else {
        const metadata = await this.fetchMetadata(script.metadataUrl);
        this.cache.set(script.metadataUrl, metadata);
        await this.executeScript(script, metadata);
      }
    } catch (error) {
      console.error(`Failed to load script ${scriptId}:`, error);
      // Implement retry logic and fallback strategies here
    } finally {
      delete this.locks[scriptId];
    }
  }

  async fetchMetadata(url) {
    const MAX_RETRIES = 3;
    let attempts = 0;

    while (attempts < MAX_RETRIES) {
      try {
        const response = await fetch(url);
        if (!response.ok) throw new Error(`Failed to fetch metadata from ${url}`);
        return await response.json();
      } catch (error) {
        attempts++;
        console.error(`Attempt ${attempts} failed to fetch metadata from ${url}:`, error);
        // Implement retry logic and fallback strategies here
      }
    }

    throw new Error(`Max retries exceeded while fetching metadata from ${url}`);
  }

  async executeScript(script, metadata) {
    const scriptElement = document.createElement('script');
    scriptElement.id = script.id;
    scriptElement.textContent = `(${script.code})(${JSON.stringify(metadata)})`;
    document.body.appendChild(scriptElement);

    return new Promise((resolve, reject) => {
      scriptElement.onload = resolve;
      scriptElement.onerror = reject;
    });
  }

  // Add methods for system metrics handling, queuing mechanism, configuration management,
  // versioning, rollback mechanisms, modular architecture, logging and monitoring features here.
}

// Usage example:
const loader = new DynamicScriptLoader();
loader.addScript({
  id: 'script1',
  code: `(function(metadata) { console.log('Script 1', metadata); })(metadata)`,
  dependencies: [],
  priority: 1,
  metadataUrl: '/api/metadata/script1'
});
loader.addScript({
  id: 'script2',
  code: `(function(metadata) { console.log('Script 2', metadata); })(metadata)`,
  dependencies: ['script1'],
  priority: 2,
  metadataUrl: '/api/metadata/script2'
});

loader.loadScripts();
