['```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

#define MAX_STATES 1024
#define MAX_TRANSITIONS 256

typedef struct {
    int id;
    char metadata[256];
} State;

typedef struct {
    int src_state_id;
    int dst_state_id;
} Transition;

typedef struct {
    State states[MAX_STATES];
    Transition transitions[MAX_TRANSITIONS];
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} FSM;

FSM *fsm_create() {
    FSM *fsm = (FSM *)malloc(sizeof(FSM));
    if (!fsm) return NULL;

    pthread_mutex_init(&fsm->mutex, NULL);
    pthread_cond_init(&fsm->cond, NULL);

    return fsm;
}

void fsm_destroy(FSM *fsm) {
    free(fsm);
}

int fsm_add_state(FSM *fsm, int id, const char *metadata) {
    pthread_mutex_lock(&fsm->mutex);
    if (fsm->states[id].id != 0) {
        pthread_mutex_unlock(&fsm->mutex);
        return -1;
    }
    fsm->states[id].id = id;
    strncpy(fsm->states[id].metadata, metadata, sizeof(fsm->states[id].metadata));
    pthread_mutex_unlock(&fsm->mutex);
    return 0;
}

int fsm_add_transition(FSM *fsm, int src_state_id, int dst_state_id) {
    pthread_mutex_lock(&fsm->mutex);
    if (fsm->transitions[src_state_id].src_state_id != 0) {
        pthread_mutex_unlock(&fsm->mutex);
        return -1;
    }
    fsm->transitions[src_state_id].src_state_id = src_state_id;
    fsm->transitions[src_state_id].dst_state_id = dst_state_id;
    pthread_mutex_unlock(&fsm->mutex);
    return 0;
}

int fsm_transition(FSM *fsm, int current_state_id) {
    pthread_mutex_lock(&fsm->mutex);
    if (current_state_id >= MAX_STATES || fsm->transitions[current_state_id].src_state_id == 0) {
        pthread_mutex_unlock(&fsm->mutex);
        return -1;
    }
    int next_state_id = fsm->transitions[current_state_id].dst_state_id;
    current_state_id = next_state_id;
    pthread_cond_signal(&fsm->cond);
    pthread_mutex_unlock(&fsm->mutex);
    return 0;
}

int fsm_wait_for_transition(FSM *fsm) {
    pthread_mutex_lock(&fsm->mutex);
    while (current_state_id == -1) {
        pthread_cond_wait(&fsm->cond, &fsm->mutex);
    }
    int next_state_id = current_state_id;
    current_state_id = -1;
    pthread_mutex_unlock(&fsm->mutex);
    return next_state_id;
}

int fsm_get_metadata(FSM *fsm, int state_id, char **metadata) {
    pthread_mutex_lock(&fsm->mutex);
    if (state_id >= MAX_STATES || !fsm->states[state_id].id) {
        pthread_mutex_unlock(&fsm->mutex);
        return -1;
    }
    *metadata = fsm->states[state_id].metadata;
    pthread_mutex_unlock(&fsm->mutex);
    return 0;
}
