class DynamicThrottler {
public:
    DynamicThrottler(size_t maxStreams, size_t maxBandwidth)
        : maxStreams(maxStreams), maxBandwidth(maxBandwidth) {}

    void addStream(const std::string& streamId) {
        std::unique_lock<std::mutex> lock(mutex);
        while (streamMap.size() >= maxStreams) {
            cv.wait(lock, [this] { return streamMap.size() < maxStreams; });
        }
        streamMap[streamId] = BandwidthInfo{};
        lock.unlock();
    }

    void removeStream(const std::string& streamId) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = streamMap.find(streamId);
        if (it != streamMap.end()) {
            streamMap.erase(it);
        }
        cv.notify_one();
    }

    void allocateBandwidth(const std::string& streamId, size_t bytes) {
        // Implement bandwidth allocation logic here
    }

    void deallocateBandwidth(const std::string& streamId, size_t bytes) {
        // Implement bandwidth deallocation logic here
    }

    static std::string calculateSHA256(const unsigned char* data, size_t length) {
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256(data, length, hash);
        char buffer[65];
        for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
            sprintf(buffer + (i * 2), "%02x", hash[i]);
        }
        return std::string(buffer, 64);
    }

private:
    struct BandwidthInfo {
        size_t currentBandwidth;
        size_t peakBandwidth;
    };

    size_t maxStreams;
    size_t maxBandwidth;
    std::unordered_map<std::string, BandwidthInfo> streamMap;
    std::mutex mutex;
    std::condition_variable cv;
};

int main() {
    DynamicThrottler throttler(1000, 100 * 1024 * 1024); // 1000 streams, 100 MB/s max bandwidth

    // Example usage
    throttler.addStream("stream1");
    throttler.allocateBandwidth("stream1", 5 * 1024 * 1024);

    unsigned char data[32] = {0};
    std::string hash = DynamicThrottler::calculateSHA256(data, sizeof(data));
    std::cout << "SHA-256: " << hash << std::endl;

    throttler.deallocateBandwidth("stream1", 5 * 1024 * 1024);
    throttler.removeStream("stream1");

    return 0;
}
