#include <iostream>
#include <vector>
#include <memory>
#include <mutex>
#include <condition_variable>

// Define the Service interface
class Service {
public:
    virtual ~Service() {}
    virtual void run() = 0;
    virtual void stop() = 0;
};

// Implement a simple service
class MyService : public Service {
public:
    void run() override {
        std::cout << "MyService is running" << std::endl;
    }
    void stop() override {
        std::cout << "MyService is stopping" << std::endl;
    }
};

// Define the ServiceManager class
class ServiceManager {
private:
    std::vector<std::shared_ptr<Service>> services;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void addService(std::shared_ptr<Service> service) {
        std::lock_guard<std::mutex> lock(mtx);
        services.push_back(service);
        cv.notify_all();
    }

    void startAllServices() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return !services.empty(); });
            for (auto& service : services) {
                service->run();
            }
        }
    }

    void stopAllServices() {
        for (auto& service : services) {
            service->stop();
        }
    }
};

int main() {
    ServiceManager manager;
    auto myService = std::make_shared<MyService>();
    manager.addService(myService);
    manager.startAllServices();

    // Simulate stopping all services
    manager.stopAllServices();

    return 0;
}
