#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

#define MAX_COMMANDS 100
#define MAX_CMD_LENGTH 256

typedef struct {
    char command[MAX_CMD_LENGTH];
    char output_log[MAX_CMD_LENGTH];
    char error_log[MAX_CMD_LENGTH];
} Command;

void execute_command(Command *cmd) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return;
    } else if (pid == 0) {
        FILE *output_file = fopen(cmd->output_log, "w");
        if (!output_file) {
            perror("fopen output log");
            exit(EXIT_FAILURE);
        }
        FILE *error_file = freopen(cmd->error_log, "w", stderr);
        if (!error_file) {
            perror("freopen error log");
            fclose(output_file);
            exit(EXIT_FAILURE);
        }

        execl("/bin/sh", "sh", "-c", cmd->command, (char *)NULL);
        perror("execl");
        fclose(output_file);
        fclose(error_file);
        exit(EXIT_FAILURE);
    } else {
        int status;
        if (waitpid(pid, &status, 0) == -1) {
            perror("waitpid");
            return;
        }
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            fprintf(stderr, "Command failed: %s\n", cmd->command);
        }
    }
}

void process_commands(Command *commands, int count) {
    for (int i = 0; i < count; i++) {
        execute_command(&commands[i]);
    }
}

int main() {
    Command commands[MAX_COMMANDS];
    // Populate the commands array with user-provided or external input
    // Example: parse_commands_from_api(commands, &count);

    int count = 5;
    process_commands(commands, count);

    return 0;
}
