using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Polly;
using Polly.Retry;

public class Startup
{
    public IConfiguration Configuration { get; }

    public Startup(IConfiguration configuration)
    {
        Configuration = configuration;
    }

    public void ConfigureServices(IServiceCollection services)
    {
        services.AddControllers();
        services.AddSingleton<HttpClient>(new HttpClient());

        var retryPolicy = Policy.Handle<HttpRequestException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

        services.AddSingleton(retryPolicy);

        services.AddDistributedMemoryCache();

        services.AddScoped<IUserActivityService, UserActivityService>();
        services.AddScoped<IUserService, UserService>();
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }

        app.UseRouting();

        app.UseAuthorization();

        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllers();
        });
    }
}

public interface IUserActivityService
{
    Task<List<UserActivity>> GetUserActivitiesAsync(string userId);
}

public class UserActivityService : IUserActivityService
{
    private readonly HttpClient _httpClient;
    private readonly IPolicy _retryPolicy;
    private readonly IDistributedCache _cache;

    public UserActivityService(HttpClient httpClient, IPolicy retryPolicy, IDistributedCache cache)
    {
        _httpClient = httpClient;
        _retryPolicy = retryPolicy;
        _cache = cache;
    }

    public async Task<List<UserActivity>> GetUserActivitiesAsync(string userId)
    {
        var cachedActivities = await _cache.GetStringAsync(userId);
        if (cachedActivities != null)
        {
            return JsonConvert.DeserializeObject<List<UserActivity>>(cachedActivities);
        }

        var activities = await _retryPolicy.ExecuteAsync(() =>
        {
            return FetchUserActivitiesFromApiAsync(userId);
        });

        await _cache.SetStringAsync(userId, JsonConvert.SerializeObject(activities), new DistributedCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10)
        });

        return activities;
    }

    private async Task<List<UserActivity>> FetchUserActivitiesFromApiAsync(string userId)
    {
        var response = await _httpClient.GetAsync($"https://api.example.com/user/{userId}/activities");
        response.EnsureSuccessStatusCode();
        return JsonConvert.DeserializeObject<List<UserActivity>>(await response.Content.ReadAsStringAsync());
    }
}

public class UserActivity
{
    public string Id { get; set; }
    public string UserId { get; set; }
    public DateTime Timestamp { get; set; }
    public string Action { get; set; }
}

public interface IUserService
{
    Task<User> GetUserAsync(string userId);
}

public class UserService : IUserService
{
    private readonly HttpClient _httpClient;
    private readonly IPolicy _retryPolicy;

    public UserService(HttpClient httpClient, IPolicy retryPolicy)
    {
        _httpClient = httpClient;
        _retryPolicy = retryPolicy;
    }

    public async Task<User> GetUserAsync(string userId)
    {
        return await _retryPolicy.ExecuteAsync(() =>
        {
            return FetchUserFromApiAsync(userId);
        });
    }

    private async Task<User> FetchUserFromApiAsync(string userId)
    {
        var response = await _httpClient.GetAsync($"https://api.example.com/user/{userId}");
        response.EnsureSuccessStatusCode();
        return JsonConvert.DeserializeObject<User>(await response.Content.ReadAsStringAsync());
    }
}

public class User
{
    public string Id { get; set; }
    public string Username { get; set; }
    public string Email { get; set; }
}
