    public void deserializeAndCache() {
        while (true) {
            try {
                byte[] chunk = readChunkFromNetwork();
                Object obj = objectInputStream.readObject();

                if (!validate(obj)) {
                    throw new ValidationException("Object schema validation failed");
                }

                cache.put(obj);

            } catch (IOException e) {
                logger.error("Error reading from network stream: " + e.getMessage());
            } catch (ClassNotFoundException e) {
                logger.error("Class not found while deserializing object: " + e.getMessage());
