public class CacheRegion
{
    private readonly ConcurrentDictionary<string, string> _cache;
    private readonly IDataSource _dataSource;

    public CacheRegion(IDataSource dataSource)
    {
        _cache = new ConcurrentDictionary<string, string>();
        _dataSource = dataSource;
    }

    public async Task<string> GetAsync(string key)
    {
        if (!_cache.TryGetValue(key, out var value))
        {
            value = await _dataSource.GetDataAsync(key);
            _cache.TryAdd(key, value);
        }
        return value;
    }

    public async Task SetAsync(string key, string value)
    {
        _cache.TryUpdate(key, value, value);
        await _dataSource.SetDataAsync(key, value);
    }
}

public class DistributedCache
{
    private readonly ConcurrentDictionary<string, CacheRegion> _regions;

    public DistributedCache(IEnumerable<IDataSourceFactory> factories)
    {
        _regions = new ConcurrentDictionary<string, CacheRegion>();
        foreach (var factory in factories)
        {
            var regionName = factory.RegionName;
            var dataSource = factory.CreateDataSource();
            _regions.TryAdd(regionName, new CacheRegion(dataSource));
        }
    }

    public async Task<string> GetAsync(string key, string regionName)
    {
        if (_regions.TryGetValue(regionName, out var region))
        {
            return await region.GetAsync(key);
        }
        throw new ArgumentException("Invalid region name");
    }

    public async Task SetAsync(string key, string value, string regionName)
    {
        if (_regions.TryGetValue(regionName, out var region))
        {
            await region.SetAsync(key, value);
        }
        else
        {
            throw new ArgumentException("Invalid region name");
        }
    }
}

public interface IDataSourceFactory
{
    string RegionName { get; }
    IDataSource CreateDataSource();
}

public class ExternalDataSourceFactory : IDataSourceFactory
{
    public string RegionName => "External";

    public IDataSource CreateDataSource()
    {
        var httpClient = new HttpClient(new HttpClientHandler());
        return new ExternalDataSource(httpClient);
    }
}

public class NoSqlStoreFactory : IDataSourceFactory
{
    public string RegionName => "NoSql";

    public IDataSource CreateDataSource()
    {
        // Initialize NoSQL store client
        throw new NotImplementedException();
    }
}
