import time
import queue
import threading
import requests

class LogFramework:
    def __init__(self, services):
        self.services = services
        self.log_queue = queue.Queue()
        self.worker_threads = []
        self.setup_workers()

    def setup_workers(self):
        for _ in range(5):  # Adjust the number of workers based on load
            thread = threading.Thread(target=self.process_logs)
            thread.daemon = True
            thread.start()
            self.worker_threads.append(thread)

    def log(self, message):
        self.log_queue.put(message)

    def process_logs(self):
        while True:
            message = self.log_queue.get()
            if message is None:  # Exit signal for the worker
                break
            self.send_log_to_services(message)
            self.log_queue.task_done()

    def send_log_to_services(self, message):
        for service in self.services:
            try:
                response = requests.post(service['url'], data=message, timeout=5)
                if response.status_code != 200:
                    raise Exception(f"Failed to log to {service['name']}")
            except requests.RequestException as e:
                print(f"Error logging to {service['name']}: {e}")

# Example usage
services = [
    {'name': 'Service1', 'url': 'https://service1.com/log'},
    {'name': 'Service2', 'url': 'https://service2.com/log'}
]

logging_framework = LogFramework(services)
logging_framework.log("This is a log message")
```

