#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int log_level;
    FILE* log_file;
} metadata;

static pthread_mutex_t call_stack_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_tls_t call_stack_key;
static const char* function_name = "processString";

void log_message(const char* message, ...) {
    va_list args;
    va_start(args, message);
    vfprintf(metadata.log_file, message, args);
    va_end(args);
}

const char* processString(const char* input, int sizeLimit, metadata* config) {
    if (!input || !config || !config->log_file) {
        log_message("Error: Invalid parameters.\n");
        return NULL;
    }

    pthread_mutex_lock(&call_stack_lock);
    if (pthread_getspecific(call_stack_key)) {
        log_message("Error: Recursive call detected.\n");
        pthread_mutex_unlock(&call_stack_lock);
        return NULL;
    }
    pthread_setspecific(call_stack_key, &function_name);

    if (strlen(input) >= sizeLimit) {
        log_message("Info: String exceeds size limit.\n");
        pthread_setspecific(call_stack_key, NULL);
        pthread_mutex_unlock(&call_stack_lock);
        return NULL;
    }

    char* output = malloc(strlen(input) + 2); // +1 for '/', +1 for null terminator
    if (!output) {
        log_message("Error: Memory allocation failed.\n");
        pthread_setspecific(call_stack_key, NULL);
        pthread_mutex_unlock(&call_stack_lock);
        return NULL;
    }

    strcpy(output, input);
    output[strlen(input)] = '/';
    output[strlen(input) + 1] = '\0';

    log_message("Info: String processed. Original length %lu, new length %lu\n",
                strlen(input), strlen(output));

    pthread_setspecific(call_stack_key, NULL);
    pthread_mutex_unlock(&call_stack_lock);

    return output;
}

int main() {
    // Initialize metadata and call stack
    metadata config = { LOG_INFO, stdout };
    pthread_key_create(&call_stack_key, NULL);

    const char* testString = "HelloWorld";
    int sizeLimit = 12;

    const char* result = processString(testString, sizeLimit, &config);
    if (result) {
        printf("Processed string: %s\n", result);
        free((char*)result); // Free the allocated memory
    }

    pthread_key_delete(call_stack_key);
    return 0;
}
