#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the DeviceStatusReport structure
typedef struct {
    time_t timestamp;
    char device_id[10];
    int signal_strength;
    int *error_codes;
    size_t error_count;
} DeviceStatusReport;

// Define the DeviceStatusLibrary structure
typedef struct {
    DeviceStatusReport **reports;
    size_t count;
    pthread_mutex_t lock;
} DeviceStatusLibrary;

// Initialize the library
void init_library(DeviceStatusLibrary *lib) {
    lib->reports = NULL;
    lib->count = 0;
    pthread_mutex_init(&lib->lock, NULL);
}

// Add a report to the library
int add_report(DeviceStatusLibrary *lib, DeviceStatusReport *report) {
    pthread_mutex_lock(&lib->lock);
    DeviceStatusReport **new_reports = realloc(lib->reports, (lib->count + 1) * sizeof(DeviceStatusReport *));
    if (!new_reports) {
        pthread_mutex_unlock(&lib->lock);
        return -1; // Memory allocation failed
    }
    new_reports[lib->count] = report;
    lib->reports = new_reports;
    lib->count++;
    pthread_mutex_unlock(&lib->lock);
    return 0;
}

// Update an existing report in the library
int update_report(DeviceStatusLibrary *lib, const char *device_id, DeviceStatusReport *new_report) {
    pthread_mutex_lock(&lib->lock);
    for (size_t i = 0; i < lib->count; i++) {
        if (strcmp(lib->reports[i]->device_id, device_id) == 0) {
            free(lib->reports[i]->error_codes);
            free(lib->reports[i]);
            lib->reports[i] = new_report;
            pthread_mutex_unlock(&lib->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&lib->lock);
    return -1; // Report not found
}

// Retrieve a report from the library
DeviceStatusReport *get_report(DeviceStatusLibrary *lib, const char *device_id) {
    pthread_mutex_lock(&lib->lock);
    for (size_t i = 0; i < lib->count; i++) {
        if (strcmp(lib->reports[i]->device_id, device_id) == 0) {
            DeviceStatusReport *report_copy = malloc(sizeof(DeviceStatusReport));
            memcpy(report_copy, lib->reports[i], sizeof(DeviceStatusReport));
            report_copy->error_codes = malloc(lib->reports[i]->error_count * sizeof(int));
            memcpy(report_copy->error_codes, lib->reports[i]->error_codes, lib->reports[i]->error_count * sizeof(int));
            pthread_mutex_unlock(&lib->lock);
            return report_copy;
        }
    }
    pthread_mutex_unlock(&lib->lock);
    return NULL; // Report not found
}

// Delete a report from the library
int delete_report(DeviceStatusLibrary *lib, const char *device_id) {
    pthread_mutex_lock(&lib->lock);
    for (size_t i = 0; i < lib->count; i++) {
        if (strcmp(lib->reports[i]->device_id, device_id) == 0) {
            free(lib->reports[i]->error_codes);
            free(lib->reports[i]);
            for (size_t j = i; j < lib->count - 1; j++) {
                lib->reports[j] = lib->reports[j + 1];
            }
            lib->reports = realloc(lib->reports, (lib->count - 1) * sizeof(DeviceStatusReport *));
            lib->count--;
            pthread_mutex_unlock(&lib->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&lib->lock);
    return -1; // Report not found
}

// Clean up the library
void cleanup_library(DeviceStatusLibrary *lib) {
    pthread_mutex_lock(&lib->lock);
    for (size_t i = 0; i < lib->count; i++) {
        free(lib->reports[i]->error_codes);
        free(lib->reports[i]);
    }
    free(lib->reports);
    pthread_mutex_destroy(&lib->lock);
}
