// TransactionLog struct
struct TransactionLog {
    int transactionID;
    int userID;
    std::chrono::system_clock::time_point timestamp;
    double amount;
    std::vector<std::string> entities;
};

// TransactionManager class
class TransactionManager {
public:
    void addLog(const TransactionLog& log) {
        std::lock_guard<std::mutex> lock(mutex_);
        logs_[log.transactionID] = log;
    }

    bool updateLog(int transactionID, const TransactionLog& newLog) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (logs_.find(transactionID) != logs_.end()) {
            logs_[transactionID] = newLog;
            return true;
        }
        return false;
    }

    bool getLog(int transactionID, TransactionLog& log) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = logs_.find(transactionID);
        if (it != logs_.end()) {
            log = it->second;
            return true;
        }
        return false;
    }

    bool deleteLog(int transactionID) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (logs_.find(transactionID) != logs_.end()) {
            logs_.erase(transactionID);
            return true;
        }
        return false;
    }

private:
    std::map<int, TransactionLog> logs_;
    mutable std::mutex mutex_;
};

// PaymentProcessor interface
class PaymentProcessor {
public:
    virtual bool processTransaction(const TransactionLog& log) = 0;
    virtual ~PaymentProcessor() {}
};

// Example payment processor
class ExampleProcessor : public PaymentProcessor {
public:
    bool processTransaction(const TransactionLog& log) override {
        // Simulate processing time and success rate
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
        return true;
    }
};

// ExternalPaymentService class
template <typename Processor>
class ExternalPaymentService {
public:
    ExternalPaymentService(TransactionManager& manager, Processor processor)
        : manager_(manager), processor_(processor) {}

    void addTransaction(const TransactionLog& log) {
        if (processor_.processTransaction(log)) {
            manager_.addLog(log);
        }
    }

private:
    TransactionManager& manager_;
    Processor processor_;
};

// PaymentServiceFactory class
class PaymentServiceFactory {
public:
    static ExternalPaymentService<ExampleProcessor> createExampleService(TransactionManager& manager) {
        return ExternalPaymentService<ExampleProcessor>(manager, ExampleProcessor());
    }
};

int main() {
    TransactionManager manager;
    auto service = PaymentServiceFactory::createExampleService(manager);

    // Simulate transaction
    TransactionLog log{1, 1001, std::chrono::system_clock::now(), 100.5, {"entity1", "entity2"}};
    service.addTransaction(log);

    return 0;
}
```

