// Cache class for storing weather data
class WeatherCache {
public:
    static WeatherCache& getInstance() {
        static WeatherCache instance;
        return instance;
    }

    void addCurrentWeather(const std::string& location, const WeatherData& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        currentCache_[location] = data;
    }

    void addHistoricalWeather(const std::string& location, const WeatherData& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        historicalCache_[location].push_back(data);
    }

    WeatherData getCurrentWeather(const std::string& location) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (currentCache_.find(location) != currentCache_.end()) {
            return currentCache_[location];
        }
        return {};
    }

    std::vector<WeatherData> getHistoricalWeather(const std::string& location) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (historicalCache_.find(location) != historicalCache_.end()) {
            return historicalCache_[location];
        }
        return {};
    }

private:
    WeatherCache() = default;
    WeatherCache(const WeatherCache&) = delete;
    WeatherCache& operator=(const WeatherCache&) = delete;

    std::unordered_map<std::string, WeatherData> currentCache_;
    std::unordered_map<std::string, std::vector<WeatherData>> historicalCache_;
    mutable std::mutex mutex_;
};

// Service class for fetching weather data
class WeatherService {
public:
    void addAPI(WeatherAPI* api) {
        apis_.push_back(api);
    }

    WeatherData getCurrentWeather(const std::string& location) {
        return fetchData(location, [](WeatherAPI* api) { return api->getCurrentWeather; });
    }

    std::vector<WeatherData> getHistoricalWeather(const std::string& location, const std::tm& date) {
        return fetchData(location, [&](WeatherAPI* api) { return api->getHistoricalWeather; }, date);
    }

private:
    template<typename Func>
    void fetchAndCacheData(WeatherAPI* api, Func func, const std::string& location, const std::tm& date = {}) {
        try {
            WeatherData data = func(api, location, date);
            if (date.tm_isdst == -1) { // Check for historical data
                WeatherCache::getInstance().addHistoricalWeather(location, data);
            } else {
                WeatherCache::getInstance().addCurrentWeather(location, data);
            }
        } catch (...) {
            std::cerr << "API call failed" << std::endl;
        }
    }

    template<typename Func>
    auto fetchData(const std::string& location, Func func, const std::tm& date = {}) -> decltype(func(apis_[0], location, date)) {
        for (auto api : apis_) {
            WeatherData data = WeatherCache::getInstance().getCurrentWeather(location);
            if (!data.location.empty()) {
                return data;
            }
            fetchAndCacheData(api, func, location, date);
        }
        return {};
    }

    std::vector<WeatherAPI*> apis_;
};

int main() {
    OpenWeatherAPI openWeatherAPI;
    WeatherService weatherService;
    weatherService.addAPI(&openWeatherAPI);

    // Fetch and display current weather
    WeatherData currentWeather = weatherService.getCurrentWeather("New York");
    std::cout << "Current weather in New York: " << currentWeather.condition << ", " << currentWeather.temperature << "C" << std::endl;

    // Fetch and display historical weather
    std::tm date = {0, 0, 12, 24, 9, 130}; // October 24, 2023
    WeatherData historicalWeather = weatherService.getHistoricalWeather("New York", date);
    std::cout << "Historical weather in New York on Oct 24, 2023: " << historicalWeather.condition << ", " << historicalWeather.temperature << "C" << std::endl;

    return 0;
}
