#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_UE_INSTANCES 100

typedef struct {
    int crc_value;
    // Other fields as needed
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* crc_indications[MAX_UE_INSTANCES];
pthread_mutex_t resource_pool_lock = PTHREAD_MUTEX_INITIALIZER;
int current_ue_count = 0;

void populate_crc_indications(int ue_id, int crc_value) {
    pthread_mutex_lock(&resource_pool_lock);
    if (current_ue_count >= MAX_UE_INSTANCES) {
        printf("Error: Maximum UE instances reached.\n");
        pthread_mutex_unlock(&resource_pool_lock);
        return;
    }

    crc_indications[current_ue_count] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crc_indications[current_ue_count] == NULL) {
        printf("Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&resource_pool_lock);
        return;
    }

    crc_indications[current_ue_count]->crc_value = crc_value;
    current_ue_count++;
    pthread_mutex_unlock(&resource_pool_lock);
}

void free_crc_indications() {
    for (int i = 0; i < current_ue_count; i++) {
        if (crc_indications[i] != NULL) {
            free(crc_indications[i]);
        }
    }
    current_ue_count = 0;
}

// Example usage
int main() {
    populate_crc_indications(0, 1234);
    populate_crc_indications(1, 5678);

    // Use crc_indications for further processing

    free_crc_indications();
    return 0;
}
```

