class GlobalMetricsCoordinator {
public:
    void CollectMetric(const std::string& service, const std::string& metric, double value) {
        std::lock_guard<std::mutex> lock(mutex_);
        metrics_[service][metric] += value;
    }

    void StartAggregation() {
        aggregation_thread_ = std::thread(&GlobalMetricsCoordinator::AggregateMetrics, this);
    }

    void StopAggregation() {
        stop_aggregation_.store(true);
        aggregation_cv_.notify_all();
        if (aggregation_thread_.joinable()) {
            aggregation_thread_.join();
        }
    }

private:
    void AggregateMetrics() {
        while (!stop_aggregation_.load()) {
            std::unique_lock<std::mutex> lock(mutex_);
            aggregation_cv_.wait_for(lock, std::chrono::seconds(1), [this] { return stop_aggregation_.load(); });

            for (const auto& service : metrics_) {
                double total = 0.0;
                for (const auto& metric : service.second) {
                    total += metric.second;
                }
                aggregated_metrics_[service.first] = total;
            }

            lock.unlock();
            DisseminateMetrics(aggregated_metrics_);
        }
    }

    void DisseminateMetrics(const std::unordered_map<std::string, double>& metrics) {
        // Code to disseminate metrics across the ecosystem
        for (const auto& metric : metrics) {
            std::cout << "Disseminating metric for service " << metric.first << ": " << metric.second << std::endl;
        }
    }

    std::unordered_map<std::string, std::unordered_map<std::string, double>> metrics_;
    std::unordered_map<std::string, double> aggregated_metrics_;
    std::mutex mutex_;
    std::condition_variable aggregation_cv_;
    std::thread aggregation_thread_;
    std::atomic<bool> stop_aggregation_{false};
};

int main() {
    GlobalMetricsCoordinator coordinator;
    coordinator.StartAggregation();

    // Simulate metric collection
    for (int i = 0; i < 10; ++i) {
        coordinator.CollectMetric("service1", "cpu_usage", 5.0 + i % 3);
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    coordinator.StopAggregation();
    return 0;
}
