class FinancialMarketDataLibrary {
public:
    void addDataProvider(std::shared_ptr<DataProvider> provider) {
        std::lock_guard<std::mutex> lock(mutex_);
        providers_.push_back(provider);
    }

    void startIngestion() {
        for (auto& provider : providers_) {
            ingestionThreads_.emplace_back([this, provider]() {
                while (true) {
                    if (!provider->connect()) {
                        std::this_thread::sleep_for(std::chrono::seconds(1));
                        continue;
                    }
                    std::vector<Data> data = provider->fetchData();
                    if (!data.empty()) {
                        processData(data);
                    }
                }
            });
        }
    }

    void stopIngestion() {
        for (auto& thread : ingestionThreads_) {
            thread.join();
        }
    }

private:
    void processData(const std::vector<Data>& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        processedData_.insert(processedData_.end(), data.begin(), data.end());
        condition_.notify_all();
    }

    std::vector<std::shared_ptr<DataProvider>> providers_;
    std::vector<std::thread> ingestionThreads_;
    std::queue<Data> processedData_;
    std::mutex mutex_;
    std::condition_variable condition_;
};

