#include <openssl/pem.h>
#include <iostream>
#include <thread>
#include <mutex>
#include <vector>
#include <queue>

// Define constants
const int KEY_SIZE = 32;
const int IV_SIZE = 16;
const int TAG_SIZE = 16;
const int RSA_KEY_SIZE = 2048;

// Function to generate AES key and IV
void generateAESKeyAndIV(unsigned char* key, unsigned char* iv) {
    RAND_bytes(key, KEY_SIZE);
    RAND_bytes(iv, IV_SIZE);
}

// Function to encrypt data using AES-256-GCM
void encryptData(const unsigned char* plaintext, int plaintext_len, const unsigned char* key, const unsigned char* iv, unsigned char* ciphertext, unsigned char* tag) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx, ciphertext + ciphertext_len, &ciphertext_len);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, TAG_SIZE, tag);
    EVP_CIPHER_CTX_free(ctx);
}

// Function to decrypt data using AES-256-GCM
void decryptData(const unsigned char* ciphertext, int ciphertext_len, const unsigned char* tag, const unsigned char* key, const unsigned char* iv, unsigned char* plaintext) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv);
    EVP_DecryptUpdate(ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len);
    EVP_DecryptFinal_ex(ctx, plaintext + plaintext_len, &plaintext_len);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, TAG_SIZE, tag);
    EVP_CIPHER_CTX_free(ctx);
}

// Function to generate RSA key pair
void generateRSAKeyPair(RSA*& rsa_pub, RSA*& rsa_priv) {
    rsa_pub = RSA_new();
    rsa_priv = RSA_new();
    BIGNUM *e = BN_new();
    BN_set_word(e, RSA_F4);
    RSA_generate_key_ex(rsa_pub, RSA_KEY_SIZE, e, NULL);
    RSA_copy_public(rsa_priv, rsa_pub);
}

// Function to encrypt data using RSA-OAEP
void encryptDataRSA(const unsigned char* plaintext, int plaintext_len, RSA* rsa_pub, unsigned char* ciphertext) {
    int ciphertext_len;
    RSA_public_encrypt(plaintext_len, plaintext, ciphertext, rsa_pub, RSA_PKCS1_OAEP_PADDING);
}

// Function to decrypt data using RSA-OAEP
void decryptDataRSA(const unsigned char* ciphertext, int ciphertext_len, RSA* rsa_priv, unsigned char* plaintext) {
    int plaintext_len;
    RSA_private_decrypt(ciphertext_len, ciphertext, plaintext, rsa_priv, RSA_PKCS1_OAEP_PADDING);
}

// Thread-safe mechanism for cipher context management
class CipherContextManager {
private:
    std::mutex mtx;
    std::queue<EVP_CIPHER_CTX*> ctx_pool;
public:
    CipherContextManager(int pool_size) {
        for (int i = 0; i < pool_size; ++i) {
            EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
            ctx_pool.push(ctx);
        }
    }
    ~CipherContextManager() {
        while (!ctx_pool.empty()) {
            EVP_CIPHER_CTX_free(ctx_pool.front());
            ctx_pool.pop();
        }
    }
    EVP_CIPHER_CTX* getCtx() {
        std::lock_guard<std::mutex> lock(mtx);
        if (ctx_pool.empty()) {
            return EVP_CIPHER_CTX_new();
        } else {
            EVP_CIPHER_CTX* ctx = ctx_pool.front();
            ctx_pool.pop();
            return ctx;
        }
    }
    void releaseCtx(EVP_CIPHER_CTX* ctx) {
        std::lock_guard<std::mutex> lock(mtx);
        ctx_pool.push(ctx);
    }
};

// Class for managing encryption service
class EncryptionService {
private:
    CipherContextManager cipher_manager;
    RSA* rsa_pub;
    RSA* rsa_priv;
public:
    EncryptionService(int pool_size) : cipher_manager(pool_size), rsa_pub(nullptr), rsa_priv(nullptr) {
        generateRSAKeyPair(rsa_pub, rsa_priv);
    }
    ~EncryptionService() {
        if (rsa_pub) RSA_free(rsa_pub);
        if (rsa_priv) RSA_free(rsa_priv);
    }
    void encrypt(const unsigned char* plaintext, int plaintext_len, unsigned char* ciphertext, unsigned char* tag) {
        EVP_CIPHER_CTX* ctx = cipher_manager.getCtx();
        generateAESKeyAndIV(ctx->key, ctx->iv);
        encryptData(plaintext, plaintext_len, ctx->key, ctx->iv, ciphertext, tag);
        cipher_manager.releaseCtx(ctx);
    }
    void decrypt(const unsigned char* ciphertext, int ciphertext_len, const unsigned char* tag, unsigned char* plaintext) {
        EVP_CIPHER_CTX* ctx = cipher_manager.getCtx();
        decryptData(ciphertext, ciphertext_len, tag, ctx->key, ctx->iv, plaintext);
        cipher_manager.releaseCtx(ctx);
    }
};

int main() {
    EncryptionService service(1000);
    // Simulate encryption and decryption
    unsigned char plaintext[128];
    unsigned char ciphertext[256];
    unsigned char tag[TAG_SIZE];
    service.encrypt(plaintext, sizeof(plaintext), ciphertext, tag);
    unsigned char decryptedtext[sizeof(plaintext)];
    service.decrypt(ciphertext, sizeof(ciphertext) - TAG_SIZE, tag, decryptedtext);
    return 0;
}
```

