using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class OAuthTokenValidator : IAsyncDisposable
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, TokenValidationRule> _validationRules = new();
    private readonly SemaphoreSlim _rulesUpdateSemaphore = new(1);
    private CancellationTokenSource _tokenCancellationTokenSource = new();

    public OAuthTokenValidator()
    {
        _httpClient = new HttpClient
        {
            BaseAddress = new Uri("https://oauth2service.com"),
            Timeout = TimeSpan.FromSeconds(5)
        };
    }

    public async Task<bool> ValidateTokenAsync(string token, CancellationToken cancellationToken = default)
    {
        var rule = GetValidationRule();
        if (rule == null)
        {
            throw new InvalidOperationException("No validation rules available.");
        }

        try
        {
            return await rule.ValidateAsync(token, _httpClient, cancellationToken);
        }
        catch (Exception ex)
        {
            // Log error and handle as needed
            Console.WriteLine($"Token validation failed: {ex.Message}");
            return false;
        }
    }

    public async Task UpdateValidationRulesAsync(CancellationToken cancellationToken = default)
    {
        await _rulesUpdateSemaphore.WaitAsync(cancellationToken);
        try
        {
            using (var response = await _httpClient.GetAsync("api/rules", cancellationToken))
            {
                if (response.IsSuccessStatusCode)
                {
                    var newRules = await response.Content.ReadAsAsync<Dictionary<string, TokenValidationRule>>();
                    _validationRules.Clear();
                    foreach (var rule in newRules)
                    {
                        _validationRules.TryAdd(rule.Key, rule.Value);
                    }
                }
                else
                {
                    // Handle error, e.g., log and retry later
                    Console.WriteLine($"Failed to update validation rules: {response.StatusCode}");
                }
            }
        }
        finally
        {
            _rulesUpdateSemaphore.Release();
        }
    }

    public async ValueTask DisposeAsync()
    {
        _tokenCancellationTokenSource.Cancel();
        await _httpClient.DisposeAsync();
        GC.SuppressFinalize(this);
    }

    private TokenValidationRule GetValidationRule()
    {
        if (_validationRules.Count == 0)
        {
            return null;
        }

        // Implement a strategy for selecting a validation rule, e.g., round-robin
        var keys = _validationRules.Keys.ToArray();
        int index = Interlocked.Increment(ref _nextRuleIndex) % keys.Length;
        return _validationRules[keys[index]];
    }

    private int _nextRuleIndex;

    public record TokenValidationRule(string Name, Func<string, HttpClient, CancellationToken, Task<bool>> ValidateAsync);
}
