#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the DeviceStatusReport structure
typedef struct {
    time_t timestamp;
    char deviceId[50];
    int signalStrength;
    int errorCode;
    double latitude;
    double longitude;
} DeviceStatusReport;

// Define a linked list node for dynamic collection
typedef struct Node {
    DeviceStatusReport data;
    struct Node* next;
} Node;

// Define the DeviceStatusManager structure
typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} DeviceStatusManager;

// Initialize the device status manager
void initDeviceStatusManager(DeviceStatusManager* manager) {
    manager->head = NULL;
    pthread_mutex_init(&manager->mutex, NULL);
}

// Add or update a device status report
void addOrUpdateReport(DeviceStatusManager* manager, DeviceStatusReport report) {
    pthread_mutex_lock(&manager->mutex);
    Node* current = manager->head;
    while (current != NULL) {
        if (strcmp(current->data.deviceId, report.deviceId) == 0) {
            // Update existing report
            current->data = report;
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
        current = current->next;
    }
    // Add new report
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = report;
    newNode->next = manager->head;
    manager->head = newNode;
    pthread_mutex_unlock(&manager->mutex);
}

// Retrieve a device status report by device ID
DeviceStatusReport* getReportByDeviceId(DeviceStatusManager* manager, const char* deviceId) {
    pthread_mutex_lock(&manager->mutex);
    Node* current = manager->head;
    while (current != NULL) {
        if (strcmp(current->data.deviceId, deviceId) == 0) {
            DeviceStatusReport* reportCopy = (DeviceStatusReport*)malloc(sizeof(DeviceStatusReport));
            *reportCopy = current->data;
            pthread_mutex_unlock(&manager->mutex);
            return reportCopy;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}

// Summary API: Calculate average signal strength
double calculateAverageSignalStrength(DeviceStatusManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    Node* current = manager->head;
    int count = 0;
    double totalSignalStrength = 0;
    while (current != NULL) {
        totalSignalStrength += current->data.signalStrength;
        count++;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->mutex);
    return (count > 0) ? (totalSignalStrength / count) : 0;
}

// Summary API: Frequency of error codes
int getErrorCodeFrequency(DeviceStatusManager* manager, int errorCode) {
    pthread_mutex_lock(&manager->mutex);
    Node* current = manager->head;
    int frequency = 0;
    while (current != NULL) {
        if (current->data.errorCode == errorCode) {
            frequency++;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->mutex);
    return frequency;
}

// Summary API: Geographic distribution trends
void* getGeographicDistributionTrends(DeviceStatusManager* manager, void (*callback)(double latitude, double longitude)) {
    pthread_mutex_lock(&manager->mutex);
    Node* current = manager->head;
    while (current != NULL) {
        callback(current->data.latitude, current->data.longitude);
        current = current->next;
    }
    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}

// Clean up the device status manager
void cleanupDeviceStatusManager(DeviceStatusManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    Node* current = manager->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->mutex);
}

// External data ingestion service integration
void ingestData(DeviceStatusManager* manager, DeviceStatusReport report) {
    addOrUpdateReport(manager, report);
}
