#include <iostream>
#include <thread>
#include <mutex>
#include <vector>
#include <queue>
#include <condition_variable>

// Define the Activity structure to hold user activity data
struct Activity {
    int userId;
    std::string timestamp;
    std::string eventType;
    std::string locationData;
    std::string deviceType;
    int sessionDuration;
};

class ActivityMonitor {
public:
    void addActivity(const Activity& activity);
    std::vector<Activity> getActivitiesByUserId(int userId);
    std::vector<Activity> getActivitiesByEventType(const std::string& eventType);
    std::vector<Activity> getActivitiesByLocation(const std::string& location);

private:
    mutable std::mutex mutex_;
    std::queue<Activity> activityQueue_;
    std::condition_variable cv_;
};

void ActivityMonitor::addActivity(const Activity& activity) {
    std::lock_guard<std::mutex> lock(mutex_);
    activityQueue_.push(activity);
    cv_.notify_one();
}

std::vector<Activity> ActivityMonitor::getActivitiesByUserId(int userId) {
    std::unique_lock<std::mutex> lock(mutex_);
    cv_.wait(lock, [this, userId]() { return !activityQueue_.empty(); });

    std::vector<Activity> activities;
    for (const auto& activity : activityQueue_) {
        if (activity.userId == userId) {
            activities.push_back(activity);
        }
    }
    return activities;
}

std::vector<Activity> ActivityMonitor::getActivitiesByEventType(const std::string& eventType) {
    std::unique_lock<std::mutex> lock(mutex_);
    cv_.wait(lock, [this, &eventType]() { return !activityQueue_.empty(); });

    std::vector<Activity> activities;
    for (const auto& activity : activityQueue_) {
        if (activity.eventType == eventType) {
            activities.push_back(activity);
        }
    }
    return activities;
}

std::vector<Activity> ActivityMonitor::getActivitiesByLocation(const std::string& location) {
    std::unique_lock<std::mutex> lock(mutex_);
    cv_.wait(lock, [this, &location]() { return !activityQueue_.empty(); });

    std::vector<Activity> activities;
    for (const auto& activity : activityQueue_) {
        if (activity.locationData == location) {
            activities.push_back(activity);
        }
    }
    return activities;
}

int main() {
    ActivityMonitor monitor;

    // Example usage
    Activity activity1 = {1, "2023-10-01T12:00:00Z", "login", "New York", "Desktop", 60};
    Activity activity2 = {2, "2023-10-01T12:30:00Z", "logout", "Los Angeles", "Mobile", 45};

    monitor.addActivity(activity1);
    monitor.addActivity(activity2);

    std::vector<Activity> userActivities = monitor.getActivitiesByUserId(1);
    for (const auto& activity : userActivities) {
        std::cout << "User ID: " << activity.userId << ", Event Type: " << activity.eventType << ", Location: " << activity.locationData << std::endl;
    }

    return 0;
}
