#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define DeviceStatusReport structure
typedef struct {
    int device_id;
    char *status;
} DeviceStatusReport;

// Define a dynamic array to store DeviceStatusReports
typedef struct {
    DeviceStatusReport **reports;
    size_t size;
    size_t capacity;
} DeviceCollection;

// Initialize the DeviceCollection
void init_device_collection(DeviceCollection *collection) {
    collection->reports = NULL;
    collection->size = 0;
    collection->capacity = 0;
}

// Add a new device report to the collection
void add_device_report(DeviceCollection *collection, DeviceStatusReport *report) {
    if (collection->size == collection->capacity) {
        size_t new_capacity = (collection->capacity == 0) ? 1 : collection->capacity * 2;
        collection->reports = realloc(collection->reports, new_capacity * sizeof(DeviceStatusReport *));
        collection->capacity = new_capacity;
    }
    collection->reports[collection->size++] = report;
}

// Update an existing device report in the collection
void update_device_report(DeviceCollection *collection, int device_id, char *new_status) {
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->reports[i]->device_id == device_id) {
            free(collection->reports[i]->status);
            collection->reports[i]->status = strdup(new_status);
            return;
        }
    }
}

// Retrieve a device report by device ID
DeviceStatusReport *get_device_report(DeviceCollection *collection, int device_id) {
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->reports[i]->device_id == device_id) {
            return collection->reports[i];
        }
    }
    return NULL;
}

// Free the memory allocated for the DeviceCollection
void free_device_collection(DeviceCollection *collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->reports[i]->status);
        free(collection->reports[i]);
    }
    free(collection->reports);
}

// Example usage of the library
int main() {
    DeviceCollection device_collection;
    init_device_collection(&device_collection);

    // Simulate adding and updating device reports
    add_device_report(&device_collection, (DeviceStatusReport *)malloc(sizeof(DeviceStatusReport)));
    update_device_report(&device_collection, 1, "Online");

    // Retrieve and print the device report
    DeviceStatusReport *report = get_device_report(&device_collection, 1);
    if (report) {
        printf("Device ID: %d, Status: %s\n", report->device_id, report->status);
    }

    free_device_collection(&device_collection);
    return 0;
}
