// TransactionLog class definition
class TransactionLog {
public:
    int transactionID;
    int userID;
    std::string timestamp;
    double amount;
    std::vector<std::string> entities;

    // Constructor and other methods
};

// TransactionManager class definition
class TransactionManager {
private:
    std::unordered_map<int, TransactionLog*> logs;
    mutable std::mutex mutex;
    std::condition_variable cv;

public:
    // Add a new transaction log
    void addLog(std::unique_ptr<TransactionLog> log) {
        std::lock_guard<std::mutex> lock(mutex);
        logs[log->transactionID] = log.release();
        cv.notify_one();
    }

    // Retrieve a transaction log by ID
    std::shared_ptr<const TransactionLog> getLog(int id) const {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this, id] { return logs.find(id) != logs.end(); });
        auto it = logs.find(id);
        if (it != logs.end()) {
            return std::shared_ptr<const TransactionLog>(it->second);
        }
        return nullptr;
    }

    // Update an existing transaction log
    void updateLog(int id, const TransactionLog& newLog) {
        std::lock_guard<std::mutex> lock(mutex);
        if (logs.find(id) != logs.end()) {
            TransactionLog* oldLog = logs[id];
            *oldLog = newLog;
        }
    }

    // Delete a transaction log
    void deleteLog(int id) {
        std::lock_guard<std::mutex> lock(mutex);
        if (logs.find(id) != logs.end()) {
            delete logs[id];
            logs.erase(id);
        }
    }
};

