#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <vector>
#include <fstream>
#include <sstream>
#include <regex>

// Define a generic interface for data sources
class DataSource {
public:
    virtual ~DataSource() {}
    virtual std::string fetchNextBatch() = 0;
};

// Implement an example data source that reads from a file
class FileDataSource : public DataSource {
public:
    FileDataSource(const std::string& filePath) : filePath(filePath), fileStream(filePath, std::ios::in | std::ios::binary) {}

    std::string fetchNextBatch() override {
        if (!fileStream.is_open()) return "";
        std::string batch;
        std::getline(fileStream, batch);
        return batch;
    }

private:
    std::string filePath;
    std::ifstream fileStream;
};

// Define a generic interface for data processors
class DataProcessor {
public:
    virtual ~DataProcessor() {}
    virtual void processBatch(const std::string& batch) = 0;
};

// Implement an example processor that filters lines containing a specific keyword
class KeywordFilter : public DataProcessor {
public:
    KeywordFilter(const std::string& keyword) : keyword(keyword) {}

    void processBatch(const std::string& batch) override {
        if (batch.find(keyword) != std::string::npos) {
            // Process the batch
            std::cout << "Processed: " << batch << std::endl;
        }
    }

private:
    std::string keyword;
};

// Main command-line tool implementation
class DataProcessingTool {
public:
    DataProcessingTool(const std::vector<std::shared_ptr<DataSource>>& sources, const std::vector<std::shared_ptr<DataProcessor>>& processors)
        : dataSources(sources), processors(processors), stop(false) {}

    void start() {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] { workerThread(i); });
        }
    }

    void stopProcessing() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        cv.notify_all();
        for (std::thread& w : workers) {
            w.join();
        }
    }

private:
    std::vector<std::shared_ptr<DataSource>> dataSources;
    std::vector<std::shared_ptr<DataProcessor>> processors;
    std::vector<std::thread> workers;
    std::queue<std::string> taskQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    bool stop;

    void workerThread(size_t threadId) {
        while (true) {
            std::string batch;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                cv.wait(lock, [this] { return !taskQueue.empty() || stop; });
                if (stop && taskQueue.empty()) break;
                batch = taskQueue.front();
                taskQueue.pop();
            }

            for (const auto& processor : processors) {
                processor->processBatch(batch);
            }
        }
    }
};

int main(int argc, char* argv[]) {
    // Example usage
    std::vector<std::shared_ptr<DataSource>> sources;
    sources.emplace_back(std::make_shared<FileDataSource>("data.txt"));
    std::vector<std::shared_ptr<DataProcessor>> processors;
    processors.emplace_back(std::make_shared<KeywordFilter>("important"));

    DataProcessingTool tool(sources, processors);
    tool.start();

    // Simulate data arrival
    for (int i = 0; i < 10; ++i) {
        std::string batch = "Data line " + std::to_string(i);
        {
            std::unique_lock<std::mutex> lock(tool.queueMutex);
            tool.taskQueue.push(batch);
        }
        cv.notify_one();
    }

    // Stop processing after some time
    std::this_thread::sleep_for(std::chrono::seconds(5));
    tool.stopProcessing();

    return 0;
}
