class FileProcessor {
public:
    FileProcessor(int maxThreads, const std::string& metadataServiceUrl) 
        : maxThreads(maxThreads), metadataServiceUrl(metadataServiceUrl), stop(false) {}

    void start() {
        for (int i = 0; i < maxThreads; ++i) {
            workers.emplace_back(&FileProcessor::workerThread, this);
        }
    }

    void stopProcessing() {
        std::unique_lock<std::mutex> lock(queueMutex);
        stop = true;
        condition.notify_all();
    }

    void addFileForProcessing(const std::string& filePath) {
        std::lock_guard<std::mutex> lock(queueMutex);
        fileQueue.push(filePath);
        condition.notify_one();
    }

private:
    int maxThreads;
    std::string metadataServiceUrl;
    bool stop;
    std::queue<std::string> fileQueue;
    std::vector<std::thread> workers;
    std::mutex queueMutex;
    std::condition_variable condition;

    void workerThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            condition.wait(lock, [this] { return !fileQueue.empty() || stop; });
            if (stop && fileQueue.empty()) break;

            std::string filePath = fileQueue.front();
            fileQueue.pop();
            lock.unlock();

            processFile(filePath);
        }
    }

    void processFile(const std::string& filePath) {
        // Implement file processing logic here
    }
};

int main() {
    FileProcessor processor(10, "https://metadata.service.com");
    processor.start();

    // Add files to be processed
    processor.addFileForProcessing("/path/to/file1.txt");
    processor.addFileForProcessing("/path/to/file2.txt");

    // Stop processing when done
