#include <iostream>
#include <string>
#include <fstream>
#include <regex>

void modifyFileExtension(const std::string& filename, int numDigits, const std::string& fileType) {
    std::string baseName;
    size_t dotPos = filename.find_last_of('.');
    if (dotPos != std::string::npos) {
        baseName = filename.substr(0, dotPos);
    } else {
        baseName = filename;
    }

    std::regex digitPattern("\\d+");
    std::smatch match;
    if (std::regex_search(baseName, match, digitPattern)) {
        // Remove existing digits
        size_t firstDigitPos = match.position();
        baseName.erase(firstDigitPos);
    }

    // Append the new digits and file type
    baseName += std::to_string(numDigits) + fileType;

    // Rename the file
    std::string newFilename = filename.substr(0, dotPos) + baseName;
    if (std::rename(filename.c_str(), newFilename.c_str()) != 0) {
        std::cerr << "Failed to rename file: " << filename << " to " << newFilename << std::endl;
    }
}

int main() {
    modifyFileExtension("sensor_data.csv", 3, "_v2");
    return 0;
}
