['```rust
use std::path::Path;
use tokio::fs::File;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::time::{Instant, Duration};

async fn compile_project(path: &Path) -> Result<i32, std::io::Error> {
    let output = tokio::process::Command::new("cargo")
        .arg("build")
        .current_dir(path)
        .output()
        .await?;

    if !output.status.success() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::Other,
            "Compilation failed",
        ));
    }

    Ok(output.status.code().unwrap_or(0))
}

async fn profile_project(path: &Path) -> Result<(), std::io::Error> {
    // Assume a profiling tool is available that can be invoked
    tokio::process::Command::new("cargo")
        .arg("profiler")
        .current_dir(path)
        .output()
        .await?;

    Ok(())
}

async fn log_build_details(project_path: &Path, build_duration: Duration) -> Result<(), std::io::Error> {
    let mut file = File::create("build_log.txt").await?;
    file.write_all(format!("Project Path: {}\nBuild Duration: {:?}", project_path.display(), build_duration).as_bytes()).await?;

    Ok(())
}

async fn compile_and_profile(project_path: &Path) -> Result<i32, std::io::Error> {
    let start_time = Instant::now();

    let compilation_exit_code = compile_project(project_path).await?;
    let build_duration = start_time.elapsed();

    profile_project(project_path).await?;

    log_build_details(project_path, build_duration).await?;

    Ok(compilation_exit_code)
}

#[cfg(test)]
mod tests {
