        // Teardown
        fs::remove_dir_all(project_path).unwrap();

        // Assert
        assert!(result.is_ok());
    }

    #[tokio::test]
    async fn test_compile_and_profile_failure() {
        // Setup
        let project_path = Path::new("path/to/test/project");

        // Mock the compilation to fail
        tokio::process::Command::new("cargo")
            .arg("build")
            .current_dir(project_path)
            .status()
            .unwrap_err();

        // Run the function
        let result = compile_and_profile(project_path).await;

        // Assert
        assert!(result.is_err());
    }
}
