<?php

class User {
    private $id;
    private $name;
    private $email;
    private $password;

    public function __construct($id = null, $name, $email, $password) {
        $this->id = $id;
        $this->name = $name;
        $this->email = $email;
        $this->password = password_hash($password, PASSWORD_DEFAULT);
    }

    // Getters and setters
    public function getId() { return $this->id; }
    public function getName() { return $this->name; }
    public function getEmail() { return $this->email; }
    public function getPassword() { return $this->password; }
}

class UserRepository {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function save(User $user) {
        if ($user->getId()) {
            // Update user
            $stmt = $this->db->prepare("UPDATE users SET name=?, email=?, password=? WHERE id=?");
            return $stmt->execute([$user->getName(), $user->getEmail(), $user->getPassword(), $user->getId()]);
        } else {
            // Create new user
            $stmt = $this->db->prepare("INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
            return $stmt->execute([$user->getName(), $user->getEmail(), $user->getPassword()]);
        }
    }

    public function delete($id) {
        $stmt = $this->db->prepare("DELETE FROM users WHERE id=?");
        return $stmt->execute([$id]);
    }
}

class UserService {
    private $userRepository;

    public function __construct(UserRepository $userRepository) {
        $this->userRepository = $userRepository;
    }

    public function handleRequest($_REQUEST) {
        if (!isset($_REQUEST['name']) || !isset($_REQUEST['email']) || !isset($_REQUEST['password'])) {
            return json_encode(['message' => 'error']);
        }

        $user = new User(isset($_REQUEST['id']) ? $_REQUEST['id'] : null, 
                        $_REQUEST['name'], 
                        $_REQUEST['email'], 
                        $_REQUEST['password']);

        if (isset($_REQUEST['sub_action']) && $_REQUEST['sub_action'] === 'delete') {
            if (!$this->userRepository->delete($user->getId())) {
                return json_encode(['message' => 'error']);
            }
        } else {
            if (!$this->userRepository->save($user)) {
                return json_encode(['message' => 'error']);
            }
        }

        return json_encode(['message' => 'success']);
    }
}

// Usage example
$db = new PDO('mysql:host=localhost;dbname=yourdb', 'username', 'password');
$userRepository = new UserRepository($db);
$userService = new UserService($userRepository);

echo $userService->handleRequest($_REQUEST);
