#include <iostream>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <atomic>
#include <chrono>
#include <memory>

class MessageBroker {
public:
    struct Config {
        int max_messages;
        int max_subscribers;
        int max_routes;
        std::chrono::milliseconds timeout_ms;
        std::chrono::milliseconds reconnect_interval_ms;
    };

    MessageBroker(const Config& config)
        : config_(config),
          running_(true) {}

    ~MessageBroker() {
        stop();
    }

    void start() {
        worker_thread_ = std::thread(&MessageBroker::run, this);
    }

    void stop() {
        running_.store(false);
        if (worker_thread_.joinable()) {
            worker_thread_.join();
        }
    }

    void publish(const std::string& message) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (messages_.size() < config_.max_messages) {
            messages_.push(message);
            condition_.notify_one();
        }
    }

    void subscribe() {
        subscriber_count_.fetch_add(1, std::memory_order_relaxed);
    }

    void unsubscribe() {
        subscriber_count_.fetch_sub(1, std::memory_order_relaxed);
    }

private:
    void run() {
        while (running_.load(std::memory_order_relaxed)) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait_for(lock, config_.timeout_ms, [this] {
                return !messages_.empty() || !running_.load(std::memory_order_relaxed);
            });

            if (!messages_.empty()) {
                auto message = messages_.front();
                messages_.pop();

                // Forward message to subscribers
                for (auto& subscriber : subscribers_) {
                    subscriber->onMessage(message);
                }
            }
        }
    }

    Config config_;
    std::queue<std::string> messages_;
    std::vector<std::shared_ptr<Subscriber>> subscribers_;
    std::mutex mutex_;
    std::condition_variable condition_;
    std::thread worker_thread_;
    std::atomic<bool> running_;
    std::atomic<int> subscriber_count_{0};
};

class Subscriber {
public:
    virtual ~Subscriber() = default;
    virtual void onMessage(const std::string& message) = 0;
};

int main() {
    MessageBroker::Config config = {
        .max_messages = 1000,
        .max_subscribers = 500,
        .max_routes = 10,
        .timeout_ms = std::chrono::milliseconds(100),
        .reconnect_interval_ms = std::chrono::milliseconds(200)
    };

    MessageBroker broker(config);
    broker.start();

    // Simulate message publishing
    for (int i = 0; i < 500; ++i) {
        broker.publish("Message " + std::to_string(i));
    }

    // Simulate subscriber registration
    for (int i = 0; i < 100; ++i) {
        auto subscriber = std::make_shared<Subscriber>();
        broker.subscribe();
    }

    std::this_thread::sleep_for(std::chrono::seconds(5));

    broker.stop();

    return 0;
}
```']

