    RSA_SHA1_SIGNATURE,
    RSA_SHA256_SIGNATURE
} SignatureType;

EVP_CIPHER *get_cipher(CipherType type) {
    switch (type) {
        case AES_CIPHER:
            return EVP_aes_256_cbc();
        case CAMELLIA_CIPHER:
            return EVP_camellia_256_cbc();
        case CHACHA20_CIPHER:
            return EVP_chacha20_poly1305();
        default:
            return NULL;
    }
}

EVP_MD *get_digest(DigestType type) {
    switch (type) {
        case MD5_DIGEST:
            return EVP_md5();
        case SHA1_DIGEST:
            return EVP_sha1();
        case SHA256_DIGEST:
            return EVP_sha256();
        case SHA3_DIGEST:
            return EVP_sha3_256();
        default:
            return NULL;
    }
}

