// Define the data structure for sensor readings
struct SensorData {
    std::string nodeId;
    double temperature;
    double humidity;
    double pressure;
};

// Message queueing system for prioritizing critical data streams
class MessageQueue {
private:
    std::priority_queue<SensorData> queue;
    mutable std::mutex mutex;
    std::condition_variable cond;

public:
    void push(const SensorData& data) {
        std::lock_guard<std::mutex> lock(mutex);
        queue.push(data);
        cond.notify_one();
    }

    SensorData pop() {
        std::unique_lock<std::mutex> lock(mutex);
        cond.wait(lock, [this] { return !queue.empty(); });
        SensorData data = queue.top();
        queue.pop();
        return data;
    }
};

// Fault-tolerant sensor node manager
