#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Define the resource processor structure
typedef struct {
    char *resource_path;
    int version;
    sem_t lock;
} ResourceProcessor;

// Initialize a resource processor instance
ResourceProcessor* init_resource_processor(const char *path, int version) {
    ResourceProcessor *processor = (ResourceProcessor*)malloc(sizeof(ResourceProcessor));
    if (!processor) return NULL;
    processor->resource_path = strdup(path);
    processor->version = version;
    sem_init(&processor->lock, 0, 1);
    return processor;
}

// Load a resource bundle asynchronously
void load_resource_async(ResourceProcessor *processor, void (*callback)(ResourceProcessor*)) {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, load_resource_thread, processor) != 0) {
        perror("Failed to create thread");
        return;
    }
    pthread_detach(thread_id);
}

// Thread function for loading resources asynchronously
void* load_resource_thread(void *arg) {
    ResourceProcessor *processor = (ResourceProcessor*)arg;
    sem_wait(&processor->lock);
    // Simulate resource loading and processing
    printf("Loading resource from %s version %d\n", processor->resource_path, processor->version);
    sleep(2);  // Simulate I/O operation delay
    sem_post(&processor->lock);
    callback(processor);
    return NULL;
}

// Callback function to handle the loaded resource
void handle_loaded_resource(ResourceProcessor *processor) {
    printf("Resource loaded successfully: %s version %d\n", processor->resource_path, processor->version);
}

int main() {
    ResourceProcessor *processor = init_resource_processor("/path/to/resource", 1);
    if (!processor) {
        fprintf(stderr, "Failed to initialize resource processor\n");
        return EXIT_FAILURE;
    }
    load_resource_async(processor, handle_loaded_resource);
    free(processor->resource_path);
    free(processor);
    return EXIT_SUCCESS;
}
```

This code provides a basic implementation of the `ResourceProcessor` library with asynchronous resource loading and a callback-based reduction operation. The `init_resource_processor` function initializes a new resource processor instance, `load_resource_async` loads a resource asynchronously, and `handle_loaded_resource` is a callback function to handle the loaded resource. The actual resource loading logic is simulated with a sleep for demonstration purposes.']

