#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <queue>
#include <atomic>
#include <functional>

template<typename T>
class ThreadSafeQueue {
private:
    std::queue<T> queue_;
    mutable std::mutex mutex_;
    std::condition_variable cond_;

public:
    void push(T value) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(value);
        cond_.notify_one();
    }

    T wait_and_pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        cond_.wait(lock, [this]{ return !queue_.empty(); });
        T value = queue_.front();
        queue_.pop();
        return value;
    }

    bool try_pop(T& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (queue_.empty()) {
            return false;
        }
        value = queue_.front();
        queue_.pop();
        return true;
    }

    size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.size();
    }
};

class ActivityReport {
public:
    int userId;
    std::chrono::time_point<std::chrono::system_clock> timestamp;
    std::string eventType;
    double locationData;
    std::string deviceType;
    int sessionDuration;

    // Constructor, getters and setters
};

class ActivityProcessor {
private:
    ThreadSafeQueue<ActivityReport> queue_;
    std::vector<std::thread> workers_;
    std::atomic<bool> stop_{false};

public:
    ActivityProcessor(size_t numThreads) : stop_(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers_.emplace_back([this]() { worker(); });
        }
    }

    ~ActivityProcessor() {
        stop_ = true;
        for (auto& worker : workers_) {
            worker.join();
        }
    }

    void enqueue(const ActivityReport& report) {
        queue_.push(report);
    }

private:
    void worker() {
        while (!stop_) {
            if (queue_.try_pop(activity)) {
                processActivity(activity);
            } else {
                std::this_thread::yield();
            }
        }
    }

    void processActivity(const ActivityReport& report) {
        // Process activity logic here
    }

    ActivityReport activity;
};

int main() {
    ActivityProcessor processor(4);

    // Simulate enqueuing activity reports
    for (int i = 0; i < 100; ++i) {
        ActivityReport report;
        report.userId = i;
        report.timestamp = std::chrono::system_clock::now();
        report.eventType = "login";
        report.locationData = 37.4222;
        report.deviceType = "Mobile";
        report.sessionDuration = 120;

        processor.enqueue(report);
    }

    return 0;
}
```

