        "amount": amount,
        "payment_method_nonce": nonce_from_the_client,
        "options": {
            "submit_for_settlement": True
        }
    })

    if result.is_success:
        return result.transaction.id
    else:
        print(result.message)
        return None

# Routes
@app.route('/charge', methods=['POST'])
def charge():
    amount = request.form['amount']
    gateway = request.form['gateway']

    if gateway == 'stripe':
        transaction_id = stripe_charge(amount)
    elif gateway == 'paypal':
        transaction_id = paypal_charge(amount)
    elif gateway == 'braintree':
        transaction_id = braintree_charge(amount)
    else:
        return jsonify({'error': 'Invalid payment gateway'}), 400

    if transaction_id:
        transaction = Transaction(amount=amount, gateway=gateway, status='success')
        db.session.add(transaction)
        db.session.commit()
        return jsonify({'transaction_id': transaction_id}), 200
    else:
        transaction = Transaction(amount=amount, gateway=gateway, status='failed')
        db.session.add(transaction)
        db.session.commit()
        return jsonify({'error': 'Transaction failed'}), 500

if __name__ == '__main__':
    app.run(debug=True)
