package main

import (
    "crypto/aes"
    "crypto/cipher"
    "crypto/rand"
    "crypto/subtle"
    "encoding/base64"
    "errors"
    "fmt"
    "golang.org/x/crypto/pbkdf2"
)

const (
    keySize = 32
    saltSize = 16
    ivSize = 12
    tagSize = 16
    pbkdf2Iterations = 100000
)

type EncryptionService struct {
    // Store cipher contexts for reuse
    cipherContexts map[string]cipher.AEAD
}

func NewEncryptionService() *EncryptionService {
    return &EncryptionService{
        cipherContexts: make(map[string]cipher.AEAD),
    }
}

func (es *EncryptionService) deriveKey(password string, salt []byte) ([]byte, error) {
    key := pbkdf2.Key([]byte(password), salt, pbkdf2Iterations, keySize)
    return key, nil
}

func (es *EncryptionService) generateIV() ([]byte, error) {
    iv := make([]byte, ivSize)
    _, err := rand.Read(iv)
    if err != nil {
        return nil, err
    }
    return iv, nil
}

func (es *EncryptionService) createCipherContext(password string, salt []byte) (cipher.AEAD, error) {
    key, err := es.deriveKey(password, salt)
    if err != nil {
        return nil, err
    }

    aesBlock, err := aes.NewCipher(key)
    if err != nil {
        return nil, err
    }

    gcm, err := cipher.NewGCM(aesBlock)
    if err != nil {
        return nil, err
    }

    return gcm, nil
}

func (es *EncryptionService) encrypt(data []byte, password string, salt []byte) ([]byte, error) {
    ctxKey := fmt.Sprintf("%s:%x", password, salt)
    var ctx cipher.AEAD

    if _, exists := es.cipherContexts[ctxKey]; !exists {
        ctx, err = es.createCipherContext(password, salt)
        if err != nil {
            return nil, err
        }
        es.cipherContexts[ctxKey] = ctx
    } else {
        ctx = es.cipherContexts[ctxKey]
    }

    iv, err := es.generateIV()
    if err != nil {
        return nil, err
    }

    ciphertext := ctx.Seal(nil, iv, data, nil)
    combined := append(iv, ciphertext...)
    encoded := base64.StdEncoding.EncodeToString(combined)

    return []byte(encoded), nil
}

func (es *EncryptionService) decrypt(ciphertext []byte, password string, salt []byte) ([]byte, error) {
    ctxKey := fmt.Sprintf("%s:%x", password, salt)
    var ctx cipher.AEAD

    if _, exists := es.cipherContexts[ctxKey]; !exists {
        ctx, err := es.createCipherContext(password, salt)
        if err != nil {
            return nil, err
        }
        es.cipherContexts[ctxKey] = ctx
    } else {
        ctx = es.cipherContexts[ctxKey]
    }

    decoded, err := base64.StdEncoding.DecodeString(string(ciphertext))
    if err != nil {
        return nil, err
    }

    iv := decoded[:ivSize]
    encryptedData := decoded[ivSize:]

    plaintext, ok := ctx.Open(nil, iv, encryptedData, nil)
    if !ok {
        return nil, errors.New("decryption failed")
    }

    return plaintext, nil
}

func main() {
    // Example usage
    es := NewEncryptionService()
    password := "securepassword"
    salt := []byte("randomsalt")

    originalData := []byte("Hello, secure world!")
    encryptedData, err := es.encrypt(originalData, password, salt)
    if err != nil {
        fmt.Println("Error encrypting:", err)
        return
    }

    decryptedData, err := es.decrypt(encryptedData, password, salt)
    if err != nil {
        fmt.Println("Error decrypting:", err)
        return
    }

    fmt.Println("Original Data:", string(originalData))
    fmt.Println("Decrypted Data:", string(decryptedData))
}
```

This code provides a basic implementation of an encryption service using AES-256-GCM with PBKDF2-based key derivation. It includes functions for encrypting and decrypting data, managing cipher contexts securely, and handling errors. The `main` function demonstrates how to use the service with an example.']

