#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct DeviceStatusReport {
    int device_id;
    char *status;
} DeviceStatusReport;

typedef struct DeviceManager {
    pthread_mutex_t mutex;
    DeviceStatusReport **reports;
    size_t count;
    size_t capacity;
} DeviceManager;

DeviceManager* create_device_manager() {
    DeviceManager *manager = malloc(sizeof(DeviceManager));
    manager->mutex = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    manager->reports = NULL;
    manager->count = 0;
    manager->capacity = 0;
    return manager;
}

void destroy_device_manager(DeviceManager *manager) {
    for (size_t i = 0; i < manager->count; i++) {
        free(manager->reports[i]->status);
        free(manager->reports[i]);
    }
    free(manager->reports);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_device_report(DeviceManager *manager, DeviceStatusReport *report) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        DeviceStatusReport **new_reports = realloc(manager->reports, new_capacity * sizeof(DeviceStatusReport *));
        if (!new_reports) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Memory allocation failed
        }
        manager->reports = new_reports;
        manager->capacity = new_capacity;
    }
    manager->reports[manager->count++] = report;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

DeviceStatusReport* get_device_report(DeviceManager *manager, int device_id) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->reports[i]->device_id == device_id) {
            DeviceStatusReport *report = malloc(sizeof(DeviceStatusReport));
            memcpy(report, manager->reports[i], sizeof(DeviceStatusReport));
            pthread_mutex_unlock(&manager->mutex);
            return report;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return NULL; // Report not found
}

void update_device_report(DeviceManager *manager, int device_id, const char *new_status) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->reports[i]->device_id == device_id) {
            free(manager->reports[i]->status);
            manager->reports[i]->status = strdup(new_status);
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}
