    public class ComponentController : ControllerBase
    {
        private readonly HttpClient _httpClient;
        private readonly IDistributedCache _cache;
        private readonly AsyncRetryPolicy _retryPolicy;

        public ComponentController(HttpClient httpClient, IDistributedCache cache)
        {
            _httpClient = httpClient;
            _cache = cache;
            _retryPolicy = Policy.Handle<HttpRequestException>()
                .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));
        }

        [HttpPost]
        public async Task<IActionResult> UpdateComponents([FromBody] List<ComponentUpdate> updates)
        {
            var tasks = new List<Task<bool>>();

            foreach (var update in updates)
            {
                tasks.Add(ProcessComponentUpdate(update));
            }

            await Task.WhenAll(tasks);

            return Ok(new { UpdatedCount = tasks.Count(t => t.Result) });
        }

        private async Task<bool> ProcessComponentUpdate(ComponentUpdate update)
        {
            var cachedData = await _cache.GetStringAsync($"component:{update.ComponentId}");
            if (cachedData != null)
            {
                update.Config = JsonConvert.DeserializeObject<ComponentConfig>(cachedData);
            }
            else
