                    if (response.IsSuccessStatusCode)
                    {
                        update.Config = JsonConvert.DeserializeObject<ComponentConfig>(await response.Content.ReadAsStringAsync());
                        await _cache.SetStringAsync($"component:{update.ComponentId}", JsonConvert.SerializeObject(update.Config), new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10) });
