#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

#define MAX_FILES 1024
#define THREAD_POOL_SIZE 16

typedef struct {
    char *filename;
    size_t line_count;
} FileStats;

FileStats file_stats[MAX_FILES];
int file_count = 0;

pthread_mutex_t stats_lock = PTHREAD_MUTEX_INITIALIZER;

void* process_file(void* arg) {
    int fd = *(int*)arg;
    off_t file_size;
    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("Failed to get file size");
        return NULL;
    }
    file_size = st.st_size;

    char *file_data = mmap(NULL, file_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (file_data == MAP_FAILED) {
        perror("Failed to memory-map the file");
        close(fd);
        return NULL;
    }

    size_t line_count = 1; // Start with one for the first line
    for (off_t i = 0; i < file_size; ++i) {
        if (file_data[i] == '\n') {
            line_count++;
        }
    }

    pthread_mutex_lock(&stats_lock);
    file_stats[file_count].filename = strdup(file_data); // Assuming filename is small
    file_stats[file_count++].line_count = line_count;
    pthread_mutex_unlock(&stats_lock);

    munmap(file_data, file_size);
    close(fd);
    return NULL;
}

int main(int argc, char *argv[]) {
    DIR *dir;
    struct dirent *ent;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        return 1;
    }

    dir = opendir(argv[1]);
    if (!dir) {
        perror("Failed to open directory");
        return 1;
    }

    pthread_t threads[THREAD_POOL_SIZE];
    int thread_indices[THREAD_POOL_SIZE];

    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;

        char path[1024];
        snprintf(path, sizeof(path), "%s/%s", argv[1], ent->d_name);

        int fd = open(path, O_RDONLY);
        if (fd == -1) {
            perror("Failed to open file");
            continue;
        }

        for (int i = 0; i < THREAD_POOL_SIZE; ++i) {
            if (threads[i] == 0) {
                thread_indices[i] = fd;
                pthread_create(&threads[i], NULL, process_file, &thread_indices[i]);
                break;
            }
        }

        if (pthread_equal(threads[THREAD_POOL_SIZE - 1], pthread_self())) {
            for (int i = 0; i < THREAD_POOL_SIZE; ++i) {
                pthread_join(threads[i], NULL);
                threads[i] = 0;
            }
        }
    }

    closedir(dir);

    // Collect results and report
    size_t total_lines = 0;
    int max_lines_index = -1;
    for (int i = 0; i < file_count; ++i) {
        total_lines += file_stats[i].line_count;
        if (max_lines_index == -1 || file_stats[i].line_count > file_stats[max_lines_index].line_count) {
            max_lines_index = i;
        }
    }

    printf("Total lines: %zu\n", total_lines);
    if (max_lines_index != -1) {
        printf("File with most lines: %s (%zu)\n", file_stats[max_lines_index].filename, file_stats[max_lines_index].line_count);
    }

    // Cleanup
    for (int i = 0; i < file_count; ++i) {
        free(file_stats[i].filename);
    }

    return 0;
}
