    std::vector<NFAPI_CRC_INDICATION_PDU_T> indications(num_ues);
    static std::random_device rd;
    static std::mt19937 gen(rd());
    static std::bernoulli_distribution dis(0.5); // 50% chance of CRC flag being set

    for (int i = 0; i < num_ues; ++i) {
        indications[i].RX_UE_INFORMATION_TAG.value = /* Initialize */;
        indications[i].RNTI.value = /* Initialize */;
        indications[i].CRC_INDICATION_REL8_TAG.CRCFLAG = dis(gen);
        // Populate other fields as needed
    }

    *crc_indications = indications.data();
