# Define encryption classes for AES, Camellia, DES, RSA
class Encryptor:
    def __init__(self, algorithm):
        self.algorithm = algorithm
        self.backend = default_backend()

    def encrypt(self, data, key, iv=None):
        if iv is None:
            iv = os.urandom(algorithm.block_size)
        cipher = Cipher(self.algorithm(key), modes.CFB(iv), backend=self.backend)
        encryptor = cipher.encryptor()
        return iv + encryptor.update(data) + encryptor.finalize()

    def decrypt(self, data, key):
        iv = data[:algorithm.block_size]
        cipher = Cipher(self.algorithm(key), modes.CFB(iv), backend=self.backend)
        decryptor = cipher.decryptor()
        return decryptor.update(data[algorithm.block_size:]) + decryptor.finalize()

