int pdu_count = 0;

void generate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&pdu_pool_mutex);
    if (pdu_count >= MAX_PDUS) {
        fprintf(stderr, "Error: PDU pool is full.\n");
        pthread_mutex_unlock(&pdu_pool_mutex);
        return;
    }
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    pdu_pool[pdu_count++] = *pdu;
    pthread_mutex_unlock(&pdu_pool_mutex);
}

void process_pdus(int num_pdus) {
