#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_INFO 1000
#define MAX_PDUS 1000

typedef struct {
    int rx_ue_information_tag;
    int rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    // Define fields for CRC_INDICATION_REL8_TAG as needed
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} PduPool;

void initPduPool(PduPool *pool, size_t initialCapacity) {
    pool->capacity = initialCapacity;
    pool->count = 0;
    pool->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pdus) {
        fprintf(stderr, "Failed to allocate memory for PDU pool\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&pool->mutex, NULL);
}

void freePduPool(PduPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    free(pool->pdus);
    pool->pdus = NULL;
    pthread_mutex_unlock(&pool->mutex);
    pthread_mutex_destroy(&pool->mutex);
}

int populatePduIndications(PduPool *pool, RX_UE_INFORMATION_TAG *ueInfoList, size_t ueCount) {
    if (!pool || !ueInfoList || ueCount > MAX_PDUS) {
        fprintf(stderr, "Invalid input\n");
        return -1;
    }

    pthread_mutex_lock(&pool->mutex);
    if (pool->count + ueCount > pool->capacity) {
        size_t newCapacity = pool->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newPdus = (NFAPI_CRC_INDICATION_PDU_T *)realloc(pool->pdus, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newPdus) {
            fprintf(stderr, "Failed to allocate memory for PDU pool expansion\n");
            pthread_mutex_unlock(&pool->mutex);
            return -1;
        }
        pool->pdus = newPdus;
        pool->capacity = newCapacity;
    }

    // Simulate retrieval of RNTI and random CRCFLAG
    srand(time(NULL));
    for (size_t i = 0; i < ueCount; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pool->pdus[pool->count + i];
        pdu->rx_ue_info = ueInfoList[i];
        pdu->rnti = rand() % 1024;
        // Set random CRCFLAG
        pdu->crc_ind_rel8.crcflag = (rand() % 2) ? 1 : 0;
    }

    pool->count += ueCount;
    pthread_mutex_unlock(&pool->mutex);
    return 0;
}

// Example usage
int main() {
    RX_UE_INFORMATION_TAG ueInfo[MAX_UE_INFO];
    // Populate ueInfo with actual data

    PduPool pduPool;
    initPduPool(&pduPool, MAX_PDUS);

    if (populatePduIndications(&pduPool, ueInfo, MAX_UE_INFO) == 0) {
        printf("PDUs populated successfully\n");
    }

    freePduPool(&pduPool);
    return 0;
}
