#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <memory>
#include <chrono>
#include <thread>
#include <fstream>

struct LTE_TRANSPORT_CONTEXT {
    int CELL_ID;
    int PCI;
    std::vector<int> TX_POWER_LEVELS;
    std::string RF_BAND_CONFIG;
};

class LTEContextManager {
public:
    LTEContextManager(size_t initialSize = 1024) : contexts(initialSize), contextCount(0), bufferSize(initialSize) {}

    void addContext(const LTE_TRANSPORT_CONTEXT& ctx) {
        std::lock_guard<std::mutex> lock(mutex);
        if (contextCount >= bufferSize) {
            resizeBuffer();
        }
        contexts[contextCount++] = ctx;
        notifyWaiters();
    }

    void removeContext(int cellId) {
        std::lock_guard<std::mutex> lock(mutex);
        for (size_t i = 0; i < contextCount; ++i) {
            if (contexts[i].CELL_ID == cellId) {
                contexts.erase(contexts.begin() + i);
                --contextCount;
                notifyWaiters();
                return;
            }
        }
    }

    void updateContext(int cellId, const LTE_TRANSPORT_CONTEXT& newCtx) {
        std::lock_guard<std::mutex> lock(mutex);
        for (size_t i = 0; i < contextCount; ++i) {
            if (contexts[i].CELL_ID == cellId) {
                contexts[i] = newCtx;
                notifyWaiters();
                return;
            }
        }
    }

    std::optional<LTE_TRANSPORT_CONTEXT> getContext(int cellId) const {
        std::lock_guard<std::mutex> lock(mutex);
        for (const auto& ctx : contexts) {
            if (ctx.CELL_ID == cellId) {
                return ctx;
            }
        }
        return std::nullopt;
    }

private:
    void resizeBuffer() {
        size_t newSize = bufferSize * 2;
        contexts.resize(newSize);
        bufferSize = newSize;
    }

    void notifyWaiters() {
        condition.notify_one();
    }

    mutable std::mutex mutex;
    std::condition_variable condition;
    std::vector<LTE_TRANSPORT_CONTEXT> contexts;
    size_t contextCount;
    size_t bufferSize;
};

class RFConfigUpdater {
public:
    RFConfigUpdater(LTEContextManager& manager, const std::string& dataSource)
        : manager(manager), dataSource(dataSource) {}

    void updateConfigs() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::minutes(10));
            loadRFConfigurations();
        }
    }

private:
    void loadRFConfigurations() {
        // Simulate external data source read
        std::ifstream file(dataSource);
        if (!file.is_open()) {
            std::cerr << "Failed to open data source" << std::endl;
            return;
        }

        LTE_TRANSPORT_CONTEXT ctx;
        while (file >> ctx.CELL_ID >> ctx.PCI >> ctx.RF_BAND_CONFIG) {
            manager.updateContext(ctx.CELL_ID, ctx);
        }
    }

    LTEContextManager& manager;
    const std::string dataSource;
};

int main() {
    LTEContextManager manager;
    RFConfigUpdater updater(manager, "rf_configs.txt");

    std::thread updateThread(&RFConfigUpdater::updateConfigs, &updater);

    // Simulate adding and removing contexts
    for (int i = 0; i < 50000; ++i) {
        LTE_TRANSPORT_CONTEXT ctx{i, i * 10, {i, i + 1}, "Band" + std::to_string(i)};
        manager.addContext(ctx);
        if (i % 1000 == 0) {
            manager.removeContext(i - 1000);
        }
    }

    updateThread.join();

    return 0;
}
```

