public class PaymentGatewayAdapter {
    private Map<String, PaymentProcessor> gatewayMap = new HashMap<>();

    public void addGateway(String gatewayName, PaymentProcessor processor) {
        gatewayMap.put(gatewayName, processor);
    }

    public void removeGateway(String gatewayName) {
        gatewayMap.remove(gatewayName);
    }

    public void updateGateway(String gatewayName, PaymentProcessor processor) {
        if (gatewayMap.containsKey(gatewayName)) {
            gatewayMap.replace(gatewayName, processor);
        }
    }

    public void processPayment(String gatewayName, PaymentRequest request) {
        PaymentProcessor processor = gatewayMap.get(gatewayName);
        if (processor != null) {
            processor.process(request);
        } else {
            throw new RuntimeException("Gateway not found: " + gatewayName);
        }
    }
}

interface PaymentProcessor {
    void process(PaymentRequest request);
}

class PaymentRequest {
    private String cardNumber;
    private double amount;

    public PaymentRequest(String cardNumber, double amount) {
        this.cardNumber = cardNumber;
        this.amount = amount;
    }

    // Getters and setters
}
