public class ErrorLoggingFramework {

    private static final String ERROR_LOG_SERVICE_URL = "https://error-log-service.example.com/log";
    private static final int MAX_RETRIES = 3;
    private static final long RETRY_DELAY_MS = 1000;
    private static final int BATCH_SIZE = 50;

    private ExecutorService executorService = Executors.newFixedThreadPool(20);
    private ErrorLogQueue errorLogQueue = new ErrorLogQueue();

    public void logError(ErrorDetails errorDetails) {
        CompletableFuture.runAsync(() -> {
            for (int attempt = 0; attempt <= MAX_RETRIES; attempt++) {
                try {
                    postToExternalService(errorDetails);
                    break;
                } catch (Exception e) {
                    if (attempt == MAX_RETRIES - 1) {
                        handleLoggingFailure(errorDetails, e);
                    }
                    try {
                        TimeUnit.MILLISECONDS.sleep(RETRY_DELAY_MS * (1 << attempt));
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
        }, executorService);
    }

    private void postToExternalService(ErrorDetails errorDetails) throws Exception {
        // Simulate HTTP POST request to external service
