    }

    void updateNode(const Node& node) {
        // Update the distributed key-value store
        kvStore.put(node.id, node.config);
    }

    void logUpdate(const Node& node) {
        // Log update details
        logger.log("Updated node " + std::to_string(node.id));
    }

