public class OrderProcessorService : IOrderProcessorService
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, DateTime> _rateLimitTokens = new();

    public OrderProcessorService()
    {
        _httpClient = new HttpClient();
    }

    public async Task ProcessOrderAsync(Order order)
    {
        try
        {
            var productDetails = await FetchProductDetailsAsync(order.ProductId);
            // Process the order using product details
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw;
        }
    }

    private async Task<Product> FetchProductDetailsAsync(string productId)
    {
        var rateLimitKey = $"user_{Environment.GetEnvironmentVariable("USER_ID")}";
        if (_rateLimitTokens.TryGetValue(rateLimitKey, out var lastRequestTime) && 
            DateTime.Now - lastRequestTime < TimeSpan.FromSeconds(60 / 50))
        {
            throw new Exception("Rate limit exceeded");
        }

        _rateLimitTokens[rateLimitKey] = DateTime.Now;

        var response = await _httpClient.GetAsync($"https://api.example.com/products/{productId}");
        if (response.IsSuccessStatusCode)
        {
            return JsonSerializer.Deserialize<Product>(await response.Content.ReadAsStringAsync());
        }
        else
        {
            throw new Exception("Failed to fetch product details");
        }
    }

    private void LogError(Exception ex)
    {
        // Log the error using an external logging infrastructure
    }
}

public interface IOrderProcessorService
{
    Task ProcessOrderAsync(Order order);
}

public class Order
{
    public string ProductId { get; set; }
}

public class Product
{
    public string Name { get; set; }
    public decimal Price { get; set; }
