const fs = require('fs');
const path = require('path');
const { Queue } = require('async');
const cloudStorage = require('@google-cloud/storage')();
const metadataApi = require('metadata-api');

const storageBucket = 'your-bucket-name';
const scanDirectory = '/path/to/directory';
const concurrencyLimit = 5;

const fileQueue = new Queue(async (file) => {
  try {
    const stats = await fs.promises.stat(file);
    const meta = await metadataApi.extractMetadata(file);

    const validatedMeta = await metadataApi.validateAndCategorize(meta);

    const blob = cloudStorage.bucket(storageBucket).file(path.basename(file));
    await blob.upload(file, { metadata: validatedMeta });

    console.log(`Processed ${file}`);
  } catch (error) {
    console.error(`Failed to process ${file}:`, error);
  }
}, concurrencyLimit);

fs.promises.readdir(scanDirectory)
  .then((files) => files.map((f) => path.join(scanDirectory, f)))
  .then((files) => files.forEach(fileQueue.push.bind(fileQueue)));

setInterval(() => {
  fs.promises.readdir(scanDirectory)
    .then((files) => files.map((f) => path.join(scanDirectory, f)))
    .then((files) => files.forEach(fileQueue.push.bind(fileQueue)));
}, 60000); // Scan every minute

app.get('/health', (req, res) => {
  res.status(200).send('Service is healthy');
});
