class DynamicScriptLoader {
  constructor(config) {
    this.config = config;
    this.scriptCache = {};
    this.locks = new Map();
    this.queue = [];
    this.loadingScripts = new Set();
  }

  async loadScript(scriptId) {
    if (this.loadingScripts.has(scriptId)) return;
    this.loadingScripts.add(scriptId);

    try {
      let script = await this.getScriptMetadata(scriptId);
      if (!script) throw new Error('Script not found');

      await this.executeDependencies(script.dependencies);
      this.executeScript(script);
    } catch (error) {
      console.error(`Failed to load script ${scriptId}:`, error);
    } finally {
      this.loadingScripts.delete(scriptId);
    }
  }

  async getScriptMetadata(scriptId) {
    if (this.scriptCache[scriptId]) return this.scriptCache[scriptId];

    let retryCount = 0;
    const maxRetries = 3;
    while (retryCount < maxRetries) {
      try {
        let response = await fetch(this.config.metadataUrl + scriptId);
        if (!response.ok) throw new Error('Failed to fetch metadata');
        let scriptMetadata = await response.json();
        this.scriptCache[scriptId] = scriptMetadata;
        return scriptMetadata;
      } catch (error) {
        retryCount++;
        console.warn(`Retry fetching metadata for ${scriptId}, attempt ${retryCount}:`, error);
        if (retryCount === maxRetries) throw error;
      }
    }
  }

  async executeDependencies(dependencies) {
    if (!dependencies || dependencies.length === 0) return;

    let dependencyMap = new Map();
    dependencies.forEach(dep => {
      dependencyMap.set(dep.id, dep.priority);
    });

    let executedIds = new Set();
    while (executedIds.size < dependencyMap.size) {
      let highestPriority = -Infinity;
      let selectedDepId = null;

      for (let [depId, priority] of dependencyMap.entries()) {
        if (!executedIds.has(depId) && priority > highestPriority) {
          highestPriority = priority;
          selectedDepId = depId;
        }
      }

      if (selectedDepId === null) break;

      await this.loadScript(selectedDepId);
      executedIds.add(selectedDepId);
    }
  }

  executeScript(script) {
    let scriptElement = document.createElement('script');
    scriptElement.id = script.id;
    scriptElement.text = script.code;
    document.body.appendChild(scriptElement);

    if (this.config.themeCaching) {
      this.recycleThemeBitmap(script.metadata.themeBitmap);
      this.setDefaultThemeDirectory(script.metadata.defaultThemeDir);
      this.parsePngFile(script.metadata.pngFilePath);
    }
  }

  recycleThemeBitmap(bitmap) {
    // Logic to recycle the theme bitmap
    console.log(`Recycling theme bitmap: ${bitmap}`);
  }

  setDefaultThemeDirectory(directory) {
    if (!directory) {
      directory = this.config.defaultThemeDir;
      console.log(`Setting default theme directory to: ${directory}`);
    }
  }

  parsePngFile(filePath) {
    // Logic to parse PNG file and extract metadata
    console.log(`Parsing PNG file at path: ${filePath}`);
  }
}

// Usage example:
const config = {
  metadataUrl: 'https://api.example.com/scripts/',
  themeCaching: true,
  defaultThemeDir: '/default/theme/directory'
};

let loader = new DynamicScriptLoader(config);
loader.loadScript('script1');
