from flask import Flask, request, jsonify
from threading import Lock
import time
import requests
import logging

app = Flask(__name__)
data_cache = {}
cache_lock = Lock()
last_update_time = 0
cache_policy = {
    'max_age': 60,
    'max_entries': 1000
}

# External API Integration
def fetch_stock_data(symbol):
    # Example of fetching data from an external API
    response = requests.get(f'https://api.example.com/stock/{symbol}')
    return response.json()

# Data Cache Management
def update_cache(symbol, data):
    with cache_lock:
        if symbol not in data_cache or time.time() - last_update_time > cache_policy['max_age']:
            data_cache[symbol] = data
            last_update_time = time.time()
            # Remove oldest entries to limit memory usage
            while len(data_cache) > cache_policy['max_entries']:
                oldest_key = min(data_cache, key=data_cache.get)
                del data_cache[oldest_key]

# RESTful API Endpoint for Real-time Data Querying
@app.route('/data', methods=['GET'])
def get_data():
    symbol = request.args.get('symbol')
    if symbol not in data_cache:
        try:
            stock_data = fetch_stock_data(symbol)
            update_cache(symbol, stock_data)
        except requests.RequestException as e:
            logging.error(f"Failed to fetch data for {symbol}: {e}")
