use tokio::net::{TcpListener, TcpStream};
use tower_http::auth::RequireAuthorizationLayer;
use tower_http::services::ServeDir;
use tower_http::trace::{TraceLayer, StandardBody};
use tower_service::ServiceExt;

#[tokio::main]
async fn main() {
    // Initialize the server with authentication and authorization layers
    let listener = TcpListener::bind("127.0.0.1:8080").await.unwrap();
    let app = ServeDir::new("./static")
        .layer(RequireAuthorizationLayer::basic("realm", |user| {
            // Check if the user is authenticated and authorized
            true
        }))
        .layer(TraceLayer::new_for_http());

    println!("Listening on http://127.0.0.1:8080");
    loop {
        let (stream, _) = listener.accept().await.unwrap();
        app.ready().await.expect("Server not ready").call(stream).await;
    }
}
