class DistributedConfigurationManager {
public:
    struct ConfigVersion {
        std::string data;
        int version;
    };

    using ConfigMap = std::unordered_map<std::string, ConfigVersion>;
    using NodeId = std::string;

    void updateConfig(const NodeId& nodeId, const ConfigVersion& config);
    ConfigVersion getConfig(const NodeId& nodeId) const;

private:
    mutable std::mutex mutex_;
    ConfigMap configData_;
    std::condition_variable cv_;
};

// DistributedConfigurationManager.cpp
#include "DistributedConfigurationManager.h"
#include <algorithm>

void DistributedConfigurationManager::updateConfig(const NodeId& nodeId, const ConfigVersion& config) {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = configData_.find(nodeId);
    if (it != configData_.end()) {
        if (it->second.version >= config.version) return;
        it->second = config;
    } else {
        configData_[nodeId] = config;
    }
    cv_.notify_all();
}

DistributedConfigurationManager::ConfigVersion DistributedConfigurationManager::getConfig(const NodeId& nodeId) const {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = configData_.find(nodeId);
    if (it != configData_.end()) {
        return it->second;
    }
    // Handle error or return a default configuration
    throw std::runtime_error("Configuration not found for node: " + nodeId);
}

