using TokenValidationFunction = std::function<bool(const std::string& token)>;

class OAuth2TokenValidationService {
public:
    OAuth2TokenValidationService(std::vector<TokenValidationFunction> validators)
        : validators_(validators) {}

    void addValidator(TokenValidationFunction validator) {
        std::lock_guard<std::mutex> lock(mutex_);
        validators_.push_back(validator);
    }

    bool validateToken(const std::string& token, const std::function<void(bool)>& callback) {
        if (token.empty()) {
            return false;
        }

        std::vector<std::future<bool>> futures;
        for (const auto& validator : validators_) {
            futures.push_back(std::async(std::launch::async, validator, token));
        }

        bool result = false;
        for (auto& future : futures) {
            if (future.get()) {
                result = true;
                break;
            }
        }

        callback(result);
        return result;
    }

private:
    std::vector<TokenValidationFunction> validators_;
    mutable std::mutex mutex_;
};

// Example validator function
