namespace MultimediaContentService.Controllers
{
    [Route("api/[controller]")]
    [ApiController]
    public class ContentController : ControllerBase
    {
        private readonly IDistributedCache _cache;
        private readonly IContentProcessor _contentProcessor;

        public ContentController(IDistributedCache cache, IContentProcessor contentProcessor)
        {
            _cache = cache;
            _contentProcessor = contentProcessor;
        }

        [HttpPost("upload")]
        public async Task<IActionResult> UploadContent([FromForm] IFormFile file)
        {
            var metadata = await _contentProcessor.ProcessMetadata(file);
            var cachedKey = $"metadata:{file.FileName}";
            await _cache.SetStringAsync(cachedKey, JsonSerializer.Serialize(metadata));

            return Ok(new { Message = "Content uploaded and metadata processed successfully." });
        }

        [HttpGet("download/{fileName}")]
        public async Task<IActionResult> DownloadContent(string fileName)
        {
            var cachedKey = $"content:{fileName}";
            var contentBytes = await _cache.GetStringAsync(cachedKey);
            if (contentBytes == null)
            {
                // Simulate fetching from file storage or CDN
                contentBytes = Encoding.UTF8.GetBytes("Sample multimedia content");
                await _cache.SetStringAsync(cachedKey, contentBytes);
            }

            return File(Encoding.UTF8.GetBytes(contentBytes), "application/octet-stream", fileName);
        }
    }
}

public interface IContentProcessor
{
    Task<Dictionary<string, object>> ProcessMetadata(IFormFile file);
}

public class ContentProcessor : IContentProcessor
{
    private readonly HttpClient _httpClient;

    public ContentProcessor(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<Dictionary<string, object>> ProcessMetadata(IFormFile file)
    {
        // Simulate calling third-party APIs for content analysis and categorization
        var response = await _httpClient.GetAsync("https://api.example.com/analyze");
        var metadata = await response.Content.ReadAsAsync<Dictionary<string, object>>();
        return metadata;
    }
}

public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        services.AddControllers();
        services.AddStackExchangeRedisCache(options =>
        {
            options.Configuration = "localhost:6379";
            options.InstanceName = "SampleInstance";
        });
        services.AddSingleton<IContentProcessor, ContentProcessor>();
        services.AddHttpClient();
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }

        app.UseRouting();

        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllers();
        });
    }
}
