class LTEContextManager {
public:
    LTEContextManager(int initialSize, bool useGPU = false)
        : contexts(initialSize), maxContexts(100000), useGPU(useGPU) {}

    void createContext(const LTE_TRANSPORT_CONTEXT& context) {
        std::lock_guard<std::mutex> lock(mutex);
        if (currentContexts < maxContexts) {
            contexts[currentContexts++] = context;
        }
    }

    void deleteContext(int index) {
        std::lock_guard<std::mutex> lock(mutex);
        if (index >= 0 && index < currentContexts) {
            --currentContexts;
            contexts[index] = contexts[currentContexts];
        }
    }

    void modifyContext(int index, const LTE_TRANSPORT_CONTEXT& context) {
        std::lock_guard<std::mutex> lock(mutex);
        if (index >= 0 && index < currentContexts) {
            contexts[index] = context;
        }
    }

