#include <unistd.h>
#include <sys/time.h>

#define MAX_PDUS 10000
#define CACHE_SIZE 100
#define RETRY_DELAY 1000 // milliseconds

typedef struct {
    int ue_info_tag;
    int rnti;
} UeInfo;

typedef struct {
    int crcflag;
} CrcIndication;

typedef struct {
    int id;
    UeInfo ue_info;
    CrcIndication crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_PDUS];
    int count;
    pthread_mutex_t mutex;
} PduCache;

PduCache cache = {0};

void *fetchUeInfo(void *arg) {
    // Simulate fetching UE info from external data source
    UeInfo *ue_info = (UeInfo *)malloc(sizeof(UeInfo));
    ue_info->ue_info_tag = rand() % 100;
    ue_info->rnti = rand() % 100;
    return ue_info;
}

void populatePduIndications(int num_pdus) {
    pthread_mutex_lock(&cache.mutex);
    if (num_pdus > MAX_PDUS || num_pdus > cache.count + CACHE_SIZE) {
        printf("Error: Requested PDUs exceed capacity or limit.\n");
        pthread_mutex_unlock(&cache.mutex);
        return;
    }

    for (int i = cache.count; i < cache.count + num_pdus; i++) {
        if (i >= MAX_PDUS) break;

        NFAPI_CRC_INDICATION_PDU_T *pdu = &cache.pdus[i];
        pdu->id = i;

        // Check cache first
        UeInfo *ue_info = NULL;
        for (int j = 0; j < cache.count; j++) {
            if (cache.pdus[j].ue_info.ue_info_tag == pdu->ue_info.ue_info_tag) {
                ue_info = &cache.pdus[j].ue_info;
                break;
            }
        }

        // Fetch from external source if not in cache
        if (!ue_info) {
            ue_info = (UeInfo *)fetchUeInfo(NULL);
            cache.pdus[i].ue_info = *ue_info;
            pthread_mutex_unlock(&cache.mutex);
            free(ue_info); // Simulate freeing allocated memory
            pthread_mutex_lock(&cache.mutex);
        }

        pdu->crc_indication.crcflag = rand() % 2; // Random CRC flag

        cache.count++;
    }
    pthread_mutex_unlock(&cache.mutex);

    printf("Populated %d PDUs.\n", num_pdus);
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, populatePduIndications, (void *)10) != 0) {
        printf("Error creating thread.\n");
        return 1;
    }

    if (pthread_join(thread, NULL) != 0) {
        printf("Error joining thread.\n");
        return 1;
    }

    return 0;
}
```

