// Define necessary structures and types
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    // Other fields as per the PDU structure
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int CRCFLAG;
    // Other fields as per the CRC indication structure
} CRC_INDICATION_REL8_TAG;

// Function to populate an array of PDUs
void populatePduIndications(NFAPI_CRC_INDICATION_PDU_T *pdus, int count) {
    pthread_t threads[count];
    for (int i = 0; i < count; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = getRxUeInformationTagFromApi(i);
        pdus[i].RNTI = getRntiFromApi(i);
        CRC_INDICATION_REL8_TAG *crcIndication = (CRC_INDICATION_REL8_TAG *)malloc(sizeof(CRC_INDICATION_REL8_TAG));
        crcIndication->CRCFLAG = getRandomCrcFlag();
        pthread_create(&threads[i], NULL, populatePduThreadFunc, (void *)&pdus[i]);
    }

    for (int i = 0; i < count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Thread function to populate PDU details
void *populatePduThreadFunc(void *arg) {
