#include <vector>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <memory>
#include <chrono>
#include <future>

class MetricsCollector {
public:
    void collectMetrics(const std::string& source, const std::string& metric) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push({source, metric});
        condition_.notify_one();
    }

private:
    struct Metric {
        std::string source;
        std::string metric;
    };

    std::queue<Metric> queue_;
    std::mutex mutex_;
    std::condition_variable condition_;
};

class MetricsProcessor {
public:
    void startProcessing() {
        processingThread_ = std::thread(&MetricsProcessor::processMetrics, this);
    }

    void stopProcessing() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            stop_ = true;
        }
        condition_.notify_all();
        if (processingThread_.joinable()) {
            processingThread_.join();
        }
    }

private:
    void processMetrics() {
        while (true) {
            Metric metric;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                condition_.wait(lock, [this] { return !queue_.empty() || stop_; });
                if (stop_ && queue_.empty()) {
                    break;
                }
                metric = queue_.front();
                queue_.pop();
            }

            // Process the metric
            processMetric(metric);
        }
    }

    void processMetric(const Metric& metric) {
        // Implement metric processing logic here
        std::cout << "Processing metric from source: " << metric.source << ", metric: " << metric.metric << std::endl;
    }

    std::thread processingThread_;
    std::mutex mutex_;
    std::condition_variable condition_;
    bool stop_{false};
};

int main() {
    MetricsCollector collector;
    MetricsProcessor processor;

    processor.startProcessing();

    // Simulate collecting metrics
    for (int i = 0; i < 10; ++i) {
        collector.collectMetrics("HTTP", "Metric" + std::to_string(i));
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }

    processor.stopProcessing();

    return 0;
}
```

