#define MAX_CONCURRENCY 10

typedef struct {
    uint32_t RNTI;
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint8_t CRCFLAG;
    // Other fields...
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc_indication;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T create_nfaip_pdu(uint32_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.ue_info.RNTI = rnti;
    pdu.crc_indication.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    // Initialize other fields...
    return pdu;
}

void handle_api_failure(int attempt) {
    if (attempt > MAX_CONCURRENCY) {
        fprintf(stderr, "API call failed after maximum attempts\n");
        exit(EXIT_FAILURE);
    }
    sleep(pow(2, attempt)); // Exponential backoff
}

NFAPI_CRC_INDICATION_PDU_T* fetch_and_process_pdu(uint32_t rnti, int attempt) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_memory(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    // Simulate API call with potential failure
    if (rand() % 5 == 0) { // 20% chance of failure
        handle_api_failure(attempt);
        free(pdu);
        return fetch_and_process_pdu(rnti, attempt + 1);
    }
    *pdu = create_nfaip_pdu(rnti);
    return pdu;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <number_of_structures>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int num_structures = atoi(argv[1]);
    NFAPI_CRC_INDICATION_PDU_T** pdus = allocate_memory(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for (int i = 0; i < num_structures; ++i) {
        uint32_t rnti = rand() % 1000; // Random RNTI
        pdus[i] = fetch_and_process_pdu(rnti, 1);
    }

    // Process and serialize the PDUs...
    for (int i = 0; i < num_structures; ++i) {
        free(pdus[i]);
    }
    free(pdus);

    return 0;
}
