// Define the Octree node structure
struct OctreeNode {
    std::unique_ptr<OctreeNode> children[8];
    int data;

    OctreeNode(int d) : data(d), children() {}
};

class OctreeManager {
public:
    OctreeManager(size_t nodes);
    ~OctreeManager();

    void updateNode(size_t index, int newData);

private:
    std::unique_ptr<OctreeNode> root;
    size_t totalNodes;

    OctTreeNode* getNodeAt(OctTreeNode* node, size_t index);
};

OctreeManager::OctreeManager(size_t nodes) : totalNodes(nodes) {
    // Initialize the octree with the specified number of nodes
    root = std::make_unique<OctreeNode>(0); // Assuming initial data is 0
}

OctreeManager::~OctreeManager() {}

void OctreeManager::updateNode(size_t index, int newData) {
    OctTreeNode* node = getNodeAt(root.get(), index);
    if (node) {
        node->data = newData;
    } else {
        throw std::runtime_error("Invalid node index");
    }
}

OctreeNode* OctreeManager::getNodeAt(OctTreeNode* node, size_t index) {
    // Navigate the octree to find the node at the specified index
    if (index == 0) return node;
    size_t childIndex = (index - 1) % 8;
    if (!node->children[childIndex]) return nullptr;
    return getNodeAt(node->children[childIndex].get(), (index - 1) / 8);
}

