class APIClient {
public:
    static void updateElementHTML(const std::string& elementId, const std::string& newContent);

private:
    static void retryWithExponentialBackoff(std::function<void()> task, int maxRetries = 5) {
        for (int attempt = 0; attempt <= maxRetries; ++attempt) {
            try {
                task();
                return;
            } catch (const std::exception& e) {
                if (attempt == maxRetries) throw;
                std::this_thread::sleep_for(std::chrono::milliseconds(1 << attempt));
            }
        }
    }

    static void callAPI(const std::string& url, const std::string& data);
};

void APIClient::updateElementHTML(const std::string& elementId, const std::string& newContent) {
    retryWithExponentialBackoff([&]() {
