async function handleFileUpload(fileURL, uploadMethod, storageService, credentials) {
  // Validate URL
  if (!/^https:\/\//.test(fileURL)) {
    throw new Error('Invalid file URL. Must be HTTPS.');
  }

  try {
    const response = await fetch(fileURL);
    if (!response.ok || !['application/pdf', 'image/jpeg'].includes(response.headers.get('content-type'))) {
      throw new Error('File type not supported or invalid');
    }
  } catch (error) {
    console.error('Error validating file URL:', error);
    throw error;
  }

  // Select appropriate upload method
  const fileSize = await getFileSize(fileURL);
  let selectedMethod = uploadMethod;

  if (fileSize > MAX_FILE_SIZE || isNetworkUnpredictable()) {
    selectedMethod = 'multipart';
  } else if (isServerSideResourceLimited()) {
    selectedMethod = 'chunked';
  }

  // Integrate with cloud storage
  const serviceInstance = getServiceInstance(storageService, credentials);
  try {
    return await serviceInstance.upload(fileURL, fileSize, selectedMethod);
  } catch (error) {
    console.error('Error uploading file:', error);
    throw error;
  }
}

