from abc import ABC, abstractmethod
from typing import List, Any, Callable

class DataProcessorStage(ABC):
    @abstractmethod
    def process(self, data: List[Any]) -> List[Any]:
        pass

class FilterStage(DataProcessorStage):
    def __init__(self, predicate: Callable[[Any], bool]):
        self.predicate = predicate

    def process(self, data: List[Any]) -> List[Any]:
        return [item for item in data if self.predicate(item)]

class MapStage(DataProcessorStage):
    def __init__(self, mapper: Callable[[Any], Any]):
        self.mapper = mapper

    def process(self, data: List[Any]) -> List[Any]:
        return [self.mapper(item) for item in data]

class AggregateStage(DataProcessorStage):
    def __init__(self, key_func: Callable[[Any], Any], aggregate_func: Callable[[List[Any]], Any]):
        self.key_func = key_func
        self.aggregate_func = aggregate_func

    def process(self, data: List[Any]) -> List[Any]:
        from collections import defaultdict
        result = defaultdict(list)
        for item in data:
            result[self.key_func(item)].append(item)
        return [self.aggregate_func(items) for items in result.values()]

class DataProcessor:
    def __init__(self):
        self.stages: List[DataProcessorStage] = []

    def add_stage(self, stage: DataProcessorStage):
        self.stages.append(stage)

    def process(self, data: List[Any]) -> List[Any]:
        current_data = data
        for stage in self.stages:
            current_data = stage.process(current_data)
        return current_data

class DataSource(ABC):
    @abstractmethod
    def fetch(self) -> List[Any]:
        pass

class StreamingDataSource(DataSource):
    def __init__(self, stream: Any):
        self.stream = stream

    def fetch(self) -> List[Any]:
        return [item for item in iter(self.stream)]

class BatchDataSource(DataSource):
    def __init__(self, batch_job: Callable[[], List[Any]]):
        self.batch_job = batch_job

    def fetch(self) -> List[Any]:
        return self.batch_job()

# Example usage
if __name__ == "__main__":
    # Define data processing stages
    filter_stage = FilterStage(lambda x: x > 10)
    map_stage = MapStage(lambda x: x * 2)
    aggregate_stage = AggregateStage(key_func=lambda x: x % 2, aggregate_func=sum)

    processor = DataProcessor()
    processor.add_stage(filter_stage)
    processor.add_stage(map_stage)
    processor.add_stage(aggregate_stage)

    # Define data sources
    streaming_source = StreamingDataSource(range(100))
    batch_source = BatchDataSource(lambda: list(range(50, 150)))

    # Process data from both sources
    result_streaming = processor.process(streaming_source.fetch())
    result_batch = processor.process(batch_source.fetch())

    print("Streaming Result:", result_streaming)
    print("Batch Result:", result_batch)
```']

