typedef struct {
    const char* connectionDetails;
    const char** wsEndpoints;
    int maxConcurrentThreads;
    char duplicateHandlingPolicy;
} Metadata;

struct StringProcessingContext {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int processingCount;
    int sizeLimit;
};

char* processStringWithDialogRefresh(const char* input, int sizeLimit, Metadata* metadata, const char** fieldNames) {
    static struct StringProcessingContext context = {PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER, 0, sizeLimit};
    static pthread_t* threads = NULL;
    static int threadCount = 0;

    if (input == NULL || metadata == NULL || fieldNames == NULL) {
        fprintf(stderr, "Invalid input or metadata pointer\n");
        return NULL;
    }

    pthread_mutex_lock(&context.mutex);
    while (context.processingCount >= context.sizeLimit) {
        pthread_cond_wait(&context.cond, &context.mutex);
    }
    context.processingCount++;
    pthread_mutex_unlock(&context.mutex);

    if (strlen(input) + 1 > sizeLimit) {
        fprintf(stderr, "Input exceeds size limit\n");
        pthread_mutex_lock(&context.mutex);
        context.processingCount--;
        pthread_cond_signal(&context.cond);
        pthread_mutex_unlock(&context.mutex);
        return NULL;
    }

    char* processedString = malloc(strlen(input) + 2);
    strcpy(processedString, input);
    strncat(processedString, "/", sizeLimit - strlen(input));

    // Simulate asynchronous logging
    struct timeval now;
    gettimeofday(&now, NULL);
    printf("Processed string: %s at %ld.%06ld\n", processedString, now.tv_sec, now.tv_usec);

    for (int i = 0; fieldNames[i] != NULL; i++) {
        // Simulate dialog refresh
        printf("Refreshing dialog field: %s\n", fieldNames[i]);
    }

    pthread_mutex_lock(&context.mutex);
    context.processingCount--;
    pthread_cond_signal(&context.cond);
    pthread_mutex_unlock(&context.mutex);

    return processedString;
}
