#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_PDUS 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    NFAPI_CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_PDUS];
    int count;
    pthread_mutex_t lock;
} PduPool;

PduPool pduPool;

void initializePduPool() {
    memset(&pduPool, 0, sizeof(pduPool));
    pthread_mutex_init(&pduPool.lock, NULL);
}

void addToPduPool(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&pduPool.lock);
    if (pduPool.count < MAX_PDUS) {
        pduPool.pdus[pduPool.count++] = pdu;
    }
    pthread_mutex_unlock(&pduPool.lock);
}

void* processPduIndications(void* arg) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    while (1) {
        // Fetch UE information and RNTI from external data source
        char url[256];
        snprintf(url, sizeof(url), "http://example.com/api/ue_info?timestamp=%ld", time(NULL));
        curl_easy_setopt(curl, CURLOPT_URL, url);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            continue;
        }

        // Parse response and create PDU
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Populate pdu with parsed data and random CRCFLAG
        // ...

        addToPduPool(pdu);

        // Sleep for a short duration before the next update
        usleep(1000 * 100); // 100ms
    }

    curl_easy_cleanup(curl);
    curl_global_cleanup();
    return NULL;
}

int main() {
    initializePduPool();

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, processPduIndications, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    // Wait for the thread to finish
    pthread_join(thread_id, NULL);

    return 0;
}
