class SessionManager {
public:
    SessionManager(AnalyticsService& analytics)
        : analytics_(analytics), retryDelay_(std::chrono::milliseconds(100)), maxRetries_(5) {}

    void addUserSession(const UserSession& session) {
        std::lock_guard<std::mutex> lock(mutex_);
        sessions_[session.sessionId] = session;
        notifyAnalytics(session);
    }

    UserSession getUserSession(const std::string& sessionId) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = sessions_.find(sessionId);
        if (it != sessions_.end()) {
            return it->second;
        }
        throw std::runtime_error("Session not found");
    }

private:
