// Define the Union-Find data structure
class UnionFind {
    private int[] parent;
    private int[] rank;

    public UnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY) return;
        if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }

    public boolean isConnected(int x, int y) {
        return find(x) == find(y);
    }
}

// Define the service class
@Service
public class DisjointPairService {

    @Autowired
    private AuthenticationApi authenticationApi;

    @Autowired
    private UserDAO userDAO;

    private static final Logger logger = LoggerFactory.getLogger(DisjointPairService.class);

    public int computeDisjointPairs(int[] array) {
        UnionFind uf = new UnionFind(array.length);
        for (int i = 0; i < array.length - 1; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (!uf.isConnected(array[i], array[j])) {
                    uf.union(array[i], array[j]);
                }
            }
        }
        int disjointPairs = array.length - uf.find(0);
        logger.info("Computed {} disjoint pairs", disjointPairs);
        return disjointPairs;
    }

    public void updatePassword(String userId, String newPassword) {
        try {
            boolean isValid = authenticationApi.validatePassword(newPassword);
            if (!isValid) {
                throw new IllegalArgumentException("Invalid password");
            }
            userDAO.updatePassword(userId, newPassword);
            logger.info("Updated password for user {}", userId);
        } catch (Exception e) {
            logger.error("Failed to update password for user {} due to {}", userId, e.getMessage());
        }
    }

    public void handleUserRequest(String userId, String operation, Object data) {
        long startTime = System.currentTimeMillis();
        try {
            switch (operation) {
                case "computeDisjointPairs":
                    int[] array = (int[]) data;
                    computeDisjointPairs(array);
                    break;
                case "updatePassword":
                    updatePassword(userId, (String) data);
                    break;
                default:
                    throw new IllegalArgumentException("Invalid operation");
            }
        } catch (Exception e) {
            logger.error("Failed to handle request for user {} due to {}", userId, e.getMessage());
        } finally {
            long endTime = System.currentTimeMillis();
            logger.info("Completed {} in {} ms", operation, endTime - startTime);
        }
    }
}
