    async fn new(queue: mpsc::Sender<ProcessedData>) -> Self {
        DataProcessor {
            client: Client::new(),
            queue,
        }
    }

    async fn process_data(&self, data: IncomingData) -> Result<(), reqwest::Error> {
        let processed = self.convert_and_normalize(data).await?;
        self.queue.send(processed).await?;
        Ok(())
    }

    async fn convert_and_normalize(&self, data: IncomingData) -> Result<ProcessedData, reqwest::Error> {
        match data {
            IncomingData::Legacy(legacy_data) => self.legacy_converter(legacy_data),
            IncomingData::Stream(stream_data) => self.stream_converter(stream_data),
            IncomingData::API(api_data) => self.api_converter(api_data).await,
        }
    }

    fn legacy_converter(&self, legacy_data: LegacyData) -> Result<ProcessedData, reqwest::Error> {
        // Convert legacy data to internal format
        Ok(ProcessedData::new(/* converted data */))
    }

    async fn api_converter(&self, api_data: APIData) -> Result<ProcessedData, reqwest::Error> {
