#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int device_id;
    float signal_strength;
    int* error_codes;
    int error_count;
} DeviceStatusReport;

typedef struct ReportNode {
    DeviceStatusReport report;
    struct ReportNode* next;
} ReportNode;

typedef struct {
    pthread_mutex_t mutex;
    ReportNode* head;
} ReportList;

void init_report_list(ReportList* list) {
    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;
}

void add_report(ReportList* list, DeviceStatusReport report) {
    pthread_mutex_lock(&list->mutex);
    ReportNode* new_node = (ReportNode*)malloc(sizeof(ReportNode));
    new_node->report = report;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
}

void update_report(ReportList* list, DeviceStatusReport new_report) {
    pthread_mutex_lock(&list->mutex);
    ReportNode* current = list->head;
    while (current != NULL) {
        if (current->report.device_id == new_report.device_id) {
            current->report = new_report;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

DeviceStatusReport get_report(ReportList* list, int device_id) {
    pthread_mutex_lock(&list->mutex);
    ReportNode* current = list->head;
    while (current != NULL) {
        if (current->report.device_id == device_id) {
            DeviceStatusReport report = current->report;
            pthread_mutex_unlock(&list->mutex);
            return report;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    DeviceStatusReport empty_report = {0};
    return empty_report;
}

void delete_report(ReportList* list, int device_id) {
    pthread_mutex_lock(&list->mutex);
    ReportNode* current = list->head;
    ReportNode* prev = NULL;
    while (current != NULL) {
        if (current->report.device_id == device_id) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void destroy_report_list(ReportList* list) {
    pthread_mutex_lock(&list->mutex);
    ReportNode* current = list->head;
    while (current != NULL) {
        ReportNode* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
}
