    int device_id;
    float signal_strength;
    Error *errors;
    int error_count;
} DeviceStatusReport;

typedef struct ReportCollection {
    DeviceStatusReport **reports;
    int count;
    pthread_mutex_t lock;
} ReportCollection;

// Function prototypes
void init_report_collection(ReportCollection *collection);
void add_device_status_report(ReportCollection *collection, DeviceStatusReport *report);
void remove_device_status_report(ReportCollection *collection, int device_id);

int main() {
    ReportCollection collection;
    init_report_collection(&collection);

    // Example usage
    DeviceStatusReport report = {time(NULL), 12345, 75.5, NULL, 0};
    add_device_status_report(&collection, &report);

    remove_device_status_report(&collection, 12345);
    return 0;
}

void init_report_collection(ReportCollection *collection) {
    collection->reports = NULL;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

void add_device_status_report(ReportCollection *collection, DeviceStatusReport *report) {
    pthread_mutex_lock(&collection->lock);

    // Grow the reports array if necessary
    collection->reports = realloc(collection->reports, (collection->count + 1) * sizeof(DeviceStatusReport *));
    collection->reports[collection->count++] = report;

    pthread_mutex_unlock(&collection->lock);
}

void remove_device_status_report(ReportCollection *collection, int device_id) {
    pthread_mutex_lock(&collection->lock);

    for (int i = 0; i < collection->count; i++) {
        if (collection->reports[i]->device_id == device_id) {
            free(collection->reports[i]);
            memmove(&collection->reports[i], &collection->reports[i + 1], (collection->count - i - 1) * sizeof(DeviceStatusReport *));
            collection->count--;
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}
