using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.Configuration;
using Microsoft.IdentityModel.Tokens;
using System;
using System.IdentityModel.Tokens.Jwt;
using System.Net.Http;
using System.Security.Claims;
using System.Threading.Tasks;

[ApiController]
[Route("api/[controller]")]
public class UserProfileController : ControllerBase
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;
    private readonly IConfiguration _configuration;

    public UserProfileController(HttpClient httpClient, IDistributedCache cache, IConfiguration configuration)
    {
        _httpClient = httpClient;
        _cache = cache;
        _configuration = configuration;
    }

    [HttpPost("update")]
    [Authorize(AuthenticationSchemes = JwtBearerDefaults.AuthenticationScheme)]
    public async Task<IActionResult> UpdateUserProfile([FromBody] UserProfileRequest request)
    {
        try
        {
            // Validate session token TTL
            var token = HttpContext.User.Identity as ClaimsIdentity;
            if (token == null || !token.HasClaim(c => c.Type == ClaimTypes.Expiration))
            {
                return Unauthorized("Invalid or missing token.");
            }

            var expirationTime = DateTimeOffset.FromUnixTimeSeconds(long.Parse(token.FindFirst(ClaimTypes.Expiration).Value));
            if (expirationTime < DateTimeOffset.UtcNow)
            {
                return Unauthorized("Token expired.");
            }

            // Validate rate limit
            var ipKey = $"RateLimit:{HttpContext.Connection.RemoteIpAddress}";
            var currentRequestCount = await _cache.GetStringAsync(ipKey);
            if (currentRequestCount == null)
            {
                await _cache.SetStringAsync(ipKey, "1", new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(1) });
            }
            else
            {
                int count = int.Parse(currentRequestCount);
                if (count >= 100) // Adjust the limit based on your requirements
                {
                    return StatusCode(429, "Too Many Requests");
                }

                await _cache.SetStringAsync(ipKey, $"{count + 1}", new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(1) });
            }

            // Update user profile in the database or external system
            var response = await _httpClient.PostAsJsonAsync("https://externalapi.com/update", request);
            if (!response.IsSuccessStatusCode)
            {
                return StatusCode((int)response.StatusCode, "Failed to update user profile.");
            }

            // Log operation for auditing and debugging
            LogOperation(request);

            return Ok(new { Message = "User profile updated successfully." });
        }
        catch (Exception ex)
        {
            // Log exception details
            LogError(ex);

            return StatusCode(500, "Internal server error.");
        }
    }

    private void LogOperation(UserProfileRequest request)
    {
        // Implement logging logic here
    }

    private void LogError(Exception ex)
    {
        // Implement error logging logic here
    }
}

public class UserProfileRequest
{
    public string UserId { get; set; }
    public string Name { get; set; }
    public string Email { get; set; }
}
