void handleSensorDataStreams(ThreadSafeQueue<SensorData>& queue, SchemaVersioning& schemaValidator, AlertingSystem& alertingSystem, TransactionalStorage& storage) {
    std::atomic<bool> running(true);

    auto worker = [&queue, &schemaValidator, &alertingSystem, &storage, &running]() {
