import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class MissionCriticalMicroservicesArchitecture {

    private static final int MAX_CONCURRENT_TASKS = 1000;
    private ExecutorService executorService;

    public MissionCriticalMicroservicesArchitecture() {
        this.executorService = Executors.newFixedThreadPool(MAX_CONCURRENT_TASKS);
    }

    public void processTransaction(Transaction transaction) throws InterruptedException {
        executorService.execute(() -> {
            try {
                // Process the transaction
                System.out.println("Processing transaction: " + transaction.getId());
                Thread.sleep(10); // Simulate processing time
                System.out.println("Processed transaction: " + transaction.getId());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                System.err.println("Transaction processing interrupted");
            }
        });
    }

    public void shutdown() throws InterruptedException {
        executorService.shutdown();
        if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
            executorService.shutdownNow();
        }
    }

    public static void main(String[] args) {
        MissionCriticalMicroservicesArchitecture architecture = new MissionCriticalMicroservicesArchitecture();
        // Simulate processing multiple transactions
        for (int i = 1; i <= 5000; i++) {
            try {
                architecture.processTransaction(new Transaction(i));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                System.err.println("Error processing transaction");
            }
        }
        try {
            architecture.shutdown();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Error shutting down architecture");
        }
    }

    static class Transaction {
        private int id;

        public Transaction(int id) {
            this.id = id;
        }

        public int getId() {
            return id;
        }
    }
}
```

