#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <unordered_map>
#include <atomic>
#include <chrono>

class SensorData {
public:
    int vehicleID;
    std::chrono::system_clock::time_point timestamp;
    double latitude, longitude;
    double temperature, pressure, acceleration;
    std::vector<std::string> anomalies;

    SensorData(int id, std::chrono::system_clock::time_point ts, double lat, double lon, 
                 double temp, double pres, double acc, const std::vector<std::string>& anoms)
        : vehicleID(id), timestamp(ts), latitude(lat), longitude(lon),
          temperature(temp), pressure(pres), acceleration(acc), anomalies(anoms) {}
};

class SensorDataQueue {
private:
    std::queue<SensorData> queue;
    mutable std::mutex mtx;
    std::condition_variable cond;
public:
    void push(const SensorData& data) {
        std::lock_guard<std::mutex> lock(mtx);
        queue.push(data);
        cond.notify_one();
    }

    bool try_pop(SensorData& data, int timeout_ms = 100) {
        std::unique_lock<std::mutex> lock(mtx);
        if (cond.wait_for(lock, std::chrono::milliseconds(timeout_ms), [this] { return !queue.empty(); })) {
            data = queue.front();
            queue.pop();
            return true;
        }
        return false;
    }
};

class DataProcessor {
public:
    void process_data(SensorDataQueue& queue) {
        while (true) {
            SensorData data;
            if (queue.try_pop(data)) {
                // Process the sensor data
                std::cout << "Processing vehicle " << data.vehicleID << " at time " 
                          << std::chrono::system_clock::to_time_t(data.timestamp) << std::endl;
            }
        }
    }
};

int main() {
    SensorDataQueue queue;
    DataProcessor processor;

    std::thread consumer(processor, std::ref(queue));

    for (int i = 0; i < 100; ++i) {
        queue.push(SensorData(i, std::chrono::system_clock::now(), 
                             static_cast<double>(rand()) / RAND_MAX * 90.0 - 45.0,
                             static_cast<double>(rand()) / RAND_MAX * 180.0 - 90.0,
                             20.0 + static_cast<double>(rand()) / RAND_MAX * 10.0,
                             1013.0 + static_cast<double>(rand()) / RAND_MAX * 50.0,
                             0.0 + static_cast<double>(rand()) / RAND_MAX * 10.0,
                             {"Anomaly1", "Anomaly2"}));
    }

    consumer.join();
}
