#include <stdio.h>
#include <stdarg.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

#define MAX_LOG_SIZE 1024

typedef struct {
    int condition;
    FILE *log_file;
    pthread_mutex_t lock;
} LogContext;

LogContext log_ctx = {0, NULL, PTHREAD_MUTEX_INITIALIZER};

void init_logger(int condition, const char *log_file_path) {
    log_ctx.condition = condition;
    log_ctx.log_file = fopen(log_file_path, "a");
}

void cleanup_logger() {
    if (log_ctx.log_file) {
        fclose(log_ctx.log_file);
    }
}

void log_conditionally(int condition, const char *format, ...) {
    va_list args;
    va_start(args, format);

    if (!log_ctx.log_file || log_ctx.condition != condition) {
        va_end(args);
        return;
    }

    pthread_mutex_lock(&log_ctx.lock);
    struct tm *timeinfo;
    time_t now = time(NULL);
    timeinfo = localtime(&now);
    fprintf(log_ctx.log_file, "%s - ", asctime(timeinfo));

    char buffer[MAX_LOG_SIZE];
    vsnprintf(buffer, sizeof(buffer), format, args);
    fprintf(log_ctx.log_file, "%s\n", buffer);

    fflush(log_ctx.log_file);
    pthread_mutex_unlock(&log_ctx.lock);

    va_end(args);
}
```

This code snippet provides a basic structure for the modular C library component with conditional logging functionality. The `init_logger` function initializes the logger with a specific condition and log file path, while the `cleanup_logger` function cleans up resources when done. The `log_conditionally` function formats and logs messages only when the specified condition is met, ensuring thread safety through mutual exclusion.']

