        std::lock_guard<std::mutex> lock(mutex);
        if (dataMap.find(sensorID) != dataMap.end()) {
            dataMap.erase(sensorID);
            return true;
        }
        return false;
    }

    SensorData* get(const std::string& sensorID) const {
        std::lock_guard<std::mutex> lock(mutex);
