#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_DEVICES 100
#define MAX_ERRORS 5

typedef struct {
    time_t timestamp;
    int device_id;
    float signal_strength;
    int error_codes[MAX_ERRORS];
    int error_count;
} DeviceStatusReport;

typedef struct {
    pthread_mutex_t lock;
    DeviceStatusReport devices[MAX_DEVICES];
    int count;
} DeviceCollection;

void init_device_collection(DeviceCollection *collection) {
    pthread_mutex_init(&collection->lock, NULL);
    collection->count = 0;
}

int add_device_status(DeviceCollection *collection, const DeviceStatusReport *report) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count < MAX_DEVICES) {
        collection->devices[collection->count++] = *report;
        pthread_mutex_unlock(&collection->lock);
        return 0;
    }
    pthread_mutex_unlock(&collection->lock);
    return -1; // Collection full
}

void print_device_collection(const DeviceCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->count; i++) {
        printf("Device ID: %d, Timestamp: %ld, Signal Strength: %.2f\n",
               collection->devices[i].device_id,
               collection->devices[i].timestamp,
               collection->devices[i].signal_strength);
    }
    pthread_mutex_unlock(&collection->lock);
}

int main() {
    DeviceCollection collection;
    init_device_collection(&collection);

    DeviceStatusReport report = {time(NULL), 1, 95.0, {0}, 0};
    add_device_status(&collection, &report);

    print_device_collection(&collection);

    return 0;
}
```

