// Define log levels
#define LOG_DEBUG 1
#define LOG_INFO 2
#define LOG_WARNING 3
#define LOG_ERROR 4

// Function to format and log messages conditionally
void log_conditionally(int level, const char* format, ...) {
    va_list args;
    va_start(args, format);

    // Check if the log level is enabled
    if (level == LOG_DEBUG) {
        char buffer[1024];
        vsnprintf(buffer, sizeof(buffer), format, args);
        printf("[DEBUG] %s\n", buffer);
    } else if (level == LOG_INFO) {
        char buffer[1024];
        vsnprintf(buffer, sizeof(buffer), format, args);
        printf("[INFO] %s\n", buffer);
    } else if (level == LOG_WARNING) {
        char buffer[1024];
        vsnprintf(buffer, sizeof(buffer), format, args);
        printf("[WARNING] %s\n", buffer);
    } else if (level == LOG_ERROR) {
        char buffer[1024];
        vsnprintf(buffer, sizeof(buffer), format, args);
        printf("[ERROR] %s\n", buffer);
    }

    va_end(args);
}

// Example usage
int main() {
    log_conditionally(LOG_INFO, "This is an info message.");
    log_conditionally(LOG_ERROR, "This is an error message.");
    return 0;
}
```

