    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;
    private readonly ILogger<UserService> _logger;

    public UserService(HttpClient httpClient, IMemoryCache cache, ILogger<UserService> logger)
    {
        _httpClient = httpClient;
        _cache = cache;
        _logger = logger;
    }

    public async Task<int> CreateUserAsync(User user)
    {
        var response = await _httpClient.PostAsJsonAsync("api/users", user);
        if (response.IsSuccessStatusCode)
        {
            return await response.Content.ReadAsAsync<int>();
        }
        throw new Exception($"Failed to create user: {await response.Content.ReadAsStringAsync()}");
    }

    public async Task UpdateUserAsync(User user)
    {
        var response = await _httpClient.PutAsJsonAsync($"api/users/{user.Id}", user);
        if (!response.IsSuccessStatusCode)
        {
            throw new Exception($"Failed to update user: {await response.Content.ReadAsStringAsync()}");
        }
    }

    public async Task DeleteUserAsync(int userId)
    {
        var response = await _httpClient.DeleteAsync($"api/users/{userId}");
        if (!response.IsSuccessStatusCode)
        {
            throw new Exception($"Failed to delete user: {await response.Content.ReadAsStringAsync()}");
        }
    }

    public async Task<User> GetUserByIdAsync(int userId)
    {
        return await _cache.GetOrCreateAsync(userId, entry =>
        {
            entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10);
            var response = _httpClient.GetAsync($"api/users/{userId}");
            if (response.Result.IsSuccessStatusCode)
            {
                return response.Result.Content.ReadAsAsync<User>().Result;
            }
            throw new Exception($"Failed to get user: {await response.Result.Content.ReadAsStringAsync()}");
        });
    }

    public async Task StreamLargeDataToDatabaseAsync(byte[] data, string connectionString)
    {
        using (var connection = new SqlConnection(connectionString))
        {
            await connection.OpenAsync();
            using (var command = new SqlCommand("INSERT INTO LargeData (Data) VALUES (@Data)", connection))
            {
                command.Parameters.AddWithValue("@Data", data);
                await command.ExecuteNonQueryAsync();
            }
        }
    }

    public async Task<byte[]> ExecuteDynamicFilterQueryAsync(byte[] filterCriteria, string connectionString)
    {
        using (var connection = new SqlConnection(connectionString))
        {
            await connection.OpenAsync();
            using (var command = new SqlCommand("SELECT * FROM Users WHERE Age > @Age", connection))
            {
                command.Parameters.AddWithValue("@Age", BitConverter.ToInt32(filterCriteria, 0));
                using (var reader = await command.ExecuteReaderAsync())
                {
                    var result = new List<byte[]>();
                    while (await reader.ReadAsync())
                    {
                        using (var memoryStream = new MemoryStream())
                        {
                            // Serialize user data to byte array
                            result.Add(memoryStream.ToArray());
                        }
                    }
                    return result.ToArray();
                }
            }
        }
    }

    public async Task HandleConcurrentExecutionAsync()
    {
        // Implement thread-safe operations and resource management
    }

