typedef struct {
    time_t timestamp;
    int device_id;
    int signal_strength;
    int *error_codes;
    int error_count;
} DeviceStatusReport;

// Define a mutex for thread-safe operations
pthread_mutex_t report_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a DeviceStatusReport
void init_report(DeviceStatusReport *report, time_t timestamp, int device_id, int signal_strength) {
    report->timestamp = timestamp;
    report->device_id = device_id;
    report->signal_strength = signal_strength;
    report->error_codes = NULL;
    report->error_count = 0;
}

// Function to add an error code to a DeviceStatusReport
void add_error_code(DeviceStatusReport *report, int error_code) {
    pthread_mutex_lock(&report_mutex);
    report->error_codes = (int *)realloc(report->error_codes, (report->error_count + 1) * sizeof(int));
    report->error_codes[report->error_count++] = error_code;
    pthread_mutex_unlock(&report_mutex);
}

// Function to clear all error codes from a DeviceStatusReport
void clear_error_codes(DeviceStatusReport *report) {
    pthread_mutex_lock(&report_mutex);
    free(report->error_codes);
    report->error_codes = NULL;
    report->error_count = 0;
    pthread_mutex_unlock(&report_mutex);
}

// Function to simulate sending a report to an external data ingestion service
int send_report(DeviceStatusReport *report) {
    // Simulate potential failure of the external service
    if (rand() % 2 == 0) {
        return -1; // Failure
    }
    printf("Report sent successfully for device ID: %d\n", report->device_id);
    return 0; // Success
}

// Function to store a DeviceStatusReport in a distributed database system
void store_report(DeviceStatusReport *report) {
    pthread_mutex_lock(&report_mutex);
    // Simulate storing the report in a database
    printf("Storing report for device ID: %d\n", report->device_id);
    pthread_mutex_unlock(&report_mutex);
}

// Function to trigger real-time alerts for devices exceeding predefined thresholds
void trigger_alert(DeviceStatusReport *report) {
    if (report->signal_strength < 50 || report->error_count > 3) {
        printf("Alert triggered for device ID: %d\n", report->device_id);
    }
}

// Function to handle network failures and retry logic
int handle_network_failure(int max_retries, int delay_seconds) {
    for (int i = 1; i <= max_retries; i++) {
        if (send_report(&report) == 0) {
            return 0; // Success
        }
        sleep(delay_seconds);
    }
    return -1; // Failure after retries
}

// Example usage of the library functions
int main() {
    DeviceStatusReport report;
    init_report(&report, time(NULL), 12345, 80);

    add_error_code(&report, 1001);
    add_error_code(&report, 1002);

    if (handle_network_failure(3, 5) == -1) {
        printf("Failed to send report after retries\n");
    }

    store_report(&report);
    trigger_alert(&report);

    clear_error_codes(&report);

    return 0;
}
