#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct DeviceStatusReport {
    time_t timestamp;
    int deviceId;
    float signalStrength;
    int* errorCodes;
    size_t errorCount;
} DeviceStatusReport;

typedef struct ReportManager {
    DeviceStatusReport** reports;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} ReportManager;

ReportManager* createReportManager() {
    ReportManager* manager = (ReportManager*)malloc(sizeof(ReportManager));
    manager->reports = NULL;
    manager->capacity = 0;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroyReportManager(ReportManager* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->reports[i]->errorCodes);
        free(manager->reports[i]);
    }
    free(manager->reports);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void addOrUpdateReport(ReportManager* manager, DeviceStatusReport* report) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->size >= manager->capacity) {
        manager->capacity = (manager->capacity == 0) ? 1 : manager->capacity * 2;
        manager->reports = realloc(manager->reports, manager->capacity * sizeof(DeviceStatusReport*));
    }
    bool found = false;
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->reports[i]->deviceId == report->deviceId) {
            free(manager->reports[i]->errorCodes);
            manager->reports[i] = report;
            found = true;
            break;
        }
    }
    if (!found) {
        manager->reports[manager->size++] = report;
    }
    pthread_mutex_unlock(&manager->mutex);
}

DeviceStatusReport* getReport(ReportManager* manager, int deviceId) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->reports[i]->deviceId == deviceId) {
            pthread_mutex_unlock(&manager->mutex);
            return manager->reports[i];
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}

void calculateSummary(ReportManager* manager, float* avgSignalStrength, int** errorCounts, size_t* errorCount) {
    *avgSignalStrength = 0.0f;
    *errorCounts = (int*)calloc(1024, sizeof(int)); // Assuming a max of 1024 unique error codes
    *errorCount = 0;

    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->size; ++i) {
        *avgSignalStrength += manager->reports[i]->signalStrength;
        for (size_t j = 0; j < manager->reports[i]->errorCount; ++j) {
            (*errorCounts)[manager->reports[i]->errorCodes[j]]++;
        }
    }
    *avgSignalStrength /= manager->size;
    pthread_mutex_unlock(&manager->mutex);
}

// Additional functions for Union-Find, error handling, and testing can be implemented here
