#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_DEVICES 10000

typedef struct {
    time_t timestamp;
    char device_id[256];
    int signal_strength;
    int error_codes;
    char network_condition[256];
} DeviceStatusReport;

typedef struct {
    DeviceStatusReport reports[MAX_DEVICES];
    int count;
    pthread_mutex_t lock;
} DeviceReportManager;

void init_device_report_manager(DeviceReportManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_or_update_device_report(DeviceReportManager *manager, const DeviceStatusReport *report) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (strcmp(manager->reports[i].device_id, report->device_id) == 0) {
            memcpy(&manager->reports[i], report, sizeof(DeviceStatusReport));
            pthread_mutex_unlock(&manager->lock);
            return 1;
        }
    }
    if (manager->count < MAX_DEVICES) {
        manager->reports[manager->count++] = *report;
        pthread_mutex_unlock(&manager->lock);
        return 0;
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Device limit reached
}

DeviceStatusReport* get_device_report(DeviceReportManager *manager, const char *device_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (strcmp(manager->reports[i].device_id, device_id) == 0) {
            DeviceStatusReport* report = malloc(sizeof(DeviceStatusReport));
            memcpy(report, &manager->reports[i], sizeof(DeviceStatusReport));
            pthread_mutex_unlock(&manager->lock);
            return report;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL; // Report not found
}

void free_device_report(DeviceStatusReport *report) {
    if (report != NULL) {
        free(report);
    }
}

// Additional functions for real-time data ingestion, error handling, logging, etc.
