#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    int deviceId;
    float signalStrength;
    int* errorCodes;
    int errorCodeCount;
    char firmwareVersion[20];
    unsigned int operationalFlags;
} DeviceStatusReport;

typedef struct {
    DeviceStatusReport** reports;
    int count;
    pthread_mutex_t lock;
} ReportCollection;

ReportCollection* createReportCollection() {
    ReportCollection* collection = (ReportCollection*)malloc(sizeof(ReportCollection));
    collection->reports = NULL;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void addReport(ReportCollection* collection, DeviceStatusReport* report) {
    pthread_mutex_lock(&collection->lock);
    collection->reports = (DeviceStatusReport**)realloc(collection->reports, (collection->count + 1) * sizeof(DeviceStatusReport*));
    collection->reports[collection->count++] = report;
    pthread_mutex_unlock(&collection->lock);
}

void freeReportCollection(ReportCollection* collection) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->count; i++) {
        free(collection->reports[i]->errorCodes);
        free(collection->reports[i]);
    }
    free(collection->reports);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int main() {
    ReportCollection* collection = createReportCollection();

    DeviceStatusReport* report1 = (DeviceStatusReport*)malloc(sizeof(DeviceStatusReport));
    report1->timestamp = 1633072800;
    report1->deviceId = 101;
    report1->signalStrength = -50.0;
    report1->errorCodes = (int*)malloc(2 * sizeof(int));
    report1->errorCodes[0] = 404;
    report1->errorCodes[1] = 503;
    report1->errorCodeCount = 2;
    strcpy(report1->firmwareVersion, "v1.2");
    report1->operationalFlags = 0x0001;

    addReport(collection, report1);

    freeReportCollection(collection);

    return 0;
}
```

