use std::sync::{Arc, Mutex};
use tokio::task;
use tokio::time::{self, Duration};
use reqwest::Client;
use lru_cache::LruCache;
use tracing::{info, error};

// Define custom error types
#[derive(Debug)]
enum AppError {
    ServiceError(reqwest::Error),
    ParseError(String),
    // Add more error variants as needed
}

impl std::fmt::Display for AppError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            AppError::ServiceError(e) => write!(f, "Service Error: {}", e),
            AppError::ParseError(msg) => write!(f, "Parse Error: {}", msg),
            // Format other error variants
        }
    }
}

impl std::error::Error for AppError {}

// Token bucket rate limiting struct
struct TokenBucket {
    capacity: usize,
    refill_rate: f64,
    tokens: Arc<Mutex<Vec<f64>>>,
    last_refill: time::Instant,
}

impl TokenBucket {
    fn new(capacity: usize, refill_rate: f64) -> Self {
        TokenBucket {
            capacity,
            refill_rate,
            tokens: Arc::new(Mutex::new(vec![time::Instant::now(); capacity])),
            last_refill: time::Instant::now(),
        }
    }

    fn try_consume(&self) -> Result<(), AppError> {
        self.refill();
        if let Some(token_time) = self.tokens.lock().unwrap().pop() {
            let elapsed = token_time.elapsed().as_secs_f64();
            if elapsed >= 1.0 / self.refill_rate {
                self.tokens.lock().unwrap().push(time::Instant::now());
                Ok(())
            } else {
                Err(AppError::ServiceError(reqwest::Error::new(reqwest::error::ErrorKind::Other, "Rate limit exceeded")))
            }
        } else {
            Ok(())
        }
    }

    fn refill(&self) {
        let now = time::Instant::now();
        let elapsed = now.duration_since(self.last_refill).as_secs_f64();
        let tokens_to_add = (elapsed * self.refill_rate).floor() as usize;
        if tokens_to_add > 0 {
            for _ in 0..tokens_to_add {
                self.tokens.lock().unwrap().push(now);
            }
            self.last_refill = now;
        }
    }
}

// Service client with retry and rate limiting
async fn fetch_grammar_from_service(url: &str, bucket: Arc<TokenBucket>) -> Result<String, AppError> {
    if let Err(_) = bucket.try_consume() {
        return Err(AppError::ServiceError(reqwest::Error::new(reqwest::error::ErrorKind::Other, "Rate limit exceeded")));
    }

    for _ in 0..3 { // Retry up to 2 times
        match reqwest::get(url).await {
            Ok(response) => {
                if response.status().is_success() {
                    return response.text().await.map_err(AppError::ServiceError);
                } else {
                    error!("Failed to fetch grammar: {}", response.status());
                }
            },
            Err(e) => {
                error!("Request failed: {:?}", e);
            },
        }
        time::sleep(Duration::from_secs(1)).await;
    }

    Err(AppError::ServiceError(reqwest::Error::new(reqwest::error::ErrorKind::Other, "Failed to fetch grammar after retries")))
}

// Main function to demonstrate the application
#[tokio::main]
async fn main() {
    let url = "http://example.com/grammar";
    let bucket = Arc::new(TokenBucket::new(10, 5.0)); // Capacity of 10 tokens, refilling at 5Hz

    match fetch_grammar_from_service(url, bucket).await {
        Ok(grammar) => info!("Fetched grammar: {}", grammar),
        Err(e) => error!("Error fetching grammar: {:?}", e),
    }
}
```

This code snippet demonstrates a basic structure for implementing the described Rust application. It includes custom error handling, token bucket rate limiting, and a service client with retry logic. The `fetch_grammar_from_service` function attempts to fetch a grammar from an external service while respecting rate limits and handling errors gracefully. The main function demonstrates how to use this client to fetch a grammar.

Remember that this is a simplified example and may need further refinement based on specific requirements and constraints of your project.']

