// Microservice framework setup using Express.js and Node.js
const express = require('express');
const app = express();
const bodyParser = require('body-parser');

app.use(bodyParser.json());

// Message queue setup using RabbitMQ
const amqp = require('amqplib/callback_api');

let channel, connection;

function connectToRabbitMQ() {
    amqp.connect('amqp://localhost', (err, conn) => {
        if (err) {
            setTimeout(connectToRabbitMQ, 1000);
            return;
        }
        connection = conn;
        conn.createChannel((err, ch) => {
            if (err) {
                setTimeout(connectToRabbitMQ, 1000);
                return;
            }
            channel = ch;
            channel.assertQueue('device_status_queue', { durable: false });
        });
    });
}

// External API integrations
const fetch = require('node-fetch');

async function fetchDeviceStatus() {
    // Fetch device status from API 1 with authentication method A and rate limit B
    const responseAPI1 = await fetch('https://api1.example.com/status', {
        headers: { 'Authorization': 'Bearer token1' }
    });
    if (!responseAPI1.ok) throw new Error('API 1 error');

    // Fetch device status from API 2 with authentication method C and rate limit D
    const responseAPI2 = await fetch('https://api2.example.com/status', {
        headers: { 'Authorization': 'Bearer token2' }
    });
    if (!responseAPI2.ok) throw new Error('API 2 error');

    // Fetch device status from API 3 with authentication method E and rate limit F
    const responseAPI3 = await fetch('https://api3.example.com/status', {
        headers: { 'Authorization': 'Bearer token3' }
    });
    if (!responseAPI3.ok) throw new Error('API 3 error');

    // Aggregate metrics from API responses
    const aggregatedMetrics = {
        totalDevices: responseAPI1.json().total + responseAPI2.json().total + responseAPI3.json().total,
        onlineDevices: responseAPI1.json().online + responseAPI2.json().online + responseAPI3.json().online,
        offlineDevices: responseAPI1.json().offline + responseAPI2.json().offline + responseAPI3.json().offline
    };

    // Publish aggregated metrics to message queue
    channel.sendToQueue('device_status_queue', Buffer.from(JSON.stringify(aggregatedMetrics)));
}

// Error handling and retry logic
const CircuitBreaker = require('opossum');

const deviceStatusCircuitBreaker = new CircuitBreaker(fetchDeviceStatus, {
    timeout: 3000,
    errorThresholdPercentage: 50,
    resetTimeout: 10000
});

deviceStatusCircuitBreaker.on('open', () => {
    console.log('Device status service is now open');
});

deviceStatusCircuitBreaker.on('halfOpen', () => {
    console.log('Device status service is now half-open');
});

deviceStatusCircuitBreaker.on('close', () => {
    console.log('Device status service is now closed');
});

// Schedule periodic updates
setInterval(() => {
    deviceStatusCircuitBreaker.fire();
}, 1000);

app.listen(3000, () => {
    console.log('Microservice listening on port 3000');
});
