// Include necessary headers
#include <iostream>
#include <mutex>
#include <unordered_map>
#include <thread>
#include <chrono>
#include <condition_variable>

// Define the CacheEntry struct to hold data and metadata
struct CacheEntry {
    int value;
    std::time_t expirationTime;

    CacheEntry(int val, std::time_t exp) : value(val), expirationTime(exp) {}
};

// Define the Cache class
class Cache {
private:
    std::unordered_map<std::string, CacheEntry> cacheMap;
    mutable std::mutex mtx;
    std::condition_variable cv;

public:
    // Method to set a key-value pair in the cache with TTL
    void set(const std::string& key, int value, std::time_t ttl) {
        std::unique_lock<std::mutex> lock(mtx);
        cacheMap[key] = CacheEntry(value, time(nullptr) + ttl);
        cv.notify_all();
    }

    // Method to get a value by key from the cache
    int get(const std::string& key) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this, &key]() {
            auto it = cacheMap.find(key);
            return it != cacheMap.end() && time(nullptr) < it->second.expirationTime;
        });
        if (cacheMap.find(key) == cacheMap.end()) {
            return -1; // Key not found or expired
        }
        return cacheMap[key].value;
    }

    // Method to remove a key from the cache
    void remove(const std::string& key) {
        std::unique_lock<std::mutex> lock(mtx);
        cacheMap.erase(key);
        cv.notify_all();
    }

    // Method to clear all entries from the cache
    void clear() {
        std::unique_lock<std::mutex> lock(mtx);
        cacheMap.clear();
        cv.notify_all();
    }
};

// Main function to demonstrate usage
int main() {
    Cache myCache;
    myCache.set("key1", 42, 60); // Set key1 with value 42 and TTL of 60 seconds

    std::this_thread::sleep_for(std::chrono::seconds(30)); // Wait for 30 seconds
    int value = myCache.get("key1"); // Retrieve value after 30 seconds
    std::cout << "Value: " << value << std::endl;

    myCache.remove("key1"); // Remove key1 from the cache

    value = myCache.get("key1"); // Retrieve value of removed key
    std::cout << "Value: " << value << std::endl; // Output should be -1 (not found)

    return 0;
}
```

This code provides a basic implementation of an in-memory cache with thread-safe operations and TTL support. It includes methods to set, get, remove, and clear entries from the cache. The `main` function demonstrates how to use these methods.

Note: This is a simplified version for demonstration purposes. In a real-world application, you would need to implement additional features such as adaptive eviction policies, external key-value store integration, serialization framework, testing frameworks, and more.']

