    virtual bool isAvailable() const = 0;
    virtual ~ExternalService() {}
};

// In-memory implementation of ExternalService
class MemoryService : public ExternalService {
public:
    void ingest(const UserActivityLog& log) override {
        std::lock_guard<std::mutex> lock(mutex_);
        logs_.push_back(log);
    }
    bool isAvailable() const override { return true; }

private:
