int loadResourceBundle(const std::string& filePath) {
    std::ifstream file(filePath);
    if (!file.is_open()) {
        return -1; // Error: File not found or could not be opened.
    }

    int itemCount = 0;
    std::string line;
    while (std::getline(file, line)) {
        if (!line.empty()) {
            itemCount++;
        }
    }

    file.close();
    return itemCount;
}

int main() {
    const std::string resourceFilePath = "path/to/resource/bundle.txt";
    int itemCount = loadResourceBundle(resourceFilePath);

    if (itemCount == -1) {
        std::cerr << "Failed to load resource bundle." << std::endl;
        return 1; // Error code for failure.
    }

    std::cout << "Number of items in the resource bundle: " << itemCount << std::endl;

    return 0;
}
