use std::sync::{Arc, Mutex};
use tokio::sync::mpsc;
use tokio::task;
use tokio::time::{self, Duration};
use bytes::BytesMut;

struct ConfigServiceClient {
    url: String,
    client: reqwest::Client,
}

impl ConfigServiceClient {
    fn new(url: String) -> Self {
        ConfigServiceClient {
            url,
            client: reqwest::Client::new(),
        }
    }

    async fn fetch_grammar(&self, config_id: &str) -> Result<String, Box<dyn std::error::Error>> {
        let response = self.client.get(format!("{}/grammar/{}", self.url, config_id)).send().await?;
        if response.status().is_success() {
            Ok(response.text().await?)
        } else {
            Err("Failed to fetch grammar".into())
        }
    }
}

struct GrammarParser {
    grammars: Arc<Mutex<Vec<String>>>,
    service_client: ConfigServiceClient,
}

impl GrammarParser {
    fn new(service_client_url: String) -> Self {
        GrammarParser {
            grammars: Arc::new(Mutex::new(Vec::new())),
            service_client: ConfigServiceClient::new(service_client_url),
        }
    }

    async fn load_grammars(&self, config_ids: &[&str]) -> Result<(), Box<dyn std::error::Error>> {
        for config_id in config_ids {
            let grammar = self.service_client.fetch_grammar(config_id).await?;
            self.grammars.lock().unwrap().push(grammar);
        }
        Ok(())
    }

    async fn parse_file(&self, file_path: &str) -> Result<(), Box<dyn std::error::Error>> {
        // Simulate file parsing with grammar
        let grammars = self.grammars.lock().unwrap();
        for grammar in grammars.iter() {
            println!("Parsing file {} with grammar: {}", file_path, grammar);
        }
        Ok(())
    }

    async fn process_files(&self, file_paths: &[&str]) -> Result<(), Box<dyn std::error::Error>> {
        let (tx, mut rx) = mpsc::channel(32);

        for &file_path in file_paths.iter() {
            let tx = tx.clone();
            task::spawn(async move {
                if let Err(e) = self.parse_file(file_path).await {
                    tx.send(Err(e)).await.unwrap();
                } else {
                    tx.send(Ok(file_path.to_string())).await.unwrap();
                }
            });
        }

        while let Some(result) = rx.recv().await {
            match result {
                Ok(file_path) => println!("Processed file: {}", file_path),
                Err(e) => eprintln!("Error processing file: {:?}", e),
            }
        }

        Ok(())
    }
}

#[tokio::main]
