    int device_id;
    int signal_strength;
    int *error_codes;
    int error_count;
} DeviceStatusReport;

DeviceStatusReport reports[MAX_REPORTS];
int report_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_report(DeviceStatusReport report) {
    pthread_mutex_lock(&mutex);
    if (report_count < MAX_REPORTS) {
        reports[report_count++] = report;
    }
    pthread_mutex_unlock(&mutex);
}

DeviceStatusReport* get_report(int device_id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < report_count; i++) {
        if (reports[i].device_id == device_id) {
            pthread_mutex_unlock(&mutex);
            return &reports[i];
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void update_report(DeviceStatusReport new_report) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < report_count; i++) {
        if (reports[i].device_id == new_report.device_id) {
            reports[i] = new_report;
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    pthread_mutex_unlock(&mutex);
}

