#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPICRCQueue;

NFAPICRCQueue* nfapi_crc_queue_create() {
    NFAPICRCQueue *queue = (NFAPICRCQueue*)malloc(sizeof(NFAPICRCQueue));
    if (!queue) return NULL;

    queue->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!queue->elements) {
        free(queue);
        return NULL;
    }

    queue->size = 0;
    queue->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&queue->lock, NULL);

    return queue;
}

void nfapi_crc_queue_destroy(NFAPICRCQueue *queue) {
    if (queue) {
        free(queue->elements);
        pthread_mutex_destroy(&queue->lock);
        free(queue);
    }
}

int nfapi_crc_queue_push(NFAPICRCQueue *queue, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&queue->lock);

    if (queue->size >= queue->capacity) {
        size_t new_capacity = queue->capacity == 0 ? 1 : queue->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(queue->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&queue->lock);
            return -1; // Memory allocation failure
        }
        queue->elements = new_elements;
        queue->capacity = new_capacity;
    }

    queue->elements[queue->size++] = pdu;

    pthread_mutex_unlock(&queue->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T nfapi_crc_queue_pop(NFAPICRCQueue *queue) {
    NFAPI_CRC_INDICATION_PDU_T pdu = {0};
    pthread_mutex_lock(&queue->lock);

    if (queue->size > 0) {
        pdu = queue->elements[--queue->size];
    }

    pthread_mutex_unlock(&queue->lock);
    return pdu;
}

int main() {
    NFAPICRCQueue *queue = nfapi_crc_queue_create();
    if (!queue) {
        fprintf(stderr, "Failed to create CRC queue\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = {12345, 0x1234, 0x01};
    nfapi_crc_queue_push(queue, pdu);

    NFAPI_CRC_INDICATION_PDU_T received_pdu = nfapi_crc_queue_pop(queue);
    if (received_pdu.RX_UE_INFORMATION_TAG != 12345) {
        fprintf(stderr, "CRC queue pop failed\n");
        nfapi_crc_queue_destroy(queue);
        return 1;
    }

    nfapi_crc_queue_destroy(queue);
    return 0;
}
```']

