ModuleState* module_init(size_t initial_capacity, size_t num_dbs) {
    ModuleState* state = (ModuleState*)malloc(sizeof(ModuleState));
    state->records.capacity = initial_capacity;
    state->records.data = (Record*)malloc(initial_capacity * sizeof(Record));
    state->records.size = 0;
    pthread_mutex_init(&state->mutex, NULL);
    state->db_connections = (MYSQL**)malloc(num_dbs * sizeof(MYSQL*));
    for (size_t i = 0; i < num_dbs; ++i) {
        state->db_connections[i] = mysql_init(NULL);
    }
    state->num_dbs = num_dbs;
    return state;
}

void module_insert(ModuleState* state, Record record) {
    pthread_mutex_lock(&state->mutex);
    if (state->records.size >= state->records.capacity) {
        size_t new_capacity = state->records.capacity * 2;
        state->records.data = realloc(state->records.data, new_capacity * sizeof(Record));
        state->records.capacity = new_capacity;
    }
    state->records.data[state->records.size++] = record;
    pthread_mutex_unlock(&state->mutex);
}

void module_process(ModuleState* state) {
    for (size_t i = 0; i < state->records.size; ++i) {
        Record record = state->records.data[i];
        for (size_t j = 0; j < state->num_dbs; ++j) {
            MYSQL* db_connection = state->db_connections[j];
            if (mysql_query(db_connection, "INSERT INTO records (offset, key, crc_indication_rel8_tag) VALUES (?, ?, ?)") != 0) {
                fprintf(stderr, "MySQL Error: %s\n", mysql_error(db_connection));
            }
        }
    }
}

void module_cleanup(ModuleState* state) {
    pthread_mutex_destroy(&state->mutex);
    free(state->records.data);
    for (size_t i = 0; i < state->num_dbs; ++i) {
        mysql_close(state->db_connections[i]);
    }
    free(state->db_connections);
    free(state);
}
