NFAPI_CRC_INDICATION_PDU_T* create_crc_indication() {
    NFAPI_CRC_INDICATION_PDU_T *indication;

    pthread_mutex_lock(&mutex);
    while (current_index >= MAX_CRC_INDICATIONS && indication_count == MAX_CRC_INDICATIONS) {
        pthread_cond_wait(&cond_var, &mutex);
    }

    if (current_index >= MAX_CRC_INDICATIONS) {
        log_error("Maximum CRC indications reached");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    indication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indication) {
        log_error("Memory allocation failed for CRC indication");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Initialize the structure fields here

    crc_indications[current_index++] = indication;
    indication_count++;
    pthread_cond_signal(&cond_var);
    pthread_mutex_unlock(&mutex);

    return indication;
}

void destroy_crc_indication(NFAPI_CRC_INDICATION_PDU_T *indication) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < current_index; i++) {
        if (crc_indications[i] == indication) {
            free(indication);
            crc_indications[i] = crc_indications[--current_index];
            break;
        }
    }

    if (indication_count > 0) {
        indication_count--;
    } else {
        log_error("Attempt to destroy non-existent CRC indication");
    }

    pthread_cond_signal(&cond_var);
    pthread_mutex_unlock(&mutex);
}

