#include <iostream>
#include <vector>
#include <queue>
#include <unordered_set>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <memory>

// Forward declarations
class NotificationService;
class DeliveryService;

// Interface for delivery services
class IDeliveryService {
public:
    virtual ~IDeliveryService() = default;
    virtual bool deliver(const std::string& message) = 0;
};

// Concrete delivery service implementations (e.g., SMS, Email)
class SmsDeliveryService : public IDeliveryService {
public:
    bool deliver(const std::string& message) override {
        // Simulate SMS delivery
        std::cout << "Sending SMS: " << message << std::endl;
        return true;
    }
};

class EmailDeliveryService : public IDeliveryService {
public:
    bool deliver(const std::string& message) override {
        // Simulate email delivery
        std::cout << "Sending Email: " << message << std::endl;
        return true;
    }
};

// Notification event structure
struct NotificationEvent {
    std::string message;
    int priority;
    IDeliveryService* service;
};

// Prioritizing queue for notifications
class PriorityQueue : public std::priority_queue<NotificationEvent, std::vector<NotificationEvent>, std::greater<NotificationEvent>> {
public:
    bool try_pop(NotificationEvent& event) {
        if (this->empty()) return false;
        event = this->top();
        this->pop();
        return true;
    }
};

// Notification service to manage delivery and prioritization
class NotificationService {
private:
    std::mutex queue_mutex_;
    std::condition_variable condition_;
    PriorityQueue pq_;
    std::vector<std::thread> workers_;
    bool stop_;

public:
    NotificationService(size_t num_workers) : stop_(false) {
        for (size_t i = 0; i < num_workers; ++i) {
            workers_.emplace_back([this] {
                while (true) {
                    NotificationEvent event;
                    std::unique_lock<std::mutex> lock(queue_mutex_);
                    condition_.wait(lock, [this] { return !pq_.empty() || stop_; });
                    if (stop_ && pq_.empty()) break;
                    pq_.try_pop(event);
                    lock.unlock();
                    if (event.service->deliver(event.message)) {
                        std::cout << "Notification delivered: " << event.message << std::endl;
                    } else {
                        std::cout << "Delivery failed for notification: " << event.message << std::endl;
                    }
                }
            });
        }
    }

    ~NotificationService() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex_);
            stop_ = true;
        }
        condition_.notify_all();
        for (auto& worker : workers_) {
            worker.join();
        }
    }

    void publish(const std::string& message, int priority, IDeliveryService* service) {
        NotificationEvent event{message, priority, service};
        std::lock_guard<std::mutex> lock(queue_mutex_);
        pq_.push(event);
        condition_.notify_one();
    }
};

// Example usage
int main() {
    NotificationService ns(5);

    SmsDeliveryService sms_service;
    EmailDeliveryService email_service;

    ns.publish("Hello via SMS", 1, &sms_service);
    ns.publish("Hello via Email", 2, &email_service);
    ns.publish("Critical Error", 3, &sms_service);

    return 0;
}
```']

