    void subscribe(const std::string& user, const std::string& notificationType);
    void unsubscribe(const std::string& user, const std::string& notificationType);
    bool isSubscribed(const std::string& user, const std::string& notificationType);

private:
    std::unordered_map<std::string, std::set<std::string>> subscriptions;
};

class NotificationQueue {
public:
    void push(const std::string& user, const std::string& message, int priority);
    std::vector<std::pair<std::string, std::string>> pop(int batchSize);

private:
    std::priority_queue<std::tuple<int, std::string, std::string>, std::vector<std::tuple<int, std::string, std::string>>, std::greater<>> queue;
};

class NotificationService {
public:
    void sendNotification(const std::string& user, const std::string& message);
    void start();
    void stop();

private:
    SubscriptionManager subscriptionManager;
    NotificationQueue notificationQueue;
    std::vector<std::thread> workers;
    std::condition_variable cv;
    std::mutex mtx;
    bool running = false;
};

class ExternalDeliveryProvider {
public:
    bool deliver(const std::string& user, const std::string& message);
};

// Implementation details for SubscriptionManager
void SubscriptionManager::subscribe(const std::string& user, const std::string& notificationType) {
    subscriptions[user].insert(notificationType);
}

void SubscriptionManager::unsubscribe(const std::string& user, const std::string& notificationType) {
    subscriptions[user].erase(notificationType);
}

bool SubscriptionManager::isSubscribed(const std::string& user, const std::string& notificationType) {
    return subscriptions.find(user) != subscriptions.end() && subscriptions[user].find(notificationType) != subscriptions[user].end();
}

// Implementation details for NotificationQueue
void NotificationQueue::push(const std::string& user, const std::string& message, int priority) {
    queue.emplace(priority, user, message);
}

std::vector<std::pair<std::string, std::string>> NotificationQueue::pop(int batchSize) {
    std::vector<std::pair<std::string, std::string>> notifications;
    for (int i = 0; i < batchSize && !queue.empty(); ++i) {
        notifications.emplace_back(std::get<1>(queue.top()), std::get<2>(queue.top()));
        queue.pop();
    }
    return notifications;
}

// Implementation details for NotificationService
void NotificationService::sendNotification(const std::string& user, const std::string& message) {
    if (subscriptionManager.isSubscribed(user, "email")) {
        ExternalDeliveryProvider provider;
        provider.deliver(user, message);
    }
}

void NotificationService::start() {
    running = true;
    for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
        workers.emplace_back([this]() {
            while (true) {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [this] { return !running || !notificationQueue.queue.empty(); });
                if (!running && notificationQueue.queue.empty()) break;
                auto notifications = notificationQueue.pop(10);
                lock.unlock();
                for (const auto& [user, message] : notifications) {
                    sendNotification(user, message);
                }
            }
        });
    }
}

void NotificationService::stop() {
    running = false;
    cv.notify_all();
    for (auto& worker : workers) {
        worker.join();
    }
}
