// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new record
void addRecord(int RNTI, long offset, int key) {
    pthread_mutex_lock(&mutex);
    if (currentSize >= maxSize) {
        Record** temp = realloc(recordArray, sizeof(Record*) * (maxSize + 1000));
        if (temp == NULL) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        recordArray = temp;
        maxSize += 1000;
    }
    Record* newRecord = malloc(sizeof(Record));
    newRecord->RNTI = RNTI;
    newRecord->offset = offset;
    newRecord->key = key;
    recordArray[currentSize++] = newRecord;
    pthread_mutex_unlock(&mutex);
}

// Function to save records to database
void saveToDatabase(const char* db_url) {
    sqlite3* db;
    int rc = sqlite3_open(db_url, &db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return;
