            printf("Processing record: RNTI=%d, offset=%ld, key=%d\n", 
                   record->RNTI, record->offset, record->key);
        }
        saveToDatabase("path_to_your_db.db");
        sleep(1); // Simulate periodic updates
    }
    return NULL;
}

int main() {
