#include <iostream>
#include <vector>
#include <queue>
#include <unordered_map>
#include <functional>
#include <future>
#include <mutex>
#include <condition_variable>

class NotificationSystem {
public:
    void subscribe(int userId, std::function<void(const std::string&)> callback) {
        std::lock_guard<std::mutex> lock(mutex_);
        subscribers_[userId] = callback;
    }

    void unsubscribe(int userId) {
        std::lock_guard<std::mutex> lock(mutex_);
        subscribers_.erase(userId);
    }

    void sendNotification(const std::string& message, int priority, bool deduplicate = true) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (deduplicate && recentMessages_.find(message) != recentMessages_.end()) {
            return;
        }
        notifications_.emplace(priority, message);
        recentMessages_[message] = true;
        lock.unlock();
        cv_.notify_one();
    }

private:
    std::mutex mutex_;
    std::condition_variable cv_;
    std::unordered_map<int, std::function<void(const std::string&)>> subscribers_;
    std::priority_queue<std::pair<int, std::string>, std::vector<std::pair<int, std::string>>, std::greater<>> notifications_;
    std::unordered_set<std::string> recentMessages_;
};

class NotificationWorker {
public:
    NotificationWorker(NotificationSystem& system) : system_(system), running_(true) {
        thread_ = std::thread(&NotificationWorker::run, this);
    }

    ~NotificationWorker() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            running_ = false;
        }
        cv_.notify_one();
        thread_.join();
    }

private:
    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !running_ || !system_.notifications_.empty(); });
            if (!running_ && system_.notifications_.empty()) {
                break;
            }
            int priority;
            std::string message;
            if (system_.notifications_.top().first == priority) {
                message = system_.notifications_.top().second;
                system_.notifications_.pop();
            } else {
                // Handle prioritization logic here
                continue;
            }

            lock.unlock();

            for (const auto& subscriber : subscribers_) {
                subscriber.second(message);
            }
        }
    }

private:
    NotificationSystem& system_;
    std::thread thread_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::unordered_map<int, std::function<void(const std::string&)>> subscribers_;
};

int main() {
    NotificationSystem system;
    NotificationWorker worker(system);

    // Example usage
    system.subscribe(1, [](const std::string& message) { std::cout << "User 1: " << message << std::endl; });
    system.subscribe(2, [](const std::string& message) { std::cout << "User 2: " << message << std::endl; });

    system.sendNotification("Hello User 1!", 5);
    system.sendNotification("Hello User 2!", 3);
    system.sendNotification("Important Update!", 7);

    return 0;
}
