#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_RECORDS 10000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    // Other fields as needed
} Record;

typedef struct {
    Record *records;
    int size;
    pthread_mutex_t mutex;
    sem_t full, empty;
} SharedQueue;

SharedQueue queue;

void init_queue() {
    queue.records = (Record *)malloc(MAX_RECORDS * sizeof(Record));
    queue.size = 0;
    pthread_mutex_init(&queue.mutex, NULL);
    sem_init(&queue.full, 0, 0);
    sem_init(&queue.empty, 0, MAX_RECORDS);
}

void enqueue(Record record) {
    sem_wait(&queue.empty);
    pthread_mutex_lock(&queue.mutex);
    queue.records[queue.size++] = record;
    pthread_mutex_unlock(&queue.mutex);
    sem_post(&queue.full);
}

int dequeue(Record *record) {
    sem_wait(&queue.full);
    pthread_mutex_lock(&queue.mutex);
    if (queue.size > 0) {
        *record = queue.records[--queue.size];
    } else {
        pthread_mutex_unlock(&queue.mutex);
        sem_post(&queue.empty);
        return -1;
    }
    pthread_mutex_unlock(&queue.mutex);
    sem_post(&queue.empty);
    return 0;
}

void destroy_queue() {
    free(queue.records);
    pthread_mutex_destroy(&queue.mutex);
    sem_destroy(&queue.full);
    sem_destroy(&queue.empty);
}
```

This code defines a simple thread-safe queue using a dynamic array to manage records. It includes functions for initializing the queue, enqueuing records, dequeuing records, and destroying the queue. The use of semaphores ensures that the queue is not accessed concurrently by multiple threads, preventing race conditions. This setup can be integrated into a larger system as described in the task requirements.']

