class NotificationService {
public:
    void subscribe(int userId, std::string event) {
        std::lock_guard<std::mutex> lock(mutex_);
        subscriptions_[userId].insert(event);
    }

    void unsubscribe(int userId, std::string event) {
        std::lock_guard<std::mutex> lock(mutex_);
        subscriptions_[userId].erase(event);
    }

    void notify(int userId, std::string message) {
        if (subscriptions_.find(userId) != subscriptions_.end()) {
            for (auto& observer : observers_) {
                observer->update(userId, message);
            }
        }
    }

private:
    std::unordered_map<int, std::unordered_set<std::string>> subscriptions_;
    std::vector<Observer*> observers_;
    std::mutex mutex_;
};

class Observer {
public:
    virtual void update(int userId, std::string message) = 0;
    virtual ~Observer() {}
};

class EmailService : public Observer {
public:
    void update(int userId, std::string message) override {
        // Logic to send email
        std::cout << "Sending email to user " << userId << ": " << message << std::endl;
    }
};

class SMSService : public Observer {
public:
    void update(int userId, std::string message) override {
        // Logic to send SMS
        std::cout << "Sending SMS to user " << userId << ": " << message << std::endl;
    }
};

int main() {
    NotificationService service;
    EmailService emailObserver;
    SMSService smsObserver;

    service.registerObserver(&emailObserver);
    service.registerObserver(&smsObserver);

    service.notify(1, "Welcome to our service!");
    service.notify(2, "Your order has been shipped.");

    return 0;
}
