        pthread_mutex_unlock(&data_buffer.lock);
        usleep(1000); // Sleep for a short time before checking again
    }
    return NULL;
}

void add_record(NFAPI_CRC_INDICATION_PDU_T *record) {
    pthread_mutex_lock(&data_buffer.lock);
    if (data_buffer.count >= MAX_RECORDS) {
