```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <queue>
#include <functional>
#include <future>

// Define NFAPI structures (simplified for example purposes)
struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t rnti;
    bool crcPass;
};

// Thread-safe queue for incoming reports
class SafeQueue {
private:
    std::queue<NFAPI_CRC_INDICATION_PDU_T> queue_;
    mutable std::mutex mutex_;
    std::condition_variable cond_;

public:
    void push(const NFAPI_CRC_INDICATION_PDU_T& item) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(item);
        cond_.notify_one();
    }

    bool pop(NFAPI_CRC_INDICATION_PDU_T& item, std::chrono::milliseconds timeout = std::chrono::milliseconds(100)) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (cond_.wait_for(lock, timeout, [this]{ return !queue_.empty(); })) {
            item = queue_.front();
            queue_.pop();
            return true;
        }
        return false;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.empty();
    }
};

// CRC validator function
void validateCRC(const NFAPI_CRC_INDICATION_PDU_T& report) {
    if (!report.crcPass) {
        std::cout << "CRC failure for RNTI: " << report.rnti << std::endl;
    } else {
        std::cout << "CRC pass for RNTI: " << report.rnti << std::endl;
    }
}

// Worker thread function
void workerThread(SafeQueue& queue) {
    NFAPI_CRC_INDICATION_PDU_T report;
    while (true) {
        if (queue.pop(report)) {
            validateCRC(report);
        } else {
            // Handle timeout, e.g., sleep briefly
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }
}

// Start worker threads
void startWorkerThreads(SafeQueue& queue, size_t numThreads) {
    for (size_t i = 0; i < numThreads; ++i) {
        std::thread(workerThread, std::ref(queue)).detach();
    }
}
