using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;

[ApiController]
[Route("api/[controller]")]
public class ComponentConfigController : ControllerBase
{
    private readonly HttpClient _httpClient;
    private readonly CircuitBreaker _circuitBreaker;

    public ComponentConfigController(HttpClient httpClient)
    {
        _httpClient = httpClient;
        _circuitBreaker = new CircuitBreaker();
    }

    [HttpPost("bulk-update")]
    public async Task<IActionResult> BulkUpdate([FromBody] List<ComponentConfig> configs)
    {
        try
        {
            var tasks = new List<Task<bool>>();
            foreach (var config in configs)
            {
                tasks.Add(_circuitBreaker.ExecuteAsync(() => FetchAndPersistConfig(config)));
            }

            await Task.WhenAll(tasks);

            return Ok();
        }
        catch (Exception ex)
        {
            return StatusCode(500, "Internal Server Error: " + ex.Message);
        }
    }

    private async Task<bool> FetchAndPersistConfig(ComponentConfig config)
    {
        try
        {
            var response = await _httpClient.GetAsync($"https://api.example.com/configs/{config.Id}");
            if (response.IsSuccessStatusCode)
            {
                // Process and persist config
                return true;
            }
            else
            {
                return false;
            }
        }
        catch (Exception)
        {
            // Handle exception, possibly log it and retry
            throw new Exception("Failed to fetch or persist config");
        }
    }

    public class CircuitBreaker
    {
        private readonly object _lock = new object();
        private bool _isOpen = false;
        private DateTime? _lastClosedTime;

        public async Task<T> ExecuteAsync<T>(Func<Task<T>> action)
        {
            while (true)
            {
                lock (_lock)
                {
                    if (!_isOpen)
                    {
                        try
                        {
                            return await action();
                        }
                        catch (Exception)
                        {
                            OpenCircuit();
                        }
                    }

                    var waitTime = CalculateWaitTime(_lastClosedTime);
                    if (waitTime == TimeSpan.Zero)
                    {
                        _isOpen = false;
                    }
                }

                await Task.Delay(waitTime);
            }
        }

        private void OpenCircuit()
        {
            _isOpen = true;
            _lastClosedTime = DateTime.UtcNow;
        }

        private TimeSpan CalculateWaitTime(DateTime? lastClosedTime)
        {
            if (lastClosedTime.HasValue)
            {
                var timeSinceLastClose = DateTime.UtcNow - lastClosedTime.Value;
                return TimeSpan.FromSeconds(Math.Pow(2, Math.Min(timeSinceLastClose.TotalSeconds / 30, 5)));
            }
            return TimeSpan.Zero;
        }
    }

    public class ComponentConfig
    {
        public int Id { get; set; }
        // Other properties
    }
}
