    max_pool_size: usize,
    connection_timeout: Duration,
}

impl ConnectionManager {
    fn new(max_pool_size: usize, connection_timeout: Duration) -> Self {
        let mut clients = HashMap::new();
        // Initialize clients for different service URLs
        clients.insert("service1".to_string(), Client::builder().build().unwrap());
        clients.insert("service2".to_string(), Client::builder().build().unwrap());

        ConnectionManager {
            clients,
            max_pool_size,
            connection_timeout,
        }
    }

    async fn fetch_user_profile(&self, service_url: &str, user_id: u64) -> Result<UserProfile, AppError> {
        let client = self.clients.get(service_url).ok_or(AppError::ServiceUnavailable)?;
        let response = client
            .get(format!("{}/users/{}", service_url, user_id))
            .timeout(self.connection_timeout)
            .send()
            .await?;

        if response.status() == StatusCode::OK {
            // Parse the JSON response into a UserProfile object
            response.json().await.map_err(AppError::RequestFailed)
        } else {
            Err(AppError::ServiceUnavailable)
        }
    }

    // Other methods for updating and archiving user profiles can be implemented here
}

// Define a struct to manage the application state
struct AppState {
    connection_manager: Arc<ConnectionManager>,
}

impl AppState {
    fn new() -> Self {
        let connection_manager = ConnectionManager::new(10, Duration::from_secs(5));
        AppState {
            connection_manager: Arc::new(connection_manager),
        }
    }

    async fn handle_request(&self, user_id: u64) -> Result<UserProfile, AppError> {
        // Route the request to a healthy service
        let services = ["service1", "service2"];
        for &service in services.iter() {
            if let Ok(profile) = self.connection_manager.fetch_user_profile(service, user_id).await {
                return Ok(profile);
            }
        }

        Err(AppError::ServiceUnavailable)
    }
}

#[tokio::main]
