mod cache {
    use std::collections::{HashMap, VecDeque};

    pub struct LRUCache<K, V> {
        capacity: usize,
        map: HashMap<K, (V, usize)>,
        queue: VecDeque<usize>,
        next_id: usize,
    }

    impl<K: Eq + std::hash::Hash, V> LRUCache<K, V> {
        pub fn new(capacity: usize) -> Self {
            LRUCache {
                capacity,
                map: HashMap::new(),
                queue: VecDeque::new(),
                next_id: 0,
            }
        }

        pub fn get(&mut self, key: &K) -> Option<&V> {
            if let Some((value, id)) = self.map.get(key).cloned() {
                self.queue.retain(|&i| i != id);
                self.queue.push_back(id);
                return Some(value);
            }
            None
        }

        pub fn insert(&mut self, key: K, value: V) {
            if let Some((_, id)) = self.map.insert(key.clone(), (value, self.next_id)) {
                self.queue.retain(|&i| i != id);
            } else if self.map.len() >= self.capacity {
                if let Some(id) = self.queue.pop_front() {
                    self.map.remove(&id);
                }
            }
            self.queue.push_back(self.next_id);
            self.next_id += 1;
        }
    }
}

mod rate_limiter {
    use std::sync::{Arc, Mutex};
    use std::time::{Duration, Instant};

    pub struct RateLimiter {
        limit: usize,
        interval: Duration,
        remaining_tokens: Arc<Mutex<Vec<Instant>>>,
    }

    impl RateLimiter {
        pub fn new(limit: usize, interval: Duration) -> Self {
            RateLimiter {
                limit,
                interval,
                remaining_tokens: Arc::new(Mutex::new(Vec::new())),
            }
        }

        pub async fn acquire_token(&self) -> bool {
            let mut tokens = self.remaining_tokens.lock().unwrap();
            while tokens.len() > 0 && tokens[0] + self.interval < Instant::now() {
                tokens.remove(0);
            }
            if tokens.len() >= self.limit {
                return false;
            }
            tokens.push(Instant::now());
            true
        }
    }
}

mod resource_accounting {
