        pub fn new() -> Self {
            ResourceAccounting {
                usage: Arc::new(Mutex::new(HashMap::new())),
            }
        }

        pub async fn record_usage(&self, resource_name: &str, amount: u64) {
            let mut usage = self.usage.lock().unwrap();
            *usage.entry(resource_name.to_string()).or_insert(0) += amount;
        }

        pub async fn get_usage(&self, resource_name: &str) -> Option<u64> {
            let usage = self.usage.lock().unwrap();
            usage.get(resource_name).cloned()
        }
    }
}

