#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define the DeviceStatusReport structure
typedef struct {
    time_t timestamp;
    char deviceId[256];
    int signalStrength;
    int errorCodes[100];
} DeviceStatusReport;

// Define a node for the linked list of DeviceStatusReports
typedef struct Node {
    DeviceStatusReport data;
    struct Node* next;
} Node;

// Define the head and tail of the linked list
Node* head = NULL;
Node* tail = NULL;

// Mutex for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new report to the list
void addReport(DeviceStatusReport report) {
    pthread_mutex_lock(&mutex);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = report;
    newNode->next = NULL;
    if (head == NULL) {
        head = newNode;
        tail = newNode;
    } else {
        tail->next = newNode;
        tail = newNode;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to remove a report from the list
void removeReport(DeviceStatusReport report) {
    pthread_mutex_lock(&mutex);
    Node* current = head;
    Node* previous = NULL;
    while (current != NULL) {
        if (current->data.timestamp == report.timestamp &&
            strcmp(current->data.deviceId, report.deviceId) == 0) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to find a report in the list
Node* findReport(DeviceStatusReport report) {
    pthread_mutex_lock(&mutex);
    Node* current = head;
    while (current != NULL) {
        if (current->data.timestamp == report.timestamp &&
            strcmp(current->data.deviceId, report.deviceId) == 0) {
            pthread_mutex_unlock(&mutex);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Function to create a new state list from an FSA
Node* createStateList(Node* fsaStates, int numStates) {
    Node* newStateList = NULL;
    for (int i = 0; i < numStates; i++) {
        DeviceStatusReport report = {time(NULL), "device" + i, rand() % 100, {rand() % 100}};
        addReport(report);
        if (newStateList == NULL) {
            newStateList = findReport(report);
        }
    }
    return newStateList;
}

// Main function to demonstrate the library's functionality
