    // Create some reports and add them to the list
    DeviceStatusReport report1 = {time(NULL), "device1", 90, {1, 2}};
    DeviceStatusReport report2 = {time(NULL), "device2", 85, {3}};
    addReport(report1);
    addReport(report2);

