struct SensorReading {
    std::chrono::system_clock::time_point timestamp;
    int sensorID;
    std::pair<double, double> location;
    std::string units;
    std::string firmwareVersion;
    std::string calibrationSettings;
};

class SensorDataLibrary {
public:
    void addSensorReading(const SensorReading& reading) {
        std::lock_guard<std::mutex> lock(mutex_);
        sensorReadings_.push_back(reading);
        condition_.notify_one();
    }

    void addIngestionService(std::function<void()> service, std::string serviceName) {
        ingestionServices_[serviceName] = service;
    }

    void startProcessing() {
        processingThread_ = std::thread(&SensorDataLibrary::processData, this);
    }

    ~SensorDataLibrary() {
        stopProcessing();
        if (processingThread_.joinable()) {
            processingThread_.join();
        }
    }

private:
    std::mutex mutex_;
    std::condition_variable condition_;
    std::vector<SensorReading> sensorReadings_;
    std::unordered_map<std::string, std::function<void()>> ingestionServices_;
    std::thread processingThread_;

    void processData() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this]() { return !sensorReadings_.empty(); });
            SensorReading reading = sensorReadings_.back();
            sensorReadings_.pop_back();
            lock.unlock();

            for (const auto& service : ingestionServices_) {
                std::thread([service, reading]() {
                    try {
                        service.second(reading);
                    } catch (...) {
                        // Handle exception
                    }
                }).detach();
            }
        }
    }
};

int main() {
    SensorDataLibrary library;
    library.addSensorReading(SensorReading{std::chrono::system_clock::now(), 1, {40.7128, -74.0060}, "Celsius", "v1.0", "none"});
    library.addIngestionService([](const SensorReading& reading) {
        // Handle sensor reading with service A
    }, "serviceA");
    library.startProcessing();

    return 0;
}
