class DoublyLinkedList {
public:
    void insertOrReplace(int id, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = find(id);
        if (it != list_.end()) {
            it->value = value;
        } else {
            Node* newNode = new Node{id, value, nullptr, nullptr};
            if (!list_.empty()) {
                list_.front().prev = newNode;
                newNode->next = &list_.front();
            }
            list_.push_front(*newNode);
        }
    }

private:
    std::mutex mutex_;
    std::vector<Node> list_;

    auto find(int id) -> decltype(list_.begin()) {
        for (auto it = list_.begin(); it != list_.end(); ++it) {
            if (it->id == id) {
                return it;
            }
        }
        return list_.end();
    }
};

