// Include necessary headers
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define DeviceStatusReport structure
typedef struct {
    time_t timestamp;
    int deviceID;
    float signalStrength;
    // List of error codes
    int* errorCodeList;
    int numErrors;
    // Metadata about the report source
    char* sourceMetadata;
} DeviceStatusReport;

// Define DeviceManager structure
typedef struct {
    DeviceStatusReport** reports;
    int capacity;
    int size;
    pthread_mutex_t lock;
} DeviceManager;

// Function to create a new DeviceManager
DeviceManager* createDeviceManager() {
    DeviceManager* manager = (DeviceManager*)malloc(sizeof(DeviceManager));
    manager->reports = NULL;
    manager->capacity = 0;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Function to add a new report to the DeviceManager
void addReport(DeviceManager* manager, DeviceStatusReport* report) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        // Resize the reports array
        manager->capacity *= 2;
        manager->reports = (DeviceStatusReport**)realloc(manager->reports, sizeof(DeviceStatusReport*) * manager->capacity);
    }
    manager->reports[manager->size++] = report;
    pthread_mutex_unlock(&manager->lock);
}

// Function to update an existing report based on deviceID
void updateReport(DeviceManager* manager, int deviceID, DeviceStatusReport* newReport) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->size; i++) {
        if (manager->reports[i]->deviceID == deviceID) {
            // Update the report
            free(manager->reports[i]);
            manager->reports[i] = newReport;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Function to retrieve a report based on deviceID
DeviceStatusReport* getReport(DeviceManager* manager, int deviceID) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->size; i++) {
        if (manager->reports[i]->deviceID == deviceID) {
            DeviceStatusReport* report = manager->reports[i];
            pthread_mutex_unlock(&manager->lock);
            return report;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Function to destroy the DeviceManager
void destroyDeviceManager(DeviceManager* manager) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->size; i++) {
        free(manager->reports[i]);
    }
    free(manager->reports);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
