typedef struct {
    char timestamp[20];
    int device_id;
    float signal_strength;
    int *error_codes;
    int error_count;
    void *metadata;
} DeviceStatusReport;

typedef struct {
    DeviceStatusReport **reports;
    int count;
    pthread_mutex_t lock;
} ReportManager;

void report_manager_init(ReportManager *manager) {
    manager->reports = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void report_manager_add_report(ReportManager *manager, DeviceStatusReport *report) {
    pthread_mutex_lock(&manager->lock);
    manager->reports = realloc(manager->reports, (manager->count + 1) * sizeof(DeviceStatusReport *));
    manager->reports[manager->count++] = report;
    pthread_mutex_unlock(&manager->lock);
}

DeviceStatusReport* report_manager_get_report(ReportManager *manager, int device_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->reports[i]->device_id == device_id) {
            pthread_mutex_unlock(&manager->lock);
            return manager->reports[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void report_manager_update_report(ReportManager *manager, DeviceStatusReport *report) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->reports[i]->device_id == report->device_id) {
            free(manager->reports[i]);
            manager->reports[i] = report;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void report_manager_destroy(ReportManager *manager) {
    for (int i = 0; i < manager->count; i++) {
        free(manager->reports[i]);
    }
    free(manager->reports);
    pthread_mutex_destroy(&manager->lock);
}
