import io.github.resilience4j.circuitbreaker.CircuitBreaker;
import io.github.resilience4j.circuitbreaker.CircuitBreakerConfig;
import io.github.resilience4j.circuitbreaker.CircuitBreakerRegistry;
import io.github.resilience4j.retry.Retry;
import io.github.resilience4j.retry.RetryConfig;

import java.time.Duration;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.stream.IntStream;

public class ErrorLoggingFramework {

    private static final CircuitBreakerRegistry circuitBreakerRegistry = CircuitBreakerRegistry.of();
    private static final ExecutorService executorService = Executors.newCachedThreadPool();

    public static void main(String[] args) {
        CircuitBreaker circuitBreaker = circuitBreakerRegistry.circuitbreaker("errorLogService");
        Retry retry = Retry.ofDefaults();

        IntStream.range(0, 1_000_000)
                .forEach(i -> executorService.submit(() -> logError(circuitBreaker, retry)));
    }

    private static void logError(CircuitBreaker circuitBreaker, Retry retry) {
        try (CircuitBreaker.CircuitBreakerContext context = circuitBreaker.acquireContext()) {
            CompletableFuture.runAsync(() -> {
                try {
                    sendErrorToService(context.getExecution().getExecutionType());
                } catch (Exception e) {
                    context.onResult(e);
                }
            }, executorService).exceptionally(throwable -> {
                context.onResult(throwable);
                return null;
            });
        }
    }

    private static void sendErrorToService(String errorDetails) {
        CircuitBreaker circuitBreaker = circuitBreakerRegistry.circuitbreaker("errorLogService");
        Retry retry = Retry.ofDefaults();

        try (CircuitBreaker.CircuitBreakerContext context = circuitBreaker.acquireContext()) {
            CompletableFuture.runAsync(() -> {
                try {
                    sendErrorToExternalService(errorDetails);
                } catch (Exception e) {
                    context.onResult(e);
                }
            }, executorService).exceptionally(throwable -> {
                context.onResult(throwable);
                return null;
            });
        }
    }

    private static void sendErrorToExternalService(String errorDetails) throws Exception {
        // Simulate sending error to external service
        if (Math.random() < 0.1) {
            throw new RuntimeException("External service outage");
        }
        System.out.println("Logged error: " + errorDetails);
    }

    public static void tearDown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}
