import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cache.CacheManager;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

@Service
public class UserProfileService {

    @Autowired
    private RestTemplate restTemplate;

    @Autowired
    private CacheManager cacheManager;

    public String getUserProfile(String userId, String role) {
        try {
            return cache.get("userProfile:" + userId + ":" + role).get();
        } catch (Exception e) {
            // Handle cache miss or failure to retrieve from cache
            String userProfile = fetchUserProfileFromExternalAPI(userId, role);
            cache.put("userProfile:" + userId + ":" + role, userProfile);
            return userProfile;
        }
    }

