# Define the DocumentManager class
class DocumentManager:
    def __init__(self, storage_service, cache_service):
        self.storage_service = storage_service
        self.cache_service = cache_service

    def upload_document(self, document_id, content, tags):
        # Upload document to S3 or Google Cloud Storage
        self.storage_service.upload(document_id, content)

        # Cache metadata in Redis for quick access
        self.cache_service.set(document_id, {'content': content, 'tags': tags})

    def download_document(self, document_id):
        # Check cache first
        cached_data = self.cache_service.get(document_id)
        if cached_data:
            return cached_data['content']

        # Fall back to storage service
        content = self.storage_service.download(document_id)

        # Cache the retrieved data
        self.cache_service.set(document_id, {'content': content})
        return content

    def resize_and_compress(self, document_id):
        # Resize and compress document using a third-party service
        processed_content = self.document_processing_service.process(document_id)
        self.storage_service.update(document_id, processed_content)

    def categorize_document(self, document_id, new_tags):
        # Update tags in the database and cache
        current_data = self.cache_service.get(document_id)
        current_data['tags'] += new_tags
        self.cache_service.set(document_id, current_data)
        self.storage_service.update(document_id, current_data['content'])

    def version_document(self, document_id, content):
        # Store a new version of the document in storage
        new_version_id = f"{document_id}_v{self.get_latest_version(document_id) + 1}"
        self.storage_service.upload(new_version_id, content)
        return new_version_id

    def get_document_versions(self, document_id):
        # Retrieve all versions of a document from storage
        versions = []
        for version in range(1, self.get_latest_version(document_id) + 2):
            version_id = f"{document_id}_v{version}"
            versions.append(self.storage_service.download(version_id))
        return versions

    def get_latest_version(self, document_id):
        # Determine the latest version number
        max_version = 0
        for key in self.storage_service.list_keys():
            if key.startswith(document_id) and key.endswith('_v'):
                try:
                    version = int(key.split('_v')[-1])
                    if version > max_version:
                        max_version = version
                except ValueError:
                    pass
        return max_version

    def delete_document(self, document_id):
        # Delete the document from storage and cache
        self.storage_service.delete(document_id)
        self.cache_service.delete(document_id)

