from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from sqlalchemy.exc import SQLAlchemyError
import requests

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'postgresql://user:password@localhost/db'
db = SQLAlchemy(app)

class Resource(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    data = db.Column(db.JSON, nullable=False)
    version = db.Column(db.Integer, default=0)

@app.route('/resources/<int:id>', methods=['PUT'])
def update_resource(id):
    resource = Resource.query.filter_by(id=id).first()
    if not resource:
        return jsonify({'error': 'Resource not found'}), 404

    data = request.get_json()
    schema = {
        "type": "object",
        "properties": {
            "field1": {"type": "string"},
            "field2": {"type": "number"}
        },
        "required": ["field1"]
    }

    if not validate_json(data, schema):
        return jsonify({'error': 'Invalid data'}), 400

    if resource.version != request.headers.get('X-Version'):
        return jsonify({'error': 'Conflict', 'message': 'Resource has been updated by another user'}), 409

    resource.data = {**resource.data, **data}
    resource.version += 1
    try:
        db.session.commit()
    except SQLAlchemyError as e:
        return jsonify({'error': 'Database error', 'details': str(e)}), 500

    response = requests.put('https://external-datasource.com/update', json=resource.data)
    if response.status_code != 200:
        return jsonify({'error': 'External datasource error'}), response.status_code

    return jsonify({'message': 'Resource updated successfully', 'data': resource.data}), 200

@app.route('/resources/<int:id>', methods=['DELETE'])
def delete_resource(id):
    resource = Resource.query.filter_by(id=id).first()
    if not resource:
        return jsonify({'error': 'Resource not found'}), 404

    if resource.version != request.headers.get('X-Version'):
        return jsonify({'error': 'Conflict', 'message': 'Resource has been updated by another user'}), 409

    try:
        db.session.delete(resource)
        db.session.commit()
    except SQLAlchemyError as e:
        return jsonify({'error': 'Database error', 'details': str(e)}), 500

    response = requests.post('https://external-datasource.com/delete', json={'id': id})
    if response.status_code != 200:
        return jsonify({'error': 'External datasource error'}), response.status_code

    return jsonify({'message': 'Resource deleted successfully'}), 200

@app.route('/resources/<int:id>', methods=['GET'])
def get_resource(id):
    resource = Resource.query.filter_by(id=id).first()
    if not resource:
        return jsonify({'error': 'Resource not found'}), 404
    return jsonify(resource.data), 200

if __name__ == '__main__':
    app.run(debug=True, threaded=True)
