package com.example.caching;

import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Flux;
import reactor.core.scheduler.Schedulers;

@Service
public class CacheService {

    @Autowired
    private MongoTemplate mongoTemplate;

    @Autowired
    private RedisTemplate<String, String> redisTemplate;

    @KafkaListener(topics = "data-stream", groupId = "cache-group")
    public void consume(ConsumerRecord<String, String> record) {
        Flux.fromStream(Flux.just(record))
            .flatMap(this::processData)
            .subscribeOn(Schedulers.boundedElastic())
            .onErrorResume(Exception.class, e -> handleException(e));
    }

    private Mono<Void> processData(ConsumerRecord<String, String> record) {
        return Mono.fromCallable(() -> {
                    // Process data here
                    String key = record.key();
                    String value = record.value();

                    // Synchronize with NoSQL database
                    mongoTemplate.save(new DataEntity(key, value));

                    // Update cache
                    redisTemplate.opsForValue().set(key, value);

                    return null;
                })
                .onErrorResume(Exception.class, e -> {
                    handleException(e);
                    return Mono.empty();
                });
    }

    private void handleException(Throwable e) {
        // Log the error and retry mechanism here
        System.err.println("Error processing data: " + e.getMessage());
        // Implement retry logic or fallback mechanisms
    }
}
