["```javascript
const fs = require('fs');
const path = require('path');
const axios = require('axios');
const async = require('async');

// Configuration
const MAX_FILES_PER_MINUTE = 10000;
const PROCESSING_TIME_MS = 500;
const API_URL = 'https://example.com/api/endpoint';
const RETRY_DELAY_MS = 1000;

// File processing queue
let fileQueue = [];
let isProcessing = false;

// Function to process files from the queue
function processFileQueue() {
  if (isProcessing || fileQueue.length === 0) return;
  isProcessing = true;

  async.eachSeries(
    fileQueue,
    (file, callback) => {
      fs.readFile(file.path, 'utf8', (err, data) => {
        if (err) {
          console.error(`Error reading file ${file.path}:`, err);
          file.retries++;
          if (file.retries < 3) setTimeout(() => processFileQueue(), RETRY_DELAY_MS);
          return callback();
        }

        let parsedData;
        try {
          parsedData = JSON.parse(data);
        } catch {
          console.error(`Malformed JSON in file ${file.path}`);
          file.retries++;
          if (file.retries < 3) setTimeout(() => processFileQueue(), RETRY_DELAY_MS);
          return callback();
        }

        axios.post(API_URL, parsedData)
          .then(response => {
            console.log(`Processed file ${file.path}:`, response.data);
          })
          .catch(error => {
            console.error(`Error processing file ${file.path}:`, error);
            file.retries++;
            if (file.retries < 3) setTimeout(() => processFileQueue(), RETRY_DELAY_MS);
          })
          .finally(() => {
            callback();
          });
      });
    },
    () => {
      isProcessing = false;
      setTimeout(processFileQueue, PROCESSING_TIME_MS / MAX_FILES_PER_MINUTE);
    }
  );
}

// Function to add a file to the queue
function enqueueFile(file) {
  if (fileQueue.length >= MAX_FILES_PER_MINUTE) return;
  fileQueue.push({ path: file.path, retries: 0 });
  processFileQueue();
}

// Monitor directory for new files and add them to the queue
fs.watch(path.join(__dirname, 'data'), { recursive: true }, (eventType, filename) => {
  if (filename && eventType === 'rename') {
    const filePath = path.join(__dirname, 'data', filename);
    fs.stat(filePath, (err, stats) => {
      if (!err && stats.isFile()) enqueueFile({ path: filePath });
    });
  }
});
