#include <condition_variable>

class CombatSystem {
public:
    CombatSystem(size_t maxCombatants) : maxCombatants(maxCombatants), combatants(maxCombatants, nullptr) {}

    void addCombatant(int id) {
        std::lock_guard<std::mutex> lock(mutex);
        if (id >= 0 && id < maxCombatants && !combatants[id]) {
            combatants[id] = new Combatant(id);
        }
    }

    void performAttack(int attackerId, int defenderId) {
        std::lock_guard<std::mutex> lock(mutex);
        if (attackerId >= 0 && attackerId < maxCombatants && combatants[attackerId]) {
            combatants[attackerId]->performAttack(defenderId);
        }
    }

private:
    struct Combatant {
        int id;
        std::atomic<bool> ready;
        std::mutex cooldownMutex;
        std::condition_variable cooldownCV;

        Combatant(int id) : id(id), ready(false) {}

        void performAttack(int defenderId) {
            std::unique_lock<std::mutex> lock(cooldownMutex);
            if (ready.load()) {
                // Perform attack
                std::cout << "Combatant " << id << " attacks Combatant " << defenderId << std::endl;
                ready.store(false);
                cooldownCV.notify_one();
            } else {
                cooldownCV.wait(lock, [this] { return ready.load(); });
                performAttack(defenderId); // Recursively retry
            }
        }

        void resetCooldown() {
            std::unique_lock<std::mutex> lock(cooldownMutex);
            int delay = 5 + rand() % 11; // 5 to 15 seconds
            std::this_thread::sleep_for(std::chrono::seconds(delay));
            ready.store(true);
        }
    };

    size_t maxCombatants;
    std::vector<Combatant*> combatants;
};

int main() {
    CombatSystem combatSystem(5000);

    for (int i = 0; i < 5000; ++i) {
        combatSystem.addCombatant(i);
    }

    // Simulate attacks
    std::thread attacker([&combatSystem] {
        while (true) {
            for (int i = 0; i < 100; ++i) {
                int defenderId = rand() % 5000;
                combatSystem.performAttack(i, defenderId);
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
    }).detach();

    for (int i = 0; i < 50; ++i) {
        std::thread cooldownThread([&combatSystem] {
            while (true) {
                for (auto& combatant : combatSystem.combatants) {
                    if (combatant && !combatant->ready.load()) {
                        combatant->resetCooldown();
                    }
                }
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        }).detach();
    }

    return 0;
}
```

This code provides a basic structure for the `CombatSystem` library. It includes a `Combatant` class with thread-safe attack logic and cooldown management, as well as a main function to simulate combat interactions. The system supports up to 5000 concurrent combatants and demonstrates how to handle thread synchronization and performance optimization in a real-time combat scenario.']

