#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NetworkEvent {
    time_t timestamp;
    int eventType; // 0 for connection, 1 for disconnection
    int clientId;
    double serverResponseTime;
} NetworkEvent;

typedef struct EventArray {
    NetworkEvent *events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} EventArray;

EventArray *eventArrayCreate(size_t initialCapacity) {
    EventArray *array = (EventArray *)malloc(sizeof(EventArray));
    array->events = (NetworkEvent *)calloc(initialCapacity, sizeof(NetworkEvent));
    array->capacity = initialCapacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void eventArrayDestroy(EventArray *array) {
    free(array->events);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int eventArrayAdd(EventArray *array, NetworkEvent event) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t newCapacity = array->capacity ? array->capacity * 2 : 1;
        NetworkEvent *newEvents = (NetworkEvent *)realloc(array->events, newCapacity * sizeof(NetworkEvent));
        if (!newEvents) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->events = newEvents;
        array->capacity = newCapacity;
    }
    array->events[array->size++] = event;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

void eventArrayCleanup(EventArray *array, time_t retentionTime) {
    pthread_mutex_lock(&array->lock);
    while (array->size > 0 && difftime(array->events[0].timestamp, retentionTime) > 0) {
        memmove(array->events, array->events + 1, (array->size - 1) * sizeof(NetworkEvent));
        --array->size;
    }
    pthread_mutex_unlock(&array->lock);
}

