NFAPI_CRC_INDICATION_PDU_T array[MAX_ELEMENTS];
int count = 0;

void initializeArray() {
    srand(time(NULL));
}

int addElement(unsigned int tag, unsigned short rnti) {
    if (count >= MAX_ELEMENTS) return -1; // Array full
    for (int i = 0; i < count; i++) {
        if (array[i].RX_UE_INFORMATION_TAG == tag) return -2; // Duplicate tag
    }
    array[count].RX_UE_INFORMATION_TAG = tag;
    array[count].RNTI = rnti;
    array[count].CRCFLAG = rand() % 256;
    count++;
    return 0;
}

int updateElement(unsigned int tag, unsigned short new_rnti) {
    for (int i = 0; i < count; i++) {
        if (array[i].RX_UE_INFORMATION_TAG == tag) {
            array[i].RNTI = new_rnti;
            return 0;
        }
    }
    return -1; // Tag not found
}

int deleteElement(unsigned int tag) {
    for (int i = 0; i < count; i++) {
        if (array[i].RX_UE_INFORMATION_TAG == tag) {
            for (int j = i; j < count - 1; j++) {
                array[j] = array[j + 1];
            }
            count--;
            return 0;
        }
    }
    return -1; // Tag not found
}

void printArray() {
    for (int i = 0; i < count; i++) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %hu, CRCFLAG: %hhu\n",
               array[i].RX_UE_INFORMATION_TAG, array[i].RNTI, array[i].CRCFLAG);
    }
}

int main() {
    initializeArray();

    // Example usage
    addElement(12345, 1001);
    addElement(67890, 2002);
    updateElement(12345, 1002);
    deleteElement(67890);

    printArray();

    return 0;
}
