#include <iostream>
#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <vector>

class TransactionPipeline {
public:
    TransactionPipeline(size_t numWorkers) : stop(false) {
        for (size_t i = 0; i < numWorkers; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->queue_mutex);
                        this->condition.wait(lock, [this]{ return this->stop || !this->tasks.empty(); });
                        if (this->stop && this->tasks.empty()) {
                            return;
                        }
                        task = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    template<typename F, typename... Args>
    void enqueue(F&& f, Args&&... args) {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            if (stop) {
                throw std::runtime_error("enqueue on stopped ThreadPool");
            }
            tasks.emplace([f, args...] { f(args...); });
        }
        condition.notify_one();
    }

    ~TransactionPipeline() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread &worker : workers) {
            worker.join();
        }
    }

private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queue_mutex;
    std::condition_variable condition;
    bool stop;
};

class PaymentGateway {
public:
    void processTransaction(const std::string& transactionId) {
        // Simulate payment processing
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        std::cout << "Processed transaction: " << transactionId << std::endl;
    }
};

class TransactionDatabase {
public:
    void recordTransaction(const std::string& transactionId) {
        // Simulate database recording
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
        std::cout << "Recorded transaction: " << transactionId << std::endl;
    }
};

int main() {
    TransactionPipeline pipeline(10);
    PaymentGateway paymentGateway;
    TransactionDatabase transactionDatabase;

    for (size_t i = 0; i < 100; ++i) {
        std::string transactionId = "TX" + std::to_string(i);
        pipeline.enqueue([&paymentGateway, &transactionDatabase, transactionId]() {
            paymentGateway.processTransaction(transactionId);
            transactionDatabase.recordTransaction(transactionId);
        });
    }

    return 0;
}
