    time_t FRAME_Reception_TIME;
} LTE_PHY_RX_FRAME_INFO;

LTE_PHY_RX_FRAME_INFO *frame_list[MAX_ELEMENTS];
int list_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void synchronize_with_device(int device_id) {
    // Placeholder for synchronization logic
}

void* device_thread(void* arg) {
    int device_id = *(int*)arg;
    while (1) {
        synchronize_with_device(device_id);
        sleep(5);  // Simulate periodic sync every 5 seconds
    }
    return NULL;
}

void print_list() {
    for (int i = 0; i < list_size; i++) {
        printf("CELL_ID: %d, RNTI: %d, SNR_DB: %.2f, Frame Time: %s",
               frame_list[i]->CELL_ID,
               frame_list[i]->RNTI,
               frame_list[i]->SNR_DB,
               ctime(&frame_list[i]->FRAME_Reception_TIME));
    }
}

void export_to_csv(const char* filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    fprintf(file, "CELL_ID,RNTI,SNR_DB,Frame Time\n");
    for (int i = 0; i < list_size; i++) {
        fprintf(file, "%d,%d,%.2f,%s",
               frame_list[i]->CELL_ID,
               frame_list[i]->RNTI,
               frame_list[i]->SNR_DB,
               ctime(&frame_list[i]->FRAME_Reception_TIME));
    }
    fclose(file);
}

int import_from_csv(const char* filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        LTE_PHY_RX_FRAME_INFO *info = malloc(sizeof(LTE_PHY_RX_FRAME_INFO));
        if (!info) break;

        if (sscanf(line, "%d,%d,%f,%s", 
                   &info->CELL_ID, 
                   &info->RNTI, 
                   &info->SNR_DB, 
                   ctime(&info->FRAME_Reception_TIME)) == 4) {
            pthread_mutex_lock(&lock);
            frame_list[list_size++] = info;
            pthread_mutex_unlock(&lock);
        } else {
            free(info);
        }
    }
    fclose(file);
    return list_size;
}

int main() {
    int device_ids[MAX_DEVICES];
    for (int i = 0; i < MAX_DEVICES; i++) {
        device_ids[i] = i;
        pthread_t thread_id;
        pthread_create(&thread_id, NULL, device_thread, &device_ids[i]);
    }

    // Example usage
    print_list();
    export_to_csv("output.csv");
    import_from_csv("input.csv");

    // Cleanup
    for (int i = 0; i < list_size; i++) {
        free(frame_list[i]);
    }
    pthread_mutex_destroy(&lock);

    return 0;
}
