    if (doc == NULL || doc->xmlRootNode == NULL) {
        fprintf(stderr, "Failed to read existing XML configuration file\n");
        return -1;
    }

    // Update the configuration data
    // ...

    // Save the updated XML document back to the file
    xmlSaveFormatFileEnc(filePath, doc, "UTF-8", 1);
    xmlFreeDoc(doc);

    return 0;
}

