        // Parse PNG file from cache root directory
    }
};

}  // namespace OAuth2Service

int main() {
    OAuth2Service::OAuth2Server::Config serverConfig = {
        "https://example.com/oauth/token",
        OAuth2Service::TokenValidatorFactory::createDefaultValidator()
    };
    OAuth2Service::OAuth2Server server(serverConfig);
    auto tokenFuture = server.getToken();
    try {
        nlohmann::json token = tokenFuture.get();
        if (!token.is_null()) {
            std::cout << "Valid token: " << token.dump(4) << std::endl;
