using Microsoft.Extensions.DependencyInjection;
using System.Collections.Generic;

public class IoTDataProcessingService
{
    private readonly IServiceProvider _serviceProvider;

    public IoTDataProcessingService(IServiceProvider serviceProvider)
    {
        _serviceProvider = serviceProvider;
    }

    public void ProcessData(IEnumerable<SensorData> data)
    {
        using var scope = _serviceProvider.CreateScope();
        var messageProcessor = scope.ServiceProvider.GetRequiredService<IMessageProcessor>();
        var rateLimiter = scope.ServiceProvider.GetRequiredService<IRateLimiter>();
        var storageManager = scope.ServiceProvider.GetRequiredService<IStorageManager>();
        var cachingLayer = scope.ServiceProvider.GetRequiredService<ICachingLayer>();
        var alertingSystem = scope.ServiceProvider.GetRequiredService<IAlertingSystem>();
        var batchProcessor = scope.ServiceProvider.GetRequiredService<IBatchProcessor>();
        var securityManager = scope.ServiceProvider.GetRequiredService<ISecurityManager>();
        var monitoringService = scope.ServiceProvider.GetRequiredService<IMonitoringService>();

        // Process data
        foreach (var item in data)
        {
            messageProcessor.Process(item);
            if (rateLimiter.AllowProcessing(item))
            {
                storageManager.Store(item);
                cachingLayer.Cache(item);
            }
        }

        // Trigger alerts
        var anomalies = alertingSystem.DetectAnomalies(data);
        foreach (var anomaly in anomalies)
        {
            alertingSystem.Notify(anomaly);
        }

        // Batch process historical data
        var batchData = storageManager.RetrieveBatchData();
        batchProcessor.Process(batchData);

        // Monitor and log performance
        monitoringService.LogPerformanceMetrics();

        // Secure access
        securityManager.EnforceAccessControls();
    }
}
