# Import necessary libraries
from abc import ABC, abstractmethod
import logging
from datetime import datetime

# Define an interface for Notification Platforms
class INotificationPlatform(ABC):
    @abstractmethod
    def send_notification(self, message: str) -> None:
        pass

# Concrete implementations of Notification Platforms
class SlackNotification(INotificationPlatform):
    def send_notification(self, message: str) -> None:
        # Code to send notification via Slack
        print(f"Slack: {message}")

class MicrosoftTeamsNotification(INotificationPlatform):
    def send_notification(self, message: str) -> None:
        # Code to send notification via Microsoft Teams
        print(f"Microsoft Teams: {message}")

class EmailNotification(INotificationPlatform):
    def send_notification(self, message: str) -> None:
        # Code to send notification via Email
        print(f"Email: {message}")

# Notification Service class
class NotificationService:
    platforms = {
        "Slack": SlackNotification(),
        "MicrosoftTeams": MicrosoftTeamsNotification(),
        "Email": EmailNotification()
    }

    def __init__(self):
        self.logger = logging.getLogger("NotificationService")

    def send_event_notification(self, event_type: str, message: str) -> None:
        # Validate event and message
        if not event_type or not isinstance(message, str):
            raise ValueError("Invalid event type or message format")

        # Route notification based on event type
        if event_type in self.platforms:
            self.platforms[event_type].send_notification(message)
        else:
            raise ValueError(f"Unsupported platform: {event_type}")

    def log_event(self, event_type: str, success: bool) -> None:
        current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        if success:
            self.logger.info(f"{current_time} - Event {event_type} sent successfully")
        else:
            self.logger.error(f"{current_time} - Failed to send event {event_type}")

# Example usage
if __name__ == "__main__":
    service = NotificationService()
    try:
        service.send_event_notification("Slack", "This is a test notification.")
        service.log_event("Slack", True)
    except ValueError as e:
        print(e)
```

