from abc import ABC, abstractmethod
import aioredis
import asyncio

class Cache(ABC):
    @abstractmethod
    async def get(self, key: str) -> any:
        pass

    @abstractmethod
    async def set(self, key: str, value: any, expire: int = None) -> bool:
        pass

    @abstractmethod
    async def delete(self, key: str) -> bool:
        pass

class RedisCache(Cache):
    def __init__(self, url: str):
        self.redis = await aioredis.create_redis_pool(url)

    async def get(self, key: str) -> any:
        return await self.redis.get(key)

    async def set(self, key: str, value: any, expire: int = None) -> bool:
        if expire is not None:
            return await self.redis.setex(key, expire, value)
        else:
            return await self.redis.set(key, value)

    async def delete(self, key: str) -> bool:
        return await self.redis.delete(key)

class CacheManager:
    def __init__(self):
        self.caches = {}

    def add_cache(self, service_id: str, cache: Cache):
        self.caches[service_id] = cache

    async def get(self, service_id: str, key: str) -> any:
        return await self.caches[service_id].get(key)

    async def set(self, service_id: str, key: str, value: any, expire: int = None) -> bool:
        return await self.caches[service_id].set(key, value, expire)

    async def delete(self, service_id: str, key: str) -> bool:
        return await self.caches[service_id].delete(key)
