#include <openssl/evp.h>
#include <openssl/hmac.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to initialize OpenSSL library
void init_openssl() {
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();
}

// Function to cleanup OpenSSL library
void cleanup_openssl() {
    EVP_cleanup();
    ERR_free_strings();
}

// Function to encrypt data
int encrypt_data(const unsigned char *data, size_t data_len, const unsigned char *key,
                 const unsigned char *iv, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int len;
    if (!EVP_EncryptUpdate(ctx, ciphertext, &len, data, data_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int ciphertext_len = len;
    if (!EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len += len;
    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

// Function to decrypt data
int decrypt_data(const unsigned char *ciphertext, size_t ciphertext_len, const unsigned char *key,
                 const unsigned char *iv, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int len;
    if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int plaintext_len = len;
    if (!EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len += len;
    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}

// Function to sign data
int sign_data(const unsigned char *data, size_t data_len, const unsigned char *key,
              unsigned char *signature) {
    HMAC_CTX *ctx = HMAC_CTX_new();
    if (!HMAC_Init_ex(ctx, key, 32, EVP_sha256(), NULL)) {
        HMAC_CTX_free(ctx);
        return -1;
    }
    if (!HMAC_Update(ctx, data, data_len)) {
        HMAC_CTX_free(ctx);
        return -1;
    }
    int len = 0;
    if (!HMAC_Final(ctx, signature, &len)) {
        HMAC_CTX_free(ctx);
        return -1;
    }
    HMAC_CTX_free(ctx);
    return len;
}

// Function to verify data
int verify_data(const unsigned char *data, size_t data_len, const unsigned char *signature,
                 const unsigned char *key) {
    unsigned char expected_signature[32];
    int signature_len = sign_data(data, data_len, key, expected_signature);
    if (signature_len < 0) {
        return -1;
    }
    return memcmp(signature, expected_signature, signature_len) == 0 ? 1 : 0;
}

// Function to generate a random initialization vector
void generate_iv(unsigned char *iv) {
    if (!RAND_bytes(iv, EVP_CIPHER_block_size(EVP_aes_256_cbc()))) {
        fprintf(stderr, "Failed to generate IV\n");
        exit(EXIT_FAILURE);
    }
}
