#define MAX_KEY_SIZE 32
#define MAX_IV_SIZE 16

typedef enum {
    ENCRYPTION_ALGORITHM_AES,
    ENCRYPTION_ALGORITHM_RSA
} EncryptionAlgorithm;

typedef enum {
    ENCRYPTION_MODE_CBC,
    ENCRYPTION_MODE_GCM
} EncryptionMode;

typedef struct {
    EncryptionAlgorithm algorithm;
    EncryptionMode mode;
    unsigned char key[MAX_KEY_SIZE];
    unsigned char iv[MAX_IV_SIZE];
} EncryptionConfig;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    pthread_mutex_t lock;
} EncryptionContext;

void init_encryption_context(EncryptionContext *context) {
    context->ctx = EVP_CIPHER_CTX_new();
    pthread_mutex_init(&context->lock, NULL);
}

void free_encryption_context(EncryptionContext *context) {
    EVP_CIPHER_CTX_free(context->ctx);
    pthread_mutex_destroy(&context->lock);
}

int encrypt_data(const unsigned char *plaintext, int plaintext_len,
                 const EncryptionConfig *config, unsigned char **ciphertext,
                 int *ciphertext_len) {
    pthread_mutex_lock(&config->lock);
    int result = EVP_EncryptInit_ex(config->ctx, config->algorithm, NULL, config->key, config->iv);
    if (!result) {
        pthread_mutex_unlock(&config->lock);
        return -1;
    }
    *ciphertext_len = plaintext_len + EVP_CIPHER_block_size(config->algorithm);
    *ciphertext = (unsigned char *)malloc(*ciphertext_len);
    int len;
    result = EVP_EncryptUpdate(config->ctx, *ciphertext, &len, plaintext, plaintext_len);
    if (!result) {
        pthread_mutex_unlock(&config->lock);
        free(*ciphertext);
        return -1;
    }
    int final_len;
    result = EVP_EncryptFinal_ex(config->ctx, (*ciphertext + len), &final_len);
    if (!result) {
        pthread_mutex_unlock(&config->lock);
        free(*ciphertext);
        return -1;
    }
    *ciphertext_len = len + final_len;
    pthread_mutex_unlock(&config->lock);
    return 0;
}

int decrypt_data(const unsigned char *ciphertext, int ciphertext_len,
                 const EncryptionConfig *config, unsigned char **plaintext,
                 int *plaintext_len) {
    pthread_mutex_lock(&config->lock);
    int result = EVP_DecryptInit_ex(config->ctx, config->algorithm, NULL, config->key, config->iv);
    if (!result) {
        pthread_mutex_unlock(&config->lock);
        return -1;
    }
    *plaintext_len = ciphertext_len + EVP_CIPHER_block_size(config->algorithm);
    *plaintext = (unsigned char *)malloc(*plaintext_len);
    int len;
    result = EVP_DecryptUpdate(config->ctx, *plaintext, &len, ciphertext, ciphertext_len);
    if (!result) {
        pthread_mutex_unlock(&config->lock);
        free(*plaintext);
        return -1;
    }
    int final_len;
    result = EVP_DecryptFinal_ex(config->ctx, (*plaintext + len), &final_len);
    if (!result) {
        pthread_mutex_unlock(&config->lock);
        free(*plaintext);
        return -1;
    }
    *plaintext_len = len + final_len;
    pthread_mutex_unlock(&config->lock);
    return 0;
}

void *encryption_worker(void *arg) {
    EncryptionConfig config;
    // Initialize encryption context and load configuration
    init_encryption_context(&context);

    while (1) {
        // Fetch data from input queue
        unsigned char *data, *ciphertext;
        int data_len, ciphertext_len;

        // Encrypt data
        if (encrypt_data(data, data_len, &config, &ciphertext, &ciphertext_len) == 0) {
            // Send encrypted data to output queue or process further
            free(ciphertext);
        } else {
            // Handle encryption error
        }
    }

    return NULL;
}

int main() {
    pthread_t worker_thread;
    // Initialize OpenSSL library and load configuration

    if (pthread_create(&worker_thread, NULL, encryption_worker, NULL) != 0) {
        perror("Failed to create encryption worker thread");
        return EXIT_FAILURE;
    }

    // Wait for graceful shutdown
    pthread_join(worker_thread, NULL);

    return EXIT_SUCCESS;
}
