#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_LINE_LENGTH 1024
#define BUFFER_SIZE 10

typedef struct {
    char *data;
    size_t length;
} String;

String* read_line(FILE *file) {
    String *line = (String*)malloc(sizeof(String));
    line->data = NULL;
    line->length = 0;
    ssize_t bytes_read = getline(&(line->data), &(line->length), file);
    if (bytes_read == -1) {
        free(line->data);
        free(line);
        return NULL;
    }
    line->length = bytes_read - 1; // Remove newline character
    return line;
}

void process_line(String *line, FILE *output_file) {
    int numbers[BUFFER_SIZE];
    int count = sscanf(line->data, "%d %d", &numbers[0], &numbers[1]);
    if (count < 2) {
        fprintf(stderr, "Error: Insufficient numeric fields in line\n");
        return;
    }
    double average = (double)(numbers[count - 1] + numbers[count - 2]) / 2.0;
    fprintf(output_file, "%s %.2f\n", line->data, average);
}

void *process_file(void *arg) {
    char *input_file_path = (char*)arg;
    FILE *input_file = fopen(input_file_path, "r");
    if (!input_file) {
        perror("Error opening input file");
        return NULL;
    }

    char output_file_path[256];
    snprintf(output_file_path, sizeof(output_file_path), "%s.processed", input_file_path);
    FILE *output_file = fopen(output_file_path, "w");
    if (!output_file) {
        perror("Error opening output file");
        fclose(input_file);
        return NULL;
    }

    String *line;
    while ((line = read_line(input_file)) != NULL) {
        process_line(line, output_file);
        free(line->data);
        free(line);
    }

    fclose(output_file);
    fclose(input_file);
    printf("Processed file: %s\n", input_file_path);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input directory>\n", argv[0]);
        return 1;
    }

    const char *input_directory = argv[1];
    DIR *dir;
    struct dirent *entry;

    dir = opendir(input_directory);
    if (!dir) {
        perror("Error opening input directory");
        return 1;
    }

    pthread_t threads[BUFFER_SIZE];
    int thread_count = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strstr(entry->d_name, ".txt") != NULL) {
            char file_path[256];
            snprintf(file_path, sizeof(file_path), "%s/%s", input_directory, entry->d_name);
            pthread_create(&threads[thread_count], NULL, process_file, (void*)file_path);
            thread_count++;
        }
    }

    closedir(dir);

    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("All files processed\n");
    return 0;
}
```

