#include <curl/curl.h>

#define MAX_FILES 1000
#define MAX_THREADS 100

typedef struct {
    char *file_path;
    int version;
} DeviceStatusReport;

DeviceStatusReport device_reports[MAX_FILES];
int report_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void *process_file(void *arg) {
    int file_index = *(int *)arg;
    json_object *json_obj;
    FILE *file = fopen(device_reports[file_index].file_path, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    char buffer[1024];
    fgets(buffer, sizeof(buffer), file);
    fclose(file);

    json_obj = json_tokener_parse(buffer);
    if (!json_obj) {
        fprintf(stderr, "Failed to parse JSON\n");
        return NULL;
    }

    int current_version = 0;
    const char *version_str = json_object_object_get_ex(json_obj, "version", &current_version) ? version_str : "";
    device_reports[file_index].version = atoi(version_str) + 1;

    // Update metadata via RESTful API
    CURL *curl;
    CURLcode res;
    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if(curl) {
        char url[256];
        snprintf(url, sizeof(url), "http://metadata-service/api/update?file=%s&version=%d",
                 device_reports[file_index].file_path, device_reports[file_index].version);

        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Authorization: Bearer YOUR_ACCESS_TOKEN");
        headers = curl_slist_append(headers, "Content-Type: application/json");

        res = curl_easy_setopt(curl, CURLOPT_URL, url);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_setopt() failed: %s\n", curl_easy_strerror(res));
        } else {
            res = curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
            if(res != CURLE_OK) {
                fprintf(stderr, "curl_easy_setopt() failed: %s\n", curl_easy_strerror(res));
            } else {
                res = curl_easy_perform(curl);
                if(res != CURLE_OK) {
                    fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
                }
            }
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    json_object_put(json_obj);

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        return 1;
    }

    DIR *dir;
    struct dirent *ent;
    dir = opendir(argv[1]);

    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        char file_path[256];
        snprintf(file_path, sizeof(file_path), "%s/%s", argv[1], ent->d_name);
        device_reports[report_count].file_path = strdup(file_path);
        device_reports[report_count++].version = 0;
    }

    pthread_t threads[MAX_THREADS];
    int thread_args[MAX_THREADS];

    for (int i = 0; i < report_count; i++) {
        thread_args[i] = i;
        pthread_create(&threads[i], NULL, process_file, &thread_args[i]);
    }

    for (int i = 0; i < report_count; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

