    void AddVertex(int key, int value) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (key >= max_keys || value < min_value || value > max_value) {
            throw std::invalid_argument("Invalid key or value");
        }
        keys[key] = 1;
        records[key].value = value;
        LoadBalancingAlgorithm::Update(key);
    }

    // Method to add an edge between vertices
    void AddEdge(int src, int dst) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (src >= max_keys || dst >= max_keys) {
