['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int CELL_ID;
    int RNTI;
    float SNR_DB;
    time_t FRAME_Reception_TIME;
} LTE_PHY_RX_FRAME_INFO;

typedef struct Node {
    LTE_PHY_RX_FRAME_INFO data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int size;
} LinkedList;

void insert_unique(LinkedList* list, LTE_PHY_RX_FRAME_INFO new_data) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.CELL_ID == new_data.CELL_ID && current->data.RNTI == new_data.RNTI) {
            // Duplicate found, update SNR_DB and timestamp
            current->data.SNR_DB = new_data.SNR_DB;
            current->data.FRAME_Reception_TIME = new_data.FRAME_Reception_TIME;
            return;
        }
        current = current->next;
    }
    // No duplicate, insert at the end
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->data = new_data;
    new_node->next = NULL;
    current = list->head;
    if (current == NULL) {
        list->head = new_node;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    list->size++;
}

void print_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("CELL_ID: %d, RNTI: %d, SNR_DB: %.2f, Frame Reception Time: %s", 
               current->data.CELL_ID, current->data.RNTI, current->data.SNR_DB,
               ctime(&current->data.FRAME_Reception_TIME));
        current = current->next;
    }
}

void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->size = 0;
}

int main() {
    LinkedList list;
    list.head = NULL;
    list.size = 0;

    LTE_PHY_RX_FRAME_INFO frame_info1 = {1, 2, -5.3, time(NULL)};
    insert_unique(&list, frame_info1);

    LTE_PHY_RX_FRAME_INFO frame_info2 = {1, 2, -4.7, time(NULL)};
    insert_unique(&list, frame_info2);

    print_list(&list);

    free_list(&list);

    return 0;
}
```']

