#include <iostream>
#include <vector>
#include <thread>
#include <atomic>
#include <mutex>
#include <condition_variable>
#include <memory>

// Define a simple task structure for data processing
struct DataTask {
    int id;
    std::string source;
};

// Task queue class to manage incoming tasks
class TaskQueue {
private:
    std::vector<DataTask> tasks;
    std::mutex mutex;
    std::condition_variable cond;
    bool closed;

public:
    TaskQueue() : closed(false) {}

    void enqueue(const DataTask& task) {
        std::lock_guard<std::mutex> lock(mutex);
        tasks.push_back(task);
        cond.notify_one();
    }

    DataTask dequeue() {
        std::unique_lock<std::mutex> lock(mutex);
        while (tasks.empty() && !closed) {
            cond.wait(lock);
        }
        if (closed && tasks.empty()) {
            throw std::runtime_error("Queue is closed");
        }
        DataTask task = tasks.front();
        tasks.erase(tasks.begin());
        return task;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(mutex);
            closed = true;
        }
        cond.notify_all();
    }

    bool isEmpty() {
        std::lock_guard<std::mutex> lock(mutex);
        return tasks.empty();
    }
};

// Worker thread class to process tasks
class WorkerThread {
private:
    TaskQueue& queue;
    std::atomic<bool> running;

public:
    WorkerThread(TaskQueue& q) : queue(q), running(true) {}

    void start() {
        while (running.load()) {
            try {
                DataTask task = queue.dequeue();
                processTask(task);
            } catch (const std::exception& e) {
                std::cerr << "Error processing task: " << e.what() << std::endl;
            }
        }
    }

    void stop() {
        running.store(false);
    }

private:
    void processTask(const DataTask& task) {
        // Simulate data processing
        std::cout << "Processing task " << task.id << " from source " << task.source << std::endl;
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }
};

int main() {
    TaskQueue queue;

    // Create multiple worker threads
    const int numWorkers = 4;
    std::vector<std::thread> workers;
    for (int i = 0; i < numWorkers; ++i) {
        workers.emplace_back(WorkerThread(queue));
    }

    // Enqueue tasks
    for (int i = 0; i < 100; ++i) {
        queue.enqueue({i, "Feed_" + std::to_string(i % 5)});
    }

    // Stop workers and join threads
    queue.close();
    for (auto& worker : workers) {
        worker.join();

    return 0;
}
```']

