#include <iostream>
#include <thread>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <future>
#include <functional>

class APIClient {
public:
    virtual std::string getUserProfile(const std::string& userId) = 0;
};

class CachingAPIClient : public APIClient {
private:
    struct CacheEntry {
        std::string data;
        std::chrono::time_point<std::chrono::system_clock> lastAccessed;
    };
    std::unordered_map<std::string, CacheEntry> cache;
    mutable std::mutex cacheMutex;
    std::condition_variable cacheCondVar;

public:
    CachingAPIClient(std::unique_ptr<APIClient>&& baseClient)
        : baseClient_(std::move(baseClient)) {}

    std::string getUserProfile(const std::string& userId) override {
        std::lock_guard<std::mutex> lock(cacheMutex);
        auto it = cache.find(userId);
        if (it != cache.end() && std::chrono::system_clock::now() - it->second.lastAccessed < std::chrono::minutes(5)) {
            return it->second.data;
        }
        std::string result = baseClient_->getUserProfile(userId);
        cache[userId] = {result, std::chrono::system_clock::now()};
        return result;
    }

private:
    std::unique_ptr<APIClient> baseClient_;
};

class AsyncAPIClient : public APIClient {
public:
    AsyncAPIClient(std::unique_ptr<APIClient>&& client)
        : client_(std::move(client)) {}

    std::future<std::string> getUserProfileAsync(const std::string& userId) {
        return std::async(std::launch::async, [this, userId]() {
            return client_->getUserProfile(userId);
        });
    }

private:
    std::unique_ptr<APIClient> client_;
};

class ThreadPool {
public:
    explicit ThreadPool(size_t threads) : stop(false) {
        for(size_t i = 0; i < threads; ++i)
            workers.emplace_back([this] {
                for(;;) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->queue_mutex);
                        this->condition.wait(lock, [this]{ return this->stop || !this->tasks.empty(); });
                        if(this->stop && this->tasks.empty())
                            return;
                        task = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    task();
                }
            });
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for(std::thread &worker: workers)
            worker.join();
    }

    template<class F, class... Args>
    auto enqueue(F&& f, Args&&... args) -> std::future<typename std::result_of<F(Args...)>::type> {
        using return_type = typename std::result_of<F(Args...)>::type;

        auto task = std::make_shared<std::packaged_task<return_type()>>(
            std::bind(std::forward<F>(f), std::forward<Args>(args)...)
        );

        std::future<return_type> res = task->get_future();
        {
            std::unique_lock<std::mutex> lock(queue_mutex);

            // don't allow enqueueing after stopping the pool
            if(stop)
                throw std::runtime_error("enqueue on stopped ThreadPool");

            tasks.emplace([task](){ (*task)(); });
        }
        condition.notify_one();
        return res;
    }

private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queue_mutex;
    std::condition_variable condition;
    bool stop;
};

int main() {
    // Example usage
    auto client = std::make_unique<CachingAPIClient>(std::make_unique<AsyncAPIClient>(std::make_unique<APIClient>()));
    ThreadPool pool(4);

    std::vector<std::future<std::string>> results;
    for(int i = 0; i < 10; ++i) {
        results.push_back(pool.enqueue([client, i]() {
            return client->getUserProfile("user" + std::to_string(i));
        }));
    }

    for(auto& result : results)
        std::cout << result.get() << std::endl;

    return 0;
}
