@Service
public class DataProviderService {

    @Autowired
    private RestTemplate restTemplate;

    @Autowired
    private CacheManager cacheManager;

    public ResponseEntity<Data> fetchData(String provider, String type) {
        String cacheKey = "provider_" + provider + "_type_" + type;
        Cache cache = cacheManager.getCache("dataCache");

        if (cache != null && cache.get(cacheKey) != null) {
            return ResponseEntity.ok((Data) cache.get(cacheKey).get());
        } else {
            Data data = restTemplate.getForObject(getProviderUrl(provider, type), Data.class);
            cache.put(cacheKey, new Cache.ValueWrapper() {
                @Override
                public Object get() {
                    return data;
                }
            });
            return ResponseEntity.ok(data);
        }
    }

    private String getProviderUrl(String provider, String type) {
        // Logic to determine the URL based on provider and type
        return "https://api." + provider + ".com/" + type;
    }
}

@Component
public class ProviderFallback implements FallbackFactory<DataProviderService> {

    @Override
    public DataProviderService create(Throwable cause) {
        return new DataProviderService() {
            @Override
            public ResponseEntity<Data> fetchData(String provider, String type) {
                // Logic for fallback implementation when provider is down or responds slowly
                return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE).body(new Data());
            }
        };
    }
}

