        // Implementation for applying grayscale filter
    }

    void applyBlur() {
        // Implementation for applying blur filter
    }

    void applySharpen() {
        // Implementation for applying sharpen filter
    }

    static const int MAX_WORKERS = 10;
    std::condition_variable cv;
};

int main() {
    ImageProcessor processor;
    processor.scheduleTask([]() { std::cout << "Processing task 1\n"; });
    processor.scheduleTask([]() { std::cout << "Processing task 2\n"; });

