// This code snippet is a template for a highly scalable and resilient C library to manage dynamic collections of DeviceStatusReport and NFAPI_CRC_INDICATION_PDU_T structures.
#include <stdlib.h>
#include <pthread.h>
#include <signal.h>

typedef struct {
    // Define the structure for DeviceStatusReport here
} DeviceStatusReport;

typedef struct {
    // Define the structure for NFAPI_CRC_INDICATION_PDU_T here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int max_size;
    int current_size;
    DeviceStatusReport** reports;
    NFAPI_CRC_INDICATION_PDU_T** pdus;
} DynamicCollection;

DynamicCollection* create_collection(int max_size) {
    DynamicCollection* collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    collection->max_size = max_size;
    collection->current_size = 0;
    collection->reports = (DeviceStatusReport**)malloc(max_size * sizeof(DeviceStatusReport*));
    collection->pdus = (NFAPI_CRC_INDICATION_PDU_T**)malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    pthread_mutex_init(&collection->lock, NULL);
    pthread_cond_init(&collection->cond, NULL);
    return collection;
}

void destroy_collection(DynamicCollection* collection) {
    for (int i = 0; i < collection->current_size; i++) {
        free(collection->reports[i]);
        free(collection->pdus[i]);
    }
    free(collection->reports);
    free(collection->pdus);
    pthread_mutex_destroy(&collection->lock);
    pthread_cond_destroy(&collection->cond);
    free(collection);
}

void add_device_status(DynamicCollection* collection, DeviceStatusReport* report) {
    pthread_mutex_lock(&collection->lock);
    while (collection->current_size == collection->max_size) {
        pthread_cond_wait(&collection->cond, &collection->lock);
    }
    collection->reports[collection->current_size] = report;
    collection->current_size++;
    pthread_cond_signal(&collection->cond);
    pthread_mutex_unlock(&collection->lock);
}

void add_crc_pdu(DynamicCollection* collection, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&collection->lock);
    while (collection->current_size == collection->max_size) {
        pthread_cond_wait(&collection->cond, &collection->lock);
    }
    collection->pdus[collection->current_size] = pdu;
    collection->current_size++;
    pthread_cond_signal(&collection->cond);
    pthread_mutex_unlock(&collection->lock);
}

void remove_device_status(DynamicCollection* collection, DeviceStatusReport* report) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->current_size; i++) {
        if (collection->reports[i] == report) {
            free(collection->reports[i]);
            collection->reports[i] = collection->reports[collection->current_size - 1];
            collection->reports[--collection->current_size] = NULL;
            pthread_cond_signal(&collection->cond);
            break;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

void remove_crc_pdu(DynamicCollection* collection, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->current_size; i++) {
        if (collection->pdus[i] == pdu) {
            free(collection->pdus[i]);
            collection->pdus[i] = collection->pdus[collection->current_size - 1];
            collection->pdus[--collection->current_size] = NULL;
            pthread_cond_signal(&collection->cond);
            break;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}
