#include <string.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    int device_id;
    float signal_strength;
    int error_codes[];
} DeviceStatusReport;

typedef struct {
    DeviceStatusReport *reports;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} ReportManager;

void init_report_manager(ReportManager *manager, size_t initial_capacity) {
    manager->reports = (DeviceStatusReport *)malloc(initial_capacity * sizeof(DeviceStatusReport));
    if (!manager->reports) {
        perror("Failed to allocate memory for report manager");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void add_report(ReportManager *manager, DeviceStatusReport *report) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        DeviceStatusReport *new_reports = realloc(manager->reports, new_capacity * sizeof(DeviceStatusReport));
        if (!new_reports) {
            perror("Failed to allocate memory for report manager");
            pthread_mutex_unlock(&manager->lock);
            exit(EXIT_FAILURE);
        }
        manager->reports = new_reports;
        manager->capacity = new_capacity;
    }
    memcpy(&manager->reports[manager->count++], report, sizeof(DeviceStatusReport));
    pthread_mutex_unlock(&manager->lock);
}

