typedef struct DeviceStatusReport {
    time_t timestamp;
    char device_id[10];
    int signal_strength;
    int error_codes[];
} DeviceStatusReport;

typedef struct Node {
    DeviceStatusReport report;
    struct Node *next;
} Node;

typedef struct List {
    Node *head;
    pthread_mutex_t mutex;
} List;

List* create_list() {
    List *list = (List*)malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void add_report(List *list, DeviceStatusReport report) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->report = report;
    new_node->next = list->head;
    pthread_mutex_lock(&list->mutex);
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
}

void print_list(List *list) {
    Node *current = list->head;
    while (current != NULL) {
        printf("Timestamp: %ld, Device ID: %s, Signal Strength: %d\n",
               current->report.timestamp,
               current->report.device_id,
               current->report.signal_strength);
        current = current->next;
    }
}

void destroy_list(List *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
