#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <fstream>

class TimeSeriesSensorData {
public:
    std::string deviceID;
    long timestamp;
    std::vector<float> readings;

    TimeSeriesSensorData(std::string id, long ts, const std::vector<float>& r)
        : deviceID(id), timestamp(ts), readings(r) {}
};

class SensorDataProcessor {
private:
    std::unordered_map<std::string, std::queue<TimeSeriesSensorData>> dataQueues;
    std::mutex queuesMutex;
    std::condition_variable dataAvailable;

public:
    void ingestData(const TimeSeriesSensorData& data) {
        std::lock_guard<std::mutex> lock(queuesMutex);
        dataQueues[data.deviceID].push(data);
        dataAvailable.notify_one();
    }

    bool processBatch(std::vector<TimeSeriesSensorData>& batch, int batchSize = 100) {
        std::unique_lock<std::mutex> lock(queuesMutex);
        if (!dataAvailable.wait_for(lock, std::chrono::seconds(1), [this, batchSize]() {
            return !dataQueues.empty() || dataQueues.size() > batchSize;
        })) {
            return false; // Timed out
        }

        batch.clear();
        for (auto& entry : dataQueues) {
            while (!entry.second.empty()) {
                batch.push_back(entry.second.front());
                entry.second.pop();
                if (batch.size() >= static_cast<size_t>(batchSize)) break;
            }
            if (batch.size() >= static_cast<size_t>(batchSize)) break;
        }

        return !batch.empty();
    }

    void storeData(const std::vector<TimeSeriesSensorData>& data) {
        // Store data in the relational database
        for (const auto& entry : data) {
            std::ofstream file("sensor_data.txt", std::ios::app);
            file << entry.deviceID << "," << entry.timestamp;
            for (float reading : entry.readings) {
                file << "," << reading;
            }
            file << std::endl;
        }
    }
};

int main() {
    SensorDataProcessor processor;

    // Simulate real-time data ingestion
    processor.ingestData(TimeSeriesSensorData("device1", 1633072800, {1.2f, 3.4f}));
    processor.ingestData(TimeSeriesSensorData("device2", 1633072805, {2.3f, 4.5f}));

    // Process and store batch of data
    std::vector<TimeSeriesSensorData> batch;
    if (processor.processBatch(batch)) {
        processor.storeData(batch);
    }

    return 0;
}
