void SensorDataProcessor::stop() {
    running = false;
    dataCondition.notify_all();
}

void SensorDataProcessor::addDataStream(const std::string& data) {
    std::unique_lock<std::mutex> lock(dataMutex);
    dataStreams.push_back(data);
    dataCondition.notify_one();
}

void SensorDataProcessor::processDataThread() {
    while (running) {
        std::unique_lock<std::mutex> lock(dataMutex);
        dataCondition.wait(lock, [this] { return !dataStreams.empty() || !running; });

        if (!running)
            break;

        std::string data = dataStreams.back();
        dataStreams.pop_back();
        lock.unlock();

        // Process the data here
        std::cout << "Processing data: " << data << std::endl;
    }
}
