class MessageQueue {
    std::queue<std::string> messages;
    std::mutex mtx;
    std::condition_variable cond;
public:
    void push(const std::string& message) {
        std::lock_guard<std::mutex> lock(mtx);
        messages.push(message);
        cond.notify_one();
    }

    bool try_pop(std::string& message) {
        std::unique_lock<std::mutex> lock(mtx);
        if (messages.empty()) return false;
        message = messages.front();
        messages.pop();
        return true;
    }
};

class SensorDataProcessor {
public:
    void startProcessing() {
        for (int i = 0; i < numThreads; ++i) {
            threads.push_back(std::thread(&SensorDataProcessor::processMessages, this));
        }
    }

    void stopProcessing() {
        {
            std::lock_guard<std::mutex> lock(mutex);
            running = false;
        }
        cond.notify_all();
        for (auto& thread : threads) {
            thread.join();
        }
    }

    void addMessage(const std::string& message) {
        messageQueue.push(message);
    }

private:
    void processMessages() {
        while (true) {
            std::string message;
            if (!messageQueue.try_pop(message)) {
                std::unique_lock<std::mutex> lock(mutex);
                cond.wait(lock, [this]{ return !running || !messages.empty(); });
                if (!running && messages.empty()) return;
            }
            processMessage(message);
        }
    }

    void processMessage(const std::string& message) {
        // Placeholder for message processing logic
        std::cout << "Processing message: " << message << std::endl;
    }

    MessageQueue messageQueue;
    std::vector<std::thread> threads;
    std::mutex mutex;
    std::condition_variable cond;
    bool running = true;
    int numThreads = 4; // Example number of worker threads
};

int main() {
    SensorDataProcessor processor;
    processor.startProcessing();

    // Simulate adding messages to the queue
    for (int i = 0; i < 100; ++i) {
        processor.addMessage("Message " + std::to_string(i));
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    std::this_thread::sleep_for(std::chrono::seconds(5));
    processor.stopProcessing();

    return 0;
}
