    std::shared_ptr<SensorData> pop() {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this] { return !queue.empty(); });
        auto data = queue.front();
        queue.pop();
        return data;
    }
};

class SensorDataProcessor {
private:
    MessageQueue messageQueue;
    std::vector<std::thread> workerThreads;
    int numWorkers;

public:
    SensorDataProcessor(int workers) : numWorkers(workers) {
        for (int i = 0; i < numWorkers; ++i) {
            workerThreads.emplace_back(&SensorDataProcessor::processMessages, this);
        }
    }

    ~SensorDataProcessor() {
        {
            std::lock_guard<std::mutex> lock(messageQueue.mutex);
            // Notify all workers to exit
        }
        for (auto& thread : workerThreads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void addData(const std::shared_ptr<SensorData>& data) {
        messageQueue.push(data);
    }

private:
    void processMessages() {
        while (true) {
            auto data = messageQueue.pop();
            if (!data) break;
            // Process the sensor data
            std::cout << "Processing data: " << data.get() << std::endl;
        }
    }
};
```

