void add_report(DeviceStatusManager* manager, DeviceStatusReport report) {
    pthread_mutex_lock(&manager->lock);
    int device_index = hash_function(report.device_id); // Implement a hash function
    ReportNode* node = (ReportNode*)malloc(sizeof(ReportNode));
    memcpy(&node->report, &report, sizeof(DeviceStatusReport));
    node->next = manager->reports_by_device[device_index];
    manager->reports_by_device[device_index] = node;
    manager->device_count++;
    pthread_mutex_unlock(&manager->lock);
}

void update_report(DeviceStatusManager* manager, DeviceStatusReport report) {
