// DeviceStatusLogger.c

#include "DeviceStatusLogger.h"
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct {
    DeviceStatusReport** reports;
    int count;
} DeviceStatusLog;

DeviceStatusLog* createDeviceStatusLog() {
    DeviceStatusLog* log = (DeviceStatusLog*)malloc(sizeof(DeviceStatusLog));
    log->reports = NULL;
    log->count = 0;
    return log;
}

void destroyDeviceStatusLog(DeviceStatusLog* log) {
    for (int i = 0; i < log->count; i++) {
        destroyDeviceStatusReport(log->reports[i]);
    }
    free(log->reports);
    free(log);
}

DeviceStatusReport* createDeviceStatusReport(const char* timestamp, int deviceID, float signalStrength, int* errorCodes, int errorCount, const char* firmwareVersion, int operationalFlags) {
    DeviceStatusReport* report = (DeviceStatusReport*)malloc(sizeof(DeviceStatusReport));
    report->timestamp = strdup(timestamp);
    report->deviceID = deviceID;
    report->signalStrength = signalStrength;
    report->errorCodes = (int*)malloc(errorCount * sizeof(int));
    memcpy(report->errorCodes, errorCodes, errorCount * sizeof(int));
    report->errorCount = errorCount;
    report->firmwareVersion = strdup(firmwareVersion);
    report->operationalFlags = operationalFlags;
    return report;
}

void destroyDeviceStatusReport(DeviceStatusReport* report) {
    free(report->timestamp);
    free(report->errorCodes);
    free(report->firmwareVersion);
    free(report);
}

int processString(const char* input, size_t sizeLimit, bool padFlag, LoggerFunction logger) {
    if (strlen(input) <= sizeLimit) {
        char* output = strdup(input);
        strcat(output, "\n");
        logger(output);
        free(output);
        return 0;
    } else if (padFlag) {
        char* output = strndup(input, sizeLimit);
        while (strlen(output) < sizeLimit) {
            strcat(output, " ");
        }
        logger(output);
        free(output);
        return 0;
    } else {
        logger("Error: Input exceeds size limit and pad flag is false.");
        return -1;
    }
}

// Example usage
void exampleUsage() {
    DeviceStatusLog* log = createDeviceStatusLog();

    int errorCodes[] = {1, 2, 3};
    DeviceStatusReport* report = createDeviceStatusReport("2023-04-01T12:00:00Z", 12345, 98.76f, errorCodes, 3, "v1.0", 0);
    log->reports = (DeviceStatusReport**)realloc(log->reports, (log->count + 1) * sizeof(DeviceStatusReport*));
    log->reports[log->count++] = report;

    // Process string example
    processString("Hello, world!", 50, true, printf);

    destroyDeviceStatusLog(log);
}
