#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CONNECTIONS 10000
#define PORT 8080

typedef struct {
    int fd;
    struct sockaddr_in address;
} NetworkEvent;

NetworkEvent* event_pool[MAX_CONNECTIONS];
int pool_size = 0;

void init_event_pool() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        event_pool[i] = malloc(sizeof(NetworkEvent));
        if (!event_pool[i]) {
            perror("Failed to allocate memory for event pool");
            exit(EXIT_FAILURE);
        }
    }
}

void add_connection(int fd, struct sockaddr_in address) {
    if (pool_size >= MAX_CONNECTIONS) {
        fprintf(stderr, "Connection pool is full\n");
        return;
    }
    NetworkEvent* new_event = event_pool[pool_size++];
    new_event->fd = fd;
    memcpy(&new_event->address, &address, sizeof(struct sockaddr_in));
}

void handle_events() {
    while (1) {
        for (int i = 0; i < pool_size; i++) {
            NetworkEvent* event = event_pool[i];
            if (event->fd == -1) continue;

            char buffer[1024] = {0};
            int valread = read(event->fd, buffer, sizeof(buffer));
            if (valread <= 0) {
                close(event->fd);
                memset(event, 0, sizeof(NetworkEvent));
                event->fd = -1;
            } else {
                printf("Received message from %s\n", inet_ntoa(event->address.sin_addr));
                // Process the received data
            }
        }
        sleep(1); // Simulate non-blocking behavior
    }
}

int main() {
    init_event_pool();

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("Failed to create socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) == -1) {
        perror("Bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, MAX_CONNECTIONS) == -1) {
        perror("Listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d\n", PORT);

    while (1) {
        int addrlen = sizeof(struct sockaddr_in);
        int new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen);
        if (new_socket == -1) {
            perror("Accept failed");
            continue;
        }
        add_connection(new_socket, address);
    }

    close(server_fd);

    return 0;
}
```

