#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_CONNECTIONS 150000

typedef struct {
    int client_socket;
    pthread_t thread_id;
} ClientConnection;

ClientConnection connections[MAX_CONNECTIONS];
int connection_count = 0;

void* handle_client(void* arg) {
    int client_socket = *(int*)arg;
    free(arg);

    // Handle client communication here
    char buffer[1024];
    while (1) {
        int bytes_received = recv(client_socket, buffer, sizeof(buffer), 0);
        if (bytes_received <= 0) break;
        send(client_socket, buffer, bytes_received, 0);
    }

    close(client_socket);
    return NULL;
}

void accept_connections(int server_socket) {
    while (1) {
        struct sockaddr_in client_addr;
        socklen_t addr_len = sizeof(client_addr);
        int client_socket = accept(server_socket, (struct sockaddr*)&client_addr, &addr_len);

        if (client_socket < 0) {
            perror("accept");
            continue;
        }

        if (connection_count >= MAX_CONNECTIONS) {
            close(client_socket);
            printf("Maximum connections reached\n");
            continue;
        }

        ClientConnection* conn = malloc(sizeof(ClientConnection));
        conn->client_socket = client_socket;
        pthread_create(&conn->thread_id, NULL, handle_client, (void*)conn);

        connections[connection_count++] = *conn;
    }
}

int main() {
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("socket");
        return EXIT_FAILURE;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(8080);

    if (bind(server_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        close(server_socket);
        return EXIT_FAILURE;
    }

    if (listen(server_socket, MAX_CONNECTIONS) < 0) {
        perror("listen");
        close(server_socket);
        return EXIT_FAILURE;
    }

    printf("Server listening on port 8080\n");

    accept_connections(server_socket);

    close(server_socket);
    return EXIT_SUCCESS;
}
```

### Notes:
1. **Concurrency and Scalability:** The code uses pthreads to handle concurrent connections, allowing for scalability up to the specified limit.
2. **Performance Optimization:** Asynchronous file descriptors are not directly used in this simple example but can be integrated into a more complex system using `select`, `poll`, or `epoll`.
3. **Error Handling:** Basic error handling is implemented with `perror` and condition checks, which should be expanded for a production environment.
4. **Resource Management:** The code does not include advanced resource management features but can be extended to monitor and reclaim resources as needed.

This code provides a basic structure and demonstrates key concepts that need further development and optimization based on the real-world engineering challenges outlined.']

