    }
    manager->reports[manager->report_count] = report;
    manager->report_count++;
    pthread_mutex_unlock(&manager->lock);
}

// Function to retrieve DeviceStatusReports within a specific time range
void get_device_status_reports_by_time(ReportManager* manager, time_t start_time, time_t end_time, DeviceStatusReport** reports, size_t* count) {
    pthread_mutex_lock(&manager->lock);
    *reports = NULL;
    *count = 0;
    for (size_t i = 0; i < manager->report_count; i++) {
        if (manager->reports[i]->timestamp >= start_time && manager->reports[i]->timestamp <= end_time) {
            *reports = realloc(*reports, (*count + 1) * sizeof(DeviceStatusReport*));
            if (*reports == NULL) {
                perror("Failed to allocate memory for reports");
                exit(EXIT_FAILURE);
            }
            (*reports)[*count] = manager->reports[i];
            (*count)++;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Function to clean up the ReportManager
void cleanup_report_manager(ReportManager* manager) {
    free(manager->reports);
    pthread_mutex_destroy(&manager->lock);
