#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define DeviceStatusReport structure
typedef struct {
    time_t timestamp;
    int device_id;
    float signal_strength;
    int *error_codes;
    size_t error_count;
} DeviceStatusReport;

// Function to create a new DeviceStatusReport
DeviceStatusReport* create_report(int device_id, float signal_strength) {
    DeviceStatusReport* report = (DeviceStatusReport*)malloc(sizeof(DeviceStatusReport));
    report->timestamp = time(NULL);
    report->device_id = device_id;
    report->signal_strength = signal_strength;
    report->error_codes = NULL;
    report->error_count = 0;
    return report;
}

// Function to add an error code to a DeviceStatusReport
void add_error_code(DeviceStatusReport* report, int error_code) {
    report->error_count++;
    report->error_codes = realloc(report->error_codes, report->error_count * sizeof(int));
    if (report->error_codes != NULL) {
        report->error_codes[report->error_count - 1] = error_code;
    }
}

// Function to free a DeviceStatusReport
void free_report(DeviceStatusReport* report) {
    free(report->error_codes);
    free(report);
}

// Thread-safe function to add reports to a shared collection
pthread_mutex_t report_lock;
DeviceStatusReport** reports;
size_t report_count = 0;

void add_report_to_collection(DeviceStatusReport* report) {
    pthread_mutex_lock(&report_lock);
    reports = realloc(reports, (report_count + 1) * sizeof(DeviceStatusReport*));
    if (reports != NULL) {
        reports[report_count++] = report;
    }
    pthread_mutex_unlock(&report_lock);
}

// Function to simulate data ingestion
void* data_ingestion_thread(void* arg) {
    while (1) {
        // Simulate receiving a new report from external source
        DeviceStatusReport* new_report = create_report(123, 98.5);
        add_error_code(new_report, 404);
        add_report_to_collection(new_report);

        // Sleep for a short interval before sending the next report
        sleep(1);
    }
    return NULL;
}

int main() {
    pthread_t ingestion_thread;

    // Initialize shared resources
    reports = NULL;
    pthread_mutex_init(&report_lock, NULL);

    // Start data ingestion thread
    if (pthread_create(&ingestion_thread, NULL, data_ingestion_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create data ingestion thread\n");
        return EXIT_FAILURE;
    }

    // Wait for the ingestion thread to finish (it should never)
    pthread_join(ingestion_thread, NULL);

    // Clean up
    pthread_mutex_destroy(&report_lock);
    for (size_t i = 0; i < report_count; i++) {
        free_report(reports[i]);
    }
    free(reports);

    return EXIT_SUCCESS;
}
