    pool->structures = (NFAPI_CRC_INDICATION_PDU_T *)calloc(MAX_STRUCTURES, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_nfaip_crc_pool(NFAPI_CRC_POOL_T *pool) {
    free(pool->structures);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int allocate_nfaip_crc_indication(NFAPI_CRC_POOL_T *pool, NFAPI_CRC_INDICATION_PDU_T **pdu) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // No more space
    }
    *pdu = &pool->structures[pool->count++];
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void free_nfaip_crc_indication(NFAPI_CRC_POOL_T *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; ++i) {
        if (&pool->structures[i] == pdu) {
            // Move the last element to fill the gap
            pool->structures[i] = pool->structures[--pool->count];
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

