#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>

// Define a simple data structure for sensor readings
struct SensorReading {
    double value;
    std::chrono::high_resolution_clock::time_point timestamp;
};

// Thread-safe queue to hold incoming sensor data
class ThreadSafeQueue {
private:
    std::queue<SensorReading> buffer;
    mutable std::mutex mtx;
    std::condition_variable cond;
public:
    void push(SensorReading reading) {
        std::lock_guard<std::mutex> lock(mtx);
        buffer.push(reading);
        cond.notify_one();
    }
    bool pop(SensorReading &item) {
        std::unique_lock<std::mutex> lock(mtx);
        while (buffer.empty()) {
            cond.wait(lock);
        }
        item = buffer.front();
        buffer.pop();
        return true;
    }
    bool empty() const {
        std::lock_guard<std::mutex> lock(mtx);
        return buffer.empty();
    }
};

// Data processor class to handle sensor data
class DataProcessor {
private:
    ThreadSafeQueue inputQueue;
    std::atomic<bool> running;
public:
    DataProcessor() : running(false) {}

    void startProcessing() {
        running = true;
        std::thread([this]() {
            while (running.load()) {
                SensorReading reading;
                if (inputQueue.pop(reading)) {
                    // Process the sensor reading here
                    processReading(reading);
                }
            }
        }).detach();
    }

    void stopProcessing() {
        running = false;
        inputQueue.cond.notify_all();
    }

    void submitReading(const SensorReading &reading) {
        inputQueue.push(reading);
    }

private:
    void processReading(const SensorReading &reading) {
        // Implement data processing logic here
        std::cout << "Processing reading at timestamp: " << reading.timestamp 
