    JsonDocument doc = future_doc.get();
    updateWithCircuitBreaker(client, "http://example.com/api/data", doc);
}

void testPerformance() {
    CacheManager cache;
    ConfigManager config;

    // Performance benchmarks
    std::vector<std::future<JsonDocument>> futures;
    for (int i = 0; i < 1000; ++i) {
        auto future_doc = fetchWithRetry(client, "http://example.com/api/data");
        futures.push_back(future_doc);
    }
}

