// Function to process strings (placeholder)
void processString(StringMetadata *metadata) {
    // Simulate string processing
    printf("Processing string %d: %s\n", metadata->id, metadata->data);
}

// Thread function for batch processing
void* threadFunction(void *arg) {
    BatchTask *task = (BatchTask *) arg;
    for (int i = 0; i < task->count; i++) {
        processString(&task->strings[i]);
    }
    pthread_exit(NULL);
}

// Function to handle dynamic input streams and batch processing
void batchProcessStrings(StringMetadata *strings, int count) {
    pthread_t threads[10];
    BatchTask tasks[10];

    // Split the work into batches for concurrent processing
    int batchSize = count / 10;
    for (int i = 0; i < 10; i++) {
        tasks[i].strings = &strings[i * batchSize];
        tasks[i].count = (i == 9) ? count - (i * batchSize) : batchSize;
        pthread_create(&threads[i], NULL, threadFunction, (void *)&tasks[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }
}

// Main function to demonstrate the batch processing
int main() {
    StringMetadata strings[10000];
    for (int i = 0; i < 10000; i++) {
        strings[i].id = i;
        snprintf(strings[i].data, sizeof(strings[i].data), "String %d", i);
    }

    batchProcessStrings(strings, 10000);

    return 0;
}
