public class SecureFileTransferManager {
    private List<StorageSystem> storageSystems;
    private EncryptionService encryptionService;
    private ThirdPartyMetadataService metadataService;

    public SecureFileTransferManager(List<StorageSystem> storageSystems, EncryptionService encryptionService) {
        this.storageSystems = storageSystems;
        this.encryptionService = encryptionService;
        this.metadataService = new ThirdPartyMetadataService();
    }

    public void transferFile(File file, String destination) throws TransferException {
        // Validate file and destination
        if (!file.exists() || destination == null) {
            throw new TransferException("Invalid file or destination");
        }

        // Extract metadata using third-party service
        Metadata metadata = metadataService.extractMetadata(file);
        if (metadata == null) {
            throw new TransferException("Failed to extract metadata");
        }

        // Encrypt data
        byte[] encryptedData = encryptionService.encrypt(file, metadata);

        // Select optimal storage system for destination
        StorageSystem targetStorage = selectStorageSystem(destination);

        try {
            // Upload data to selected storage system
            targetStorage.upload(encryptedData, metadata);
        } catch (IOException e) {
            throw new TransferException("Upload failed", e);
        }
    }

    private StorageSystem selectStorageSystem(String destination) {
        // Implement intelligent scheduling and selection logic based on current traffic and resource availability
        return storageSystems.stream()
                .min(Comparator.comparingLong(storage -> storage.getFreeSpace()))
                .orElseThrow(() -> new TransferException("No available storage system"));
    }
}
