        # Fetch data from external sources and cache
        data = []
        for source in self.data_sources:
            try:
                data.extend(source.fetch(user_id))
            except Exception as e:
                print(f"Error fetching data from {source}: {e}")

        # Store data in both caches
        self.cache.store(user_id, data)
        self.distributed_cache.store(user_id, data)

        return data

    def get_recommendations(self, user_id):
        # Retrieve cached recommendations
        if self.cache.exists(user_id):
            return self.cache.get(user_id)

        if self.distributed_cache.exists(user_id):
            return self.distributed_cache.get(user_id)

        # Fetch new data and update caches
        recommendations = self.fetch_data(user_id)
        self.cache.store(user_id, recommendations)
        self.distributed_cache.store(user_id, recommendations)

        return recommendations

