// This is a simplified example of the CloudStorageManager class.
public class CloudStorageManager {
    private List<CloudProvider> providers;
    private Map<String, CloudProvider> providerMap;

    public CloudStorageManager(List<CloudProvider> providers) {
        this.providers = providers;
        this.providerMap = new HashMap<>();
        initializeProviders();
    }

    private void initializeProviders() {
        for (CloudProvider provider : providers) {
            providerMap.put(provider.getName(), provider);
        }
    }

    public void uploadFile(String file, String providerName) throws Exception {
        CloudProvider provider = providerMap.get(providerName);
        if (provider != null) {
            provider.upload(file);
        } else {
            throw new IllegalArgumentException("Unknown provider: " + providerName);
        }
    }

    public void downloadFile(String file, String providerName) throws Exception {
        CloudProvider provider = providerMap.get(providerName);
        if (provider != null) {
            provider.download(file);
        } else {
            throw new IllegalArgumentException("Unknown provider: " + providerName);
        }
    }

    // Additional methods for handling configurations, fallbacks, logging, etc.
}

interface CloudProvider {
    String getName();
    void upload(String file) throws Exception;
    void download(String file) throws Exception;
