#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int crc_flag;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DoublyLinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct DoublyLinkedListNode* prev;
    struct DoublyLinkedListNode* next;
} DoublyLinkedListNode;

typedef struct DoublyLinkedList {
    DoublyLinkedListNode* head;
    DoublyLinkedListNode* tail;
    size_t size;
    pthread_mutex_t mutex;
} DoublyLinkedList;

void initDoublyLinkedList(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void destroyDoublyLinkedList(DoublyLinkedList* list) {
    DoublyLinkedListNode* current = list->head;
    while (current != NULL) {
        DoublyLinkedListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
}

void addElement(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= MAX_ELEMENTS) {
        DoublyLinkedListNode* lru = list->tail;
        if (lru != NULL) {
            if (lru->prev != NULL) {
                lru->prev->next = NULL;
            } else {
                list->head = NULL;
            }
            list->tail = lru->prev;
            free(lru);
        }
    }

    DoublyLinkedListNode* newNode = (DoublyLinkedListNode*)malloc(sizeof(DoublyLinkedListNode));
    if (newNode == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return; // Handle memory allocation failure
    }
    newNode->data = data;
    newNode->prev = list->tail;
    newNode->next = NULL;

    if (list->head != NULL) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

// Other functions for accessing and modifying the list...

