#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <jpeglib.h>
#include <tiffio.h>

typedef struct {
    int width;
    int height;
    int bits_per_sample;
    int samples_per_pixel;
} ImageMetadata;

ImageMetadata parseTIFF(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open TIFF file: %s\n", filename);
        exit(1);
    }

    tiff_t *tiff = TIFFOpen(filename, "r");
    if (!tiff) {
        fclose(file);
        fprintf(stderr, "Failed to open TIFF file with libtiff: %s\n", filename);
        exit(1);
    }

    ImageMetadata metadata;
    metadata.width = 0;
    metadata.height = 0;
    metadata.bits_per_sample = 0;
    metadata.samples_per_pixel = 0;

    if (TIFFGetField(tiff, TIFFTAG_IMAGEWIDTH, &metadata.width)) {
        // Width found
    }
    if (TIFFGetField(tiff, TIFFTAG_IMAGELENGTH, &metadata.height)) {
        // Height found
    }
    if (TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &metadata.bits_per_sample)) {
        // Bits per sample found
    }
    if (TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &metadata.samples_per_pixel)) {
        // Samples per pixel found
    }

    TIFFClose(tiff);
    fclose(file);

    return metadata;
}

ImageMetadata parseJPEG(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open JPEG file: %s\n", filename);
        exit(1);
    }

    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);
    jpeg_stdio_src(&cinfo, file);
    jpeg_read_header(&cinfo, TRUE);

    ImageMetadata metadata;
    metadata.width = cinfo.output_width;
    metadata.height = cinfo.output_height;
    metadata.bits_per_sample = 8 * cinfo.output_components;
    metadata.samples_per_pixel = cinfo.output_components;

    jpeg_destroy_decompress(&cinfo);
    fclose(file);

    return metadata;
}

ImageMetadata parseDynamicImage(const char *filename) {
    if (strstr(filename, ".tif") != NULL || strstr(filename, ".tiff") != NULL) {
        return parseTIFF(filename);
    } else if (strstr(filename, ".jpg") != NULL || strstr(filename, ".jpeg") != NULL) {
        return parseJPEG(filename);
    } else {
        fprintf(stderr, "Unsupported file format: %s\n", filename);
        exit(1);
    }
}

int main() {
    const char *filename = "example.jpg";
    ImageMetadata metadata = parseDynamicImage(filename);
    printf("Width: %d\nHeight: %d\nBits per Sample: %d\nSamples per Pixel: %d\n",
           metadata.width, metadata.height, metadata.bits_per_sample, metadata.samples_per_pixel);
    return 0;
}
