void saveStateToFile(const MoSTState& state, const std::string& filename) {
    std::ofstream ofs(filename, std::ios::binary);
    if (!ofs) throw std::runtime_error("Failed to open file for writing");

    try {
        ofs.write(reinterpret_cast<const char*>(&state), sizeof(state));
    } catch (...) {
        ofs.close();
        throw;
    }
}

MoSTState* loadStateFromFile(const std::string& filename) {
    std::ifstream ifs(filename, std::ios::binary);
    if (!ifs) return nullptr;

    MoSTState* state = new MoSTState;
    try {
        ifs.read(reinterpret_cast<char*>(state), sizeof(*state));
        if (ifs.gcount() != sizeof(*state)) throw std::runtime_error("Incomplete read");
    } catch (...) {
        delete state;
        ifs.close();
        throw;
    }

    ifs.close();
    return state;
}
