#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pem.h>
#include <openssl/bio.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to initialize OpenSSL
void openssl_init() {
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();
}

// Function to clean up OpenSSL
void openssl_cleanup() {
    EVP_cleanup();
    ERR_free_strings();
}

// Function to encrypt a file
int encrypt_file(const char *input_file, const char *output_file, const unsigned char *key, const unsigned char *iv) {
    FILE *in_fp = fopen(input_file, "rb");
    FILE *out_fp = fopen(output_file, "wb");

    if (!in_fp || !out_fp) {
        perror("Error opening file");
        return -1;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

    unsigned char in_buf[4096], out_buf[4096];
    int len, out_len;

    while (1) {
        if (!fread(in_buf, 1, sizeof(in_buf), in_fp)) break;
        EVP_EncryptUpdate(ctx, out_buf, &out_len, in_buf, len);
        fwrite(out_buf, 1, out_len, out_fp);
    }

    EVP_EncryptFinal_ex(ctx, out_buf, &out_len);
    fwrite(out_buf, 1, out_len, out_fp);

    fclose(in_fp);
    fclose(out_fp);
    EVP_CIPHER_CTX_free(ctx);

    return 0;
}

// Function to decrypt a file
int decrypt_file(const char *input_file, const char *output_file, const unsigned char *key, const unsigned char *iv) {
    FILE *in_fp = fopen(input_file, "rb");
    FILE *out_fp = fopen(output_file, "wb");

    if (!in_fp || !out_fp) {
        perror("Error opening file");
        return -1;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

    unsigned char in_buf[4096], out_buf[4096];
    int len, out_len;

    while (1) {
        if (!fread(in_buf, 1, sizeof(in_buf), in_fp)) break;
        EVP_DecryptUpdate(ctx, out_buf, &out_len, in_buf, len);
        fwrite(out_buf, 1, out_len, out_fp);
    }

    EVP_DecryptFinal_ex(ctx, out_buf, &out_len);
    fwrite(out_buf, 1, out_len, out_fp);

    fclose(in_fp);
    fclose(out_fp);
    EVP_CIPHER_CTX_free(ctx);

    return 0;
}

// Function to sign a file
int sign_file(const char *input_file, const char *output_file, RSA *rsa) {
    FILE *in_fp = fopen(input_file, "rb");
    FILE *out_fp = fopen(output_file, "wb");

    if (!in_fp || !out_fp) {
        perror("Error opening file");
        return -1;
    }

    unsigned char digest[EVP_MAX_MD_SIZE];
    unsigned int digest_len;

    EVP_DigestFile(input_file, digest, &digest_len, EVP_sha256());

    unsigned char *signature = (unsigned char *)malloc(RSA_size(rsa));
    int signature_len;

    RSA_sign(NID_sha256, digest, digest_len, signature, &signature_len, rsa);

    fwrite(signature, 1, signature_len, out_fp);
    free(signature);

    fclose(in_fp);
    fclose(out_fp);

    return 0;
}

// Function to verify a file
int verify_file(const char *input_file, const char *signature_file, RSA *rsa) {
    FILE *in_fp = fopen(input_file, "rb");
    FILE *sig_fp = fopen(signature_file, "rb");

    if (!in_fp || !sig_fp) {
        perror("Error opening file");
        return -1;
    }

    unsigned char digest[EVP_MAX_MD_SIZE];
    unsigned int digest_len;

    EVP_DigestFile(input_file, digest, &digest_len, EVP_sha256());

    unsigned char signature[256];
    int signature_len;

    fread(signature, 1, sizeof(signature), sig_fp);
    fclose(sig_fp);

    return RSA_verify(NID_sha256, digest, digest_len, signature, signature_len, rsa);
}

// Main function for demonstration purposes
int main() {
    openssl_init();

    unsigned char key[32];
    unsigned char iv[16];

    // Generate random key and IV
    if (!RAND_bytes(key, sizeof(key)) || !RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Error generating random bytes\n");
        return 1;
    }

    RSA *rsa = RSA_new();
    BIGNUM *e = BN_new();
    BN_set_word(e, RSA_F4);

    if (!RSA_generate_key_ex(rsa, 2048, e, NULL)) {
        fprintf(stderr, "Error generating RSA key\n");
        return 1;
    }

    // Encrypt and decrypt a file
    if (encrypt_file("input.txt", "encrypted.bin", key, iv) != 0) {
        fprintf(stderr, "Error encrypting file\n");
        return 1;
    }

    if (decrypt_file("encrypted.bin", "decrypted.txt", key, iv) != 0) {
        fprintf(stderr, "Error decrypting file\n");
        return 1;
    }

    // Sign and verify a file
    if (sign_file("input.txt", "signature.bin", rsa) != 0) {
        fprintf(stderr, "Error signing file\n");
        return 1;
    }

    if (!verify_file("input.txt", "signature.bin", rsa)) {
        fprintf(stderr, "Signature verification failed\n");
        return 1;
    }

    RSA_free(rsa);
    BN_free(e);

    openssl_cleanup();

