// Define error handling macro
#define CHECK_OPENSSL(op) if (!(op)) { fprintf(stderr, "OpenSSL error: %s\n", ERR_error_string(ERR_get_error(), NULL)); return -1; }
#define CHECK_SQLITE3(rc) if (rc != SQLITE_OK) { fprintf(stderr, "SQLite3 error: %s\n", sqlite3_errmsg(db)); return -1; }

// Define constants
#define MAX_KEY_SIZE 32

// Global variables
sqlite3 *db;
pthread_mutex_t db_lock;

// Function prototypes
int initialize_library();
int encrypt_file(const char *input_path, const char *output_path);
int decrypt_file(const char *input_path, const char *output_path);
int sign_file(const char *input_path, const char *signature_path);
