#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

int resolve_dns(const char *hostname, struct in_addr *ip) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    *ip = ((struct sockaddr_in *)res->ai_addr)->sin_addr;

    freeaddrinfo(res);
    return 0;
}

int main() {
    struct in_addr ip;
    const char *hostname = "example.com";

    if (resolve_dns(hostname, &ip)) {
        printf("Failed to resolve DNS for %s\n", hostname);
        return EXIT_FAILURE;
    }

    printf("IP address of %s is: %s\n", hostname, inet_ntoa(ip));
    return EXIT_SUCCESS;
}
