class SessionManager {
private:
    std::unordered_map<int, UserSession*> sessions;
    std::mutex sessionMutex;
    std::condition_variable sessionCondVar;

public:
    void addUserSession(int sessionId, UserSession* session) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        sessions[sessionId] = session;
        sessionCondVar.notify_one();
    }

    void removeUserSession(int sessionId) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        sessions.erase(sessionId);
        sessionCondVar.notify_one();
    }

    UserSession* getUserSession(int sessionId) {
        std::unique_lock<std::mutex> lock(sessionMutex);
        while (sessions.find(sessionId) == sessions.end()) {
            sessionCondVar.wait(lock);
        }
        return sessions[sessionId];
    }

    // Other methods
};

class Cache {
private:
    std::unordered_map<int, UserSession*> cache;
    std::mutex cacheMutex;
    std::condition_variable cacheCondVar;

