        std::lock_guard<std::mutex> lock(cacheMutex);
        cache[sessionId] = session;
        cacheCondVar.notify_one();
    }

    UserSession* getFromCache(int sessionId) {
        std::unique_lock<std::mutex> lock(cacheMutex);
        while (cache.find(sessionId) == cache.end()) {
            cacheCondVar.wait(lock);
        }
        return cache[sessionId];
    }

    void removeFromCache(int sessionId) {
        std::lock_guard<std::mutex> lock(cacheMutex);
