import asyncio
from abc import ABC, abstractmethod
from dataclasses import dataclass
from enum import Enum
import logging

# Define an enumeration for payment gateways
class PaymentGateway(Enum):
    STRIPE = 'stripe'
    PAYPAL = 'paypal'
    BRAINTREE = 'braintree'

# Abstract base class for payment processing services
class PaymentService(ABC):
    @abstractmethod
    async def process_payment(self, amount: float) -> bool:
        pass

# Concrete implementation for Stripe payment service
@dataclass
class StripePaymentService(PaymentService):
    async def process_payment(self, amount: float) -> bool:
        # Simulate payment processing logic
        return True  # Payment successful

# Concrete implementation for PayPal payment service
@dataclass
class PayPalPaymentService(PaymentService):
    async def process_payment(self, amount: float) -> bool:
        # Simulate payment processing logic
        return True  # Payment successful

# Concrete implementation for Braintree payment service
@dataclass
class BraintreePaymentService(PaymentService):
    async def process_payment(self, amount: float) -> bool:
        # Simulate payment processing logic
        return True  # Payment successful

# Service registry to manage dynamic addition of payment gateways
class PaymentServiceRegistry:
    services = {}

    @staticmethod
    def register_service(gateway_type: PaymentGateway, service: PaymentService):
        PaymentServiceRegistry.services[gateway_type.value] = service

    @staticmethod
    async def get_service(gateway_type: PaymentGateway) -> PaymentService:
        service_class = PaymentServiceRegistry.services.get(gateway_type.value)
        if service_class:
            return service_class()
        else:
            raise ValueError(f"No payment service registered for {gateway_type}")

# Main application class to handle payment processing
class PaymentProcessor:
    def __init__(self):
        self.logger = logging.getLogger(self.__class__.__name__)

    async def process_payment(self, gateway_type: PaymentGateway, amount: float) -> bool:
        try:
            service = await PaymentServiceRegistry.get_service(gateway_type)
            result = await service.process_payment(amount)
            return result
        except Exception as e:
            self.logger.error(f"Failed to process payment with {gateway_type}: {e}")
            return False

# Example usage of the PaymentProcessor class
async def main():
    PaymentServiceRegistry.register_service(PaymentGateway.STRIPE, StripePaymentService())
    PaymentServiceRegistry.register_service(PaymentGateway.PAYPAL, PayPalPaymentService())
    PaymentServiceRegistry.register_service(PaymentGateway.BRAINTREE, BraintreePaymentService())

    processor = PaymentProcessor()
    payment_success = await processor.process_payment(PaymentGateway.STRIPE, 100.0)
    print(f"Payment successful: {payment_success}")

# Run the main function
asyncio.run(main())
