void generate_crc_indication_pdu_list(int num_structures, NFAPI_CRC_INDICATION_PDU_T *list) {
    for (int i = 0; i < num_structures; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand();
        list[i].RNTI = (unsigned short)(rand() % 65536);
        list[i].CRC_INDICATION_REL8_TAG = (unsigned char)rand();
    }
}

// Function to print a list of NFAPI_CRC_INDICATION_PDU_T structures
void print_crc_indication_pdu_list(int num_structures, NFAPI_CRC_INDICATION_PDU_T *list) {
    for (int i = 0; i < num_structures; i++) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %hu, CRC_INDICATION_REL8_TAG: %hhu\n",
               list[i].RX_UE_INFORMATION_TAG, list[i].RNTI, list[i].CRC_INDICATION_REL8_TAG);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <number_of_structures>\n", argv[0]);
        return 1;
    }

    int num_structures = atoi(argv[1]);
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!list) {
        fprintf(stderr, "Failed to allocate memory\n");
        return 1;
    }

    generate_crc_indication_pdu_list(num_structures, list);
    print_crc_indication_pdu_list(num_structures, list);

    free(list);
    return 0;
}
