    DroneControlSystem dcs;
    for (int i = 0; i < 5; ++i) {
        dcs.addDrone(new Drone());
    }

    WeatherAPI weatherAPI;

    std::vector<std::string> missions = {"Deliver package to address A", "Survey area B"};
    dcs.assignMissions(missions);

    // Simulate running the system
    std::this_thread::sleep_for(std::chrono::seconds(30));

    return 0;
}
