#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct ErrorCode {
    int code;
    int frequency;
} ErrorCode;

typedef struct DeviceStatusReport {
    time_t timestamp;
    int deviceID;
    float signalStrength;
    ErrorCode* errors;
    int errorCount;
} DeviceStatusReport;

typedef struct ReportManager {
    pthread_mutex_t lock;
    DeviceStatusReport** reports;
    size_t count;
} ReportManager;

void initializeReportManager(ReportManager* manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->reports = NULL;
    manager->count = 0;
}

void addOrUpdateReport(ReportManager* manager, DeviceStatusReport* report) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->reports[i]->deviceID == report->deviceID) {
            free(manager->reports[i]);
            manager->reports[i] = report;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }
    manager->reports = realloc(manager->reports, (manager->count + 1) * sizeof(DeviceStatusReport*));
    manager->reports[manager->count++] = report;
    pthread_mutex_unlock(&manager->lock);
}

DeviceStatusReport* getReportByDeviceID(ReportManager* manager, int deviceID) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->reports[i]->deviceID == deviceID) {
            DeviceStatusReport* report = manager->reports[i];
            pthread_mutex_unlock(&manager->lock);
            return report;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void summarizeReports(ReportManager* manager, float* averageSignalStrength, ErrorCode** errorCodes, size_t* errorCodeCount) {
    *averageSignalStrength = 0.0f;
    int totalErrorFrequency = 0;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        *averageSignalStrength += manager->reports[i]->signalStrength;
        for (int j = 0; j < manager->reports[i]->errorCount; ++j) {
            int found = 0;
            for (int k = 0; k < *errorCodeCount; ++k) {
                if (manager->reports[i]->errors[j].code == errorCodes[k]->code) {
                    errorCodes[k]->frequency++;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                ErrorCode* newError = malloc(sizeof(ErrorCode));
                newError->code = manager->reports[i]->errors[j].code;
                newError->frequency = 1;
                *errorCodes = realloc(*errorCodes, (*errorCodeCount + 1) * sizeof(ErrorCode*));
                (*errorCodes)[*errorCodeCount++] = newError;
            }
        }
    }
    if (manager->count > 0) {
        *averageSignalStrength /= manager->count;
    }

    for (int i = 0; i < *errorCodeCount; ++i) {
        totalErrorFrequency += (*errorCodes)[i]->frequency;
    }
    pthread_mutex_unlock(&manager->lock);
}

void finalizeReportManager(ReportManager* manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->reports[i]);
    }
    free(manager->reports);
    pthread_mutex_destroy(&manager->lock);
}
