struct DeviceStatusReport {
    std::chrono::system_clock::time_point timestamp;
    int deviceID;
    double signalStrength;
    std::vector<int> errorCodes;
};

class DeviceStatusManager {
public:
    void addOrUpdateReport(const DeviceStatusReport& report) {
        std::lock_guard<std::mutex> lock(mutex_);
        reports_[report.deviceID] = report;
        updateSummary();
    }

    DeviceStatusReport getReport(int deviceID) {
        std::lock_guard<std::mutex> lock(mutex_);
        return reports_[deviceID];
    }

    std::pair<double, std::unordered_map<int, int>> getSummary() {
        std::lock_guard<std::mutex> lock(mutex_);
        return summary_;
    }

private:
    std::mutex mutex_;
    std::unordered_map<int, DeviceStatusReport> reports_;
    std::pair<double, std::unordered_map<int, int>> summary_;

    void updateSummary() {
        double totalSignalStrength = 0;
        std::unordered_map<int, int> errorFrequency;

        for (const auto& report : reports_) {
            totalSignalStrength += report.second.signalStrength;
            for (int errorCode : report.second.errorCodes) {
                errorFrequency[errorCode]++;
            }
        }

        summary_ = {totalSignalStrength / reports_.size(), errorFrequency};
    }
};

