using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Diagnostics;
using System.Linq;
using System.Threading.Tasks;

public class DatabaseExecutor
{
    private readonly Dictionary<string, DbCommand> _queryCache = new Dictionary<string, DbCommand>();
    private readonly string[] _allowedKeywords = { "SELECT", "FROM", "WHERE", "JOIN", "ORDER BY" };
    private readonly string[] _allowedTables = { "Users", "Orders", "Products" };

    public async Task ExecuteParameterizedQueryAsync(string connectionString, string sql, List<DbParameter> parameters, bool enableLogging = true)
    {
        if (!IsValidSql(sql))
        {
            throw new ArgumentException("SQL command is not allowed.");
        }

        var key = $"{sql}_{string.Join(",", parameters.Select(p => p.ParameterName))}";
        DbCommand command;

        if (!_queryCache.TryGetValue(key, out command))
        {
            using (var connection = CreateConnection(connectionString))
            {
                await connection.OpenAsync();
                command = connection.CreateCommand();
                command.CommandText = sql;
                command.Parameters.AddRange(parameters.ToArray());
                _queryCache[key] = command;
            }
        }

        try
        {
            if (enableLogging)
            {
                LogQueryExecution(sql, parameters);
            }

            using (var reader = await command.ExecuteReaderAsync())
            {
                // Process the data here
            }
        }
        catch (Exception ex)
        {
            HandleError(ex, sql, parameters);
        }
    }

    private bool IsValidSql(string sql)
    {
        var words = sql.Split(' ');
        foreach (var word in words)
        {
            if (_allowedKeywords.Contains(word.ToUpper()) && !_allowedTables.Contains(word))
            {
                return false;
            }
        }
        return true;
    }

    private DbConnection CreateConnection(string connectionString)
    {
        // Implement connection creation logic
        throw new NotImplementedException();
    }

    private void LogQueryExecution(string sql, List<DbParameter> parameters)
    {
        if (Configuration.IsLoggingEnabled)
        {
            Debug.WriteLine($"Executing SQL: {sql}");
            foreach (var param in parameters)
            {
                Debug.WriteLine($"{param.ParameterName}: {param.Value}");
            }
        }
    }

    private void HandleError(Exception ex, string sql, List<DbParameter> parameters)
    {
        if (Configuration.IsErrorNotificationEnabled)
        {
            // Notify error tracking system
        }

        if (Configuration.LogErrors)
        {
            Debug.WriteLine($"Error executing SQL: {sql}");
            foreach (var param in parameters)
            {
                Debug.WriteLine($"{param.ParameterName}: {param.Value}");
            }
            Debug.WriteLine(ex.Message);
        }
    }
}
