    sensorDataProcessor() : running(true) {}

    void startProcessing() {
        std::thread([this]() {
            while (running) {
                std::unique_lock<std::mutex> lock(queueMutex);
                dataReadyCondition.wait(lock, [this] { return !dataQueue.empty() || !running; });

                if (!running && dataQueue.empty()) break;

                std::string data = dataQueue.front();
                dataQueue.pop();

                lock.unlock();
                processSensorData(data);
            }
        }).detach();
    }

    void stopProcessing() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            running = false;
        }
        dataReadyCondition.notify_one();
    }

    void addData(const std::string& data) {
