#include <iostream>
#include <vector>
#include <mutex>
#include <unordered_map>
#include <condition_variable>

struct PaymentTransaction {
    int transactionID;
    int customerID;
    double paymentAmount;
    std::string currencyType;
    std::vector<std::string> processingStatuses;
};

class TransactionManager {
private:
    std::unordered_map<int, PaymentTransaction> transactions;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void addTransaction(const PaymentTransaction& transaction) {
        std::lock_guard<std::mutex> lock(mtx);
        transactions[transaction.transactionID] = transaction;
        cv.notify_one();
    }

    bool updateTransaction(int transactionID, const PaymentTransaction& updatedTransaction) {
        std::lock_guard<std::mutex> lock(mtx);
        if (transactions.find(transactionID) != transactions.end()) {
            transactions[transactionID] = updatedTransaction;
            return true;
        }
        return false;
    }

    PaymentTransaction getTransaction(int transactionID) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this, transactionID]{ return transactions.find(transactionID) != transactions.end(); });
        return transactions[transactionID];
    }

    void calculateSummary() {
        std::lock_guard<std::mutex> lock(mtx);
        double totalAmount = 0;
        int successfulCount = 0;
        std::unordered_map<std::string, int> statusFrequency;

        for (const auto& transaction : transactions) {
            totalAmount += transaction.second.paymentAmount;
            if (std::find(transaction.second.processingStatuses.begin(), transaction.second.processingStatuses.end(), "Successful") != transaction.second.processingStatuses.end()) {
                successfulCount++;
            }
            for (const auto& status : transaction.second.processingStatuses) {
                statusFrequency[status]++;
            }
        }

        std::cout << "Average Transaction Amount: " << totalAmount / transactions.size() << std::endl;
        std::cout << "Total Successful Transactions: " << successfulCount << std::endl;
        for (const auto& pair : statusFrequency) {
            std::cout << pair.first << ": " << pair.second << std::endl;
        }
    }
};

int main() {
    TransactionManager manager;

    PaymentTransaction transaction1 = {1, 1001, 50.0, "USD", {"Pending"}};
    manager.addTransaction(transaction1);

    PaymentTransaction updatedTransaction1 = {1, 1001, 50.0, "USD", {"Successful"}};
    manager.updateTransaction(1, updatedTransaction1);

    PaymentTransaction transaction2 = {2, 1002, 75.0, "EUR", {"Pending", "Failed"}};
    manager.addTransaction(transaction2);

    manager.calculateSummary();

    return 0;
}
```

This code snippet provides a basic implementation of the `TransactionManager` class, which is responsible for managing payment transactions in a thread-safe manner. It includes methods to add, update, and retrieve transactions, as well as a method to calculate summary statistics. The use of mutexes ensures that all operations are thread-safe, preventing race conditions. The condition variable allows the retrieval method to block until a transaction is available, ensuring that the application can handle concurrent access efficiently.']

