#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h>

#define SHARED_MEM_SIZE 1024 * 1024 // 1MB

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Shared memory structure
typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T PDUs[SHARED_MEM_SIZE];
    int count;
} SharedMemory;

SharedMemory *shared_memory = NULL;

void* allocate_shared_memory() {
    shared_memory = mmap(NULL, SHARED_MEM_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (shared_memory == MAP_FAILED) {
        perror("Failed to allocate shared memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&shared_memory->lock, NULL);
    return shared_memory;
}

void free_shared_memory() {
    pthread_mutex_destroy(&shared_memory->lock);
    munmap(shared_memory, SHARED_MEM_SIZE);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        perror("Failed to allocate PDU");
        return NULL;
    }
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    srand(time(NULL));
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    return pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    free(pdu);
}

int fetch_unique_RX_UE_INFORMATION_TAG() {
    // Simulate fetching unique tag from external database
    return rand() % 100000; // Random tag for demonstration
}

NFAPI_CRC_INDICATION_PDU_T** allocate_and_populate_PDUs(int N) {
    if (N > SHARED_MEM_SIZE) {
        fprintf(stderr, "Cannot allocate more PDUs than shared memory size\n");
        return NULL;
    }

    pthread_mutex_lock(&shared_memory->lock);
    for (int i = 0; i < N; i++) {
        uint32_t tag = fetch_unique_RX_UE_INFORMATION_TAG();
        while (i > 0 && tag == shared_memory->PDUs[i - 1].RX_UE_INFORMATION_TAG) {
            tag = fetch_unique_RX_UE_INFORMATION_TAG(); // Ensure uniqueness
        }
        NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_pdu(tag, rand() % 65536); // Random RNTI for demonstration
        if (pdu) {
            shared_memory->PDUs[i] = *pdu;
            free(pdu);
        } else {
            pthread_mutex_unlock(&shared_memory->lock);
            return NULL; // Allocation failed, clean up
        }
    }
    shared_memory->count = N;
    pthread_mutex_unlock(&shared_memory->lock);
    return (NFAPI_CRC_INDICATION_PDU_T**)shared_memory->PDUs;
}

int main() {
    allocate_shared_memory();
    int N = 100; // Number of PDUs to allocate and populate
    NFAPI_CRC_INDICATION_PDU_T** PDUs = allocate_and_populate_PDUs(N);
    if (PDUs) {
        printf("Successfully allocated and populated %d PDUs\n", N);
        free(PDUs);
    }
    free_shared_memory();
    return 0;
}
