#define MAX_TAGS 10000

NFAPI_CRC_INDICATION_PDU_T nfa_api_circ_queue[MAX_TAGS];
pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
uint32_t head = 0, tail = 0;
int queue_full = 0, queue_empty = 1;

void fetch_and_update_tags() {
    while (1) {
        uint32_t tag;
        // Fetch unique identifier from database
        if (!fetch_unique_tag(&tag)) {
            continue; // Retry on failure
        }

        pthread_mutex_lock(&queue_lock);
        if ((tail + 1) % MAX_TAGS == head) {
            queue_full = 1;
            queue_empty = 0;
            pthread_cond_wait(&not_full, &queue_lock); // Wait for space
        } else {
            nfa_api_circ_queue[tail].tag = tag;
            tail = (tail + 1) % MAX_TAGS;
            queue_full = 0;
            queue_empty = 0;
            if (queue_empty) {
                pthread_cond_signal(&not_empty); // Notify consumer
            }
        }
        pthread_mutex_unlock(&queue_lock);
    }
}

int main() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, fetch_and_update_tags, NULL);

    // Simulate processing PDUs
    while (1) {
        pthread_mutex_lock(&queue_lock);
        if ((head + 1) % MAX_TAGS == tail) {
            queue_empty = 1;
            queue_full = 0;
            pthread_cond_wait(&not_empty, &queue_lock); // Wait for data
        } else {
            uint32_t tag = nfa_api_circ_queue[head].tag;
            head = (head + 1) % MAX_TAGS;
            queue_empty = 0;
            queue_full = 0;
            if (queue_full) {
                pthread_cond_signal(&not_full); // Notify producer
            }
            // Process PDU with tag
        }
        pthread_mutex_unlock(&queue_lock);
    }

    pthread_join(thread_id, NULL);
    return 0;
}
