#include <aws/core/Aws.h>
#include <aws/secretsmanager/SecretsManagerClient.h>
#include <aws/secretsmanager/model/GetSecretValueRequest.h>
#include <aws/secretsmanager/model/GetSecretValueResult.h>
#include <nlohmann/json.hpp>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <atomic>

class ConfigSystem {
public:
    struct ConfigItem {
        std::string key;
        nlohmann::json value;
        bool isValid;
    };

private:
    Aws::SecretsManager::SecretsManagerClient secretsManagerClient;
    std::unordered_map<std::string, ConfigItem> configCache;
    mutable std::mutex cacheMutex;
    std::condition_variable cv;
    std::atomic<bool> shuttingDown;

public:
    ConfigSystem() : secretsManagerClient(), shuttingDown(false) {}

    ~ConfigSystem() {
        shuttingDown = true;
        cv.notify_all();
    }

    void loadConfig(const std::string& secretName) {
        while (!shuttingDown) {
            auto request = Aws::SecretsManager::Model::GetSecretValueRequest();
            request.SetSecretId(secretName);
            auto outcome = secretsManagerClient.GetSecretValue(request);

            if (outcome.IsSuccess()) {
                ConfigItem item;
                item.key = secretName;
                try {
                    item.value = nlohmann::json::parse(outcome.GetResult().GetSecretString());
                    item.isValid = true;
                } catch (...) {
                    item.isValid = false;
                }
                std::lock_guard<std::mutex> lock(cacheMutex);
                configCache[secretName] = item;
            } else {
                if (outcome.GetError().GetExceptionName() == "ResourceNotFoundException") {
                    // Secret not found, wait for a while before retrying
                    cv.wait_for(std::unique_lock<std::mutex>(cacheMutex), std::chrono::seconds(10));
                } else {
                    // Handle other errors, log them and continue
                    std::cerr << "Failed to load config: " << outcome.GetError().GetMessage() << std::endl;
                    cv.wait_for(std::unique_lock<std::mutex>(cacheMutex), std::chrono::seconds(30));
                }
            }
        }
    }

    ConfigItem getConfig(const std::string& key) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        auto it = configCache.find(key);
        if (it != configCache.end()) {
            return it->second;
        }
        // Return an invalid config item if not found
        return {"", nlohmann::json(), false};
    }

    void shutdown() {
        shuttingDown = true;
        cv.notify_all();
    }
};

int main() {
    Aws::SDKOptions options;
    Aws::InitAPI(options);
    {
        ConfigSystem configSystem;
        std::thread t1(&ConfigSystem::loadConfig, &configSystem, "my-secret");
        std::thread t2(&ConfigSystem::loadConfig, &configSystem, "another-secret");

        // Simulate running the application
        std::this_thread::sleep_for(std::chrono::seconds(60));

        configSystem.shutdown();
        t1.join();
        t2.join();
    }
    Aws::ShutdownAPI(options);
    return 0;
}
