#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int device_id;
    int signal_strength;
    int *error_codes;
    size_t error_count;
} DeviceStatusReport;

typedef struct {
    DeviceStatusReport **reports;
    size_t count;
    pthread_mutex_t lock;
} ReportManager;

ReportManager *report_manager_create() {
    ReportManager *manager = malloc(sizeof(ReportManager));
    manager->reports = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void report_manager_add_report(ReportManager *manager, DeviceStatusReport *report) {
    pthread_mutex_lock(&manager->lock);
    manager->reports = realloc(manager->reports, (manager->count + 1) * sizeof(DeviceStatusReport *));
    manager->reports[manager->count] = report;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

void report_manager_free(ReportManager *manager) {
    for (size_t i = 0; i < manager->count; i++) {
        free(manager->reports[i]);
    }
    free(manager->reports);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    ReportManager *manager = report_manager_create();

    // Example usage
    DeviceStatusReport *report = malloc(sizeof(DeviceStatusReport));
    report->timestamp = time(NULL);
    report->device_id = 123;
    report->signal_strength = -50;
    report->error_codes = malloc(2 * sizeof(int));
    report->error_codes[0] = 404;
    report->error_codes[1] = 500;
    report->error_count = 2;

    report_manager_add_report(manager, report);

    // Cleanup
    free(report->error_codes);
    free(report);
    report_manager_free(manager);

    return 0;
}
