    std::mutex mutex;

public:
    void setParameterRange(const std::string& param, int min, int max) {
        std::lock_guard<std::mutex> lock(mutex);
        parameterRanges[param] = {min, max};
    }

    float generateRandomFloat(const std::string& param) {
        std::lock_guard<std::mutex> lock(mutex);
        auto range = parameterRanges.find(param);
        if (range == parameterRanges.end()) {
            throw std::runtime_error("Parameter range not set");
