    DeviceStatusReport** new_reports = (DeviceStatusReport**)realloc(
        manager->reports, (manager->count + 1) * sizeof(DeviceStatusReport*));
    if (!new_reports) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    manager->reports = new_reports;
    manager->reports[manager->count++] = report;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

