typedef struct {
    time_t timestamp;
    int device_id;
    float signal_strength;
    int *error_codes;
    int error_count;
} DeviceStatusReport;

DeviceStatusReport reports[MAX_DEVICES];
int report_count = 0;
pthread_mutex_t reports_lock = PTHREAD_MUTEX_INITIALIZER;

void* process_reports(void* arg) {
    while (1) {
        pthread_mutex_lock(&reports_lock);
        if (report_count > 0) {
            // Process the reports
            for (int i = 0; i < report_count; i++) {
                printf("Processing report for device %d at time %ld\n", reports[i].device_id, reports[i].timestamp);
                // Simulate processing
                free(reports[i].error_codes); // Free error codes
            }
            report_count = 0;
        }
        pthread_mutex_unlock(&reports_lock);
        sleep(1); // Simulate processing interval
    }
    return NULL;
}

void add_report(DeviceStatusReport *report) {
    pthread_mutex_lock(&reports_lock);
    if (report_count < MAX_DEVICES) {
        reports[report_count++] = *report;
    } else {
        printf("Device status report limit reached\n");
    }
    pthread_mutex_unlock(&reports_lock);
}

int main() {
    pthread_t process_thread;
    pthread_create(&process_thread, NULL, process_reports, NULL);

    DeviceStatusReport new_report;
    time_t current_time = time(NULL);

    // Simulate adding reports
    for (int i = 0; i < MIN_REPORTS_PER_SECOND * 10; i++) {
        new_report.timestamp = current_time + i;
        new_report.device_id = rand() % MAX_DEVICES;
        new_report.signal_strength = 0.5f + rand() / (float)RAND_MAX;
        new_report.error_codes = (int*)malloc(sizeof(int) * 3);
        new_report.error_count = 3;
        new_report.error_codes[0] = 1001;
        new_report.error_codes[1] = 1002;
        new_report.error_codes[2] = 1003;

        add_report(&new_report);
    }

    pthread_join(process_thread, NULL);
    return 0;
}
