    int device_id;
    float signal_strength;
    int error_codes_count;
    int* error_codes;
} DeviceStatusReport;

// Define a Node for linked list of reports
typedef struct Node {
    DeviceStatusReport report;
    struct Node* next;
} Node;

// Define the dynamic collection structure
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DeviceCollection;

// Initialize the device collection
void init_device_collection(DeviceCollection* collection) {
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
}

// Add a report to the collection
void add_report(DeviceCollection* collection, DeviceStatusReport report) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->report = report;
    new_node->next = NULL;

    pthread_mutex_lock(&collection->lock);
    if (collection->head == NULL) {
        collection->head = new_node;
    } else {
        Node* current = collection->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&collection->lock);
}

// Remove a report from the collection
void remove_report(DeviceCollection* collection, int device_id) {
    pthread_mutex_lock(&collection->lock);
    Node* current = collection->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->report.device_id == device_id) {
            if (prev == NULL) {
                collection->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&collection->lock);
}

