// Include necessary headers
#include <iostream>
#include <mutex>
#include <vector>
#include <queue>
#include <thread>
#include <condition_variable>
#include <chrono>
#include <atomic>

// Define DeviceStatusReport structure
struct DeviceStatusReport {
    std::chrono::system_clock::time_point timestamp;
    int deviceId;
    float signalStrength;
    std::vector<int> errorCodes;
};

// Define AlertType enum for different types of alerts
enum class AlertType {
    SIGNAL_STRENGTH_WARNING,
    ERROR_CODE_ALERT
};

// Forward declare the DeviceStatusManager class
class DeviceStatusManager;

// Define an observer interface for alert notifications
class AlertObserver {
public:
    virtual void onAlert(const AlertType& type, const DeviceStatusReport& report) = 0;
    virtual ~AlertObserver() = default;
};

// Implement a simple thread-safe queue for alerts
template <typename T>
class SafeQueue {
private:
    std::queue<T> queue_;
    mutable std::mutex mutex_;
    std::condition_variable condition_;

public:
    void push(const T& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(value);
        condition_.notify_one();
    }

    bool try_pop(T& value) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (queue_.empty()) {
            return false;
        }
        value = queue_.front();
        queue_.pop();
        return true;
    }

    size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.size();
    }
};

// Define the DeviceStatusManager class
class DeviceStatusManager {
public:
    // Constructor
    DeviceStatusManager() : stop_(false) {}

    // Add an alert observer
    void addObserver(AlertObserver* observer) {
        std::lock_guard<std::mutex> lock(mutex_);
        observers_.push_back(observer);
    }

    // Remove an alert observer
    void removeObserver(AlertObserver* observer) {
        std::lock_guard<std::mutex> lock(mutex_);
        observers_.erase(std::remove(observers_.begin(), observers_.end(), observer), observers_.end());
    }

    // Process a new device status report
    void processReport(const DeviceStatusReport& report) {
        if (report.signalStrength < minSignalThreshold_) {
            sendAlert(AlertType::SIGNAL_STRENGTH_WARNING, report);
        }
        for (int errorCode : report.errorCodes) {
            if (errorCode != 0) {
                sendAlert(AlertType::ERROR_CODE_ALERT, report);
            }
        }
    }

    // Start the alert processing thread
    void start() {
        worker_ = std::thread([this]() {
            while (!stop_) {
                DeviceStatusReport report;
                if (alerts_.try_pop(report)) {
                    notifyObservers(report);
                } else {
                    std::this_thread::sleep_for(std::chrono::milliseconds(10));
                }
            }
        });
    }

    // Stop the alert processing thread
    void stop() {
        stop_ = true;
        worker_.join();
    }

private:
    // Send an alert to all observers
    void sendAlert(const AlertType& type, const DeviceStatusReport& report) {
        std::lock_guard<std::mutex> lock(mutex_);
        alerts_.push({type, report});
    }

    // Notify all observers about a new alert
    void notifyObservers(const DeviceStatusReport& report) {
        for (auto observer : observers_) {
            observer->onAlert(alerts_.front().first, alerts_.front().second);
        }
        alerts_.pop();
    }

    std::vector<AlertObserver*> observers_;
    SafeQueue<std::pair<AlertType, DeviceStatusReport>> alerts_;
    float minSignalThreshold_ = 0.5; // Example threshold
    bool stop_;
    std::thread worker_;
};

// Define a simple alert observer implementation
class SimpleAlertObserver : public AlertObserver {
public:
    void onAlert(const AlertType& type, const DeviceStatusReport& report) override {
        switch (type) {
            case AlertType::SIGNAL_STRENGTH_WARNING:
                std::cout << "Signal strength warning for device " << report.deviceId << std::endl;
                break;
            case AlertType::ERROR_CODE_ALERT:
                std::cout << "Error code alert for device " << report.deviceId << std::endl;
                break;
        }
    }
};

// Example usage
int main() {
    DeviceStatusManager manager;
    SimpleAlertObserver observer;

    manager.addObserver(&observer);
    manager.start();

    // Simulate processing device status reports
    for (int i = 0; i < 1000; ++i) {
        DeviceStatusReport report;
        report.timestamp = std::chrono::system_clock::now();
        report.deviceId = i;
        report.signalStrength = (float)i / 1000.0f;
        for (int j = 0; j < 5; ++j) {
            report.errorCodes.push_back(i % 3);
        }
        manager.processReport(report);
    }

    manager.stop();
    return 0;
}
