typedef struct {
    time_t timestamp;
    int device_id;
    float signal_strength;
    int* error_codes;
    int num_error_codes;
} DeviceStatusReport;

typedef struct {
    DeviceStatusReport** reports;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DeviceCollection;

void init_device_collection(DeviceCollection* collection) {
    collection->reports = NULL;
    collection->size = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

void add_report_to_collection(DeviceCollection* collection, DeviceStatusReport* report) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity == 0 ? 1 : collection->capacity * 2;
        DeviceStatusReport** new_reports = realloc(collection->reports, new_capacity * sizeof(DeviceStatusReport*));
        if (!new_reports) {
            perror("Failed to allocate memory for device reports");
            exit(EXIT_FAILURE);
        }
        collection->reports = new_reports;
        collection->capacity = new_capacity;
    }
    collection->reports[collection->size++] = report;
    pthread_mutex_unlock(&collection->lock);
}

