// device_status_library.c
#include "device_status_report.h"
#include <stdlib.h>
#include <pthread.h>

typedef struct ReportNode {
    DeviceStatusReport report;
    struct ReportNode *next;
} ReportNode;

typedef struct ReportList {
    pthread_mutex_t lock;
    ReportNode *head;
} ReportList;

void initialize_report_list(ReportList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
}

void free_report_list(ReportList *list) {
    ReportNode *current = list->head;
    while (current != NULL) {
        ReportNode *next = current->next;
        free_device_status_report(&current->report);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

void add_to_report_list(ReportList *list, DeviceStatusReport *report) {
    pthread_mutex_lock(&list->lock);
    ReportNode *new_node = (ReportNode *)malloc(sizeof(ReportNode));
    new_node->report = *report;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

DeviceStatusReport* get_from_report_list(ReportList *list, int device_id) {
    pthread_mutex_lock(&list->lock);
    ReportNode *current = list->head;
    while (current != NULL) {
        if (current->report.device_id == device_id) {
            DeviceStatusReport *copy = malloc(sizeof(DeviceStatusReport));
            *copy = current->report;
            pthread_mutex_unlock(&list->lock);
            return copy;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}
