public interface IUserProfileService
{
    Task<UserProfile> UpdateProfile(UserProfileUpdateRequest request);
}

public class UserProfileService : IUserProfileService
{
    private readonly ApplicationDbContext _dbContext;
    private readonly IConnectionMultiplexer _redis;

    public UserProfileService(ApplicationDbContext dbContext, IConnectionMultiplexer redis)
    {
        _dbContext = dbContext;
        _redis = redis;
    }

    public async Task<UserProfile> UpdateProfile(UserProfileUpdateRequest request)
    {
        var user = await _dbContext.UserProfiles.FindAsync(request.UserId);
        if (user == null)
            throw new ArgumentException("User not found");

        // Validate token TTL
        var now = DateTimeOffset.UtcNow;
        if ((now - user.LastTokenValidationTime).TotalSeconds > Configuration.GetValue<int>("OAuth2:TTL"))
            throw new UnauthorizedAccessException("Session expired");

        // Apply rate limiting and caching strategies
        var cacheKey = $"user:{request.UserId}:profile";
        var cachedProfile = _redis.GetDatabase().StringGet(cacheKey);
        if (!string.IsNullOrEmpty(cachedProfile))
            return JsonConvert.DeserializeObject<UserProfile>(cachedProfile);

        // Update user profile in database and cache
        user.Name = request.Name;
        user.Email = request.Email;
        user.LastUpdateTime = now;
        await _dbContext.SaveChangesAsync();

        _redis.GetDatabase().StringSet(cacheKey, JsonConvert.SerializeObject(user), TimeSpan.FromSeconds(Configuration.GetValue<int>("Cache:Duration")));

        return user;
    }
}

public class UserProfile
{
    public int UserId { get; set; }
    public string Name { get; set; }
    public string Email { get; set; }
    public DateTimeOffset LastUpdateTime { get; set; }
    public DateTimeOffset LastTokenValidationTime { get; set; }
}

public class UserProfileUpdateRequest
{
    public int UserId { get; set; }
    public string Name { get; set; }
    public string Email { get; set; }
}
