#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/time.h>

#define MAX_LOG_SIZE 1024
#define MAX_THREAD_POOL_SIZE 10

typedef struct log_entry {
    char data[MAX_LOG_SIZE];
    struct timeval timestamp;
    struct log_entry *next;
} log_entry;

typedef struct log_queue {
    log_entry *front, *rear;
    int size;
    pthread_mutex_t lock;
    pthread_cond_t not_empty, not_full;
} log_queue;

log_queue *create_log_queue(int capacity) {
    log_queue *q = (log_queue *)malloc(sizeof(log_queue));
    q->front = q->rear = NULL;
    q->size = 0;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    pthread_cond_init(&q->not_full, NULL);
    return q;
}

void enqueue_log(log_queue *q, const char *data) {
    log_entry *new_entry = (log_entry *)malloc(sizeof(log_entry));
    strcpy(new_entry->data, data);
    gettimeofday(&new_entry->timestamp, NULL);
    new_entry->next = NULL;

    pthread_mutex_lock(&q->lock);
    while (q->size == MAX_THREAD_POOL_SIZE) {
        pthread_cond_wait(&q->not_full, &q->lock);
    }

    if (q->rear != NULL) {
        q->rear->next = new_entry;
    } else {
        q->front = new_entry;
    }
    q->rear = new_entry;
    q->size++;

    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->lock);
}

void *process_logs(void *arg) {
    log_queue *q = (log_queue *)arg;
    while (1) {
        pthread_mutex_lock(&q->lock);
        while (q->size == 0) {
            pthread_cond_wait(&q->not_empty, &q->lock);
        }

        log_entry *entry = q->front;
        q->front = entry->next;
        if (q->front == NULL) {
            q->rear = NULL;
        }
        q->size--;

        pthread_cond_signal(&q->not_full);
        pthread_mutex_unlock(&q->lock);

        // Process the log entry here
        printf("Processing log: %s\n", entry->data);
        free(entry);
    }

    return NULL;
}

int main() {
    log_queue *log_q = create_log_queue(MAX_THREAD_POOL_SIZE);
    pthread_t threads[MAX_THREAD_POOL_SIZE];

    for (int i = 0; i < MAX_THREAD_POOL_SIZE; i++) {
        pthread_create(&threads[i], NULL, process_logs, log_q);
    }

    // Simulate logging
    for (int i = 0; i < 100; i++) {
        char buffer[MAX_LOG_SIZE];
        snprintf(buffer, sizeof(buffer), "Log entry %d", i);
        enqueue_log(log_q, buffer);
    }

    for (int i = 0; i < MAX_THREAD_POOL_SIZE; i++) {
        pthread_join(threads[i], NULL);
    }

    free(log_q);
    return 0;
}
