#include <iostream>
#include <string>
#include <atomic>
#include <mutex>
#include <vector>
#include <queue>
#include <thread>
#include <condition_variable>
#include <future>
#include <functional>

class DynamicDataProcessor {
public:
    DynamicDataProcessor(size_t max_buffer_size, size_t min_buffer_size)
        : max_buffer_size_(max_buffer_size), min_buffer_size_(min_buffer_size),
          buffer_(new std::queue<std::string>()), running_(true) {}

    ~DynamicDataProcessor() {
        stop();
        delete buffer_;
    }

    void add_data(const std::string& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (buffer_->size() < max_buffer_size_) {
            buffer_->push(data);
            condition_.notify_one();
        }
    }

    std::vector<std::future<void>> process_data(size_t batch_size = 1) {
        std::vector<std::future<void>> futures;
        for (size_t i = 0; i < batch_size && running_; ++i) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this]{ return !buffer_->empty() || !running_; });
            if (!running_) break;

            auto data = buffer_->front();
            buffer_->pop();
            lock.unlock();

            futures.push_back(std::async(std::launch::async, [&data] {
                // Process the data here
                std::cout << "Processing: " << data << std::endl;
            }));
        }
        return futures;
    }

    void stop() {
        running_ = false;
        condition_.notify_all();
    }

private:
    size_t max_buffer_size_;
    size_t min_buffer_size_;
    std::queue<std::string>* buffer_;
    std::mutex mutex_;
    std::condition_variable condition_;
    std::atomic<bool> running_;
};
