    const char* output_file_path;
    json_object* transformation_rules;
    int num_threads;
    pthread_mutex_t lock;
    io_context_t* aio_ctx;
} ModuleConfig;

Buffer read_file_async(const char* file_path, size_t offset, size_t length);
void write_file_async(io_context_t* ctx, const char* file_path, Buffer buffer);
json_object* compile_transformation_rules(const char* config_path);
void apply_transformation(Buffer* buffer, json_object* rules);
int execute_transformations(ModuleConfig* config);

ModuleConfig* create_module_config(const char* input_path, const char* output_path, const char* rules_path, int num_threads) {
    ModuleConfig* config = (ModuleConfig*)malloc(sizeof(ModuleConfig));
    config->input_file_path = strdup(input_path);
    config->output_file_path = strdup(output_path);
    config->transformation_rules = compile_transformation_rules(rules_path);
    config->num_threads = num_threads;
    pthread_mutex_init(&config->lock, NULL);
    io_setup(num_threads, &config->aio_ctx);
    return config;
}

void destroy_module_config(ModuleConfig* config) {
    free(config->input_file_path);
    free(config->output_file_path);
    json_object_put(config->transformation_rules);
    pthread_mutex_destroy(&config->lock);
    io_destroy(config->aio_ctx);
    free(config);
}

int main(int argc, char** argv) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <rules_file> <num_threads>\n", argv[0]);
        return EXIT_FAILURE;
    }

    ModuleConfig* config = create_module_config(argv[1], argv[2], argv[3], atoi(argv[4]));
    int result = execute_transformations(config);
    destroy_module_config(config);

    if (result != 0) {
        fprintf(stderr, "Transformation failed with error code %d\n", result);
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
