// Define constants and types for clarity
using DataPacket = std::string;
using TimeStamp = std::chrono::system_clock::time_point;

struct Config {
    size_t maxBufferSize;
    time_t dataRetentionTime;
    bool enableRealTimeProcessing;
};

class IoTDevice {
public:
    virtual void send(DataPacket data) = 0;
    virtual ~IoTDevice() {}
};

class CloudService {
public:
    virtual void ingestData(DataPacket data) = 0;
    virtual ~CloudService() {}
};

class NoSQLDatabase {
public:
    virtual void store(DataPacket data, TimeStamp timestamp) = 0;
    virtual ~NoSQLDatabase() {}
};

class DataProcessor {
private:
    std::queue<DataPacket> buffer;
    std::mutex bufferMutex;
    std::condition_variable notEmptyCondVar;
    size_t bufferSize;
    Config config;
    std::shared_ptr<CloudService> cloudService;
    std::shared_ptr<NoSQLDatabase> database;
    std::atomic<bool> running;

public:
    DataProcessor(size_t maxBufferSize, time_t dataRetentionTime, std::shared_ptr<CloudService> cloudService, std::shared_ptr<NoSQLDatabase> database)
        : bufferSize(maxBufferSize), config({maxBufferSize, dataRetentionTime, true}), cloudService(cloudService), database(database), running(true) {}

    void startProcessing() {
        while (running.load()) {
            std::unique_lock<std::mutex> lock(bufferMutex);
            notEmptyCondVar.wait(lock, [this] { return !buffer.empty() || !running.load(); });
            if (!running.load()) break;
            DataPacket data = buffer.front();
            buffer.pop();
            lock.unlock();

            process(data);
        }
    }

private:
    void process(DataPacket data) {
        TimeStamp timestamp = std::chrono::system_clock::now();

        if (config.enableRealTimeProcessing && cloudService->isAvailable()) {
            cloudService->ingestData(data);
        } else {
            database->store(data, timestamp);
        }
    }

public:
    void addData(DataPacket data) {
        std::lock_guard<std::mutex> lock(bufferMutex);
        if (buffer.size() < bufferSize) {
            buffer.push(data);
            notEmptyCondVar.notify_one();
        } else {
            // Handle buffer overflow
            std::cerr << "Buffer overflow, dropping packet" << std::endl;
        }
    }

    void setConfig(const Config& newConfig) {
        config = newConfig;
    }

    void stopProcessing() {
        running.store(false);
        notEmptyCondVar.notify_all();
    }
};

class RealTimeAlertSystem {
public:
    virtual void sendAlert(DataPacket data) = 0;
    virtual ~RealTimeAlertSystem() {}
};

class DataValidationSystem {
public:
    virtual bool validateData(DataPacket data) const = 0;
    virtual ~DataValidationSystem() {}
};

// Implement concrete classes for IoTDevice, CloudService, NoSQLDatabase, RealTimeAlertSystem, and DataValidationSystem
// ...

