    auto database = std::make_shared<NoSQLDatabaseImpl>();
    auto alertSystem = std::make_shared<RealTimeAlertSystemImpl>();
    auto dataValidator = std::make_shared<DataValidationSystemImpl>();

    Config config;
    DataProcessor processor(config.maxBufferSize, config.dataRetentionTime, cloudService, database);

    // Add IoT devices
    std::vector<IoTDevice*> devices = {new IoTDeviceImpl1(), new IoTDeviceImpl2()};
    for (auto& device : devices) {
        device->send("data_packet");
    }

    // Start processing
    std::thread processorThread(&DataProcessor::startProcessing, &processor);

    // Simulate system operation and configuration changes
    // ...

    // Stop processing
    processor.stopProcessing();
    processorThread.join();

    return 0;
}
