#include <future>
#include <stdexcept>

struct DeviceStatusReport {
    std::time_t timestamp;
    int deviceID;
    double signalStrength;
    int errorCode;
};

class DeviceStatusManager {
public:
    void addReport(const DeviceStatusReport& report) {
        std::lock_guard<std::mutex> lock(mutex_);
        reports_[report.deviceID] = report;
    }

    void updateReport(int deviceID, const DeviceStatusReport& updatedReport) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (reports_.find(deviceID) != reports_.end()) {
            reports_[deviceID] = updatedReport;
        }
    }

    DeviceStatusReport getReport(int deviceID) const {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = reports_.find(deviceID);
        if (it != reports_.end()) {
            return it->second;
        } else {
            throw std::runtime_error("Device report not found");
        }
    }

    void summary() const {
        std::lock_guard<std::mutex> lock(mutex_);
        double totalSignalStrength = 0;
        std::unordered_map<int, int> errorCodeFrequency;

        for (const auto& report : reports_) {
            totalSignalStrength += report.second.signalStrength;
            errorCodeFrequency[report.second.errorCode]++;
        }

        size_t numReports = reports_.size();
        if (numReports > 0) {
            double averageSignalStrength = totalSignalStrength / numReports;
            std::cout << "Average Signal Strength: " << averageSignalStrength << std::endl;

            for (const auto& pair : errorCodeFrequency) {
                std::cout << "Error Code " << pair.first << ": " << pair.second << " occurrences" << std::endl;
            }
        } else {
            std::cout << "No reports available" << std::endl;
        }
    }

private:
    mutable std::mutex mutex_;
    std::unordered_map<int, DeviceStatusReport> reports_;
};

class DataIngestionService {
public:
    void ingestData(DeviceStatusManager& manager) {
        // Simulate data ingestion
        for (int i = 0; i < 10; ++i) {
            DeviceStatusReport report;
            report.timestamp = std::time(nullptr);
            report.deviceID = i;
            report.signalStrength = static_cast<double>(rand()) / RAND_MAX * 100;
            report.errorCode = rand() % 5;
            manager.addReport(report);
        }
    }
};

int main() {
    DeviceStatusManager manager;
    DataIngestionService service;

    std::thread ingestThread(&DataIngestionService::ingestData, &service, std::ref(manager));

    // Simulate processing
    std::this_thread::sleep_for(std::chrono::seconds(2));
    manager.summary();

    ingestThread.join();
    return 0;
}
