public:
    void addOrUpdateReport(const DeviceStatusReport& report) {
        std::lock_guard<std::mutex> lock(mutex_);
        reports_[report.deviceId] = report;
    }

    DeviceStatusReport getReport(int deviceId) const {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = reports_.find(deviceId);
        if (it != reports_.end()) {
            return it->second;
        } else {
            throw std::runtime_error("Device status report not found");
        }
    }

private:
    mutable std::mutex mutex_;
    std::unordered_map<int, DeviceStatusReport> reports_;
};

int main() {
