#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define DeviceStatusReport structure
typedef struct {
    time_t timestamp;
    int device_id;
    float signal_strength;
    int *error_codes;
    int error_count;
} DeviceStatusReport;

// Define a node for the linked list
typedef struct report_node {
    DeviceStatusReport report;
    struct report_node *next;
} ReportNode;

// Define a structure to manage the collection of reports
typedef struct {
    pthread_mutex_t lock;
    ReportNode *head;
} ReportCollection;

// Function to initialize the report collection
void init_report_collection(ReportCollection *collection) {
    pthread_mutex_init(&collection->lock, NULL);
    collection->head = NULL;
}

// Function to add a new report to the collection
void add_report_to_collection(ReportCollection *collection, DeviceStatusReport *report) {
    pthread_mutex_lock(&collection->lock);
    ReportNode *new_node = (ReportNode *)malloc(sizeof(ReportNode));
    new_node->report = *report;
    new_node->next = collection->head;
    collection->head = new_node;
    pthread_mutex_unlock(&collection->lock);
}

// Function to remove all reports from the collection
void clear_report_collection(ReportCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    ReportNode *current = collection->head;
    while (current != NULL) {
        ReportNode *next = current->next;
        free(current);
        current = next;
    }
    collection->head = NULL;
    pthread_mutex_unlock(&collection->lock);
}

// Function to process reports from the ingestion service
void *process_reports(void *arg) {
    ReportCollection *collection = (ReportCollection *)arg;
    // Simulate fetching and processing reports from an external data ingestion service
    DeviceStatusReport report;
    while (1) {
        // Fetch a new report from the ingestion service
        fetch_report_from_service(&report);

        // Add the report to the collection
        add_report_to_collection(collection, &report);

        // Sleep for a short duration before fetching the next report
        sleep(1);
    }
}

// Function to start processing threads based on current load
void start_processing_threads(ReportCollection *collection, int num_threads) {
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&threads[i], NULL, process_reports, collection) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }
    // Wait for all threads to finish
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

// Function to dynamically adjust the number of processing threads
void adjust_processing_threads(ReportCollection *collection, int current_load) {
    int target_threads = current_load / 100 + 1;
    start_processing_threads(collection, target_threads);
}
