#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define DeviceStatusReport structure
typedef struct {
    time_t timestamp;
    int device_id;
    float signal_strength;
    int *error_codes;
    size_t error_count;
} DeviceStatusReport;

// Define a node for the linked list
typedef struct Node {
    DeviceStatusReport report;
    struct Node *next;
} Node;

// Define the library's data structure
typedef struct {
    Node *head;
    pthread_mutex_t lock;
} DeviceStatusLibrary;

// Initialize the library
void init_library(DeviceStatusLibrary *library) {
    library->head = NULL;
    pthread_mutex_init(&library->lock, NULL);
}

// Add a report to the library
void add_report(DeviceStatusLibrary *library, DeviceStatusReport report) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->report = report;
    new_node->next = NULL;

    pthread_mutex_lock(&library->lock);
    if (library->head == NULL) {
        library->head = new_node;
    } else {
        Node *current = library->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&library->lock);
}

// Remove all reports from the library
void clear_library(DeviceStatusLibrary *library) {
    pthread_mutex_lock(&library->lock);
    Node *current = library->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }
    library->head = NULL;
    pthread_mutex_unlock(&library->lock);
}

// Destroy the library
void destroy_library(DeviceStatusLibrary *library) {
    clear_library(library);
    pthread_mutex_destroy(&library->lock);
}
