public class ErrorLoggingFramework {

    private static final int MAX_RETRIES = 3;
    private static final long INITIAL_DELAY_MS = 100;
    private static final CircuitBreaker circuitBreaker = new CircuitBreaker(MAX_RETRIES, INITIAL_DELAY_MS);

    public void logError(String errorDetails) {
        if (circuitBreaker.isClosed()) {
            try {
                // Asynchronous logging to a distributed queue
                sendToQueue(errorDetails);
            } catch (Exception e) {
                circuitBreaker.open();
                logFallback(errorDetails);
            }
        } else {
            logFallback(errorDetails);
        }
    }

    private void sendToQueue(String errorDetails) throws Exception {
        // Simulate sending to a distributed queue
        if (Math.random() < 0.5) {
            throw new Exception("Network issue");
        }
