using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Net.Http;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Xml.Linq;

public class OrderProcessorService
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, DateTime> _apiRequestTimes = new();
    private const int MaxApiRequestsPerMinute = 50;
    private static readonly TimeSpan RateLimitInterval = TimeSpan.FromMinutes(1);
    private static readonly Random _random = new Random();

    public OrderProcessorService()
    {
        _httpClient = new HttpClient
        {
            Timeout = TimeSpan.FromSeconds(30) // configurable through environment variable
        };
    }

    public async Task ProcessOrdersAsync(string xmlFilePath)
    {
        var xmlDocument = XDocument.Load(xmlFilePath);
        var orders = xmlDocument.Descendants("Order").ToList();

        foreach (var order in orders)
        {
            await ProcessOrderAsync(order).ConfigureAwait(false);
        }
    }

    private async Task ProcessOrderAsync(XElement orderElement)
    {
        var orderId = orderElement.Attribute("Id")?.Value;
        if (string.IsNullOrEmpty(orderId))
            return;

        while (!CanMakeApiRequest())
        {
            await Task.Delay(100); // backoff strategy
        }

        try
        {
            var productDetails = await FetchProductDetailsAsync(orderId).ConfigureAwait(false);
            // Process order with product details
        }
        catch (Exception ex)
        {
            HandleError(ex, orderId);
        }
    }

    private async Task<string> FetchProductDetailsAsync(string orderId)
    {
        var apiEndpoint = Environment.GetEnvironmentVariable("API_ENDPOINT") ?? "https://api.example.com/product";
        var requestHeaders = new Dictionary<string, string>
        {
            { "Authorization", Environment.GetEnvironmentVariable("API_KEY") },
            { "Content-Type", "application/json" }
        };

        var response = await _httpClient.GetAsync($"{apiEndpoint}/{orderId}", HttpCompletionOption.ResponseHeadersRead).ConfigureAwait(false);

        if (!response.IsSuccessStatusCode)
        {
            throw new Exception($"Failed to fetch product details for order ID {orderId}");
        }

        return await response.Content.ReadAsStringAsync().ConfigureAwait(false);
    }

    private bool CanMakeApiRequest()
    {
        var now = DateTime.UtcNow;
        var requestsInLastMinute = _apiRequestTimes.Values.Count(t => t >= now - RateLimitInterval);

        if (requestsInLastMinute < MaxApiRequestsPerMinute)
        {
            _apiRequestTimes[orderId] = now;
            return true;
        }

        return false;
    }

    private void HandleError(Exception ex, string orderId)
    {
        // Implement configurable backoff strategy
        Console.WriteLine($"Error processing order ID {orderId}: {ex.Message}");
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        var service = new OrderProcessorService();
        await service.ProcessOrdersAsync("orders.xml");
    }
}
