#include <mutex>
#include <condition_variable>

struct DeviceStatusReport {
    std::time_t timestamp;
    int deviceID;
    double signalStrength;
    std::vector<int> errorCodes;
};

class DeviceStatusManager {
public:
    void addReport(const DeviceStatusReport& report) {
        std::lock_guard<std::mutex> lock(mutex_);
        reports_[report.deviceID] = report;
        cv_.notify_one();
    }

    bool getReport(int deviceID, DeviceStatusReport& report) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (reports_.find(deviceID) == reports_.end()) {
            if (!cv_.wait_for(lock, std::chrono::seconds(1), [this, deviceID] { return reports_.find(deviceID) != reports_.end(); })) {
                return false; // Timeout
            }
        }
        report = reports_[deviceID];
        return true;
    }

private:
    std::unordered_map<int, DeviceStatusReport> reports_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

int main() {
    DeviceStatusManager manager;
    DeviceStatusReport report1 = {std::time(nullptr), 12345, 90.5, {101, 102}};
    DeviceStatusReport retrievedReport;

    manager.addReport(report1);
    if (manager.getReport(12345, retrievedReport)) {
        std::cout << "Report retrieved successfully." << std::endl;
    } else {
        std::cout << "Failed to retrieve report." << std::endl;
    }

    return 0;
}
