class DynamicDeviceScriptManager {
private:
    mutable std::mutex deviceReportMutex_;
    std::unordered_map<std::string, DeviceStatusReport> deviceReports_;

    mutable std::mutex scriptElementMutex_;
    std::unordered_map<int, ScriptElement> scriptElements_;

public:
    void addOrUpdateDeviceReport(const std::string& deviceId, const DeviceStatusReport& report) {
        std::lock_guard<std::mutex> lock(deviceReportMutex_);
        deviceReports_[deviceId] = report;
    }

    DeviceStatusReport* getDeviceReport(const std::string& deviceId) {
        std::lock_guard<std::mutex> lock(deviceReportMutex_);
        auto it = deviceReports_.find(deviceId);
        return it != deviceReports_.end() ? &it->second : nullptr;
    }

    void addOrUpdateScriptElement(const int scriptId, const ScriptElement& element) {
        std::lock_guard<std::mutex> lock(scriptElementMutex_);
        scriptElements_[scriptId] = element;
    }

    ScriptElement* getScriptElement(int scriptId) {
        std::lock_guard<std::mutex> lock(scriptElementMutex_);
        auto it = scriptElements_.find(scriptId);
        return it != scriptElements_.end() ? &it->second : nullptr;
    }
};
