class SocialMediaProcessor:
    @inject
    def __init__(self, social_media_sources: Dict[str, object]):
        self.social_media_sources = social_media_sources

    def process_stream(self, stream_data):
        for source in self.social_media_sources.values():
            source.process(stream_data)

class SocialMediaSource:
    def process(self, data):
        # Process data from a specific social media platform
        pass

class PluginRegistry:
    @inject
    def __init__(self, plugins: List[SocialMediaSource]):
        self.plugins = plugins

    def get_source(self, name: str) -> SocialMediaSource:
        return next((p for p in self.plugins if p.__class__.__name__ == name), None)

@app.route('/process_stream', methods=['POST'])
@inject
def process_stream(plugin_registry: PluginRegistry):
    stream_data = request.json
    source_name = request.args.get('source')
    source = plugin_registry.get_source(source_name)
    if source:
        processor = SocialMediaProcessor(social_media_sources={source_name: source})
        processor.process_stream(stream_data)
        return jsonify({"status": "success"}), 200
    else:
        return jsonify({"error": "Source not found"}), 404

if __name__ == '__main__':
