['```python
# This code is a high-level representation of an adaptive, fault-tolerant API gateway implementation in Python.
# It includes advanced features such as rate limiting, request queuing, fallback strategies, anomaly detection,
# caching invalidation, tiered caching, asynchronous request handling, real-time analytics, and cost optimization.

import asyncio
from fastapi import FastAPI, HTTPException, Depends, Request
from pydantic import BaseModel
from starlette.middleware.cors import CORSMiddleware

app = FastAPI()

# Middleware for rate limiting and request queuing
class RateLimitMiddleware:
    def __init__(self, app, limit):
        self.app = app
        self.limit = limit
        self.requests = {}

    async def __call__(self, scope, receive, send):
        if scope['type'] == 'http':
            method = scope['method']
            client_host = scope['client'][0]
            current_time = asyncio.get_event_loop().time()

            if client_host not in self.requests:
                self.requests[client_host] = []

            self.requests[client_host].append(current_time)
            self.requests[client_host] = [t for t in self.requests[client_host] if current_time - t < 60]

            if len(self.requests[client_host]) > self.limit:
                raise HTTPException(status_code=429, detail="Too Many Requests")

        return await self.app(scope, receive, send)

# Fallback strategy for non-critical services
class FallbackStrategy:
    def __init__(self, services):
        self.services = services

    async def get_service(self, request):
        for service in self.services:
            try:
                response = await service(request)
                return response
            except Exception as e:
                print(f"Service {service} failed: {e}")
