['```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class SecureConnectionService {

    private AsynchronousChannelGroup channelGroup;
    private ExecutorService executorService;

    public SecureConnectionService(int numberOfThreads) {
        this.executorService = Executors.newFixedThreadPool(numberOfThreads);
        try {
            this.channelGroup = AsynchronousChannelGroup.withCachedThreadPool(executorService, numberOfThreads);
        } catch (IOException e) {
            throw new RuntimeException("Failed to initialize channel group", e);
        }
    }

    public void connectToServer(String host, int port, ConnectionHandler handler) {
        try {
            AsynchronousSocketChannel socketChannel = AsynchronousSocketChannel.open(channelGroup);
            socketChannel.connect(new InetSocketAddress(host, port), null, new CompletionHandler<Void, Void>() {
                @Override
                public void completed(Void result, Void attachment) {
                    System.out.println("Connected to " + host + ":" + port);
                    readFromServer(socketChannel, handler);
                }

                @Override
                public void failed(Throwable exc, Void attachment) {
                    System.err.println("Failed to connect to " + host + ":" + port);
                    exc.printStackTrace();
                }
            });
        } catch (IOException e) {
            throw new RuntimeException("Failed to create socket channel", e);
        }
    }

    private void readFromServer(AsynchronousSocketChannel socketChannel, ConnectionHandler handler) {
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        socketChannel.read(buffer, buffer, null, new CompletionHandler<Integer, ByteBuffer>() {
            @Override
            public void completed(Integer result, ByteBuffer attachment) {
                attachment.flip();
                byte[] data = new byte[attachment.remaining()];
                attachment.get(data);
                String response = new String(data);
                handler.handleResponse(response);
                readFromServer(socketChannel, handler);
            }

            @Override
            public void failed(Throwable exc, ByteBuffer attachment) {
                System.err.println("Failed to read from server");
                exc.printStackTrace();
                socketChannel.close().exceptionally(e -> null);
            }
        });
    }

    public interface ConnectionHandler {
        void handleResponse(String response);
    }

    public static void main(String[] args) {
        SecureConnectionService service = new SecureConnectionService(10);
        service.connectToServer("example.com", 80, new ConnectionHandler() {
            @Override
            public void handleResponse(String response) {
                System.out.println("Received: " + response);
            }
        });
    }
}
