#[derive(Clone)]
struct Transaction {
    id: u64,
    age: i32,
    frequency: i32,
    weighted_sum: f64,
}

async fn filter_transactions(transactions: Vec<Transaction>, max_weighted_sum: Option<f64>) -> Vec<Transaction> {
    let filtered = transactions.into_iter().filter(|t| {
        if let Some(max) = max_weighted_sum {
            t.weighted_sum <= max
        } else {
            true
        }
    }).collect();
    filtered
}

#[tokio::main]
async fn main() {
    let mut transactions = vec![
        Transaction { id: 1, age: 30, frequency: 5, weighted_sum: 20.0 },
        Transaction { id: 2, age: 60, frequency: 1, weighted_sum: 15.0 },
        // Add more transactions as needed
    ];

    let max_weighted_sum = Some(25.0);
    let filtered_transactions = filter_transactions(transactions.clone(), max_weighted_sum).await;

    println!("Filtered Transactions: {:?}", filtered_transactions);
}
```

