    public void scaleService(String serviceName, int desiredInstances) {
        List<ServiceInstance> instances = registry.getInstances(serviceName);
        if (instances.size() < desiredInstances) {
            for (int i = instances.size(); i < desiredInstances; i++) {
                ServiceInstance instance = createNewInstance(serviceName);
                registry.register(instance);
                monitor.startMonitoring(instance);
            }
        } else if (instances.size() > desiredInstances) {
            for (ServiceInstance instance : instances.subList(desiredInstances, instances.size())) {
                registry.deregister(instance);
                monitor.stopMonitoring(instance);
            }
        }
    }

