#include <iostream>
#include <unordered_map>
#include <vector>
#include <string>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <queue>
#include <openssl/md5.h>

struct DeviceStatusReport {
    std::string timestamp;
    int deviceId;
    float signalStrength;
    std::vector<int> errorCodes;
};

class DeviceStatusManager {
private:
    std::unordered_map<int, DeviceStatusReport> reports;
    std::mutex mtx;
    std::condition_variable cv;
    std::queue<DeviceStatusReport> incomingReports;

public:
    void addOrUpdateReport(const DeviceStatusReport& report) {
        std::unique_lock<std::mutex> lock(mtx);
        reports[report.deviceId] = report;
        lock.unlock();
        cv.notify_one();
    }

    DeviceStatusReport getReport(int deviceId) {
        std::unique_lock<std::mutex> lock(mtx);
        while (reports.find(deviceId) == reports.end()) {
            cv.wait(lock);
        }
        return reports[deviceId];
    }

    void processIncomingReports() {
        while (true) {
            DeviceStatusReport report;
            {
                std::unique_lock<std::mutex> lock(mtx);
                if (incomingReports.empty()) {
                    cv.wait(lock, [this] { return !incomingReports.empty(); });
                }
                report = incomingReports.front();
                incomingReports.pop();
            }
            addOrUpdateReport(report);
        }
    }

    static std::string md5(const std::string& input) {
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)input.c_str(), input.length(), (unsigned char*)&digest);    
        char buf[33];
        for(int i = 0; i < 16; ++i)
            sprintf(buf + i*2, "%02x", digest[i]);
        return std::string(buf);
    }
};

int main() {
    DeviceStatusManager manager;
    std::thread t(&DeviceStatusManager::processIncomingReports, &manager);

    DeviceStatusReport report1 = {"2023-04-01 12:00:00", 1, 5.6f, {101, 102}};
    manager.addOrUpdateReport(report1);
    DeviceStatusReport retrievedReport = manager.getReport(1);
    std::cout << "Retrieved Report: " << retrievedReport.timestamp << ", ID: " << retrievedReport.deviceId 
              << ", Signal Strength: " << retrievedReport.signalStrength << std::endl;

    t.join();
    return 0;
}
