// External API client with rate limiting and retries
class ApiClient {
    private $baseUrl;
    private $apiKey;
    private $maxRetries = 3;

    public function __construct($baseUrl, $apiKey) {
        $this->baseUrl = $baseUrl;
        $this->apiKey = $apiKey;
    }

    public function request($endpoint, $method = 'GET', $data = []) {
        for ($retryCount = 0; $retryCount <= $this->maxRetries; $retryCount++) {
            try {
                $ch = curl_init();
                curl_setopt($ch, CURLOPT_URL, $this->baseUrl . $endpoint);
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
                curl_setopt($ch, CURLOPT_HEADER, ['Authorization: Bearer ' . $this->apiKey]);
                if ($method === 'POST') {
                    curl_setopt($ch, CURLOPT_POST, 1);
                    curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($data));
                }
                $response = curl_exec($ch);
                $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
                curl_close($ch);

                if ($httpCode == 200) {
                    return json_decode($response, true);
                } elseif ($httpCode >= 500 && $retryCount < $this->maxRetries) {
                    sleep(1); // Exponential backoff
                } else {
                    throw new Exception("API request failed with HTTP code: $httpCode");
                }
            } catch (Exception $e) {
                logMessage('Error during API request: ' . $e->getMessage());
                if ($retryCount < $this->maxRetries) {
                    sleep(1); // Exponential backoff
                } else {
                    throw $e;
                }
            }
        }
    }
}

// Example usage of the API client
$apiClient = new ApiClient($currentEnv['api']['baseUrl'], $currentEnv['api']['apiKey']);
$response = $apiClient->request('/endpoint');

// Handle response or error
