#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the DeviceStatusReport structure
typedef struct {
    time_t timestamp;
    char device_id[50];
    int signal_strength;
    int* error_codes;
    int num_error_codes;
} DeviceStatusReport;

// Define a node for the linked list of DeviceStatusReports
typedef struct DeviceNode {
    DeviceStatusReport report;
    struct DeviceNode* next;
} DeviceNode;

// Define a mutex to protect concurrent access
pthread_mutex_t device_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new DeviceStatusReport to the list
void add_device_report(DeviceNode** head, DeviceStatusReport report) {
    pthread_mutex_lock(&device_list_mutex);
    DeviceNode* newNode = (DeviceNode*)malloc(sizeof(DeviceNode));
    newNode->report = report;
    newNode->next = *head;
    *head = newNode;
    pthread_mutex_unlock(&device_list_mutex);
}

// Function to delete the entire list of DeviceStatusReports
void delete_device_report_list(DeviceNode** head) {
    pthread_mutex_lock(&device_list_mutex);
    while (*head != NULL) {
        DeviceNode* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
    pthread_mutex_unlock(&device_list_mutex);
}

// Function to print the list of DeviceStatusReports
void print_device_report_list(DeviceNode* head) {
    pthread_mutex_lock(&device_list_mutex);
    DeviceNode* current = head;
    while (current != NULL) {
        printf("Timestamp: %ld, Device ID: %s, Signal Strength: %d\n", 
               current->report.timestamp, current->report.device_id, current->report.signal_strength);
        for (int i = 0; i < current->report.num_error_codes; i++) {
            printf("Error Code: %d ", current->report.error_codes[i]);
        }
        printf("\n");
        current = current->next;
    }
    pthread_mutex_unlock(&device_list_mutex);
}

// Main function to demonstrate the library usage
int main() {
    DeviceNode* head = NULL;

    // Create some sample DeviceStatusReports
    DeviceStatusReport report1 = {time(NULL), "Device001", 95, (int[]){101, 102}, 2};
    DeviceStatusReport report2 = {time(NULL) + 3600, "Device002", 88, (int[]){201}, 1};

    // Add the reports to the list
    add_device_report(&head, report1);
    add_device_report(&head, report2);

    // Print the list of reports
    print_device_report_list(head);

    // Delete the entire list of reports
    delete_device_report_list(&head);

    return 0;
}
