['```rust
use std::process::{Command, Stdio};
use std::time::Instant;
use libc::getrusage;
use std::sync::atomic::{AtomicUsize, Ordering};

static RESIDENT_SET_SIZE: AtomicUsize = AtomicUsize::new(0);

fn get_resident_set_size() -> usize {
    unsafe {
        let mut usage = getrusage(RUSAGE_SELF);
        RESIDENT_SET_SIZE.fetch_add(usage.ru_maxrss as usize, Ordering::SeqCst);
        usage.ru_maxrss as usize
    }
}

fn compile_rust_code_with_logging() -> i32 {
    let start_time = Instant::now();
    let before_memory_usage = get_resident_set_size();

    let output = Command::new("rustc")
        .arg("--crate-type=bin")
        .arg("main.rs")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("Failed to start rustc process");

    match output.wait() {
        Ok(status) => {
            let after_memory_usage = get_resident_set_size();
            println!("Compilation time: {:?}", start_time.elapsed());
            println!("Memory usage before compilation: {} KB", before_memory_usage);
            println!("Memory usage after compilation: {} KB", after_memory_usage);
            status.code().unwrap_or(1)
        }
        Err(e) => {
            eprintln!("Error during rustc execution: {}", e);
            1
        }
    }
}

fn main() {
    let exit_code = compile_rust_code_with_logging();
    println!("Rust compiler exited with code: {}", exit_code);
}
