// Load environment variables from a .env file
require 'vendor/autoload.php';
use Dotenv\Dotenv;
$dotenv = Dotenv::createImmutable(__DIR__);
$dotenv->load();

// Define constants for API endpoints and parameters
define('EMPLOYEE_API_URL', getenv('EMPLOYEE_API_URL'));
define('CITY_API_URL', getenv('CITY_API_URL'));
define('HR_SYSTEM_URL', getenv('HR_SYSTEM_URL'));

// Function to authenticate user using OAuth 2.0 client
function authenticateUser($clientId, $clientSecret) {
    $tokenUrl = EMPLOYEE_API_URL . '/oauth/token';
    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $tokenUrl);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query([
        'grant_type' => 'client_credentials',
        'client_id' => $clientId,
        'client_secret' => $clientSecret
    ]));
    $response = curl_exec($ch);
    if (curl_errno($ch)) {
        throw new Exception('OAuth token request failed: ' . curl_error($ch), 500);
    }
    curl_close($ch);
    $tokenData = json_decode($response, true);
    $_SESSION['access_token'] = $tokenData['access_token'];
}

// Function to get user information using access token
function getUserInfo() {
    if (!isset($_SESSION['access_token'])) {
        throw new Exception('User not authenticated', 401);
    }
    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, EMPLOYEE_API_URL . '/user/info');
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_HTTPHEADER, [
        'Authorization: Bearer ' . $_SESSION['access_token']
    ]);
    $response = curl_exec($ch);
    if (curl_errno($ch)) {
        throw new Exception('User info request failed: ' . curl_error($ch), 500);
    }
    curl_close($ch);
    return json_decode($response, true);
}

// Example usage
try {
    authenticateUser(getenv('CLIENT_ID'), getenv('CLIENT_SECRET'));
    $userInfo = getUserInfo();
    echo "Authenticated as user: " . htmlspecialchars($userInfo['name']);
} catch (Exception $e) {
    http_response_code($e->getCode());
    echo $e->getMessage();
}
