subscription_path = config['pubsub']['subscription_path']

@app.route('/subscribe', methods=['POST'])
def subscribe():
    data = request.json
    subscription_id = data.get('subscription_id')
    topic_type = data.get('topic_type')

    if not subscription_id or not topic_type:
        return jsonify({'error': 'Missing subscription ID or topic type'}), 400

    # Subscribe to the appropriate broker or service
    if topic_type == 'kafka':
        subscribe_kafka(subscription_id)
    elif topic_type == 'rabbitmq':
        subscribe_rabbitmq(subscription_id)
    elif topic_type == 'sns':
        subscribe_sns(subscription_id)
    elif topic_type == 'pubsub':
        subscribe_pubsub(subscription_id)

    return jsonify({'message': f'Subscribed to {topic_type} with ID: {subscription_id}'})

def subscribe_kafka(subscription_id):
