#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <json-c/json.h>

typedef struct {
    char* key;
    char* value;
} ResourceBundleItem;

typedef struct {
    ResourceBundleItem** items;
    size_t count;
} ResourceBundle;

ResourceBundle* loadResourceBundle(const char* filePath) {
    FILE* file = fopen(filePath, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char* buffer = (char*)malloc(fileSize + 1);
    if (!buffer) {
        fclose(file);
        perror("Failed to allocate memory");
        return NULL;
    }

    size_t bytesRead = fread(buffer, 1, fileSize, file);
    if (bytesRead != fileSize) {
        free(buffer);
        fclose(file);
        perror("Failed to read file");
        return NULL;
    }
    buffer[fileSize] = '\0';

    json_object* jsonObject = json_tokener_parse(buffer);
    if (!jsonObject || json_object_get_type(jsonObject) != json_type_object) {
        free(buffer);
        fclose(file);
        errno = ENODATA;
        return NULL;
    }

    ResourceBundle* bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    if (!bundle) {
        json_object_put(jsonObject);
        free(buffer);
        fclose(file);
        perror("Failed to allocate memory");
        return NULL;
    }
    bundle->items = NULL;
    bundle->count = 0;

    size_t itemCount = json_object_object_length(jsonObject);
    bundle->items = (ResourceBundleItem**)malloc(itemCount * sizeof(ResourceBundleItem*));
    if (!bundle->items) {
        free(bundle);
        json_object_put(jsonObject);
        free(buffer);
        fclose(file);
        perror("Failed to allocate memory");
        return NULL;
    }

    size_t index = 0;
    struct json_object_iter iter;
    json_object_object_foreachC(jsonObject, &iter) {
        char* key = strdup(iter.key);
        if (!key) {
            for (size_t i = 0; i < index; i++) {
                free(bundle->items[i]->key);
                free(bundle->items[i]->value);
                free(bundle->items[i]);
            }
            free(bundle->items);
            free(bundle);
            json_object_put(jsonObject);
            free(buffer);
            fclose(file);
            perror("Failed to allocate memory");
            return NULL;
        }

        struct json_object* valueObject = iter.val;
        const char* value = json_object_get_string(valueObject);

        bundle->items[index] = (ResourceBundleItem*)malloc(sizeof(ResourceBundleItem));
        if (!bundle->items[index]) {
            for (size_t i = 0; i <= index; i++) {
                free(bundle->items[i]->key);
                free(bundle->items[i]->value);
                free(bundle->items[i]);
            }
            free(bundle->items);
            free(key);
            free(bundle);
            json_object_put(jsonObject);
            free(buffer);
            fclose(file);
            perror("Failed to allocate memory");
            return NULL;
        }
        bundle->items[index]->key = key;
        bundle->items[index++]->value = strdup(value);
    }

    json_object_put(jsonObject);
    free(buffer);
    fclose(file);

    bundle->count = itemCount;
    return bundle;
}

void freeResourceBundle(ResourceBundle* bundle) {
    for (size_t i = 0; i < bundle->count; i++) {
        free(bundle->items[i]->key);
        free(bundle->items[i]->value);
        free(bundle->items[i]);
    }
    free(bundle->items);
    free(bundle);
}
