# Define a CacheManager bean using Ehcache for distributed caching with Redis
@Configuration
public class CacheConfig {

    @Bean
    public CacheManager cacheManager() {
        return Caching.getCachingProvider().getCacheManager();
    }

    @Bean
    public Cache<User> userCache(CacheManager cacheManager) {
        MutableConfiguration<Long, User> config = new MutableConfiguration<>();
        config.setTypes(Long.class, User.class);
        config.setExpiryPolicyFactory(Expirations.timeToLiveExpiration(Duration.ofSeconds(60)));
        return cacheManager.createCache("userCache", config);
    }
}

// Implement JWT authentication for secure access control
@Component
public class JwtAuthenticationFilter extends OncePerRequestFilter {

    @Autowired
    private JwtTokenUtil jwtTokenUtil;

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        // Extract and validate JWT token from the Authorization header
        String authHeader = request.getHeader("Authorization");
        if (authHeader != null && authHeader.startsWith("Bearer ")) {
            String jwtToken = authHeader.substring(7);
            String username = jwtTokenUtil.getUsernameFromToken(jwtToken);
            UsernamePasswordAuthenticationToken authentication = new UsernamePasswordAuthenticationToken(username, null, AuthorityUtils.NO_AUTHORITIES);
            SecurityContextHolder.getContext().setAuthentication(authentication);
        }
        chain.doFilter(request, response);
    }
}

// Implement CircuitBreaker pattern using Resilience4j
@Configuration
public class CircuitBreakerConfig {

    @Bean
    public CircuitBreakerFactory circuitBreakerFactory() {
        return new CircuitBreakerFactory("default", CircuitBreakerConfig.custom().failureRateThreshold(50).waitDurationInOpenState(Duration.ofSeconds(10)).build());
    }
}

