#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <future>
#include <memory>

// Define a structure for DeviceStatusReport
struct DeviceStatusReport {
    std::string timestamp;
    std::string deviceID;
    int signalStrength;
    std::vector<int> errorCodes;
};

class DeviceStatusManager {
public:
    // Add a report
    void addReport(const DeviceStatusReport& report) {
        std::lock_guard<std::mutex> lock(mutex_);
        reports_.push_back(report);
        condition_.notify_one();
    }

    // Get the number of reports
    size_t getNumReports() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return reports_.size();
    }

    // Retrieve a report by index
    DeviceStatusReport getReport(size_t index) const {
        std::lock_guard<std::mutex> lock(mutex_);
        if (index < reports_.size()) {
            return reports_[index];
        }
        throw std::out_of_range("Index out of range");
    }

private:
    mutable std::mutex mutex_;
    std::vector<DeviceStatusReport> reports_;
    std::condition_variable condition_;
};

int main() {
    DeviceStatusManager manager;

    // Add some reports
    manager.addReport({"2023-10-01 12:00", "device1", 50, {}});
    manager.addReport({"2023-10-01 12:01", "device2", 75, {404, 500}});

    // Retrieve and print reports
    std::cout << "Number of reports: " << manager.getNumReports() << std::endl;
    for (size_t i = 0; i < manager.getNumReports(); ++i) {
        auto report = manager.getReport(i);
        std::cout << "Timestamp: " << report.timestamp << ", Device ID: " << report.deviceID 
                  << ", Signal Strength: " << report.signalStrength << std::endl;
    }

    return 0;
}
